window.KURAN_DATA = [{"id":1,"name":"AÇILIŞ (FATİHA) SÛRESİ","verses":[{"n":1,"t":"Rahman ve Rahim ALLAH'ın ismiyle."},{"n":2,"t":"Övgü, evrenlerin Rabbi ALLAH'adır."},{"n":3,"t":"Rahman, Rahim (Merhametli),"},{"n":4,"t":"Yargı (Din) Gününün sahibi."},{"n":5,"t":"Ancak sana tapar, ancak senden yardım dileriz."},{"n":6,"t":"Bizi doğru yola ilet."},{"n":7,"t":"Gazaba uğrayanların ve sapmışların değil; kendilerine iyilikte bulunduğun kimselerin yoluna..."}]},{"id":2,"name":"İNEK (BAKARA) SÛRESİ","verses":[{"n":1,"t":"A.L.M."},{"n":2,"t":"Bu, kuşkusuz, erdemliler için yol gösterici bir kitaptır. (1) Erdemliler (Muttakiler)"},{"n":3,"t":"Onlar ki duyularıyla algılayamadıkları gerçeklere de inanırlar, namazı (salat) gözetirler,**  kendilerine verdiğimiz rızıktan muhtaçlara verirler."},{"n":4,"t":"Sana indirilene ve senden önce indirilene inanırlar. Ahiret konusunda da hiçbir kuşkuları yoktur."},{"n":5,"t":"İşte, Rableri tarafından yol gösterilenler ve mutluluğa erenler bunlardır. (2) Fanatik İnkarcılar (Kafirler)"},{"n":6,"t":"İnkar edenlere gelince, onları uyarsan da uyarmasan da onlar için birdir; onlar inanmazlar."},{"n":7,"t":"ALLAH kalplerini ve kulaklarını mühürler. Gözlerinde perde vardır ve büyük azap onlar içindir. (3) İkiyüzlüler (Münafıklar)"},{"n":8,"t":"Halktan öyle kimseler var ki aslında inanmadıkları halde \"ALLAH'a ve ahiret gününe inandık,\" derler."},{"n":9,"t":"ALLAH'ı ve müminleri aldatmak isterler. Halbuki kendi kendilerini aldatıyorlar. Farkında bile değiller."},{"n":10,"t":"Kalplerinde hastalık var. ALLAH da hastalıklarını arttırır. Yalanları yüzünden acı bir azabı hakkederler."},{"n":11,"t":"Kendilerine, \"Yeryüzünde bozgunculuk yapmayın,\" denildiğinde \"Bizler sadece düzeltenleriz,\" derler."},{"n":12,"t":"Oysa onlardır asıl bozguncu; farkında bile değiller."},{"n":13,"t":"Kendilerine, \"Şu halkın inandığı gibi inanın,\" denildiğinde, \"Beyinsizlerin inandığı gibi mi inanacağız,\" derler. Gerçek beyinsizler onlardır; fakat bilmezler."},{"n":14,"t":"İnananlarla karşılaştıkları vakit, \"İnanıyoruz,\" derler; fakat şeytanlarıyla başbaşa kaldıklarında, \"Sizinle beraberiz. Biz sadece alay etmekteyiz,\" derler."},{"n":15,"t":"ALLAH da, taşkınlıkları içinde bocalar durumda bırakarak onlarla alay eder."},{"n":16,"t":"Onlar hidayet karşılığında sapıklığı satın aldı. Ticaretleri ne kâr bırakır, ne de onları gerçeğe ulaştırır."},{"n":17,"t":"Durumları, ateş yakan kimselerin şu durumuna benzer: Ateş çevrelerini aydınlatmaya başlayınca ALLAH onların ışığını giderir ve onları karanlıklar içinde görmez bir halde bırakır."},{"n":18,"t":"Sağır, dilsiz ve kördürler; yönlerini değiştiremezler."},{"n":19,"t":"Ya da, karanlık, gökgürültüsü ve şimşekler arasında gökten boşanan bir yağmur altında yıldırımlardan ölmek korkusuyla parmaklarını kulaklarına tıkayan kimseye benzerler. ALLAH inkarcıları böyle kuşatır."},{"n":20,"t":"Şimşek neredeyse gözlerini kapıverecek! Önlerini aydınlattıkça ışığında yürürler. Üzerlerine karanlık basınca da dikilir kalırlar. ALLAH dileseydi işitme ve görmelerini giderirdi. ALLAH herşeye gücü yetendir."},{"n":21,"t":"İnsanlar! Sizi ve sizden öncekileri yaratan Rabbinize kulluk edin ki korunasınız."},{"n":22,"t":"O, yeryüzünü sizin için oturulabilir hale soktu ve göğü de bir yapı kıldı. Gökten su indirdi ve onunla rızık olarak size çeşitli ürünler çıkardı. Bile bile ALLAH'a eşler koşmayın. Yanlışlanabilir, Sınanabilir Delil"},{"n":23,"t":"Kulumuza indirdiğimizden kuşku içinde iseniz, buna benzer bir sure getirin. ALLAH'tan başka tüm tanıklarınızı da yardıma çağırın, doğru sözlü iseniz."},{"n":24,"t":"Bunu yapamazsanız -ki asla yapamıyacaksınız- o taktirde inkarcılar için hazırlanan ve yakıtı insanlar ile taşlar olan ateşten sakının."},{"n":25,"t":"İnanıp erdemli davrananları, içlerinde ırmaklar akan cennetlerle (bahçelerle) müjdele. Kendilerine oradaki ürünlerden rızıklar sunulduğunda \"Bu, daha önce bize sunulan nimetlerdir,\" derler. Böylece, kendilerine mecazi tanımlar (benzetmeler) verilir. Onlar için orada tertemiz eşler vardır ve onlar orada ebedi kalıcıdırlar. Cennet ve Cehennem Tasvirleri Birer Mecazdır"},{"n":26,"t":"ALLAH bir sivrisineği hatta ondan daha küçüğünü örnek vermekten çekinmez. İnananlar, bunun Rab'lerinden gelen bir gerçek olduğunu bilir. İnkarcılar ise \"ALLAH bu benzetme ile neyi amaçladı,\" derler. O, bununla bir çok kişiyi saptırır ve birçok kişiyi de doğruya iletir. O, bununla sadece fasıkları saptırır."},{"n":27,"t":"Onlar ki ALLAH ile yaptıkları anlaşmaya bağlılık sözü verdikten sonra onu bozarlar, ALLAH'ın birleştirilmesini emrettiği şeyi keserler ve yeryüzünde bozgunculuk yaparlar. İşte onlar kaybedenlerdir. İki Ölüm ve İki Hayat"},{"n":28,"t":"ALLAH'ı nasıl inkar edersiniz? Siz ölüler idiniz o sizi diriltti. Sonra sizi öldürür ve tekrar diriltir ve sonunda ona döndürülürsünüz."},{"n":29,"t":"Yeryüzünde herşeyi sizin için yaratan O'dur. Sonra göğe yönelip onu yedi gök olarak düzenledi.* O, her şeyi Bilir. Yaratılış"},{"n":30,"t":"Rabbin, meleklere şöyle demişti: \"Yeryüzüne bir halife yerleştireceğim.\" Melekler de: \"Orada bozgunculuk yapacak, kan akıtacak birisini mi yerleştireceksin? Halbuki biz seni överek yüceltiyor ve mutlak otoriteni onaylıyoruz,\" dediler. \"Bilmediğinizi Ben bilirim,\" dedi."},{"n":31,"t":"Adem'e tüm isimleri (nitelemeleri) öğretti, sonra onları meleklere sunup, \"Doğru iseniz, şunların isimlerini (özelliklerini, niteliklerini) siz bana bildirin,\" dedi."},{"n":32,"t":"Dediler: \"Sen Yücesin, senin bize öğrettiğinden başka bir bilgimiz yok. Sen Bilensin, Bilgesin.\""},{"n":33,"t":"Dedi: \"Adem! Onların isimlerini şunlara haber ver.\" İsimlerini onlara haber verince, \"Size, yerin ve göklerin sırlarını biliyorum, açıkladığınızı da gizlediğinizi de biliyorum dememiş miydim,\" dedi. Şeytanın İnsanla, İnsanın da Şeytanla Sınanması"},{"n":34,"t":"Meleklere, \"Adem'e secde edin,\" dedik. İblis hariç hepsi secde ettiler, o ise diretti, büyüklük tasladı ve nankörlük etti."},{"n":35,"t":"\"Adem! Eşinle birlikte cennette kal. Dilediğiniz yerde ondan bolca yeyin; ancak şu ağaca yaklaşmayın, yoksa zalimlerden olursunuz!,\" dedik."},{"n":36,"t":"Şeytan, onları oradan kaydırıp bulundukları yerden çıkarttı. Nihayet, \"Birbirinize düşman olarak aşağı inin. Yeryüzünde belli bir süre kalıp yaşayacaksınız,\" dedik."},{"n":37,"t":"Adem, Rabb'inden kelimeler aldı. Bunun üzerine onun tevbesini kabul etti. O, yönelişlere karşılık verendir, Rahim'dir."},{"n":38,"t":"\"Oradan topluca ininiz,\" dedik, \"Benden size bir yol gösterici geldiği zaman, o yol göstericiye uyanlar için artık bir korku yok ve onlar üzülmeyecekler.\""},{"n":39,"t":"\"Ayetlerimizi yalanlayıp inkar edenler ise ateşe mahkumdur; orada sürekli kalacaklar.\" Bu Kuran'a İnanmalısınız"},{"n":40,"t":"İsrailoğulları! Size verdiğim nimetimi hatırlayın, bana verdiğiniz sözü tutun ki ben de size verdiğim sözü tutayım; yalnız benden korkun!"},{"n":41,"t":"Yanınızdakini doğrulayıcı olarak indirdiğime inanın. Ona karşı çıkanların ilki olmayın. Ayetlerimi değeri düşük şeylerle değişmeyin; sadece benden çekinin."},{"n":42,"t":"Bile bile gerçeği yanlış ile karıştırmayın, gerçeği gizlemeyin."},{"n":43,"t":"Namazı gözetin, zekatı verin ve eğilenlerle birlikte eğilin."},{"n":44,"t":"Halkı iyilik yapmağa çağırıp dururken kendinizi unutuyor musunuz? Üstelik Kitabı da okuyorsunuz? Aklınızı kullanmaz mısınız?"},{"n":45,"t":"Güçlüklere karşı direnerek (sabır) ve namazla yardım isteyiniz. Elbette bu, halka ağır gelir; ancak saygılı olanlar hariç."},{"n":46,"t":"Nitekim onlar, Rab'lerine kavuşacaklarına ve O'na döneceklerine inanırlar."},{"n":47,"t":"İsrailoğulları! Size verdiğim nimetlerimi ve sizi tüm halklara üstün tutmamı hatırlayın."},{"n":48,"t":"Öyle bir günden sakının ki, kimse kimsenin yerine birşey ödeyemez, aracılık (şefaat) kabul edilmez, kimseden bir fidye alınmaz ve yardım da edilmez."},{"n":49,"t":"İşkencenin en kötüsünü size uygulayan, kadınlarınızı bırakıp oğullarınızı öldüren Firavun'un adamlarından sizi kurtarmıştık. Bu, Rabbinizden büyük bir sınav idi."},{"n":50,"t":"Denizi yararak sizi kurtarmış, Firavun'un adamlarını da gözlerinizin önünde boğmuştuk."},{"n":51,"t":"Musa'yla kırk gece için sözleşmiştik. Ancak siz onun ardından kendinize zulmederek buzağıya taptınız."},{"n":52,"t":"Bunlara rağmen, şükredersiniz diye sizi affettik."},{"n":53,"t":"Yola gelmeniz için de Musa'ya kitabı ve yasayı verdik. Egonuzu Öldürün"},{"n":54,"t":"Musa, halkına demişti ki: \"Ey halkım, sizler buzağıya tapmakla nefsinize (kişilik, öz, ruh) zulmettiniz. Yaratıcınıza tövbe edin ve nefsinizi (egonuzu) öldürün.*1 Bu, yaratıcınız katında sizin için daha iyidir.\" O, sizi affeder. Elbette O, tövbeleri kabul edendir, Rahim'dir."},{"n":55,"t":"Bir zamanlar, \"Ey Musa, ALLAH'ı fiziksel olarak görmedikçe inanmayız,\" demiştiniz. Bakınıp dururken size yıldırım çarpmıştı.*"},{"n":56,"t":"Sonra, belki şükredersiniz diye ölümünüzün ardından sizi diriltmiştik. İsrailoğulları Sina'da: Özgürlüğün Bedelini Ödemekten Kaçınıyorlar"},{"n":57,"t":"Sizi bulutlarla gölgelendirmiş ve sizin için menna ve bıldırcın indirmiştik: \"Size verdiğimiz iyi rızıklardan yiyin.\" Fakat onlar bize değil, sadece kendilerine zulmediyorlardı."},{"n":58,"t":"\"Bu şehre girin. Orada dilediğiniz yerden bol bol yiyin. Kapıdan alçak gönüllü olarak girin ve dostça konuşun ki hatalarınızı bağışlayalım. Güzel davrananlara daha fazlasını veririz,\" demiştik."},{"n":59,"t":"Ancak içinizdeki zalimler, kendilerine verilen kelimeleri başka kelimelerle değiştirdiler. Nitekim, yoldan çıktıkları için zulmedenlerin üzerine gökten bir azap indirdik."},{"n":60,"t":"Musa, bir zamanlar halkı için su aramıştı. \"Değneğinle taşa vur,\" demiştik. Bunun üzerine taştan on iki pınar fışkırmıştı. Her kabile, içmesi için ayrılan pınarı bilmişti: \"ALLAH'ın rızkından yiyin için, yeryüzünde bozgunculuk yaparak dolaşmayın.\""},{"n":61,"t":"Fakat siz, \"Musa! Artık tek bir çeşit yiyeceğe dayanamıyacağız. Rabbini bizim için çağır da bize fasulye, kabak, sarımsak, mercimek, soğan gibi toprağın bitirdiğinden yetiştirsin,\" demiştiniz de, \"İyi olanı daha düşük olanla mı (özgürlüğü kölelikle mi) değiştirmek istiyorsunuz? İsterseniz Mısır'a geri dönün, orada aradığınızı bulabilirsiniz!,\" demişti. Böylece alçaklık ve yoksulluğa mahkum edildiler ve ALLAH'ın gazabına uğradılar. Çünkü onlar ALLAH'ın ayetlerine karşı sürekli nankörce davranıyorlar, peygamberleri haksız yere öldürüyorlardı. Çünkü onlar, karşı gelip taşkınlıkta bulunuyorlardı. * 2:61 Sina çölünde özgürlüklerine kavuşan İsrailoğulları bir süre sonra Mısır'daki nimetleri özlemeye başladılar. Tanrı bu olayı aktarmakla bize özgürlüğün önemini anlatıyor. Sadece Tanrı'ya Teslimiyet Kurtuluşu Garantiler"},{"n":62,"t":"İnananlar, Yahudiler, Hristiyanlar ve diğer dinlerden her kim: ALLAH'a ve ahirete inanır ve erdemli bir hayat sürdürürse, onların ödülleri Rab'leri katındadır. Onlar için korku ve üzüntü yoktur."},{"n":63,"t":"Sina dağını üzerinize kaldırarak bir zamanlar sizden söz almıştık: \"Size verdiğimize kuvvetle sarılın, içindekileri hatırlayın ki korunasınız,\" demiştik."},{"n":64,"t":"Fakat bundan sonra da yüz çevirdiniz. ALLAH'ın size bol nimeti ve merhameti olmasaydı kaybederdiniz."},{"n":65,"t":"Sizden Cumartesi yasağını çiğneyenleri elbette biliyorsunuz. Onlara \"Aşağılık maymunlar olun,\" dedik."},{"n":66,"t":"Bu cezayı çağdaşlarına ve sonraki kuşaklara bir ibret ve erdemli insanlar için de bir öğüt yaptık. Detaylarla Dini Zorlaştırmayın"},{"n":67,"t":"Hani, Musa halkına: \"ALLAH bir düve boğazlamanızı emrediyor,\" demişti. \"Bizimle alay mı ediyorsun,\" deyince de \"Cahilce davranmaktan ALLAH'a sığınırım,\" dedi."},{"n":68,"t":"\"Bizim için Rabbini çağır da onun niteliğini bize açıklasın,\" dediler. \"O diyor ki, o ne yaşlı ne genç, ikisinin ortasında bir düvedir. Size emredileni yapın,\" dedi."},{"n":69,"t":"\"Bizim için Rabbini çağır da onun rengini de açıklasın,\" dedi ki: \"O diyor ki, o rengi parlak sarı bir düvedir, bakanların içini açar,\" dediler."},{"n":70,"t":"\"Bizim için Rabbini çağır da, onun niteliğini bize daha da açıklasın. Çünkü düveler bizce birbirine benziyor. ALLAH dilerse yolu buluruz,\" dediler."},{"n":71,"t":"\"O diyor ki, o düve yeri sürüp ekini sulayarak boyunduruk altında ezilmemiş, kusursuz, alacasız bir düvedir,\" dedi. \"İşte şimdi gerçeği getirdin!,\" diyerek sonunda düveyi boğazladılar; az kalsın bunu yapmıyacaklardı.*"},{"n":72,"t":"Hani bir kişiyi öldürmüş ve suçu birbirinize atmıştınız. Oysa ALLAH gizlediklerinizi açığa çıkaracaktı."},{"n":73,"t":"\"(Düvenin) bir parçasıyla ona (öldürülene) vurun,\" dedik. İşte, ALLAH ölüleri böyle diriltir ve düşünesiniz diye ayetlerini (mucizelerini) böyle gösterir."},{"n":74,"t":"Tüm bunlara rağmen yine kalpleriniz katılaştı; taş gibi, hatta daha katı. Çünkü öyle taşlar var ki kendisinden ırmaklar fışkırır. Bazıları yarılır, bağrından su çıkarır. Bazıları ise ALLAH'a olan saygıdan dolayı siner. ALLAH yaptıklarınızdan habersiz değildir."},{"n":75,"t":"Onların size inanacaklarını mı umuyorsunuz? Halbuki onların bir kısmı, ALLAH'ın sözünü işitip kavradıktan sonra, bile bile onu değiştirirlerdi."},{"n":76,"t":"İnananlarla karşılaşınca, \"İnandık,\" derler; başbaşa kaldıklarında ise \"Rabbiniz katında size karşı delil olarak kullanmaları için, ALLAH'ın size açıkladığını mı onlara anlatıyorsunuz, akletmez misiniz,\" derler."},{"n":77,"t":"Bilmezler mi ki ALLAH gizledikleri ve açıkladıkları herşeyi biliyor?"},{"n":78,"t":"Aralarında ümmiler*2 var ki kuruntu ve söylentilerin dışında kitabı bilmezler; bildiklerini zannederler."},{"n":79,"t":"Kitab'ı elleriyle yazdıktan sonra onu ucuz bir fiyata satmak için onun ALLAH'tan olduğunu söyleyenlerin vay haline. Ellerinin yazdığından dolayı vay haline onların. Kazandıklarından dolayı vay haline onların!"},{"n":80,"t":"\"Sayılı birkaç gün dışında ateş bize değmeyecek,\" dediler. De ki: \"ALLAH'tan böyle bir söz mü aldınız -ki ALLAH verdiği sözden dönmez- yoksa ALLAH adına bilmediğiniz bir şeyi mi söylüyorsunuz?\""},{"n":81,"t":"Günah işleyip suçu kendisini kuşatan kimseler ateş halkıdır; orada sürekli kalırlar."},{"n":82,"t":"İnanıp erdemli bir hayat sürenler ise cennet halkıdır; onlar da orada sürekli kalırlar. İsrailoğullarıyla Sözleşme"},{"n":83,"t":"İsrailoğullarından şöyle söz almıştık: ALLAH'tan başkasına tapmayacak, anaya babaya, yakınlara, yetimlere ve yoksullara iyilik edeceksiniz. İnsanlarla dostça konuşacaksınız. Namazı gözetecek, zekatı vereceksiniz. Fakat bundan sonra pek azınız hariç döndünüz."},{"n":84,"t":"Birbirinizin kanını dökmeyeceksiniz ve birbirinizi yurtlarından çıkarmıyacaksınız diye de sizden söz almıştık. Bunu kabul etmiş ve tanık olmuştunuz."},{"n":85,"t":"Tüm bunlardan sonra, sizler hala birbirinizi öldürüyor, aranızdan bir grubu yurtlarından çıkarıyor, kötülük ve düşmanlıkta onlara karşı birleşiyorsunuz. Onları yurtlarından çıkarmanız zaten size haramken, bu yetmiyormuş gibi size esir düştüklerinde bir de onlardan fidye istiyorsunuz. Yoksa siz kitabın bir kısmına inanıp bir kısmını inkar mı ediyorsunuz? Böyle davrananların cezası dünya hayatında rezil olmak ve Diriliş Gününde de azabın en çetinine uğratılmaktan başka ne olabilir? ALLAH yaptıklarınızdan gafil değil."},{"n":86,"t":"Onlar, ahiret karşılığında dünya hayatını satın alan kimselerdir. Bu yüzden azapları hafifletilmez ve kendilerine yardım edilmez. İsrailoğullarına Gönderilen Elçiler ve Fanatism"},{"n":87,"t":"Musa'ya kitabı verdik ve ondan sonra ard arda elçiler gönderdik. Meryemoğlu İsa'ya da apaçık deliller verdik ve onu Kutsal Ruh ile destekledik. Hoşunuza gitmeyen bir şeyle ne zaman size bir elçi geldiyse büyüklük taslayarak onu yalanlamadınız mı veya öldürmediniz mi?"},{"n":88,"t":"Hatta \"Sabit fikirliyiz,\" dediler. Halbuki, inkarlarından dolayı ALLAH onları lanetlemişti! Bu yüzden onların pek azı inanır. Kuran, Önceki Kitapları Onaylayıp Tamamlar"},{"n":89,"t":"İnkarcılara karşı yardım beklemelerine rağmen, onlara ALLAH katından yanlarındakini doğrulayıcı bir kitap, bu bekledikleri şey, kendilerine gelince onu inkar ettiler. ALLAH'ın laneti, inkarcılara olsun!"},{"n":90,"t":"ALLAH'ın, lütfunu kullarından dilediğine indirmesini çekemiyerek ALLAH'ın indirdiğini inkar etmek için kişiliklerini satmaları ne kötü! Böylece gazap üstüne gazaba uğradılar. Kafirlere alçaltıcı bir azap var."},{"n":91,"t":"Kendilerine, \"ALLAH'ın indirdiğine inanın!,\" denildiğinde, \"Bize indirilene inanırız,\" diyerek ondan sonrasını inkar ederler. Oysa bu, yanlarında bulunanı doğrulayan gerçektir. \"İnanmış idiyseniz, neden daha önce ALLAH'ın peygamberlerini öldürüyordunuz,\" de. İsrailoğullarının Tarihinden Dersler"},{"n":92,"t":"Musa, size mucizelerle gelmişti; fakat onun ardından buzağıyı tanrı edinerek zalimlerden oldunuz."},{"n":93,"t":"Hani üzerinize Tur dağını kaldırıp sizden söz almıştık: \"Size verdiğim emirlere sıkıca sarılın ve dinleyin.\" Fakat \"Dinledik ve karşı geldik,\" dediler. İnkarlarından dolayı kalpleri buzağı ile kandı. De ki: \"İnanmışsanız, inancınız size ne de kötü yön veriyor!\""},{"n":94,"t":"De ki: \"İleri sürdüğünüz gibi, ahiret yurdu ALLAH tarafından hiçkimseye değil sadece size ayrılmışsa ve bu savınızda samimi iseniz haydi ölümü isteyin!\""},{"n":95,"t":"Ellerinin işlediklerinden ötürü bunu asla dilemeyeceklerdir. ALLAH zalimleri bilir."},{"n":96,"t":"Onları, yaşamaya en düşkün insanlar olarak bulacaksın; putperestlerden bile fazla... Onlardan herbiri bin sene yaşamak ister. Oysa, uzun yaşaması onu azaptan uzaklaştırmaz. ALLAH yaptıklarını görendir."},{"n":97,"t":"Şunu de: \"Kendinden öncekileri doğrulayıcı, inananlara yol gösterici ve müjde olarak ALLAH'ın izniyle bunu kalbine indiren Cibril'e her kim düşman olursa,"},{"n":98,"t":"\"Evet, ALLAH'a, meleklerine, elçilerine, Cibril'e ve Mikal'e kim düşman olursa bilsin ki ALLAH da kafirlerin düşmanıdır.\""},{"n":99,"t":"Sana apaçık ayetler indirmekteyiz. Yoldan çıkmış olanlardan başkası onları inkar etmez. 100. Her ne zaman bir anlaşma yaptılarsa onlardan bir grup onu bozup atmadı mı? Zaten onların çoğu inanmaz. 101. Yanlarındakini doğrulayan bir elçi ALLAH tarafından görevli olarak kendilerine gelince, kitap verilenlerin bazısı, ALLAH'ın kitabını sırtlarının ardına attı. Bilmezlermiş gibi... Büyücülük Kınanıyor 102. Süleyman'ın otoritesi hakkında şeytanların anlattığına uydular. Oysa Süleyman inkar etmedi; halka büyücülüğü ve Babil'de Harut ve Marut adlı iki meleğe indirileni öğreten şeytanlar inkar etmişti. Bu ikisi: \"Bu bir sınavdır, (bu bilgiyi kötüye kullanıp) nankör olmayın!,\" demedikçe kimseye onu öğretmezlerdi. Fakat o ikisinden öğrendiklerini, koca ile karısının arasını açmak için kullandılar. Oysa ALLAH'ın izni olmadan onlar hiç kimseye bir zarar veremezdi. Kendilerine yarar vereni değil, zarar vereni öğreniyorlardı.*3 Üstelik, ona müşteri olanların ahirette bir payı olmadığını da iyi biliyorlardı. Karşılığında kişiliklerini sattıkları şey ne kötü. Bir bilselerdi! * 2:102 Büyücülüğün gerçek niteliği için bak 7:116-117. 103. Onlar inanıp günahlardan sakınmış olsalardı elbette ALLAH'tan alacakları ödül çok daha hayırlı olurdu. Bir bilselerdi! 104. İnananlar! \"Raina (bize çobanlık et),\" demeyin; \"Unzurna (bizi gözet),\" deyin ve dinleyin. İnkarcılar için acı bir azap var."}]},{"id":3,"name":"İMRAN AİLESİ (AL-İ İMRAN) SÛRESİ","verses":[{"n":1,"t":"A.L.M."},{"n":2,"t":"ALLAH: O'ndan başka tanrı yoktur; Diridir, Gözetendir."},{"n":3,"t":"Sana bu kitabı, kendisinden öncekileri onaylayıcı olarak gerçekle indirdi. Tevrat'ı ve İncil'i de indirdi,"},{"n":4,"t":"Bundan önce insanlara yol gösterici olarak... Yasalar kitabını indirdi. ALLAH'ın ayetlerini inkar edenlere çetin bir azap vardır. ALLAH Üstündür, Öc Alandır."},{"n":5,"t":"Yerde ve gökte hiçbir şey ALLAH'a gizli kalmaz."},{"n":6,"t":"Rahimlerde size dilediği şekilde biçim veren O'dur. O'ndan başka tanrı yoktur; Üstündür, Bilgedir. Çok Anlamlı Ayetler: Bilgi ve Dürüstlük Düzeyini Sınayan Noktalar"},{"n":7,"t":"O ki sana bu kitabı indirdi. Onun bazı ayetleri kesin anlamlıdır (muhkem), ki bunlar kitabın özüdür. Diğerleri de benzer anlamlıdır (müteşabih). Kalplerinde hastalık bulunanlar, insanları şaşırtmak ve farklı anlam vermek için benzer anlamlı olanlarının ardına düşerler. Onların gerçek anlamını ise kimse bilmez, ancak istisnadır ALLAH ve derin bilgiye sahip olanlar \"Ona inandık, hepsi Rabbimiz katındandır,\" derler. Akıl ve anlayış sahiplerinden başkası öğüt almaz."},{"n":8,"t":"\"Rabbimiz, bizi doğruya ulaştırdıktan sonra kalplerimizin eğrilmesine izin verme. Üzerimize rahmetini yağdır; kuşkusuz sen Bağışta Bulunansın.\""},{"n":9,"t":"\"Rabbimiz, gerçekleşmesi kuşku gütürmeyen günde insanları toplayacak olan sensin.\" ALLAH sözünden dönmez. İnkarcılar: Sonunda Kaybederler"},{"n":10,"t":"İnkarcıların ne paraları ne de çocukları ALLAH'a karşı hiç bir yarar sağlamaz. Onlar ateşin yakıtıdır."},{"n":11,"t":"Firavun'un halkı veya onlardan öncekilerin durumu gibi... Ayetlerimizi (vahiy ve mucizelerimizi)*18 yalanladılar ve ALLAH da onları suçüstü yakaladı. ALLAH'ın cezalandırması şiddetlidir."},{"n":12,"t":"İnkarcılara şunu söyle: \"Yenilecek ve cehenneme sürüleceksiniz.\" Ne kötü bir konuttur. İnananlar: Sonunda Kazanırlar"},{"n":13,"t":"Karşılaşan iki orduda sizin için bir ders var. Ordulardan birisi ALLAH yolunda savaşırken diğeri de inkarcı idi. Onları (inananları), gözleriyle kendilerinin iki katı olarak görüyorlardı. ALLAH dilediğini zaferle destekler. Bunda görüş sahipleri için bir ibret vardır."},{"n":14,"t":"Kadınları, çocukları, yığınlarla altın ve gümüşü, eğitilmiş atları, davarları ve ekinleri sevmek gibi zevkler insanlara alımlı görünür. Bunlar dünya hayatının nimetleridir. Oysa gidilecek en güzel yer ALLAH katındadır."},{"n":15,"t":"De ki: \"Bundan daha iyisini size haber vereyim mi? Erdemliler için Rab'lerinin yanında altlarından ırmaklar akan, içinde sonsuz kalacakları cennetler (bahçeler), tertemiz eşler ve ALLAH'ın onayını kazanmaktan dolayı mutluluk vardır.\" ALLAH kulları görür."},{"n":16,"t":"Onlar ki: \"Rabbimiz, biz inandık, günahlarımızı bağışla ve bizi cehennem azabından koru,\" derler."},{"n":17,"t":"Onlar, sabredenlerdir, doğru sözlülerdir, gönülden teslim olanlardır, insanlara yardım edenler ve seherlerde bağışlanma dileyenlerdir. İslam'ın Temel İlkesi"},{"n":18,"t":"ALLAH, kendisinden başka tanrı olmadığına şehadet eder; melekler ve adaleti gözeten ilim sahipleri de... O'ndan başka tanrı yoktur. Üstündür, Bilgedir."},{"n":19,"t":"ALLAH tarafından onaylanan biricik din, Teslim Olmak (islam) dır. Kitap verilmiş olanlar, kendilerine bilgi geldikten sonra sırf aralarındaki kıskançlık yüzünden anlaşmazlığa düştüler. ALLAH'ın ayetlerini inkar edenler için ALLAH hesabı çabuk görür. * 3:19 İslam dini bir özel isim olmayıp, insanlık tarihi boyunca Allah'a teslim olanların sahip olduğu paradigmadır. İslam dini evrenseldir (3:83), tek geçerli dindir (3:85), ırkları birleştiricidir (49:13), ulusları barıştırıcıdır (2:62; 2:135-136), herkese adaleti vadeder (5:8), kişisel deneyimin ötesinde objektif delil gerektirir (3:86; 2:111; 21:24; 74:30), korunmuş ve matematiksel olarak kodlanmış bir kitaba sahiptir (15:9; 2:23), barış ve realiteyi savunur (60:8-9), aracılar ve ruhbanlar tanımaz (2:48, 9:31, 34), servet dağılımını teşvik eder (59:7), üretimsiz ekonomiye tolerans göstermez (5:90; 3:130), toplumsal işlerin yürütülmesinde danışmayı gerekli görür (42:38), kişiye büyük değer verir (5:32), kadına değer verir (3:195; 4:124; 16:97), doğa ve çevre ile harmony içinde olmamızı ister (30:41); ögrenmede metot olarak akıl ve deneyi kullanır (17:36).... Kısacası, islam, evren'deki fiziksel yasalara ve onların dayattığı sosyal kurallara uygun bir yaşam sürmek ve evrenin yaratıcısına gönülden teslim olmaktır."},{"n":20,"t":"Seninle tartışırlarsa, \"Ben ve beni izleyenler kendimizi ALLAH'a teslim ettik,\" de. Kitap verilenlere ve kitap verilmeyenlere (ümmilere), \"Teslim oldunuz mu,\" de. Teslim olurlarsa, doğruyu bulurlar. Yüz çevirirlerse, görevin sadece duyurmaktır. ALLAH kulları görür."},{"n":21,"t":"ALLAH'ın ayetlerini inkar edenlere, haksız yere peygamberleri öldürenlere ve halkın arasında adaleti savunanları öldürenlere acıklı bir azabı müjdele."},{"n":22,"t":"Onlar, dünya ve ahirette yaptıkları boşa çıkanlardır. Onlara yardım eden de olmayacak."},{"n":23,"t":"Kitaptan kendilerine bir pay verilmiş olanlara baksana, aralarında hükmetmeleri için ALLAH'ın kitabına çağrılıyorlar da onlardan bir grup yüz çevirip geri dönüyor."},{"n":24,"t":"Çünkü onlar, \"Cehennem sayılı bir kaç günün dışında bize dokunmayacak,\" dediler. Uydurdukları şeyler onları dinlerinde böylece yanıltmıştır."},{"n":25,"t":"Herkese kazandığının karşılığı haksızlık yapılmadan ödeneceği, gerçekleşmesinde kuşku olmayan o gün için onları topladığımızda halleri nice olacak? Mutlak Yönetici"},{"n":26,"t":"De ki: \"Yöneticilerin Yöneticisi olan Tanrım, yönetimi dilediğine verir, dilediğini de yönetimden indirirsin. Dilediğini yükseltir, dilediğini de alçaltırsın. Tüm iyilikler senin elinde. Sen her şeye gücü yetensin!\" * Bak 57:22-23."},{"n":27,"t":"\"Geceyi gündüze katarsın, gündüzü de geceye katarsın. Diriyi ölüden çıkarırsın, ölüyü de diriden çıkarırsın. Dilediğini hesapsız rızıklandırırsın.\" Arkadaşlarınızı Dikkatle Seçin"},{"n":28,"t":"İnananlar, inananları bırakıp inkarcıları dost edinmesin. Kim bunu yaparsa ALLAH ile bir ilgisi kalmaz. Ancak onlardan korkmanız hali başka... ALLAH kendisi hakkında sizi uyarıyor. Dönüş ALLAH'adır."},{"n":29,"t":"De ki, \"İçinizdeki düşüncelerinizi ister gizleyin, ister açıklayın, ALLAH bilir.\" Göklerde ve yerde olan her şeyi bilir. ALLAH'ın gücü herşeye yeter."},{"n":30,"t":"Gün gelecek, her kişi yaptığı her iyiliği önünde hazır bulacaktır. İşlediği her kötülük ile kendisi arasında uzun bir mesafe olmasını isteyecek. ALLAH kendisi hakkında sizi uyarıyor. ALLAH kullara şefkatlidir."},{"n":31,"t":"De ki, \" ALLAH'ı seviyorsanız beni izleyin ki ALLAH da sizi sevsin ve günahlarınızı bağışlasın. ALLAH Bağışlayandır, Rahimdir.\""},{"n":32,"t":"\"ALLAH'a ve elçiye itaat edin,\" de. Yüz çevirirlerse, elbette ALLAH inkarcıları sevmez."},{"n":33,"t":"ALLAH Adem'i, Nuh'u, İbrahim ailesini ve İmran ailesini halkların arasından (elçi olarak) seçti."},{"n":34,"t":"Birbirlerinin soyundan olarak... ALLAH İşitir, Bilir."},{"n":35,"t":"İmran'ın karısı demişti ki: \"Rabbim, karnımdaki (bebeği) tamamiyle sana adadım, adağımı kabul buyur. Sen İşitensin, Bilensin.\""},{"n":36,"t":"Onu doğurunca, \"Rabbim, onu kız doğurdum,\" dedi -ALLAH onun ne doğuracağını biliyordu- \"Erkek kız gibi değil. Ona Meryem adını verdim. Onu ve soyunu, kovulmuş şeytandan koruman için sana yalvarırım.\""},{"n":37,"t":"Rabbi, adağını güzel bir şekilde kabul etti ve onu Zekeriya'nın himayesinde güzel bir çiçek gibi yetiştirdi. Zekeriya, tapınakta onun yanına her girişinde yanında yiyecekler bulurdu. \"Meryem, bunlar sana nereden geliyor,\" diye sorduğunda, \"Bu, ALLAH katındandır. ALLAH dilediğini hesapsız rızık verir,\" derdi. Yahya'nın Doğumu"},{"n":38,"t":"Zekeriyya oracıkta Rabbine dua etti: \"Rabbim,\" dedi, \"katından bana tertemiz bir soy ver, Sen duaları işitensin.\""},{"n":39,"t":"Tapınakta durmuş namaz kılıyorken melekler ona, \"ALLAH seni, ALLAH'ın Sözünü doğrulayacak, onurlu, iffetli ve erdemli bir peygamber olan Yahya ile müjdeliyor,\" diye seslendiler."},{"n":40,"t":"\"Rabbim, ben yaşlı ve karım kısırken nasıl olur da bir oğlum olur,\" deyince, o, \"Evet; ama ALLAH dilediğini yapar,\" dedi."},{"n":41,"t":"\"Rabbim, bana bir alamet ver,\" dedi. \"Alametin, üç gün işaretle anlaşmanın dışında halk ile konuşmamandır. Rabbini çokça an, akşam sabah onu düşün.\""},{"n":42,"t":"Melekler şöyle demişti: \"Meryem, ALLAH seni seçip arındırdı; seni tüm kadınların üzerine seçti."},{"n":43,"t":"\"Meryem, Rabbine teslim ol, secdeye kapan, eğilenlerle birlikte eğil.\""},{"n":44,"t":"Bunlar, sana vahyettiğimiz gayb haberlerindendir. Meryem'e hangisi kefil olacak diye zar atarlarken sen onların yanında değildin; çekiştikleri zaman da sen onların yanında değildin."},{"n":45,"t":"Melekler demişti ki: \"Meryem, ALLAH seni kendisinden bir Söz ile müjdeliyor. Onun adı Meryem oğlu İsa Mesih'dir. Dünyada da ahirette de önderlerdendir ve (Tanrı'ya) yakın olanlardandır."},{"n":46,"t":"\"Beşikteyken de büyüyünce de insanlarla konuşacak ve iyilerden olacak.\""},{"n":47,"t":"(Meryem), \"Rabbim! Bana bir beşer dokunmamışken nasıl olur da çocuğum olur,\" deyince, (Melek) şöyle cevap verdi: \"ALLAH dilediğini böyle yaratır. Herhangi bir şeyin olmasını dilediği an ona 'Ol' der ve o şey oluverir."},{"n":48,"t":"\"Ona kitabı, bilgeliği, Tevrat'ı ve İncil'i öğretecek."},{"n":49,"t":"\"İsrailoğullarına gönderilen bir elçi olarak (diyecek ki): 'Ben size, Rabbinizden bir kanıt ile geldim. Size balçıktan kuş heykeli yapıp ona üflerim ve ALLAH'ın izniyle bir kuş oluverir. ALLAH'ın izniyle körü ve cüzzamlıyı iyileştirir, ölüyü diriltirim. Ne yediğinizi ve evlerinizde neler biriktirdiğinizi size bildirebilirim. İnanacaksanız bu kanıtlar sizin için yeterlidir."},{"n":50,"t":"\" 'Benden önceki Tevrat'ı doğrulamak ve size haram edilen bazı şeyleri helal etmek için gönderildim. Size Rabbinizden bir kanıt getirdim. ALLAH'ı dinleyin ve beni izleyin."},{"n":51,"t":"\" ' ALLAH benim de Rabbim, sizin de Rabbiniz;*19 O'na kulluk edin. Budur doğru yol.'\""},{"n":52,"t":"İsa onlardan inkarcı bir tavır sezince, \"ALLAH yolunda kim bana yardımcı olacak,\" dedi. Öğrencileri, \"Biz ALLAH'ın yardımcılarıyız; ALLAH'a inandık. Müslüman oluşumuza tanık ol,\" diye karşılık verdiler."},{"n":53,"t":"\"Rabbimiz, indirdiğine inandık ve elçiye uyduk, bizi tanıklar listesine yaz!\" İsa'nın Ölümü*"},{"n":54,"t":"Tuzak kurdular, ALLAH da tuzak kurdu. ALLAH tuzak kuranların en iyisidir."},{"n":55,"t":"ALLAH İsa'ya şöyle demişti: \"Senin dünyadaki hayatına son vereceğim ve kendime yükselteceğim. Seni inkar edenlerden kurtaracağım ve sana uyanları Diriliş Gününe kadar inkar edenlerin üzerinde tutacağım. Sonra, dönüşünüz banadır ve anlaşmazlığa düştüğünüz konularda aranızda ben hüküm vereceğim.\""},{"n":56,"t":"\"Kafirleri ise dünyada ve ahirette şiddetli bir şekilde cezalandıracağım; yardımcıları da olmayacak.\""},{"n":57,"t":"İnanıp erdemli bir hayat sürenlere gelince, ödüllerini tam olarak ödeyecek. ALLAH zalimleri sevmez."},{"n":58,"t":"Sana bu okuduklarımız, ayetlerden ve hikmetli mesajdandır."},{"n":59,"t":"ALLAH'a göre İsa'nın örneği, Adem'in örneği gibidir;*20 topraktan biçimlendirdikten sonra ona \"Ol,\" dedi ve o da oldu."},{"n":60,"t":"Bu, Rabbinden gelen gerçektir; kuşkulananlardan olma."},{"n":61,"t":"Sana gelen bu bilgiden sonra her kim bu konuda seninle tartışırsa, de ki: \"Gelin, çocuklarımızı, çocuklarınızı, kadınlarımızı, kadınlarınızı çağırarak bizlerle sizler bir araya gelelim ve sonra ALLAH'ın lanetinin yalancıların üzerine olması için lanetleşelim."},{"n":62,"t":"İşte, söylentilerin gerçeği bu. ALLAH'tan başka hiç bir tanrı yoktur ve elbette ALLAH Güçlüdür, Bilgedir."},{"n":63,"t":"Yüz çevirirlerse, elbette ALLAH bozguncuları bilir. Birleştirici Ortak İlkeye Çağrı"},{"n":64,"t":"De ki, \"Kitaplılar! Bizimle sizin aranızda aynı olan bir ilkeye geliniz: ALLAH'tan başkasına kulluk etmeyelim ve O'na hiçbir şeyi ortak koşmayalım, birimiz diğerini ALLAH'tan sonra rabler edinmesin.\" Kabul etmezlerse, \"Şahit olun, biz müslümanlarız!,\" deyin. İbrahim"},{"n":65,"t":"Ey kitap halkı, neden İbrahim hakkında tartışıp duruyorsunuz? Oysa İncil de Tevrat da ondan sonra indirildi. Aklınızı kullanmaz mısınız?"},{"n":66,"t":"Bilgi sahibi olduğunuz konularda tartışıp duruyorsunuz! Peki hakkında hiç bir bilgiye sahip olamadığınız bir konuda nasıl tartışabiliyorsunuz? Siz bilmeyebilirsiniz; ama ALLAH bilir."},{"n":67,"t":"İbrahim ne Yahudi idi ne de Hıristiyan; tektanrıcı bir müslümandı. Hiç bir zaman ortak koşanlardan olmadı."},{"n":68,"t":"İnsanların İbrahim'e en yakın olanları, onu izleyenler, bu peygamber ve inananlardır. ALLAH inananların egemeni ve dostudur."},{"n":69,"t":"Kitap halkından bir grup sizi saptırmak ister. Onlar sadece kendilerini saptırıyor. Farkında bile değiller."},{"n":70,"t":"Kitap halkı! Tanık olduğunuz halde neden ALLAH'ın ayetlerini inkar ediyorsunuz?"},{"n":71,"t":"Kitap halkı! Neden doğru ile yanlışı birbirine karıştırıyor ve bile bile gerçeği gizliyorsunuz?"},{"n":72,"t":"Kitap halkından bir grup dedi ki: \"İnananlara indirilmiş olana gündüzün başında inanın ve sonunda inkar edin. Böylece belki dinlerinden dönerler.\""},{"n":73,"t":"\"Sizin dininize uyandan başkasına uymayın.\" Sen de onlara, \"Hidayet ALLAH'ın hidayetidir,\" de. \"Size verilenin benzerininin bir başkasına verildiğine de inanmayın; yoksa Rabbiniz hakkında sizinle tartışma hakkı kazanırlar,\" derlerse, \"Lütuf ALLAH'ın elindedir, dilediğine verir,\" de. ALLAH Cömerttir, Bilendir."},{"n":74,"t":"Rahmetini dilediğine özgü kılar. ALLAH Büyük Lütuf Sahibidir. Herkese Karşı Dürüst Ol"},{"n":75,"t":"Kitap halkından öylesi var ki kendisine yığınla emanet bıraksan sana aynen öder. Fakat onlardan öylesi de var ki kendisine bir Dinar emanet etsen, başına dikilip durmadıkça geri ödemez. \"Ümmilere karşı bizim bir sorumluluğumuz yok\"*21 dedikleri için böyle davranıyorlar ve bile bile yalanlarını ALLAH'a yakıştırıyorlar."},{"n":76,"t":"Kim sözünü yerine getirir ve erdemli bir yaşam sürerse, bilsin ki ALLAH erdemlileri sever."},{"n":77,"t":"ALLAH'a verdikleri sözü ve yeminlerini az bir fiyata değişenlerin ahirette bir payları yoktur. ALLAH onlarla konuşmaz, Diriliş Gününde onlara bakmaz ve onları arındırmaz. Onlar için acıklı bir azap var. Tanrı'nın Kitabına \"Ayet\" Eklemek İsteyenler"},{"n":78,"t":"Onların bazısı, kitapta olmayanı kitaptan sanasınız diye dillerini bükerek kitabı taklit eder ve ALLAH katından olmadığı halde, \"Bu ALLAH katındandır,\" derler. Bile bile, ALLAH adına yalan söylerler."},{"n":79,"t":"ALLAH'ın kendisine kitap, bilgelik ve peygamberlik verdiği hiç bir insan, \"ALLAH'tan sonra bana da kulluk ediniz,\" diye halkı kendisine çağırmaz. Aksine, \"Öğrenip öğrettiğiniz kitap gereğince kendisini Rabbine adayan kullar olun,\" der."},{"n":80,"t":"Ve size, melekleri ve peygamberleri rabler edinmenizi de emretmez. Siz müslüman olduktan sonra, size hiç inkarı emreder mi?"},{"n":81,"t":"ALLAH peygamberlerden (nebilerden) şöyle misak almıştı: \"Size kitap ve hikmet vereceğim. Daha sonra, beraberinizdekileri doğrulayan bir elçi (resul) geldiğinde ona inanacak ve onu destekleyeceksiniz. Bunu kabul ettiniz mi ve bu sözleşmeyi yerine getireceğinize söz verdiniz mi,\" demişti. Onlar \"Kabul ettik,\" deyince, \"Öyleyse şahid olun, ben de sizinle beraber şahid olanlardanım,\" demişti."},{"n":82,"t":"Bundan sonra kim dönerse yoldan çıkmıştır."},{"n":83,"t":"ALLAH'ın dininden başkasını mı arıyorlar? Oysa göklerde ve yerde ne varsa ister istemez O'na teslim olmuştur ve hepsi O'na döndürülecektir. Peygamberler Arasında Ayırım Yapmayınız"},{"n":84,"t":"De ki: \"ALLAH'a, bize indirilene, İbrahim'e, İsmail'e, İshak'a, Yakub'a ve torunlara indirilene; Musa'ya, İsa'ya ve peygamberlere Rab'leri tarafından verilene inandık. Onların hiçbiri arasında ayırım yapmayız ve biz O'na teslim olanlarız.\" Sadece Bir Tek Din: Tanrı'ya Teslim Olmak"},{"n":85,"t":"Kim islamdan (Tanrı'ya teslim olmaktan) başka bir din ararsa kendisinden kabul edilmeyecek ve o ahirette kaybedenlerden olacaktır."},{"n":86,"t":"İman ettikten, elçinin doğru olduğuna tanık olduktan ve kendilerine açık deliller geldikten sonra, inkar eden bir toplumu, ALLAH nasıl olur da doğruya iletir? ALLAH zalim toplumu hidayete ulaştırmaz."},{"n":87,"t":"Onlar, ALLAH'ın, meleklerin ve insanların toplu lanetini hakketmişlerdir."},{"n":88,"t":"Orada sürekli kalıcıdırlar; azapları hafifletilmez ve kendilerine bakılmaz."},{"n":89,"t":"Ancak, bundan sonra yönelip durumlarını düzeltenler başka. ALLAH Bağışlayandır, Rahimdir. Tevbenin Geçersiz Olduğu Durum"},{"n":90,"t":"İmanlarından sonra inkar edip de inkarlarında ileri gidenlerin tevbeleri kabul edilmez; onlar artık tümüyle sapmış demektir."},{"n":91,"t":"İnkar edip inkarcı olarak ölenler, dünya dolusu altını fidye olarak verseler dahi kendilerinden kabul edilmeyecektir. Onlar acıklı bir azabı hakkettiler ve hiç bir yardımcıları da olmayacak. İyilik Yapmanın Kriteri"},{"n":92,"t":"Sevdiğiniz şeylerden ekonomik yardım olarak vermedikçe erdemli bir kişi olamazsınız. Her neyi verirseniz ALLAH mutlaka onu bilir. Yasal Maddeleri Yasaklamayın"},{"n":93,"t":"Tevrat indirilmeden önce İsrail kendisine haram kılıncaya kadar İsrailoğullarına tüm yiyecekler helal idi. \"Doğru sözlülerseniz Tevrat'ı getirip okuyun,\" de."},{"n":94,"t":"Artık kim yalanları ALLAH'a yakıştırırsa, işte zalimler onlardır."},{"n":95,"t":"De ki: \"ALLAH doğruyu söyler; İbrahim'in tektanrıcı dinine uyun. O puta tapanlardan olmadı.\" Halkevi"},{"n":96,"t":"Halk için kurulan en önemli ev, tüm halklara bir hidayet kaynağı olan Bekke'deki kutlu evdir.*22"},{"n":97,"t":"Orada apaçık işaretler var: İbrahim'in (putperestliğe karşı) duruş yeridir. Oraya giren güvenlik içinde olmalı. Halktan yolculuğa gücü yetenler o Ev'i (Kabeyi) ALLAH için haccetmekle yükümlüdür. Kim inkar ederse bilsin ki ALLAH kimseye muhtaç değildir."},{"n":98,"t":"De ki, \"Kitap halkı, ALLAH yaptıklarınıza tanıkken neden ALLAH'ın ayetlerini tanımıyorsunuz?\""},{"n":99,"t":"De ki, \"Kitap halkı, doğruya tanık olduğunuz halde neden ALLAH'ın yolunu değiştirmeye yeltenerek inananları saptırıyorsunuz? ALLAH yaptıklarınızdan habersiz değildir.\" 100. İnananlar! Kitap halkından bir kısmına uyarsanız iman etmenizden sonra sizi inkarcılığa döndürürler. 101. ALLAH'ın ayetleri size okunduğu ve O'nun elçisi aranızda olduğu halde nasıl olur da inkar edersiniz? Kim ALLAH'a sarılırsa dosdoğru yola iletilmiştir. 102. İnananlar! ALLAH'ı gereğince dinleyin ve müslümanlar (Tanrı'ya teslim olanlar) olarak ölmeye bakın. İnananlar Birliktirler 103. ALLAH'ın ipine topluca sımsıkı sarılın; ayrılığa düşmeyin. ALLAH'ın size olan nimetini anımsayın. Siz birbirinize düşmanlar idiniz de kalplerinizi birleştirdi ve O'nun nimeti sayesinde kardeşler oldunuz. Bir ateş çukurunun kenarında idiniz, sizi ondan kurtardı. Yola gelesiniz diye ALLAH ayetlerini böyle açıklıyor. 104. İçinizde, iyiliğe çağıran, sağduyuyu öğütleyen ve kötülükten sakındıran bir topluluk olsun. Bunlar başaranlardır. Mezhep ve Tarikatlara Bölünmeyin 105. Kendilerine apaçık deliller geldikten sonra ayrılık ve anlaşmazlığa düşenler gibi olmayınız. Onlar için büyük bir azap var."}]},{"id":4,"name":"KADIN (NİSA) SÛRESİ","verses":[{"n":1,"t":"İnsanlar! Sizi bir tek nefisten yaratan, ondan da eşini yaratan, ikisinden pek çok erkek ve kadın üreten*23 Rabbinizi dinleyin. Adına birbirinizden isteklerde bulunduğunuz ALLAH'a saygı gösterin; akrabalara da... ALLAH elbette sizi Gözetlemektedir."},{"n":2,"t":"Yetimlere mallarını verin. Temiz olanı pis olanla değişmeyin. Mallarını kendi mallarınıza katıp yemeyin. Bu büyük bir adaletsizlik olur."},{"n":3,"t":"Yetimler hakkında adaletli davranamamaktan korkuyorsanız uygun gördüğünüz kadınlarla ikişer, üçer, dörder evlenebilirsiniz. Onlara eşit davranamamaktan korkuyorsanız bir taneyle veya yeminlerinizin/anlaşmalarınızın hak sahibi olduklari ile yetinin. Sapmamanız için en uygunu budur.* * 4:3 4:3, 24-25, 36 ve 24:33, 58 ayetlerinde gecen \"ma meleket eymanukum\" ifadesini \"Yeminlerinizin / anlaşmalarınızın hak sahibi oldukları\" biçiminde çevirmeliyiz. Zira \"eYMaN\" kelimesi \"YeMYN\" kelimesinin çoğulu olup, çoğul biçimiyle Kuran boyunca \"sözler /anlaşmalar anlamında kullanılır (Bak: 4:33 5:89; 9:12; 16:91; 2:224-225; 16:92, 94; 30:28; 66:2; 5:53; 6:109;....). Kuran'daki bu kullanılışa bakılınca EYMAN kelimesinin \"sağ el\" anlamına gelen \"YeMYN\" kelimesinin çoğulu olarak kullanılMAdığına tanık oluyoruz. Tıpkı \"AYET\" kelimesinin tekili ve çoğulu arasında yapılan fark gibi. İslam'a girmeden önce veya cahiliyye dönemindeyken nikah kıymadan birlikte hayat yaşayan insanlar bu ifadede anlatılan sınıfa girer. Kuran, bu müslüman olmaya karar verdikten sonra bu insanların aralarındaki yemini ve anlaşmayı bozup birbirlerinden ayrılmalarını istemiyor. İki kız kardeşle evlenmiş olanların da bu hatayı işledikten sonra ayrılmalarını istemediği gibi... (4:23). Ortada nikahsız birlikteliğe bir teşvik yok. Sadece mevcut bir problemi daha da büyütmemek ve insanların müslüman olmalarının önüne engeller çıkarmamak amacını gütmektedir."},{"n":4,"t":"Kadınlara mehirlerini tam verin. Kendi istekleriyle o mehrin bir kısmını size bağışlarlarsa onu günül huzuruyla yiyebilirsiniz."},{"n":5,"t":"ALLAH'ın sizi gözetici kıldığı mallarınızı aklı ermezlere vermeyin. O mallarla onları (yetimleri) besleyin, giydirin ve onlarla güzel iletişim kurun."},{"n":6,"t":"Evlenme yaşına eriştiklerinde yetimleri sınayın. Onlarda olgunluk görürseniz kendilerine mallarını verin. Onlar büyüyecek diye savurganlık ve aceleyle mallarını yemeyin. Zengin, (malın korumasına gösterdiği çabanın ücretinden) vazgeçsin. Fakir ise uygun bir miktarda harcasın. Mallarını kendilerine tanıklar huzurunda geri verin. Hesap görücü olarak ALLAH yeter. Kadının Miras Hakları"},{"n":7,"t":"Ana babanın ve akrabaların bıraktığından erkeklere bir pay vardır. Ana babanın ve akrabaların bıraktığından kadınlara da bir pay vardır. Miras ister az olsun ister çok olsun (kadın) bir pay almalıdır."},{"n":8,"t":"Miras bölüşümünde, akrabalar, yetimler ve yoksullar da hazır bulunursa güzel sözler söyleyerek onlara da verin. Vasiyeti, Çocuklarınızın Ekonomik Durumunu Gözönünde Bulundurarak Yapın"},{"n":9,"t":"Geriye zayıf çocuklar bırakan ve onların durumlarından endişe duyanlar dikkat etsinler! ALLAH'ı düşünsünler ve uygun kararlar versinler."},{"n":10,"t":"Yetimlerin mallarını haksız yere yiyenler karınlarını ateşle doldurmuş olurlar ve cehennemi boylayacaklar. Vasiyet Yapılmamışsa veya Malın Tümü Dağıtılmamışsa"},{"n":11,"t":"ALLAH size çocuklarınız hakkında öğütte bulunuyor. Erkek, kadının iki katı pay alır. Mirasçılar sadece kadın olup iki kişiden fazla iseler terekenin üçte ikisi onlarındır. Çocuk sadece bir kadınsa terekenin yarısı onundur. Ölen kişi ardında çocuk bırakmışsa, ana ve babasının her birisine altıda bir düşer. Çocuğu yok da kendisine sadece ana ve babası varis oluyorsa bu durumda annesine üçte bir pay düşer. Kardeşi varsa bu durumda annesine altıda bir düşer. Tüm bu paylaşma oranları, ölenin yaptığı vasiyetten ve borçların ödenmesinden sonra gelir. Analarınız, babalarınız ve çocuklarınızdan hangisinin size daha yararlı olduğunu bilemezsiniz. Bu ALLAH'ın yasasıdır. ALLAH Bilendir, Bilgedir."},{"n":12,"t":"Çocukları yoksa, hanımlarınızın bıraktığı mirasın yarısı sizindir. Çocukları var ise, bıraktıklarının dörtte biri sizindir. Bu pay, borçlarının ödenmesinden ve yaptıkları vasiyetteki payların dağıtılmasından sonradır. Çocuklarınız yoksa bıraktığınızın dörtte biri onlarındır. Çocuklarınız varsa, bıraktığınızın sekizde biri onlarındır. Bu pay, borçlarınızın ödenmesinden ve yaptığınız vasiyetteki payların dağıtılmasından sonradır. Miras bırakan erkeğin veya kadının, çocuğu ve eşi olmayıp bir erkek veya bir kız kardeşi var ise bu durumda herbirine altıda bir düşer. Bundan fazla iseler, üçte biri paylaşırlar. Bu paylaşım vasiyetteki payların dağıtılmasından ve borçların ödenmesinden sonra uygulanmalıdır ki kimseye zarar verilmesin. Bu, ALLAH'tan bir vasiyettir. ALLAH Bilir, Şefkatlidir."},{"n":13,"t":"Bunlar ALLAH'ın yasalarıdır. ALLAH'a ve elçisine uyanları içinden ırmaklar akan cennetlere yerleştirir. Orada sürekli kalırlar. Bu, en büyük başarıdır."},{"n":14,"t":"Kim ALLAH'a ve elçisine isyan eder ve yasalarını çiğnerse, onu içinde sürekli kalacağı bir ateşe sokar. Onun için alçaltıcı bir azap var. Sağlık Karantinası"},{"n":15,"t":"Kadınlarınızdan fuhuş yapanlara karşı içinizden dört tanık getirin. Tanıklık ederlerse, onları, ölünceye veya ALLAH onlara bir yol açıncaya kadar evlerde tutun."},{"n":16,"t":"Sizden zina işleyen çifti cezalandırın. Tevbe edip düzelirlerse onlardan vazgeçin. ALLAH yönelişleri kabul edendir, Rahim'dir."},{"n":17,"t":"Cahillik yüzünden bir kötülük işleyen ve hemen ardından tövbe edenlerin tövbesinin kabulu ALLAH'a aittir. ALLAH tövbelerini kabul eder. ALLAH Bilendir, Bilgedir."},{"n":18,"t":"Sürekli kötülük işleyen ve kendilerini ölüm yakalayınca, \"Ben artık tövbe ettim,\" diyenlerin tövbesi geçersizdir. İnkarcı olarak ölenlerin de tövbesi geçersizdir. Onlar için acıklı bir azap var."},{"n":19,"t":"İnananlar! Kadınların mirasına onların isteklerine aykırı olarak mirasçı olmanız sizin için yasal değil. Kendilerine önceden vermiş bulunduğunuz malları onlardan geri almak için onları sıkıştırmayın. Bir fuhuş işlemeleri hali istisna. Onlarla iyi geçinin. Onlardan hoşlanmıyorsanız, olur ki hoşlanmadığınız bir şeye ALLAH çok hayır koymuştur."},{"n":20,"t":"Mevcut eşinizi bırakıp bir başka eşle evlenmek istiyorsanız, birincisine büyük miktarda mal vermişseniz bile ondan hiç bir şeyi geri almayın. Sahtekarlık ve iftira ederek ve günah işleyerek mi geri alacaksınız?"},{"n":21,"t":"Bir zamanlar birbirinizin en yakın içli dışlı dostu olmanıza ve sizden sağlam bir söz almalarına rağmen nasıl olur da onu geri alırsınız? Babaya Saygı"},{"n":22,"t":"Babanızın evlenmiş bulunduğu kadınlarla artık evlenmeyin. Fakat geçmişte yaptığınız bu tip evlilikleri de bozmayın. O davranış büyük bir günahtır, iğrenç ve kötü bir yoldur. Yakın Akrabalarla Evlilik Yasaklanmıştır"},{"n":23,"t":"Size şunlar yasaklandı: Anneleriniz, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz, kardeş kızları, kız kardeş kızları, sizi emziren analarınız, süt bacılarınız, karılarınızın anaları, kendileriyle gerdeğe girdiğiniz karılarınızdan olup evlerinizde bulunan üvey kızlarınız -eğer onlarla gerdeğe girmemişseniz kızlarıyla evlenebilirsiniz-, öz oğullarınızın eşleri ve iki kız kardeşi bir arada almanız... Mevcut evlilikler bu yasanın dışındadır. ALLAH Bağışlayandır, Rahimdir. Karşılıklı Hoşlanma ve Mehir Gerekli"},{"n":24,"t":"Ayrıca yeminlerinizin/anlaşmalarınızın hak sahibi oldukları hariç, evli kadınlar... Bunlar, ALLAH'ın üzerinize farz kıldığı yasalardır. Bunların dışındakiler, iffetli yaşamanız, zina etmemeniz ve mehirleriyle istemeniz koşuluyla size helaldir.* Onlardan hoşlandıklarınıza, bir farz olarak mehirlerini ödeyin. Bu farzı yerine getirirken mehri ayarlamak için karşılıklı anlaşmanızda bir sakınca yoktur. ALLAH Bilendir, Bilgedir."},{"n":25,"t":"Sizden özgür kadınlarla evlenmeye güç yetiremiyenler, inanmış yeminlerinizin/anlaşmalarınızın hak sahibi oldukları ile evlensinler. İnancınızı en iyi bilen ALLAH'tır. Birbirinize eşitsiniz. Sahiplerinin izniyle ve uygun şekilde mehirlerini ödeyerek onlarla nikahlanın. İffetli yaşasınlar, zina etmesinler ve gizli dostlar edinmesinler. Evlilik yoluyla özgürlüklerine kavuştuktan sonra zina yaparlarsa, kendilerine özgür kadınlara verilen cezanın yarısı uygulanmalı.* Bu, günaha girmekten korkanlarınız içindir. Sabrederseniz sizin için daha iyi. ALLAH Bağışlayandır, Rahimdir."},{"n":26,"t":"ALLAH size bunları açıklamak, sizden öncekilerin yoluna sizi iletmek ve kendisine yönelişinize (tövbenize) karşılık vermek ister. ALLAH Bilendir, Bilgedir. Tanrı'nın Merhameti"},{"n":27,"t":"ALLAH sizin kendisine yönelişinize karşılık vermek ister; heva ve heveslerine uyanlar ise sizin büsbütün sapıtmanızı ister."},{"n":28,"t":"ALLAH ise yükünüzü hafifletmek istiyor. Çünkü insan zayıf yaratıldı."},{"n":29,"t":"İnananlar! Birbirinizin malını haksızlık ve hile ile yemeyin; karşılıklı rıza ile yapılan ticaret olursa başka. Birbirinizi öldürmeyin. ALLAH size Rahimdir."},{"n":30,"t":"Kim düşmanlık ve zulüm ile bunu yaparsa onu ateşe göndeririz. Bu, ALLAH'a kolaydır."},{"n":31,"t":"Büyük yasaklardan kaçınırsanız günahlarınızı örter ve sizi onurlu bir girişle kabul ederiz. Erkek ve Kadın Özel Yeteneklerle Donatılmışlardır"},{"n":32,"t":"ALLAH'ın herbirinize bağışladığı yeteneklere imrenmeyin. Erkeklere kazandıklarından bir pay, kadınlara da kazandıklarından bir pay var. ALLAH'tan size lütfunu bağışlamasını isteyin. ALLAH her şeyi Bilir."},{"n":33,"t":"Ananın, babanın, akrabaların ve evlenme yoluyla size akraba olanların bıraktıklarından herbiriniz için paylar ayırdık. Herbirine payını vermelisiniz. Elbette ALLAH her şeye Tanıktır. Erkekler Kadınları Gözetirler"},{"n":34,"t":"Erkekler kadınları gözetirler. Zira ALLAH herbirine farklı yetenekler ve özellikler vermiştir. Nitekim erkekler evin geçiminden sorumludur. Erdemli kadınlar, (Tanrı'nın yasasına) boyun eğer ve ALLAH'ın korumasını emrettiği (onur ve iffetlerini) tek başlarına bile olsalar korurlar. İffetlerinden endişe duyduğunuz kadınlara öğüt verin, yataklarınızı ayırın ve nihayet onları çıkarın.**24 Size itaat ederlerse onlara karşı bir yol aramayın. ALLAH Yücedir, Büyüktür."},{"n":35,"t":"Evli çiftin aralarının açılmasından endişeleniyorsanız, erkeğin ailesinden bir hakem, kadının ailesinden de bir hakem atamalısınız. (Karı ve koca) barışmayı isterlerse ALLAH ikisinin arasını bulur. ALLAH Bilir, Haber alır. Temel Emirler"},{"n":36,"t":"ALLAH'a kulluk edin O'na hicbirşeyi ve kimseyi ortak koşmayın. Ana-babaya, yakınlara, yetimlere, yoksullara, yakın komşuya, uzak komşuya, yanınızdaki arkadaşa, yolcuya ve yeminlerinizin/anlaşmalarınızın hak sahibi olduklarına iyi davranın. ALLAH kendini beğenmiş kibirli kişileri sevmez.*25"},{"n":37,"t":"Bunlar üstelik cimridirler ve halka cimriliği öğütlerler. ALLAH'ın kendi lütfundan onlara verdiğini gizlerler. İnkarcılara acıklı bir azap hazırladık."},{"n":38,"t":"Bunlar, mallarını gösteriş için halka verir. ALLAH'a ve ahiret gününe inanmazlar. Kimin arkadaşı şeytan olmuşsa çok kötü bir arkadaşa sahip olmuştur."},{"n":39,"t":"ALLAH'a ve ahiret gününe inansalardı ve ALLAH'ın kendilerine vermiş olduğu rızıktan yardım olarak harcasalardı ne olurdu? ALLAH onları Bilir. İlahi Adalet"},{"n":40,"t":"ALLAH bir atom ağırlığınca bile haksızlık yapmaz. Aksine iyiliğin karşılığını kat kat verir ve kendi katından büyük bir ödül de verir."},{"n":41,"t":"Her ulusun üzerine bir tanık getirdiğimizde, seni de bunların üzerine tanık olarak getirsek halleri nice olur?"},{"n":42,"t":"İnkar edenler ve elçiye karşı gelenler o gün yerle bir olmak isterler. ALLAH'tan hiç bir söz gizleyemezler. Abdesti Bozanlar ve Teyemmüm"},{"n":43,"t":"İnananlar! Sarhoşken, ne dediğinizi bilinceye kadar, yolcu olanlar hariç cinsel ilişkiden sonra yıkanıncaya kadar namaza durmayın. Hasta veya yolcu iseniz, yahut biriniz tuvaletten gelmişse,* yahut kadınlarla cinsel ilişkiye girmiş olup da su bulamamışsanız, temiz ve kuru bir toprağa dokunup yüzünüze ve ellerinize sürerek teyemmüm edin. ALLAH Affeder, Bağışlar."},{"n":44,"t":"Kendilerine kitaptan bir pay verilenlerin, sapıklığı satın aldıklarını ve sizin de yolu sapıtmanızı istediklerini görmüyor musun?"},{"n":45,"t":"ALLAH düşmanlarınızı daha iyi bilir. Dost ve sahip olarak ALLAH yeter, yardımcı olarak ALLAH yeter."},{"n":46,"t":"Yahudilerin bir kısmı kelimelerin anlamını değiştirir ve \"İşittik ancak kabul etmiyoruz,\" veya \"Sözünüz sağır kulağa giriyor\" veya dinle alay etmek için dillerini eğip bükerek, \"Raina (çobanımız ol),\" derler. Onlar, \"İşittik ve itaat ettik,\" \"Dinliyoruz\" ve \"Bizi gözet,\" deselerdi kendileri için daha iyi ve daha doğru olurdu. Ne var ki ALLAH inkarlarından ötürü onları lanetlemiştir. Çokları inanmaz."},{"n":47,"t":"Kitaplılar! Bazı yüzleri çevirip sürgüne göndermeden ve Cumartesi Halkını lanetlediğimiz gibi lanetlemeden önce, yanınızdakileri onaylayıcı olarak indirdiğimize inanın. ALLAH'ın emri sürekli uygulanmıştır. Affedilmeyen Biricik Suç"},{"n":48,"t":"ALLAH kendisine ortak koşulmasını bağışlamaz;*26 bundan başkasını dilediğine bağışlar. Kim ALLAH'a ortak koşarsa çok büyük bir hakaret etmiş olur."},{"n":49,"t":"Kendilerini temize çıkaranları görmüyor musun? Oysa ALLAH dilediğini temize çıkarır. Onlara en ufak bir haksızlık yapılmaz."},{"n":50,"t":"Bak, nasıl da yalan yere ALLAH'a iftira ediyorlar. Büyük bir hakaret olarak bu yeter."},{"n":51,"t":"Kendilerine kitaptan bir pay verilenleri görmüyor musun? Putperestliğe ve yanlış doktrinlere inanıyorlar ve inkar edenler için, \"Bunlar, inananlardan daha doğru yoldadır,\" diyorlar."},{"n":52,"t":"Onlar ALLAH'ın lanetine uğradılar. ALLAH kimi lanetlerse onun için bir yardımcı bulamazsın."},{"n":53,"t":"Yoksa onların yönetimde bir payı mı var? Öyle olsaydı insanlara bir çekirdek bile vermezlerdi."},{"n":54,"t":"Yoksa ALLAH'ın lütfundan insanlara verdiğini mi çekemiyorlar? Oysa biz, İbrahim ailesine kitap ve bilgelik verdik. Onlara büyük bir otorite verdik."},{"n":55,"t":"Onlardan kimi ona inandı, kimi de ondan yüz çevirdi. Onlara ceza olarak cehennem yeter. Cennet ve Cehennemin Benzetme Yoluyla Betimlenmesi*27"},{"n":56,"t":"Ayet ve mucizelerimizi inkar edenleri bir ateşe atacağız. Derileri yandıkça, azabı tadmaları için başka derilerle yenileyeceğiz. ALLAH Üstündür, Bilgedir."},{"n":57,"t":"İnanıp erdemli davrananları ise içinden ırmaklar akan cennetlere (bahçelere) yerleştireceğiz; orada sürekli kalırlar. Onlar için orada tertemiz eşler var. Onları serin gölgelere sokacağız. Dürüstlük ve Adalet"},{"n":58,"t":"ALLAH emaneti sahiplerine vermenizi, insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi emreder. ALLAH size ne güzel öğüt veriyor. ALLAH İşitendir, Görendir."},{"n":59,"t":"İnananlar! ALLAH'a uyun, elçisine uyun; sizden görev başında olanlara da. Her hangi bir konuda anlaşmazlığa düşerseniz onu ALLAH'a ve elçisine havale ediniz. ALLAH'a ve ahiret gününe inanıyorsanız... Bu, sizin için daha iyi ve en güzel çözüm yoludur. * 4:59 Yaşayan elçiye ve yaşayan görevlilere uymak onların görüşlerini veya emirlerini \"Allah'ın Emri\" diye mutlak, değişmez ve yanılmaz bilmek değildir. Bak 60:12. İkiyüzlüler"},{"n":60,"t":"Sana ve senden önce indirilenlere inandıklarını iddia ettikleri halde azgınların ve despotların yasalarını uygulamak isteyenleri görmüyor musun? Oysa onu inkar etmekle emredilmişlerdi; fakat şeytan onları büsbütün saptırmak istiyor."},{"n":61,"t":"Kendilerine, \"ALLAH'ın indirdiğine ve elçisine geliniz,\" dendiğinde, o ikiyüzlülerin (münafıkların) senden alabildiğine kaçtıklarını görüyorsun."},{"n":62,"t":"İşlediklerinin sonucu olarak başlarına bir musibet gelse hemen sana gelerek, \"Amacımız ancak iyilik yapmak ve uzlaştırmaktı,\" diye ALLAH adına yemin ederler."},{"n":63,"t":"ALLAH onların kalplerindekini bilir. Onlardan yüz çevir, onları aydınlat, ve kişiliklerini etkileyecek güzel sözler söyle."},{"n":64,"t":"Biz her elçiyi, ALLAH'ın izniyle kendisine itaat edilsin diye gönderdik. Onlar, kişiliklerine zulmettikleri zaman sana gelip ALLAH'tan günahlarının bağışlanmasını dileselerdi ve elçi de onlar için bağışlanma dileseydi, elbette ALLAH'ı Affedici ve Rahim bulacaklardı. * 4:64 Elçi bir lider olarak hayattayken itaat edilmeli. Elçi Allah'la ortaklaşarak dini hukümler koyamaz; herkes gibi elçi de Allah'ın hükmünü uygulamakla sorumludur (5:48-50)."},{"n":65,"t":"Hayır, Rabbine andolsun, anlaşmazlıklarında seni aralarında hakem kılmadıkça ve verdiğin kararı, kalplerinde bir burukluk duymadan kabul etmedikçe ve tam teslim olmadıkça inanmış olmazlar. İnancın Sınanması"},{"n":66,"t":"\"Canınızı adayın\" yahut \"Yurtlarınızdan çıkın,\" diye emretmiş olsaydık, pek azı hariç bunu yapmazlardı. Kendilerine öğütleneni uygulasalardı onlar için daha iyi ve daha sağlam olurdu."},{"n":67,"t":"Kendilerine katımızdan büyük bir ödül verirdik."},{"n":68,"t":"Ve onları doğru bir yola iletirdik. İnananların Ebedi Birlikteliği"},{"n":69,"t":"ALLAH'a ve elçisine uyanlar, ALLAH'ın kendilerine iyilikte bulunduğu peygamberler, doğrulayıcılar, şehitler ve salihler ile beraberdirler. Onlar ne güzel arkadaştır."},{"n":70,"t":"Bu lütuf ALLAH'tandır. Bilen olarak ALLAH yeter."},{"n":71,"t":"İnananlar! Tetikte durun. Bölük bölük ya da topluca harekete geçin."},{"n":72,"t":"İçinizde ağır davrananlar var. Size bir musibet gelirse, \"ALLAH bana iyilik etti de onlarla birlikte şehit düşmedim,\" der."},{"n":73,"t":"ALLAH'tan size bir lütuf erişirse sanki önce aranızda hiç bir dostluk yokmuş gibi, \"Keşke ben de onlarla birlikte olsaydım da büyük bir başarı kazansaydım,\" der."},{"n":74,"t":"Dünya hayatını ahirete değişenler ALLAH yolunda savaşsınlar. Kim ALLAH yolunda savaşır, ölür yahut yenerse, kendisine büyük bir ödül vereceğiz. * Başka dinlerin veya mezheplerin mensuplarına tekbir getirerek saldırmak \"Tanrı yolunda\" savaşmak değildir. Kuran'ın onayladığı savaş, saldırıya ve zulme karşı kendini ve toplumu savunma amacıyla yapılan savaştır. İnananlar Mazlumlardan Yanadır"},{"n":75,"t":"Size ne oldu ki \"Rabbimiz, bizi halkı zalim olan bu ülkeden kurtar, bize sahip çık, bize yardım et,\" diye feryad eden ezilmiş erkekler, kadınlar ve çocuklara rağmen hâlâ ALLAH yolunda savaşmıyorsunuz?"},{"n":76,"t":"İnananlar ALLAH yolunda savaşırlar. Kafirler ise azgınların ve despotların yolunda savaşırlar. Öyleyse şeytanın dostlarıyla savaşın; şeytanın planı zayıftır."},{"n":77,"t":"Kendilerine, \"Elinizi savaştan çekin, namazı gözetin, zekatı verin,\" denilenlere dikkat etmedin mi? Kendilerine savaşmaları emredildiğinde, insanlardan ALLAH'tan korkar gibi, belki daha fazla korkmaya başladılar ve \"Rabbimiz, neden bize savaşı yükledin, bizi yakın bir zamana kadar erteleyemez miydin!,\" dediler. De ki, \"Bu dünyanın varlığı azdır, erdemliler için ahiret daha hayırlıdır; en ufak bir haksızlığa uğratılmayacaksınız.\" Herşeyin Kontrolü ve Uygulaması Tanrı'ya Aittir"},{"n":78,"t":"Nerede olursanız olun, sağlam kalelerde bile olsanız ölüm sizi yakalar. Başlarına iyi bir şey gelse, \"Bu ALLAH tarafındandır,\" derler. Kendilerine bir kötülük dokunsa, \"Bu senin tarafındandır,\" derler. De ki, \"Hepsi ALLAH tarafındandır.\" Bu topluma ne oluyor ki neredeyse hiç bir söz anlamıyorlar! Tanrı'dan Sana Hiçbir Kötülük Gelmez"},{"n":79,"t":"Sana gelen her iyilik ALLAH'tan, sana gelen her kötülük ise kendindendir. Seni insanlara elçi olarak gönderdik. Tanık olarak ALLAH yeter."},{"n":80,"t":"Elçiye uyan ALLAH'a uymuş olur. Kim yüz çevirirse çevirsin; biz seni onların üzerine bekçi göndermedik."},{"n":81,"t":"\"Tamam, itaat ediyoruz,\" derler. Ancak senin yanından çıktıklarında onlardan bir takımı, söylemiş olduklarının tersini kuruyor. ALLAH onların planlayıp kurdukları şeyleri kaydediyor. Onlara aldırma; ALLAH'a güven. Destekleyici olarak ALLAH yeter. Kuran'da İç Çelişki Yoktur. Kuran Gerçekle Çelişmez"},{"n":82,"t":"Kuran'ı incelemiyorlar mı? ALLAH'tan başkasının olsaydı onda bir çok çelişki bulacaklardı."},{"n":83,"t":"Onlara güvenlik ve tehlikeyle ilgili bir söylenti ulaşsa onu yayarlar. Durumu elçiye ve aralarındaki yetkililere iletselerdi uzmanları onu değerlendirirdi. Size ALLAH'ın lütfu ve rahmeti olmasaydı pek azınız hariç şeytana uyacaktınız."},{"n":84,"t":"ALLAH yolunda savaşmalısın. Sen ancak kendinden sorumlusun. İnananları da aynı şeye özendir ki ALLAH kafirlerin gücünü etkisiz hale getirsin. ALLAH'ın gücü daha şiddetli, cezası daha çetindir."},{"n":85,"t":"Kim bir iyiliğe aracılık ederse kendisi için ondan bir kredi var. Kim bir kötülüğe aracılık ederse, kendisi için ondan bir pay var. ALLAH herşeyi kontrol eder. Dostluk ve Barışı Yayın"},{"n":86,"t":"Herhangi bir selam ile selamlandığınız zaman daha güzeliyle veya aynen iade ederek selamı alın. Kuşkusuz ALLAH herşeyi hesaba katar."},{"n":87,"t":"ALLAH: O'ndan başka tanrı yoktur. Gerçekleşmesi mutlak olan diriliş gününde sizleri biraraya toplayacaktır. ALLAH'tan daha doğru sözlü kim olabilir? Dinden Dönen İkiyüzlülere Karşı Tavır"},{"n":88,"t":"Size ne oluyor da ikiyüzlüler hakkında iki gruba ayrılıyorsunuz? İşlediklerinden ötürü ALLAH onları başaşağı çevirdi. ALLAH'ın saptırdığını siz mi doğru yola ulaştırmak istiyorsunuz? ALLAH'ın saptırdığı kimseye sen hiç bir yol bulamazsın."},{"n":89,"t":"Sizin de kendileri gibi inkar etmenizi istediler ki onlarla bir olasınız. ALLAH yolunda harekete geçinceye kadar onlardan kimseyi dost edinmeyin. Size karşı dönerlerse onları yakalayın, onları bulduğunuz yerde öldürün. Onları ne dost ne de yardımcı edinmeyin;"},{"n":90,"t":"Ancak aranızda anlaşma bulunan bir topluluğa katılan, yahut sizinle veya kendi halkıyla savaşmaktan dolayı göğüslerinde sıkıntı duyarak size gelenler hariç... ALLAH dileseydi onları başınıza musallat eder ve onlar da sizinle savaşırdı. Sizi yalnız bırakır, sizinle savaşmaz ve size barış önerirlerse ALLAH sizin onlara saldırmanıza izin vermez."},{"n":91,"t":"Hem sizinle hem kendi toplumlarıyla güven içinde durmak isteyen bir başka grup bulacaksın. Ne zaman kargaşalığa çağrılsalar içine dalarlar. Sizi yalnız bırakmaz, barış yapmak istemez ve ellerini sizden çekmezlerse karşılaştığınız yerde onları öldürebilirsiniz. Böylelerine karşı size apaçık yetki verdik."},{"n":92,"t":"İnanmış bir kişi, kaza hali hariç inanmış birisini öldüremez. Kim bir inananı kazara öldürmüşse inanmış bir köleyi salmalı ve ölenin ailesine diyet ödemeli. Ancak diyetten vazgeçip sadaka olarak kabul ederlerse başka. Öldürülen, sizinle savaş halinde olan bir topluluğa mensup bir inanan ise, o zaman inanan bir köleyi salmalısınız. Ancak, maktul aranızda anlaşma olan bir topluluktan ise ailesine diyet vermeli ve inanmış bir köleyi salmalısınız. Kim (gerekli parayı veya salacağı bir köle) bulamıyorsa, ALLAH tarafından tevbesinin kabul edilmesi için iki ay aralıksız oruç tutmalıdır. ALLAH Bilendir, Bilgedir."},{"n":93,"t":"Kim inanmış birisini kasden öldürürse yeri, sürekli kalacağı cehennemdir. ALLAH kendisine gazap ve lanet etmiştir. Ve onun için büyük bir azap hazırlamıştır."},{"n":94,"t":"İnananlar, ALLAH yolunda çarpışmağa çıktığınız zaman dikkatli olun. Size barış önerene, dünya hayatının geçici yararını gözeterek \"Sen inanmıyorsun,\" demeyin. Çünkü ALLAH'ın yanında çok ganimetler var. Daha önceleri siz de onlar gibiydiniz; fakat ALLAH size lütfetti. Öyleyse iyice araştırıp emin olun. ALLAH yaptıklarınızdan Haberdardır."},{"n":95,"t":"Geçerli özre sahip olmaksızın yerlerinde oturanlar ile mallarıyla canlarıyla ALLAH yolunda savaşım verenler bir olmaz. ALLAH mallarıyla, canlarıyla savaşım verenleri derece bakımından oturanlardan üstün kıldı. ALLAH hepsine güzellikler söz veriyor. Bununla birlikte, ALLAH savaşım verenleri oturanlar üzerine daha büyük bir ödülle üstün kıldı;"},{"n":96,"t":"Kendi katından derecelerle, bağışlama ve rahmet ile... ALLAH Bağışlayandır, Rahimdir. Zulme Rıza Göstermek Suçtur"},{"n":97,"t":"Kendilerine zulmedenlerin canlarını alırken melekler: \"Ne halde idiniz,\" derler. \"Bizler yeryüzünde ezilmiş kimselerdik,\" diye cevap verirler. \"ALLAH'ın yeri geniş değil miydi ki oralara göç edeydiniz,\" derler. Onların yeri cehennem. O ne kötü bir dönüş noktası."},{"n":98,"t":"Ancak, hiç bir çıkış yoluna gücü yetmeyen ve göç etmeye yol bulamayan erkek, kadın ve çocuk ezilmişler hariç."},{"n":99,"t":"Böylelerinin ALLAH tarafından affedilmesi umulur. ALLAH Affedicidir, Bağışlayandır. 100. Kim ALLAH yolunda göç ederse yeryüzünde barınacak çok yer ve bolluk bulur. Kim ALLAH'a ve elçisine göç etmek için evinden çıkar ve sonra kendisini ölüm yakalarsa, ödülünü vermek ALLAH'a düşer. ALLAH Bağışlayandır, Rahimdir. Tehlike Anında Namazı Kısaltmak 101. Yeryüzünde savaş için yolculuğa çıktığınız zaman inkarcıların size saldırmasından korkuyorsanız namazı kısaltmanızda bir sakınca yok. Kuşkusuz inkarcılar sizin açık düşmanınızdır."}]},{"id":5,"name":"ZİYAFET (MAİDE) SÛRESİ","verses":[{"n":1,"t":"İnananlar, anlaşmalarınızı uygulayın. Size okunacak olanların dışındaki hayvanlar size helal kılındı. Yalnız ihramda iken avlanmayı helal saymamak koşuluyla... ALLAH dilediği hükmü verir."},{"n":2,"t":"İnananlar! Ne ALLAH'ın koyduğu dinsel törenlere, ne kutsal aya, ne kurbana, ne onları işaretleyen çelenklere ve ne de Rab'lerinin lütuf ve rızasını aramak için Kutsal Ev'e doğru yola çıkanlara saygısızlık etmeyin. İhramdan çıktığınız zaman avlanabilirsiniz. Sizi Kutsal Mescid'den çeviren bir topluluğa olan kininizden dolayı provakasyona gelip saldırganlaşmayın. İyilik ve erdemlilikte yardımlaşın. Kötülük ve düşmanlıkta yardımlaşmayın. ALLAH'ı dinleyin. ALLAH'ın cezası çetindir."},{"n":3,"t":"Leş, kan, domuzun eti ve ALLAH'tan başkasına adananlar size haram kılındı. Canları çıkmadan kesmeniz hariç, boğulmuş, vurulmuş, düşmüş, boynuzlanmış ve canavar tarafından yenmiş hayvanlar,* kutsallaştırılmış taşlar üzerinde boğazlanarak fal oklarıyla dağıtılanlar,*29 evet bunlar kötüdür. Bugün size dininizi olgunlaştırdım, size nimetimi tamamladım ve size din olarak islam'ı beğendim. Kim açlıktan dolayı zorda kalırsa, günaha istekle yönelmeden yerse ona günah yoktur. Çünkü ALLAH Bağışlayandır, Rahimdir."},{"n":4,"t":"Kendilerine neyin helal olduğunu sana soruyorlar. De ki, \"Size temiz yiyecekler helal edilmiştir. ALLAH'ın size öğrettiğinden öğreterek yetiştirdiğiniz köpek ve şahin gibi avcı hayvanların sizin için yakaladıklarını da yiyin ve üzerlerinde ALLAH'ın ismini anın.\" ALLAH'ı dinleyin. ALLAH hesabı çabuk görür."},{"n":5,"t":"Bugün size iyi ve temiz şeyler helal kılındı. Kitap halkının yiyeceği size helaldir. Sizin de yiyecekleriniz onlara helaldir. Mehirlerini ödemeniz, zina etmeyip namuslu davranmanız ve gizli dost tutmamanız koşuluyla, inananlardan iffetli kadınlarla ve sizden önce kendilerine kitap verilenlerden iffetli kadınlarla evlenmeniz size helaldir. Kim inanmayı kabul etmezse tüm yaptıkları boşa çıkmıştır ve o, ahirette de kaybedenlerdendir. Aptes"},{"n":6,"t":"İnananlar! Namaza kalktığınız zaman: (1) Yüzünüzü yıkayın, (2) ellerinizi dirseklere kadar yıkayın, (3) başınızı sıvazlayın, (4) ve ayaklarınızı da topuklara kadar (sıvazlayın/yıkayın). Cinsel ilişkide bulunmuşsanız yıkanınız. Hasta veya yolcu iseniz, yahut tuvaletten gelmiş, yahut kadınlarla cinsel ilişkide bulunmuş ve su bulamamışsanız, temiz bir toprağa yönelip yüzünüzü ve kollarınızı onunla sıvazlayın. ALLAH size güçlük çıkarmak istemez. Ancak sizi temizlemek ve üzerinizdeki nimetini tamamlamak istiyor. Olur ki şükredersiniz."},{"n":7,"t":"ALLAH'ın üzerinizdeki nimetini ve O'nunla yaptığınız sözleşmeyi hatırlayın: \"İşittik ve itaat ettik,\" demiştiniz. ALLAH'ı dinleyin; ALLAH içinizde olanları biliyor. Yalan Yere Tanıklık Yapmayın"},{"n":8,"t":"İnananlar! ALLAH için adaleti gözeterek tanıklık edin. Bir topluluğa olan kininiz sizi adaletli davranmaktan alıkoymasın. Adaletli davranmak daha erdemlidir. ALLAH'ı dinleyin. ALLAH yaptıklarınızı haber alır."},{"n":9,"t":"ALLAH, inanıp iyi işler yapanlara bir bağışlanma ve büyük bir ödülü söz verdi."},{"n":10,"t":"İnkar edip ayetlerimizi yalanlayanlara gelince, onlar cehennem halkıdır. Tanrı, İnananları Savunur"},{"n":11,"t":"İnananlar! ALLAH'ın size olan nimetini hatırlayın: Hani bir topluluk size el uzatmağa yeltenmişti de onların ellerini sizden çekmişti. ALLAH'ı dinleyin. İnananlar ALLAH'a güvensin."},{"n":12,"t":"ALLAH, İsrail oğullarından söz almıştı ve içlerinden on iki başkan göndermiştik. ALLAH demişti ki: \"Namazı gözetirseniz, zekatı verirseniz, elçilerime inanıp onlara saygılı olursanız ve (erdemli bir yaşam sürmek suretiyle) ALLAH'a güzel bir borç verirseniz sizinle beraberim. Günahlarınızı örter, içlerinden ırmaklar akan bahçelerde ağırlarım. Artık sizden kim bundan sonra inkar ederse doğru yolu sapıtmış olur.\""},{"n":13,"t":"Sözlerini bozdukları için onları lanetledik, kalplerini katılaştırdık. Sözlerin anlamını bağlamından kaydırırlar. Uyarıldıkları şeylerin bir kısmını unuttular. Onların çoğundan sürekli ihanet göreceksin. Onları affet ve aldırma. ALLAH güzel davrananları sever."},{"n":14,"t":"\"Biz Hristiyanız,\" diyenlerden de söz almıştık. Ancak onlar da uyarıldıkları şeylerin bir kısmını unuttu. Bu yüzden diriliş gününe kadar aralarına düşmanlık ve kin saldık. Yaptıkları her şeyi ALLAH onlara bildirecek. Kuran: Hristiyanlara ve Yahudilere Tanrı'nın Mesajı"},{"n":15,"t":"Kitap halkı, kitabın gizlediğiniz bir çok bölümünü açığa çıkaran ve bir çoğunu da yüzünüze vurmayan elçimiz geldi size. ALLAH'tan bir ışık ve apaçık bir kitap da geldi size."},{"n":16,"t":"Onunla ALLAH, rızasını gözetenleri barış ve huzur yollarına ulaştırır, izniyle onları karanlıklardan aydınlığa çıkararak onları dosdoğru yola iletir. Büyük Küstahlık"},{"n":17,"t":"\"ALLAH Meryem oğlu Mesih'tir,\" diyenler elbette kafir olmuşlardır. De ki: \"ALLAH Meryem oğlu Mesih'i, annesini ve hatta yeryüzündekilerin tümünü helak etmek isterse, kim buna engel olabilir?\" Göklerin, yerin ve arasındakilerin egemenliği ALLAH'a aittir. Dilediğini yaratır. ALLAH herşeye Gücü Yetendir."},{"n":18,"t":"Yahudiler ve Hristiyanlar, \"Biz ALLAH'ın çocukları ve sevgilileriyiz,\" dediler. \"Öyleyse günahlarınızdan ötürü neden sizi cezalandırıyor? Siz sadece O'nun yarattığı insanlardansınız,\" de. Dileyeni/dilediğini de bağışlar, dileyeni/dilediğini de cezalandırır. Göklerin, yerin ve bunlar arasındakilerin egemenliği ALLAH'a ait olup dönüş de O'nadır. Size Gelen Elçiyi Nasıl Karşıladınız"},{"n":19,"t":"Kitap halkı! Elçiler arasındaki bir boşluk döneminden sonra size elçimiz gelmiş bulunuyor ve size gerçekleri anlatıyor ki \"Bize bir müjdeleyici ve uyarıcı gelmedi,\" demeyesiniz. ALLAH her şeye Gücü Yetendir.*"},{"n":20,"t":"Musa, halkına şöyle demişti: \"Ey halkım, ALLAH'ın üzerinizdeki nimetini hatırlayın: aranızdan peygamberler çıkardı, sizi özgür kimseler kıldı ve toplumların hiçbirine vermediğini size verdi.\" Tanrı, Kutsal Toprağı Yahudilere Veriyor"},{"n":21,"t":"\"Halkım! ALLAH'ın size ayırdığı kutsal toprağa girin. Geri dönmeyin, yoksa kaybedersiniz.\""},{"n":22,"t":"Dediler ki: \"Musa, orada zorba bir topluluk var. Onlar oradan çıkmadıkça biz asla oraya girmeyiz. Çıkarlarsa gireriz.\""},{"n":23,"t":"Korku duyanların arasında, ALLAH'ın kendisine nimet verdiği iki kişi, \"Üstlerine kapıdan yürüyün. Kapıdan girerseniz kesinlikle siz yeneceksiniz. İnanıyorsanız ALLAH'a güvenin,\" dedi."},{"n":24,"t":"\"Musa, onlar orada oldukça biz oraya asla girmeyiz. Sen ve Rabbin gidip savaşın; biz burda oturuyoruz,\" dediler."},{"n":25,"t":"O da bunun üzerine: \"Rabbim, ben ancak kendime ve kardeşime söz geçirebiliyorum. Bizimle yoldan çıkmış bu topluluğun arasını ayır,\" dedi."},{"n":26,"t":"Orası onlara kırk yıl boyunca yasaklanmıştır; yeryüzünde şaşkın şaşkın dolaşacaklar. Yoldan çıkmış bir topluluk için üzme kendini. İlk Cinayet"},{"n":27,"t":"Onlara Adem'in iki oğlunun olayını doğru anlat. Birer kurban adamışlardı da, birisinden kabul edilmiş, diğerinden edilmemişti. \"Seni öldüreceğim!,\" dedi. \"ALLAH ancak erdemli olanlardan kabul eder,\" dedi."},{"n":28,"t":"\"Beni öldürmek için elini bana uzatırsan, seni öldürmek için ben elimi sana uzatmayacağım. Ben, tüm yaratıkların sahibi ALLAH'tan korkarım. \""},{"n":29,"t":"\"Günahımı günahınla birlikte yüklenerek cehenneme girmeni isterim. Zalimler böyle cezalandırılır.\""},{"n":30,"t":"Egosu onu, kardeşini öldürmeye kışkırttı. Onu öldürdü ve böylece kaybetti."},{"n":31,"t":"ALLAH kardeşinin cesedini nasıl gömeceğini göstermek için yeri eşeleyen bir karga gönderdi. \"Yazık bana; kardeşimin cesedini gömme konusunda bu karga kadar bile olamadım,\" diyerek pişman oldu.*30"},{"n":32,"t":"Bunun için İsrail oğullarına şunu yazdık: Kim, cinayet işlememiş veya yeryüzünde bozgunculuk yapmamış bir kişiyi öldürürse tüm insanları öldürmüş gibidir. Kim de o canı yaşatırsa, bütün insanları yaşatmış gibi olur. Elçilerimiz onlara apaçık delillerle geldiler. Buna rağmen onların çoğu hemen sonra yeryüzünde azgınlık yapmaya başladılar. Ölüm Cezası Kimler İçindir"},{"n":33,"t":"ALLAH ve elçisi ile savaşan ve yeryüzünde bozgunculuk için uğraşanların cezası: Öldürülmeleri veya asılmaları, veya el ve ayaklarının çaprazlama kesilmesi, veya yerlerinden sürülmeleridir. Bu, dünyada görecekleri bir aşağılanma. Ahirette ise büyük bir ceza var."},{"n":34,"t":"Kendilerini yakalamadan önce tevbe edenler başka. Bilesiniz ki ALLAH Bağışlayandır, Rahimdir."},{"n":35,"t":"İnananlar ALLAH'ı dinleyin, O'na ulaşmak için yol arayın ve O'nun yolunda cihad edin ki başarasınız."},{"n":36,"t":"İnkarcılar, yeryüzündekilerin hepsine ve bir o kadarına da sahip olsalardı ve onları diriliş gününün azabından kurtulmak için fidye verselerdi kendilerinden kabul edilmezdi. Onlara acıklı bir azap var."},{"n":37,"t":"Ateşten çıkmak isterler; ama çıkamazlar. Onlar sürekli bir cezaya mahkum olmuşlardır. Hırsızların Ellerini Kesiniz"},{"n":38,"t":"Erkek hırsızın ve kadın hırsızın ellerini, yaptıklarına karşılık kesin. Bu ALLAH'ın öngördüğü bir caydırma yöntemidir. ALLAH Güçlüdür, Bilgedir."},{"n":39,"t":"Kim yaptığı bu haksızlıktan sonra tevbe ederek düzelirse, ALLAH yönelişini kabul eder. ALLAH kuşkusuz Bağışlayandır, Rahimdir."},{"n":40,"t":"Göklerin ve yerin egemenliğinin ALLAH'a ait olduğunu bilmez misin? Dilediğine azap eder, dilediğini bağışlar. ALLAH her şeye Gücü Yetendir. Tefsir Yoluyla Anlamı Değiştirme Yöntemi"},{"n":41,"t":"Ağızlarıyla \"İnandık,\" dedikleri halde kalpleriyle inanmıyanların inkarcılıktaki gayretleri seni üzmesin. Yahudilerin bir grubu var ki yalana kulak veriyor, seninle hiç karşılaşmamış bir topluluğu dinliyor. Kelimelerin anlamını kaydırıp. \"Size bu verilirse alın, bu verilmezse sakının,\" diyorlar. ALLAH birini şaşırtmak isterse ALLAH'a karşı kimse ona yardım edemez. İşte onlar, ALLAH'ın kalplerini temizlemeyi dilemediği kişiler. Onlar için dünyada aşağılanma, ve ahirette de büyük bir azap var."},{"n":42,"t":"Yalana kulak veriyor, yasadışı yoldan yiyorlar. Sana gelirlerse, ister aralarında hüküm ver, istersen yüz çevir. Onlardan yüz çevirdiğin taktirde sana hiç bir zarar veremezler. Hüküm verirsen, aralarında adaletle hüküm ver. ALLAH adaletli olanları sever."},{"n":43,"t":"İçinde ALLAH'ın hükmü bulunan Tevrat yanlarında dururken nasıl olur da ondan yüz çevirip de seni hakem yapıyorlar? Onlar aslında inanmıyor."},{"n":44,"t":"İçinde hidayet ve ışık bulunan Tevrat'ı biz indirdik. müslüman peygamberler onunla Yahudiler arasında hüküm veriyorlardı. Hahamlar ve din bilginleri de ALLAH'ın kitabından emredildikleri şeylerle hüküm verirler ve onun üzerine tanık olurlardı. Halkı ululamayın, beni ululayın ve ayetlerimi ucuz bir fiyata satmayın. ALLAH'ın indirdiği ile hüküm vermeyenler inkarcıdır."},{"n":45,"t":"Orada onlara: Cana can, göze göz, buruna burun, kulağa kulak, dişe diş ve yaralara ödeşmeyi emrettik. Kim bu hakkından vazgeçerse günahlarını örter. ALLAH'ın indirdiği ile hüküm vermeyenler zalimdir. İncil: İsa'ya Verilen Hidayet ve Işık"},{"n":46,"t":"Onların ardından, önceki Tevrat'ı doğrulayıcı olarak Meryem oğlu İsa'yı gönderdik. Ona, içinde hidayet ve ışık bulunan, önceki Tevratı doğrulayan ve erdemliler için bir kılavuz ve öğüt olan İncil'i verdik."},{"n":47,"t":"İncil halkı ALLAH'ın onda indirdiğiyle hüküm versin. Kim ALLAH'ın indirdiği ile hüküm vermezse işte onlar yoldan çıkanlardır. Kuran: Son ve Tek Kaynak"},{"n":48,"t":"Kendinden önceki kitapları doğrulayan, onların yerine geçen bu kitabı, gerçekleri kapsayıcı olarak sana indirdik. ALLAH'ın sana indirdiğiyle aralarında hüküm ver. Sana gelen gerçekleri bırakıp onların hevesine uyma. Her biriniz için bir yasa ve yöntem belirledik. ALLAH dileseydi hepinizi bir tek toplum yapardı. Ancak, size verdikleriyle sizleri sınıyor. İyilikte yarışın. Hepinizin dönüşü ALLAH'adır. Ayrılığa düştüğünüz konuları size bildirecek."},{"n":49,"t":"Aralarında ALLAH'ın indirdiği ile hüküm vermelisin. Onların keyfine uyma. ALLAH'ın sana indirdiklerinin bir kısmından sakın seni şaşırtmasınlar. Yüz çevirirlerse, demek ki ALLAH bazı günahları yüzünden onları cezalandırmak istiyor. Gerçekten insanların çoğu yoldan çıkmıştır."},{"n":50,"t":"Yoksa cahillik dönemindeki yasaları mı arıyorlar? Bilgiye dayanan kesin inanç sahipleri için ALLAH'tan daha güzel yasa koyucu olabilir mi? Yahudiler ve Hristiyanlar"},{"n":51,"t":"İnananlar, Yahudileri ve Hristiyanları dost edinmeyin. Onlar birbirlerinin dostudur. Sizden kim onlarla dost olursa onlardan sayılır. ALLAH zalim toplumu doğru yola iletmez."},{"n":52,"t":"Kalplerinde hastalık bulunanların, \"Başımıza bir bela gelmesinden korkuyoruz,\" diyerek onların arasında dolanıp durduklarını göreceksin. Olur ki ALLAH , zaferi veya kendi tarafından bir emri getirir de, içlerinde gizledikleri düşüncelerinden dolayı pişman olurlar."},{"n":53,"t":"O zaman inananlar, \"Sizinle beraber olduklarına bütün güçleriyle ALLAH adına yemin edenler bunlar mı,\" diyecek. Çabaları boşa çıkmış ve zarar etmişlerdir."},{"n":54,"t":"İnananlar, kim dininden dönerse şunu bilsin: ALLAH sevdiği bir toplumu getirir; onlar da O'nu sever. İnananlara karşı alçak gönüllü, kafirlere karşı güçlü ve pektirler. ALLAH yolunda cihad ederler, kınayanın kınamasından çekinmezler. Bu, ALLAH'ın lütfudur; onu dilediğine verir. ALLAH Cömerttir, Bilendir."},{"n":55,"t":"Gerçek dostlarınız, ALLAH, elçisi ve namazı gözetip alçak gönüllü olarak zekatı veren müminlerdir."},{"n":56,"t":"Kim ALLAH'ı, elçisini ve inananları dost edinirse bilsin ki ALLAH'ın partisi üstün gelecek."},{"n":57,"t":"İnananlar, sizden önceki kitap halkı ve inkarcılar arasında dininizi alay ve eğlence konusu yapanları dost edinmeyin. İnanmış iseniz ALLAH'ı dinlemelisiniz."},{"n":58,"t":"Namaza çağırdığınızda onunla alay edip eğlendiler. Düşünmeyen bir topluluktur onlar."},{"n":59,"t":"De: \"Kitaplılar! ALLAH'a, bize indirilene ve önceki indirilenlere inandık diye mi yoldan çıkmış olan çoğunluğunuzla bize karşı nefret besliyorsunuz?\""},{"n":60,"t":"De: \"ALLAH katında bundan daha kötü bir durumu size bildireyim mi? ALLAH kime lanet ve gazap ederek maymunlar, domuzlar, putperestler haline sokmuşsa, işte o kimseler yer bakımından daha kötü ve doğru yoldan en çok sapmış olanlardır."},{"n":61,"t":"Size geldiklerinde, \"İnandık,\" dediler. Oysa yanınıza inkarlarıyla girip inkarlarıyla çıkmışlardı. Onların gizlediklerini ALLAH daha iyi biliyor."},{"n":62,"t":"Onların çoğunu günahta, düşmanlıkta ve haram yemekte koşuşurken görürsün. Yaptıkları ne kötü!"},{"n":63,"t":"Hahamları ve din adamları onları bu günah sözleri söylemekten, haram yemekten menetmeli değil miydi? İşledikleri ne fena!"},{"n":64,"t":"Yahudiler \"ALLAH'ın eli bağlı,\" dedi. Aslında elleri bağlı olanlar kendileri. Halbuki O'nun iki eli de açık olup dilediği gibi harcamakta. Rabbinden sana indirilenler çoğunun azgınlığını ve inkarını arttıracak. Diriliş Gününe kadar aralarına düşmanlık ve kin saldık. Her ne zaman savaş için ateş yaksalar ALLAH onu söndürmüştür. Yeryüzünde bozgunculuk yapmak için dolaşırlar. ALLAH ise bozguncuları sevmez."},{"n":65,"t":"Kitap halkı inanıp erdemli davransa günahlarını örterek onları bol nimetli bahçelere yerleştirirdik."},{"n":66,"t":"Tevrat'ı, İncil'i ve kendilerine indirilenleri uygulasalardı onları baştan ayağa nimetlere boğardık. İçlerinde ılımlı bir toplum varsa da çoğu kötülük işlemekte."},{"n":67,"t":"Elçi, Rabbinden sana indirileni duyur. Bunu yapmazsan O'nun elçiliğini duyurmamış olursun. ALLAH seni halktan koruyacak. ALLAH inkarcıları doğru yola iletmez."},{"n":68,"t":"De, \"Kitaplılar! Tevrat'ı, İncil'i ve Rabbinizden size indirileni uygulamadıkça hiç bir dayanağınız olmaz.\" Rabbinden sana indirilenler, onların çoğunun azgınlık ve inkarını arttırır. İnkarcı toplum için kendini üzme. Kurtuluşun Minimum Koşulu"},{"n":69,"t":"İnananlar, Yahudiler, diğer dinlerden olanlar ve Hıristiyanlardan kim (1) ALLAH'a ve (2) ahiret gününe inanır ve (3) erdemli bir yaşam sürerse onlar için bir korku yoktur ve onlar üzülmeyecekler de..."},{"n":70,"t":"İsrail oğullarından söz almış, onlara elçiler göndermiştik. Her ne zaman hoşlarına gitmeyen bir şeyle onlara bir elçi gittiyse bir kısmını yalanlayıp bir kısmını da öldürdüler."},{"n":71,"t":"Test edilmeyeceklerini sandılar, körleşip sağırlaştılar. Sonra ALLAH yönelişlerini kabul etti; fakat buna rağmen çoğu yine körleşip sağırlaştı. ALLAH Yaptıklarını görmekte. Günümüzdeki Hristiyanlık İsa'nın Dini Değildir"},{"n":72,"t":"\"ALLAH, Meryem oğlu Mesih'tir,\" diyenler elbette inkar etmiştir. Oysa Mesih, \"İsrail oğulları! benim de sizin de Rabbiniz olan ALLAH'a kul olun,\" demişti. Kim ALLAH'a ortak koşarsa ALLAH ona cenneti yasaklar, yeri de ateş olur. Zalimler için yardımcı da bulunmaz. * 5:72 Bak, İncil ,Yuhanna 7:16, 28-29; 5:30; 14:28; 12:44-50; 20:127; Markos 10:17-18; 12:29; Matta 7:21."},{"n":73,"t":"\"ALLAH, üçün üçüncüsüdür,\" diyenler inkar etmiştir. Oysa bir tek Tanrı'dan başka tanrı yok. Bu sözlerine son vermezlerse, inkarcılarına acıklı bir azap dokunacak."},{"n":74,"t":"Hâlâ ALLAH'a yönelip ondan bağışlanma dilemiyecekler mi? ALLAH Bağışlayandır, Rahimdir."},{"n":75,"t":"Meryem oğlu Mesih elçiden başka bir şey değildi. Ondan önce de nice elçiler gelip geçmişti. Annesi de doğru sözlüydü. Her ikisi de yemek yerdi. Ayetlerimizi onlara nasıl açıkladığımıza dikkat et de buna rağmen nasıl da yüz çevirmekte olduklarını gör!"},{"n":76,"t":"De, \"ALLAH'tan başka, size zarar ve yarar veremiyenlere mi tapıyorsunuz? ALLAH İşitir, Bilir.\"*"},{"n":77,"t":"De, \"Kitaplılar, dininiz konusunda gerçeğin ötesine gitmeyin. Daha önce sapan, çok kimseyi de saptıran, böylece doğru yolu kaybeden bir topluluğun heveslerini izlemeyin."},{"n":78,"t":"İsrail oğullarının inkarcıları, hem Davud'un hem Meryem oğlu İsa'nın diliyle lanetlenmişti. Zira onlar isyan edip sınır tanımıyorlardı. Vurdumduymazlık Kınanmıştır"},{"n":79,"t":"Yaptıkları kötülükler konusunda birbirlerini uyarmıyorlardı. Yaptıkları ne kötü idi."},{"n":80,"t":"Çoklarının inkarcılarla dost olduğunu görürsün. Nefislerinin kendileri için gönderdiği şey ne kötü. ALLAH onlara gazap etmiştir; azapta sürekli kalacaklar."},{"n":81,"t":"ALLAH'a, peygambere ve ona indirilene inansalardı, onları dost edinmezlerdi. Ne var ki, çoğu yoldan çıkmış bulunuyor. Tarihsel Bir Realite"},{"n":82,"t":"İnsanların arasında inananların en azılı düşmanı olarak Yahudileri ve müşrikleri bulacaksın. İnananlara sevgice en yakınları da \"Biz Hristiyanız,\" diyenleri bulursun. Çünkü onlar arasında büyüklük taslamayan papazlar ve rahipler var."},{"n":83,"t":"Elçiye inenleri işittiklerinde, gerçeği tanımalarından ötürü gözlerinin yaşla dolup taştığını görürsün. Derler ki, \"Rabbimiz, inandık, bizi tanıklardan say."},{"n":84,"t":"\"Rabbimizin bizi iyiler arasına katmasını umduğumuz halde neden ALLAH'a ve bize ulaşan gerçeklere inanmıyalım?\""},{"n":85,"t":"Bu sözlerinden ötürü ALLAH onlara, içlerinde ırmaklar akan ve sürekli kalacakları cennetler verdi. İyi davrananların karşılığı budur."},{"n":86,"t":"İnkar edip ayet ve mucizelerimizi yalanlayanlar ise cehennem halkı. Tanrı'nın Haram Etmediğini Haram Etmeyin"},{"n":87,"t":"İnananlar, ALLAH'ın size helal yaptığı iyi şeyleri haram etmeyin. Sınırı aşmayın. ALLAH sınırı aşanları sevmez."},{"n":88,"t":"ALLAH'ın size rızık olarak verdiklerini, helal ve temiz olarak yeyin. İnandığınız ALLAH'ı dinleyin. Yeminlerinizi Tutun"},{"n":89,"t":"ALLAH rastgele ettiğiniz yeminlerden sizi sorumlu tutmaz. Ancak bile bile ettiklerinizden sizi sorumlu tutar. Yemininizi bozarsanız cezası, ailenize genellikle yedirdiğiniz yemeklerden on yoksulu doyurmak veya giydirmek veya bir köleyi salmaktır. Kim bulamazsa üç gün oruç tutmalı. Bu, bile bile ettiğiniz yeminlerinizin cezası. Yeminlerinizi tutun. ALLAH güzel karşılık veresiniz diye ayetlerini böyle açıklıyor. Sarhoş Edici Maddeler ve Kumar Yasaklanmıştır"},{"n":90,"t":"İnananlar, sarhoş edici maddeler, kumar, kutsal taş ve türbeler, şans oyunları şeytan işi birer pisliktir. Bunlardan sakının ki kurtulasınız."},{"n":91,"t":"Şeytan, sarhoş edicilerle, kumarla aranıza düşmanlık ve kin sokmak, sizi ALLAH'ı anmaktan, namazdan alıkoymak ister. Artık vazgeçiyorsunuz değil mi?"},{"n":92,"t":"ALLAH'a uyun, elçiye uyun, dikkatli olun. Yüz çevirirseniz bilesiniz ki elçimize düşen görev, açıkça bildirmektir."},{"n":93,"t":"İnanıp erdemli işler yapanlar, emirlere uyarak inanıp erdemli davrandıkları, günahlardan sakınıp inandıkları ve yine sakınıp iyilik yaptıkları sürece yediklerinden ötürü kendilerine bir günah yoktur. ALLAH iyi davrananları sever. Ekolojik Sistemin Korunması"},{"n":94,"t":"İnananlar, ellerinizin ve mızraklarınızın ulaşacağı avlarla ALLAH sizi sınayacak ki yalnızken de kendisinden korkanları ALLAH ayırsın. Kim bundan sonra sınırı aşarsa onun için acıklı bir azap var."},{"n":95,"t":"İnananlar, ihramdayken (Haj için kutsal bölgedeyken) av hayvanı öldürmeyin. Sizden kim kasden onu öldürürse cezası, aranızdan iki adaletli kişinin kararlaştıracağı ona denk bir evcil hayvanı kurban olarak Kabeye göndermesidir. Yahut ceza olarak, yoksulları doyurması ya da buna denk oruç tutması gerekir. Böylece yaptığının vebalini tatmış olsun. Geçmiştekileri ALLAH affetti. Kim bunu tekrarlarsa ALLAH ondan öc alır. ALLAH Üstündür, Öc alandır. Tüm Deniz Hayvanları Helal"},{"n":96,"t":"Deniz hayvanlarını avlamak ve onları yemek size helal kılındı. Size ve yolculara geçimlik olmak üzere... İhramlı bulunduğunuz sürece kara avı size yasaklandı. Huzuruna toplanacağınız ALLAH'ı dinleyin."},{"n":97,"t":"ALLAH, kutsal ev Kabeyi, kutsal ayları, adakları ve onları işaretleyen çelenkleri, insanlar için güvenlik unsuru yaptı. Bilesiniz ki ALLAH göklerde ve yerde olanları biliyor. ALLAH her şeyi Bilir."},{"n":98,"t":"Bilin ki ALLAH'ın cezası çetindir. ALLAH Bağışlayandır, Rahimdir. Elçinin Elçi Olarak Biricik Görevi"},{"n":99,"t":"Elçiye düşen görev sadece duyurmak. ALLAH ise açıkladıklarınızı da gizlediklerinizi de bilir. 100. De : \"Kötü ile iyi bir olmaz; kötünün çokluğu ilgini çekse bile... Akıl sahipleri, başarmak istiyorsanız (azınlığa düşme pahasına da olsa) ALLAH'ı dinleyin.\" Kuran'da Yeralmayan Konularda Özgürsünüz 101. İnananlar, açıklandığı vakit hoşunuza gitmeyecek şeyler hakkında sorular sormayın. Kuran'ın ışığında sorarsanız size açık olurlar. ALLAH özellikle onlardan söz etmedi. ALLAH Bağışlayandır, Yumuşaktır."}]},{"id":6,"name":"ÇİFTLİK HAYVANLARI (EN'AM) SÛRESİ","verses":[{"n":1,"t":"Övgü, gökleri ve yeri yaratan, karanlığı ve ışığı vareden ALLAH'a yaraşır. Buna rağmen, inkarcılar Rab'lerini başkalarıyla denk tutuyor."},{"n":2,"t":"O ki sizi balçıktan yarattı ve sonra yaşam süresi belirledi. Belirlenmiş süre O'nun katındadır. Siz ise hâlâ kuşku duyuyorsunuz."},{"n":3,"t":"O, göklerde ve yerde olan ALLAH. Sizin gizlinizi açığınızı bilir, kazandıklarınızı da bilir. Mucizeleri Görmezler"},{"n":4,"t":"Onlara Rab'lerinin ayetlerinden (delil ve mucizelerinden) hangi bir ayet gelmişse ondan yüz çevirmişlerdir."},{"n":5,"t":"Kendilerine gerçek gelince onu yalanladılar. Alay ettikleri şeyin haberleri yakında kendilerine gelecek."},{"n":6,"t":"Kendilerinden önce nice nesilleri yok ettiğimizi görmüyorlar mı? Sizi yerleştirmediğimiz bir biçimde onları yeryüzüne yerleştirmiştik. Onları nimetlere boğmuş, ülkelerini ırmaklarla donatmıştık. Fakat günahlarından ötürü onları yok ettik ve onlardan sonra başka nesiller yetiştirdik."},{"n":7,"t":"Sana kağıt üzerine yazılı bir kitap indirseydik ve elleriyle dokunsalardı bile, inkarcılar, \"Bu ancak apaçık bir büyüdür,\" diyeceklerdi."},{"n":8,"t":"\"Ona bir melek indirilmeli değil miydi!,\" diyorlar. Bir melek indirseydik, iş bitirilmiş olurdu. Onlara zaman da verilmezdi. Testin Gereklilikleri"},{"n":9,"t":"Onu bir melek yapsaydık, onu bir adam biçiminde gönderir ve mevcut kuşkuları içinde bırakırdık."},{"n":10,"t":"Senden önceki elçiler de eğlence konusu yapılmıştı. Ne var ki, alay edenleri eğlendikleri gerçek kuşatıverdi."},{"n":11,"t":"De: \"Yeryüzünü dolaşın da yalanlayıcıların sonu nasıl olmuş bir bakın.\""},{"n":12,"t":"De: \"Göklerde ve yerde olanlar kimin?\" \"ALLAH'ın,\" de. Kendisine merhametli olmayı gerekli kıldı. Hakkında kuşku olmayan Diriliş Günü sizi toplayacak. Kişiliklerini yitirenler inanmıyanlardır."},{"n":13,"t":"Geceleyinde gündüzünde barınan her şey O'nundur. O İşitendir, Bilendir."},{"n":14,"t":"\"Gökleri ve yeri yoktan var eden, besleyen, fakat beslenmeyen ALLAH'tan başka sahip mi edineyim,\" de. \"Ben, herkesten önce teslim olmakla emrolundum,\" de. Ortak koşmayın!"},{"n":15,"t":"\"Rabbime isyan ettiğim taktirde büyük günün azabından korkarım,\" de."},{"n":16,"t":"O gün kimden azap çevrilirse (Tanrı) ona rahmet etmiştir. En büyük zafer budur. Mutluluğu Sadece Allah Kontrol Eder"},{"n":17,"t":"ALLAH sana bir zarar dokundurmuşsa O'ndan başkası onu gideremez. Sana bir iyilikte bulunmuşsa O her şeye Kadirdir."},{"n":18,"t":"O, kullarına tam anlamıyla egemendir. O Bilgedir, Haber Alandır."},{"n":19,"t":"Sor: \"Kimin tanıklığı büyüktür?\" De ki: \"Benimle sizin aranızda ALLAH tanıktır. Sizi ve ulaştığı herkesi uyarmak için bana bu Kuran verildi. ALLAH'tan başka tanrı olduğuna mı tanıklık ediyorsunuz?\" \"Ben böyle tanıklık etmem,\" de ve ardından şunu da söyle: \"O bir tek tanrı, ben sizin ortak koştuğunuz şeyden uzağım.\""},{"n":20,"t":"Kendilerine kitap verdiklerimiz, çocuklarını tanır gibi bunu tanır. Kişiliklerini yitirenler inanmıyanlardır."},{"n":21,"t":"ALLAH'a iftira eden veya ayetlerini inkar edenden daha zalim kim olabilir? Zalimler başarıya ulaşamaz. Ortak Koşanlar, Müşrik Oluşlarını İnkar Ederler"},{"n":22,"t":"Hepsini topladığımız gün ortak koşanlara, \"Nerede iddia etmekte olduğunuz ortaklarınız?\""},{"n":23,"t":"Onların tek savunması şu olacak: \"Rabbimiz ALLAH'a andolsun ki biz ortak koşmadık.\""},{"n":24,"t":"Kendilerine karşı nasıl yalan söylediklerine dikkat et. Uydurdukları şeyler kendilerini nasıl da terketti. İkiyüzlüler Kuran'ın Mucizesine \"Efsane\" Derler*"},{"n":25,"t":"Onların bir kısmı seni dinler. Fakat, kalpleri üzerine anlamalarına engel olacak örtüler, kulaklarına da ağırlık koyarız. Her bir mucizeyi görseler de ona inanmazlar. Bundan ötürü sana geldiklerinde seninle tartışır ve inkarcılar, \"Bu ancak bir efsanedir,\" der."},{"n":26,"t":"Kendileri uzaklaştıkları gibi başkasını da ondan menediyorlar. Böylece farkında olmadan kendilerini mahfediyorlar."},{"n":27,"t":"Ateşin başında durduruldukları vakit onların \"Keşke geri döndürülseydik de Rabbimizin ayetlerini (vahiy ve mucizelerini) inkar etmeseydik ve inananlardan olsaydık,\" dediklerini bir görsen!"},{"n":28,"t":"Daha önce gizledikleri ortaya çıktığı için (bu itirafı yapıyorlar). Geri döndürülselerdi, yine menedildikleri şeye dönerlerdi. Yalan söylüyorlar."},{"n":29,"t":"\"Bizim için sadece dünya hayatı vardır, diriltilecek değiliz,\" diyorlardı."},{"n":30,"t":"Rablerinin huzurunda durdurulmuş halde onları bir görsen! \"Bu doğru değil mi,\" diyecek. \"Evet, Rabbimize and olsun doğru,\" diyecekler. \"İnkar etmenizden ötürü azabı tadın,\" diyecek."},{"n":31,"t":"Kaybedenler, ALLAH ile karşılaşmayı yalanlayanlardır. O an (dünyanın sonu) kendilerini ansızın yakalayınca, günah yüklerini sırtlarında taşıyarak, \"Oradaki hayatımızı boşa harcamamızdan ötürü vay halimize,\" diyecekler. Yüklendikleri şey ne de kötü! Öncelik Listemizi Yeniden Düzenlemeli"},{"n":32,"t":"Dünya hayatı ancak bir oyun ve eğlence. Erdemliler için ahiret yurdu daha hayırlı. Düşünmez misiniz?"},{"n":33,"t":"Söyledikleri şeylerin seni üzdüğünü biliyoruz. O zalimler seni değil ALLAH'ın ayetlerini reddediyor."},{"n":34,"t":"Senden önceki elçileri de yalancılıkla suçladılar. Yalanlanmalara karşı direndiler. Zaferimiz ulaşıncaya dek sıkıntı çektiler. ALLAH'ın sistemi değişmeyecek. Nitekim elçilerin tarihi sana ulaşmış bulunuyor. Elçiye Uyarı: Cahilce Davranma!"},{"n":35,"t":"Yüz çevirmeleri sana ağır geldiyse, bilesin ki, yerin içine bir delik açmaya ya da göğe merdiven dayamaya gücün yetse de bir mucize ortaya koysan yine kâr etmez.. ALLAH dileseydi onları doğru yola toplardı. Öyleyse cahillerden olma."},{"n":36,"t":"Ancak dinleyenler yönelir. Ölüleri ALLAH diriltir, sonra da herşey O'na döndürülür. 37. \"Ona Rabbinden bir ayet (mucize) inmeli değil miydi!,\" diyorlar. De ki: \"ALLAH istediği an bir ayet indirebilir; fakat çoğu bunu bilmez.\" Herşey Kitapta Kayıtlı"},{"n":38,"t":"Kanatlarıyla uçan kuşlar dahil yeryüzündeki tüm yaratıklar sizin gibi birer toplum. Biz kitapta hiçbir şeyi eksik bırakmadık. Sonra onlar (tüm yaratıklar) Rab'lerinin huzuruna toplanacak."},{"n":39,"t":"Ayetlerimizi yalan diyenler karanlıklar içinde bulunan birer sağır ve dilsizdirler. ALLAH kimi dilerse saptırır, kimi de dilerse doğru yola koyar."},{"n":40,"t":"De: \"Doğruysanız söyleyin bakalım, size ALLAH'ın azabı, yahut Saat (dünyanın sonu) gelse, ALLAH'tan başkasına mı yalvarırsınız?\""},{"n":41,"t":"Doğrusu, yalnız O'na yalvarırsınız. Dilerse yalvardığınız konudaki probleminizi giderir, siz de ortak koştuklarınızı unutursunuz."},{"n":42,"t":"Senden önceki toplumlara da elçiler gönderdik. Yalvarsınlar diye onları darlık ve sıkıntılarla sınadık."},{"n":43,"t":"Hiç olmazsa başlarına musibetimiz geldiğinde yalvarsalardı! Fakat kalpleri katılaştı ve şeytan işlerini kendilerine süslü gösterdi. Sistem"},{"n":44,"t":"Kendilerine iletilen mesajı unuttuklarında kendilerine her şeyin kapısını ardına kadar açtık. Kendilerine verilenlerle şımarınca onları ansızın yakaladık ve böylece şaşkın ve umutsuz kaldılar."},{"n":45,"t":"Zulmeden topluluğun ardı böyle kesilir. Övgü, evrenlerin Rabbi ALLAH'a yaraşır. Tanrı'dan Başkası Kulluk Edilmeğe Layık Değil"},{"n":46,"t":"De: \"Bir düşünün, ALLAH sizin işitme ve görme duyunuzu alıp belleğinizi kapasa, ALLAH'tan başka hangi tanrı onları size geri verebilir?\" Ayetleri nasıl açıkladığımıza ve buna rağmen nasıl da yüz çevirdiklerine dikkat et!"},{"n":47,"t":"De: \"ALLAH'ın azabı size ansızın veya duyurudan sonra gelse... Zalim toplumdan başkası mı yok edilir?\" Elçinin Biricik Görevi"},{"n":48,"t":"Biz elçileri, ancak müjdeleyiciler ve uyarıcılar olarak gönderiyoruz. Kim inanıp kendini düzeltirse, onlara bir korku yok, onlar üzülmeyecekler de."},{"n":49,"t":"Ayetlerimizi yalanlayanlara gelince, yoldan çıktıklarından ötürü onlara azap dokunacak."},{"n":50,"t":"De: \"ALLAH'ın hazineleri benim yanımda demiyorum size. Gizlilikleri de bilmiyorum. Size, bir melek olduğumu da söylemiyorum. Sadece bana vahyedileni izliyorum.\" Şunu da söyle: \"Kör ile gören bir mi?\""},{"n":51,"t":"Rab'lerinin huzuruna çıkacaklarının heyecanıyla dolanları onunla (Kuran'la) uyar: O'ndan başka bir sahipleri ve şefaatçıları (aracıları) yok. Belki korunurlar."},{"n":52,"t":"Sabah akşam Rab'lerine yalvarıp sadece O'nun hoşnutluğunu arzulayanları kovma. Onların hesabından sen sorumlu değilsin. Senin hesabından da onlar sorumlu değil. Onları kovarsan zalim olursun. İnananları Küçük Görme Hastalığı"},{"n":53,"t":"Birbirinizle böylece sınadık ki \"ALLAH'ın aramızdan seçip nimetlendirdiği kişiler bunlar mı,\" desinler. ALLAH güzel karşılık verenleri daha iyi bilmiyor mu!"},{"n":54,"t":"Ayetlerimize inananlar sana gelince, \"Size selam olsun. Rabbiniz merhametli davranmayı prensip edindi. Bunun için, her kim bilmeyerek işlediği bir kötülükten sonra tevbe ederek kendini düzeltirse, bilsin ki O Bağışlayandır, Rahimdir.\""},{"n":55,"t":"Suçluların yolunun besbelli olması için ayetleri böyle açıklarız. Muhammed Ortak Koşmaktan Menediliyor"},{"n":56,"t":"De: \"ALLAH'ın dışında çağırdıklarınıza tapmaktan menedildim.\" De: \"Sizin keyfinize uymayacağım. Aksi taktirde sapar ve doğru yolu bulamam.\""},{"n":57,"t":"De: \"Ben Rabbimden bir delile dayanmaktayım. Siz ise onu yalanladınız. Ona meydan okuyarak istediğiniz şeyi getirmek benim elimde değil. Hüküm, ancak ve ancak ALLAH'ın. Gerçeği anlatıyor. O, en iyi ayırandır."},{"n":58,"t":"De: \"Sizin acele istediğiniz şeye sahip olsaydım aramızda iş biterdi. ALLAH zalimleri iyi biliyor.\" Allah: Egemenliğin Mutlak Sahibi"},{"n":59,"t":"Gizliliklerin anahtarı onun elinde. O'ndan başkası onları bilmez. Karada ve denizde ne varsa onları bilir. Bilgisi dışında bir yaprak bile düşmez. Yerin karanlığında bir tane, yaş veya kuru hiçbir şey yok ki apaçık bir kitapta kayıtlı olmasın."},{"n":60,"t":"O'dur, geceleyin sizi öldüren, gündüzün ne işlediğinizi bilen, belli yaşam süresi dolsun diye gündüzleyin sizi dirilten... Sonra dönüşünüz O'nadır ve yaptıklarınızı size haber verecektir."},{"n":61,"t":"O, kulları üzerinde egemendir ve üzerinize koruyucu melekler gönderir. Sizden birine ölüm geldiği zaman elçilerimiz onun canını hiç vakit geçirmeden alırlar.*33"},{"n":62,"t":"Sonra gerçek Mevlaları olan ALLAH'a döndürülürler. Bilesiniz ki yargı O'nundur ve O, en hızlı hesap görendir."},{"n":63,"t":"De ki: \"Gizli ve açık olarak 'Bizi bundan kurtarsan şükredenlerden olacağız.' diye O'na yalvardığınızda sizi karanın ve denizin karanlıklarından kim kurtarabilir?\""},{"n":64,"t":"De ki: \"Ondan ve bütün sıkıntılardan sizi ALLAH kurtarıyor. Buna rağmen siz yine ortak koşuyorsunuz.\" Mezheplere Bölünmek Tanrı'dan Bir Cezadır"},{"n":65,"t":"De ki: \"Üstünüzden veya ayaklarınızın altından size bir azap göndermeğe, yahut sizleri mezheplere bölüp birbirinizin kötülüğünü tattırmağa O'nun gücü yeter.\" Bak, anlasınlar diye ayetlerimizi nasıl da açıklıyoruz. Kuran'ın Bazı Haberleri İleride Bilinecek"},{"n":66,"t":"Gerçek olmasına rağmen senin halkın bunu yalanladı. De ki: \"Ben üzerinizde gözetici değilim.\""},{"n":67,"t":"Her bir haberin gerçekleşeceği bir zaman vardır. İleride bilecekler. Tanrı'nın Sözüne Saygı"},{"n":68,"t":"Ayet ve mucizelerimizle alay edenleri gördüğün vakit, başka bir söze dalıncaya kadar onlardan yüz çevir. Şeytan sana unutturursa, hatırladıktan sonra böyle zalim kimselerle birlikte oturma."},{"n":69,"t":"Erdemliler böylelerin hesabından sorumlu tutulmaz. Fakat, olur ki dinlerler diye hatırlatmak iyi olur."},{"n":70,"t":"Dinlerini oyun eğlenceye alanları ve dünya hayatına aldananları bırak. Sen bununla (Kuran'la) hatırlat ki, bir kişi kazandığının felaketli sonucunu çekmesin. Onun ALLAH'tan başka bir Sahibi ve Şefaatçisi yoktur. Her türlü fidyeyi verse bile kendisinden kabul edilmez. Bunlar, kazandıklarından dolayı felaketli sonuca uğrayanlarlardır; inkarları yüzünden kaynar sudan bir içkiyi ve acı verici bir azabı hakketmişlerdir."},{"n":71,"t":"De ki: \"ALLAH'tan başka, bize yarar ve zarar veremiyenlere mi yalvaralım? ALLAH bizi doğru yola ulaştırdıktan sonra ökçelerimiz üzerinde gerisin geriye mi dönelim? Şeytanların ayartıp yeryüzünde şaşırttığı ve arkadaşlarının, 'Gel, bizimle birlikte doğru yola gel' diye çağırdıkları şaşkın bir kimse gibi mi olalım?\" De ki: \"Gerçek yol gösterme ALLAH'ın yol göstermesidir. Evrenlerin Rabbine teslim olmakla emredildik.\""},{"n":72,"t":"\"Namazı gözetmeli ve O'nu sayıp dinlemelisiniz. Huzurunda toplanacağınız O'dur.\""},{"n":73,"t":"O'dur gökleri ve yeri yaratan. \"Ol,\" dediği gün hemen oluverir. Sözü mutlak doğrudur. Boruya üfürüldüğü gün egemenlik tümüyle O'nundur. Gizliyi ve açığı Bilendir. Bilgedir, herşeyden Haberdardır. İbrahim, Allah Konusunda Halkıyla Tartışıyor"},{"n":74,"t":"İbrahim, babası Azer'e şöyle demişti: \"Heykelleri mi tanrı ediniyorsun? Seni ve halkını tümüyle apaçık bir sapıklık içinde görüyorum.\""},{"n":75,"t":"Kesin bir inanca sahip olması için, İbrahim'e göklerin ve yerin yönetimini şöylece gösterdik:"},{"n":76,"t":"Üzerine gece basınca bir gezegen gördü, \"Budur benim Rabbim!,\" dedi. Batınca, \"Ben batanları sevmem,\" dedi."},{"n":77,"t":"Ay'ı doğarken görünce, \"Budur benim Rabbim!,\" dedi. Batınca da, \"Rabbim bana doğru yolu göstermezse sapıtanlardan olurum,\" dedi."},{"n":78,"t":"Güneşi doğarken görünce, \"Budur benim Rabbim. Bu, daha büyük!,\" dedi. O da batınca: \"Ey halkım, ben sizin ortak koştuğunuz şeylerden uzağım,\" dedi."},{"n":79,"t":"Ben yüzümü tümüyle, gökleri ve yeri yaratana çevirdim ve ben ortak koşanlardan değilim."},{"n":80,"t":"Halkı onunla tartıştı. \"Beni doğruya ulaştırmış iken benimle hâlâ ALLAH hakkında mı tartışıyorsunuz? Sizin ortak koştuklarınızdan korkmam, meğer Rabbim bir şey dilerse... Rabbim, bilgice her şeyi kuşatmıştır. Öğüt almıyor musunuz?\""},{"n":81,"t":"\"ALLAH'ın kendileri hakkında size hiç bir delil vermediklerini O'na ortak koşmaktan korkmuyorsunuz da ben nasıl olur da sizin ortak koştuklarınızdan korkarım? Hangi taraf güvenliği daha çok hakketmektedir? Bir bilseniz!\""},{"n":82,"t":"İnananlar ve imanlarını bir zulümle bulaştırmayanlar güvenliği hakketmişlerdir ve onlar doğruyu bulmuşlardır."},{"n":83,"t":"Bunlar, halkına karşı kullanması için İbrahim'e verdiğimiz tartışma yöntemidir. Dilediğimizi derecelerle yükseltiriz. Rabbin Bilgedir, Bilendir."},{"n":84,"t":"Ona İshak'ı ve Yakub'u bağışladık. Her birisine yol gösterdik. Daha önce de Nuh'a ve onun soyundan Davud'a, Süleyman'a, Eyyub'a, Yusuf'a, Musa'ya ve Harun'a da yol gösterdik. Güzel davrananları işte böyle ödüllendiririz."},{"n":85,"t":"Zekeriyya, Yahya, İsa ve İlyas'a da... Hepsi de iyilerden idi."},{"n":86,"t":"İsmail, El-Yasa', Yunus ve Lut'a da... Hepsini halklara üstün kıldık."},{"n":87,"t":"Atalarından, soylarından, kardeşlerinden bir çoğunu seçip doğru yola ilettik."},{"n":88,"t":"ALLAH'ın hidayeti böyledir. Kullarından dilediğini ve/veya dileyeni ona ulaştırır. Ortak koşsalardı yaptıkları boşa çıkardı."},{"n":89,"t":"İşte onlar, kendilerine kitap, hikmet ve peygamberlik verdiklerimizdir. Eğer şu halk, bunları inkar ederse, biz onları inkar etmeyecek bir toplumu yerlerine geçiririz."},{"n":90,"t":"Bunlar, ALLAH'ın doğru yola ulaştırdıklarıdır. Onların yoluna uy. De ki: \"Ben buna karşılık sizden bir ücret istemiyorum. Bu, sadece tüm halklara bir mesajdır.\" Tanrı'nın Dünya Halkına Mesajı"},{"n":91,"t":"\"ALLAH hiç bir insana bir şey indirmez,\" demekle ALLAH'ı gereği gibi değerlendirmediler. De ki: \"Halka bir hidayet ve ışık olarak Musa'nın getirdiği kitabı kim indirdi -ki göstermek için onu kağıtlara yazdığınız halde çoğunu gizliyordunuz. Sizin ve atalarınızın bilmediği şeyleri onun yoluyla öğrendiniz-?\" \"ALLAH\" de ve onları daldıkları sapıklıkta bırak, oynayadursunlar."},{"n":92,"t":"Bu, kendisinden öncekileri doğrulayan kutlu bir kitap olup ülkelerin anasını ve etrafındakileri uyarman için indirilmiştir. Ahirete inananlar ona inanırlar ve onlar namazlarına da devam ederler."},{"n":93,"t":"ALLAH adına yalan uydurandan ve kendisine hiç bir şey vahyedilmediği halde, \"Bana vahyediliyor,\" diyenden ve \" ALLAH'ın indirdiği gibi ben de indireceğim,\" diyenden daha zalim kim olabilir! Can çekişmesi anında zalimleri bir görsen! Melekler, ellerini uzatmıştır: \"Canınızı verin! ALLAH hakkında gerçek olmayanı söylemenizden ve onun ayetlerini (vahyini ve mucizelerini) kibir ve gururla karşılamanızdan dolayı bugün utanç verici azapla cezalandırılacaksınız. \" Şefaat Bekleyen Putperestlere Uyarı"},{"n":94,"t":"\"Sizi ilk defa yarattığımız gibi bize tek olarak geldiniz. Size hayal gibi gösterdiğimiz şeyleri ardınızda bıraktınız. Hakkınızda (verilecek kararda Tanrı ile) ortak davranacaklarını ileri sürdüğünüz şefaatçılarınızı yanınızda görmüyoruz. Aranızdaki bağlar kesilmiştir. İleri sürdükleriniz sizi terketmiştir.\" Tanrı'nın Büyüklüğü"},{"n":95,"t":"ALLAH taneyi ve çekirdeği yarıp filizlendirendir. Ölüden diriyi çıkarır ve diriden de ölüyü çıkarandır. İşte budur ALLAH. Nasıl yüz çevirebilirsiniz!"},{"n":96,"t":"Sabahı ortaya çıkarandır. Geceyi dinlenme zamanı, güneşi ve ay'ı da bir hesaplama aracı yapmıştır. Bu, her şeyden Üstün ve her şeyi Bilen'in planıdır."},{"n":97,"t":"Karanın ve denizin karanlıklarında yollarınızı bulasınız diye sizin için yıldızları yaratan O'dur. Bilen bir toplum için ayetleri detaylı olarak açıklamış bulunuyoruz."},{"n":98,"t":"O'dur sizi bir tek kişiden inşa eden. Nitekim bir karar kılmayı bir ayrılış izler. Ayetleri, anlayan bir toplum için açıklamışızdır."},{"n":99,"t":"O'dur gökten su indiren. Onunla her çeşit bitkiyi çıkardık. O bitkiden ürettiğimiz yeşil madde ile de sayısız taneler çıkardık. Tomurcuğundan salkımlar sarkan hurma ağaçları, üzüm bağları, zeytin ve nar gibi birbirine benzeyen ve benzemeyen ürünler çıkardık. Her birinin meyve verme zamanında meyvesine ve olgunluğuna bakın. İnanan bir toplum için bunda deliller ve ibretler vardır. 100. ALLAH'a cinleri ortak koştular. Halbuki onları O yaratmıştır. Bilmeden O'na oğullar ve kızlar yakıştırdılar. O'nun şanı yücedir, onların nitelemelerinden çok üstündür. 101. Gökleri ve yeri yoktan var edendir. Eşi olmadığı halde nasıl olur da çocuğu olur? Herşeyi O yaratmıştır ve O, herşeyi bilendir. 102. Rabbiniz ALLAH işte budur. O'ndan başka tanrı yoktur. Herşeyin Yaratıcısıdır. O'na kulluk edin. O, herşeyi Kontrol Edendir. 103. Gözler O'na erişemez O, gözlere erişir. O Şefkatlidir, Haberdardır. 104. Rabbinizden size aydınlatıcı bilgiler gelmiş bulunuyor. Kim görürse kendi yararına, kim körlük ederse kendi zararınadır. Ben üzerinize bekçi değilim. 105. \"Sen ders almışsın,\" demeleri için ve bilen bir topluma açıklamak için ayetleri böyle sergiliyoruz. 106. Rabbinden sana indirilene uy. O'ndan başka tanrı yoktur. Ortak koşanlardan da yüz çevir. 107. ALLAH isteseydi ortak koşamazlardı. Seni onların üzerine bekçi yapmadık. Onların avukatı da değilsin. Seviyesiz Tartışmalara Girmeyin 108. ALLAH'ın dışında yalvardıklarına sövmeyiniz ki onlar da sınırı aşıp cehaletten dolayı ALLAH'a sövmesinler. Biz her topluluğa yaptıkları işi böyle süslü gösterdik. Sonunda dönüşleri Rab'lerinedir ve onlara yapmış bulunduklarını haber verir. Önyargılı Fanatikler Mucizeleri Göremezler 109. Kendilerine bir mucize gelse ona mutlaka inanacaklarına dair tüm güçleriyle ALLAH'a yemin ederler. De ki: \"Mucizeler ALLAH'ın yanındadır.\" Mucize geldiği zaman da onların inanmıyacağını bilmez misiniz? 110. İlk başta inanmamaya karar verdikleri için anlaklarını ve gözlerini çevirip azgınlıkları içinde bocalar durumda bırakırız."}]},{"id":7,"name":"ORTA YER (ARAF) SÛRESİ","verses":[{"n":1,"t":"A.L.M.SS."},{"n":2,"t":"Bu, sana indirilen bir kitaptır. Onunla uyarman ve inananlara öğüt vermen konusunda göğsünde bir kuşku ve sıkıntı olmasın. Kuran'dan Başka Kaynakları İzlemeyin"},{"n":3,"t":"Rabbinizden size indirileni izleyin, O'ndan başkalarını dost edinerek izlemeyin. Ne kadar az öğüt alıyorsunuz!"},{"n":4,"t":"Yok ettiğimiz nice topluluklar, uyurlarken yahut gündüzün işlerine dalmış haldeyken azabımız kendilerine ulaştı. Sorguya Çekileceksiniz"},{"n":5,"t":"Kendilerine azabımız geldiği vakit, \"Gerçekten bizler zalimler imişiz,\" demekten başka sözleri olmadı."},{"n":6,"t":"Kendilerine mesaj gönderilenleri de sorguya çekeceğiz, elçileri de sorguya çekeceğiz."},{"n":7,"t":"Onlara bir bilgiyle bildireceğiz; biz onlardan hiç uzak kalmadık."},{"n":8,"t":"O gün tartı dosdoğrudur. Tartıları ağır gelenler başarmış olanlardır."},{"n":9,"t":"Tartıları hafif gelenler ise ayetlerimize karşı haksız davranarak kişiliklerini yitirmiş olanlardır.*35"},{"n":10,"t":"Sizleri yeryüzüne yerleştirdik ve orada size yaşama imkânları sağladık. Ne kadar da az şükrediyorsunuz. Test Başlıyor"},{"n":11,"t":"Sizi yarattık, sonra size biçim verdik, sonra meleklere, \"Adem'e secde edin,\" dedik. İblis hariç hepsi secde etti; o secde edenlerden olmadı."},{"n":12,"t":"Dedi: \"Sana emrettiğim zaman seni secde etmekten ne alıkoydu?\" (İblis:) \"Ben ondan daha iyiyim; Sen beni ateşten yarattın, onu ise balçıktan yarattın,\" dedi."},{"n":13,"t":"\"Oradan aşağı in,\" dedi, \"Orada büyüklük taslayamazsın. Defol. Değerini yitirdin!\""},{"n":14,"t":"\"Dirilecekleri güne kadar bana süre tanı,\" dedi."},{"n":15,"t":"\"Sana süre tanınmıştır,\" dedi."},{"n":16,"t":"\"Beni saptırmana karşılık, onlar için senin dosdoğru yolun üzerine sinsice oturacağım.\""},{"n":17,"t":"\"Sonra önlerinden, arkalarından, sağlarından ve sollarından kendilerine sokulacağım. Böylece çoklarını şükreder bulmayacaksın.\""},{"n":18,"t":"Dedi ki: \"Horlanmış ve kovulmuş olarak oradan çık. Onlardan sana uyanlara gelince, hepinizle cehennemi dolduracağım.\""},{"n":19,"t":"\"Adem, sen ve eşin cennette durup dilediğiniz yerden yeyin. Şu ağaçtan yemeyin; yoksa zalimlerden olursunuz.\""},{"n":20,"t":"Şeytan, kendilerinden gizlenmiş olan bedenlerini ortaya çıkarmak için onlara fısıldadı: \"Rabbinizin sizi bu ağaçtan menetmesinin sebebi, ikinizin birer melek veya birer ebedi varlık olmamanız içindir,\" dedi."},{"n":21,"t":"Kendilerine yemin de etti: \"Ben size öğüt veriyorum.\""},{"n":22,"t":"Böylece onları yalanlarla aldattı. Ağacı tadınca bedenleri kendilerine göründü. Üzerlerini cennet yapraklarıyla örtmeye başladılar. Rableri kendilerini çağırdı: \"O ağaçtan ikinizi menetmedim mi ve şeytanın ikinize düşman olduğunu söylemedim mi?\" * 7:22 Bak 7:26."},{"n":23,"t":"Her ikisi: \"Rabbimiz, kendimize zulmettik. Bizi bağışlamaz ve bize acımazsan kaybedenlerden oluruz,\" dediler."},{"n":24,"t":"Dedi ki: \"Birbirinize düşmanlar olarak aşağı ininiz. Bir süreye kadar yeryüzünde yerleşip geçineceksiniz.\""},{"n":25,"t":"Dedi ki: \"Orada yaşayacak, orada ölecek ve oradan çıkarılacaksınız.\""},{"n":26,"t":"Adem oğulları, size, bedenimizi örtecek ve süsleyecek elbiseler hazırladık. Erdemlilik elbisesi ise daha hayırlıdır. Bunlar, ALLAH'ın işaretleridir, olur ki öğüt alırsınız. * 7:26 Her ne hikmetse geleneksel yorumcular burada \"beden\" olarak çevirdiğimiz kelimeyi \"çirkin yerler\" olarak çevirmekte ve bunu cinsel organlar anlamında kullanmaktadırlar. Cennette işlediğimiz günah sonucu bedenlenmemiz olumsuz bir olaydı; ama, bedenimizin en önemli ve en \"ilginç\" parçalarından biri olan cinsel organları \"çirkin yerler\" olarak tanımlamak yanlıştır. Allah bizi güzel bir biçimde yarattı; cinsel organlarımız dahil. \"Beden\" veya \"vücut\" diye çevrilmesi gerektiğine inandığımız \"SeVeT\" kelimesinin geçtiği diğer ayetler için bak 5:31; 7:20, 22, 27; 20:121."},{"n":27,"t":"Adem oğulları, şeytan, ana babanızın vücutlarını kendilerine göstermek için elbiselerini soyarak cennetten çıkardığı gibi sizi de şaşırtmasın. O ve kabilesi sizin onları görmediğiniz yerden sizi görürler. Biz, şeytanları, inanmıyanların dostları yaptık. Geleneksel İnanç ve Bilgileri Sınamalısınız."},{"n":28,"t":"Herhangi bir kötü şey işledikleri zaman, \"Atalarımızı böyle yapar bulduk; ALLAH da bize öyle emretti,\" derler. De ki: \"ALLAH kötü bir şeyi emretmez. ALLAH hakkında nasıl olur da bilmediklerinizi söylersiniz?\""},{"n":29,"t":"De ki: \"Rabbim adaleti emreder. Her mescitte (ibadet yerinde) dini sadece O'na ait kılarak O'na yalvarın. Sizi ilk yarattığı gibi O'na döneceksiniz.\" * 7:29 Bak 2:139; 39:2, 11, 14; 40:14, 65; 98:5."},{"n":30,"t":"Bir grubu doğru yola iletti, bir grup da sapıklığı hakketti. Onlar, şeytanları ALLAH'tan başka dostlar edindiler ama kendilerini doğru yolda sanıyorlar. Mescitlere Temiz ve Güzel Elbiselerinizle Gidin, Obur ve Savurgan Olmayın"},{"n":31,"t":"Adem oğulları, mescitlere giderken süsleniniz. Yiyiniz içiniz; ancak oburluk ve savurganlık yapmayınız. O, oburları ve savurganları sevmez. Altın İpek Gibi Süs Eşyalarını Yasaklama Bidati"},{"n":32,"t":"De ki: \"ALLAH'ın, kendi kulları için yarattığı süsleri ve güzel rızıkları kim haram edebilir?\" De ki: \"Onlar dünya hayatında inananlar içindir, ahirette ise sadece onlar içindir.\" Bilen bir toplum için ayetlerimizi böyle detaylı açıklarız."},{"n":33,"t":"De ki: \"Rabbim, ancak kötü işlerin açığını ve gizlisini, günahları, haksız yere saldırmayı, kendilerine hiç bir otorite ve güç vermediği bir şeyi ALLAH'a ortak koşmanızı ve ALLAH hakkında bilmediğiniz şeyleri söylemenizi haram kılmıştır.\""},{"n":34,"t":"Her bir toplumun bir süresi vardır. Süreleri gelince ne bir an erteleyebilirler, ne de öne alabilirler."},{"n":35,"t":"Adem oğulları, size içinizden elçiler gelip size ayetlerimi bildirdikleri zaman dinleyip kendilerini düzeltenlere ne bir korku vardır ne de onlar üzülürler."},{"n":36,"t":"Büyüklük taslayarak ayetlerimizi yalanlayanlar ise ateş halkıdır; orada ebedi kalıcıdırlar. İnsanların En Kötüleri"},{"n":37,"t":"ALLAH'a yalan iftira edenden veya ayetlerini yalanlayandan daha zalim kim olabilir? Onların kitapta anlatılan payları kendilerine erişecektir. Elçilerimiz kendilerine gelip canlarını alırken: \"ALLAH'ın dışında taptıklarınız nerede,\" dediklerinde, \"Bizi terkettiler,\" derler. İnkarcı olduklarına dair kendi aleyhlerinde tanıklık ederler. Karşılıklı Suçlama"},{"n":38,"t":"\"Sizden önce geçen cin ve insan topluluklarıyla birlikte ateşe girin,\" dedi. Her ne zaman bir topluluk girdiyse bir öncekine lanet etti. Hepsi oraya vardığında sonrakiler öncekiler için: \"Rabbimiz, bizi bunlar saptırdı. Bunlara ateşten bir kat daha fazla azap ver,\" dediler. \"Hepsi için iki kat vardır. Ancak bilmezsiniz,\" dedi."},{"n":39,"t":"Öncekiler sonrakilere, \"Sizin bize bir üstünlüğünüz yoktur. Kazandıklarınızdan ötürü azabı tadın,\" dediler. Delilleri Inkar Edenler"},{"n":40,"t":"Ayetlerimizi inkar edenlere ve onlara karşı büyüklük taslayanlara göğün kapısı açılmaz ve deve iğne deliğinden geçmedikçe de cennete girmezler. Suçluları böyle cezalandırırız."},{"n":41,"t":"Onlar için cehennemden bir yatak ve üstlerinde de bir örtü vardır. Zalimleri işte böyle cezalandırırız."},{"n":42,"t":"İnanıp erdemli bir hayat sürenlere gelince, biz hiç kimseye kapasitesinin üstünde sorumluluk yüklemeyiz; onlar cennet halkıdır. Onlar orada ebedi kalıcıdırlar."},{"n":43,"t":"Göğüslerinden kin ve kıskançlık duygularını çıkardık. Altlarından nehirler akarken: \"Bizi buna ulaştıran ALLAH'a övgüler olsun. ALLAH bizi doğruya iletmeseydi biz doğruyu bulamazdık. Rabbimizin elçileri gerçeği getirmişlerdi,\" dediler. Kendilerine : \"İşte bu cennet sizindir. Yaptıklarınıza karşılık olarak onu miras aldınız,\" diye seslendik Cennet ve Cehennem Halkı Arasındaki Diyalog"},{"n":44,"t":"Cennet halkı cehennem halkına seslenir: \"Rabbimizin bize söz verdiğini gerçek olarak bulduk. Rabbinizin size söz verdiğini siz de gerçek olarak buldunuz mu?\" \"Evet!,\" derler. Biri aralarında şunu ilan eder: \"ALLAH'ın laneti zalimlerin üzerine olsun.\""},{"n":45,"t":"Onlar ki ALLAH'ın yolundan alıkoyarlar ve onu eğriltmek isterler. Ahiret konusunda da inkarcıdırlar. Cennet ile Cehennemin Ortasında Kalanlar"},{"n":46,"t":"Aralarını bir perde böler. Orta yerde de bazı kimseler var ki herkesi görünüşlerinden tanırlar. Cennet halkına, \"Selam size,\" diye seslenirler. Bunlar oraya (cennete), canları istedikleri halde giremediler."},{"n":47,"t":"Gözleri ateş halkına çevrildiğinde, \"Rabbimiz, bizi zalim toplulukla birlikte bulundurma,\" derler."},{"n":48,"t":"Orta yerde bulunanlar, görünüşlerinden tanıdıkları kimselere seslenirler: \"Sizin cemaatiniz ve büyüklük taslamış olmanız size hiç bir yarar sağlamadı.\""},{"n":49,"t":"\"ALLAH onlara bir rahmet dokundurmayacak diye yemin ettiğiniz kimseler bunlar mıydı?\" (Orta Yerdekilere şunlar denecektir:) \"Cennete girin; size bir korku yoktur ve üzülmeyeceksiniz de.\"*36"},{"n":50,"t":"Ateş halkı, cennet halkına seslendi: \"Suyunuzdan, yahut ALLAH'ın size verdiği bazı nimetlerden üstümüze akıtın.\" Onlar da dediler ki: \"ALLAH bu ikisini kafirlere haram kılmıştır.\""},{"n":51,"t":"Onlar dinlerini hafife aldılar ve dünya hayatı kendilerini aldattı. Bugünleriyle karşılaşacaklarını unuttukları ve ayetlerimizi reddettikleri için bugün biz de onları unuturuz! Kuran: Tanrı'nın Bilgisiyle Detaylandırılmış * 7:52 Bak 11:1."},{"n":52,"t":"Bilgiyle detaylandırdığımız, inanan bir toplum için yol gösterici ve rahmet olan bir kitabı onlara getirdik."},{"n":53,"t":"Onun haberlerinin gerçekleşmesini mi bekliyorlar? Haberleri gerçekleştiği gün, onu daha önce önemsemeyenler, \"Rabbimizin elçileri gerçeği getirmişlerdi. Bizim için aracılık edecek bir şefaatçı var mı? Yahut, öncekinden farklı davranmak için geri gönderilsek,\" derler. Kişiliklerini yitirmişlerdir ve uydurdukları şeyler de onları terketmiştir. Evrenlerin Rabbi Allah En Yücedir"},{"n":54,"t":"Rabbiniz ALLAH, gökleri ve yeri altı günde yaratan*37 ve sonra otoritesini kurandır. Geceyi, onu durmadan kovalayan gündüze bürüyüp örter. Güneş, ay ve yıldızlar O'nun yönetimine boyun eğmiştir. Yaratılış da, yönetim de O'na aittir. Evrenlerin Rabbi olan ALLAH ne uludur!"},{"n":55,"t":"Rabbinizi içtenlikle ve gizlice çağırın. O, sınırı aşanları sevmez."},{"n":56,"t":"Düzeltildikten sonra yeryüzünde bozgunculuk yapmayın. O'na korku ve umutla yalvarın. ALLAH'ın rahmeti güzel davrananlara yakındır."},{"n":57,"t":"O, rahmetinin bir ön müjdesi olarak rüzgarları gönderendir. Toplanıp yüklendikten sonra ağır bulutları ölü bir toprağa süreriz. Onunla su indirir ve onunla her çeşit ürünü çıkarırız. Ölüleri de böyle çıkarırız. Belki bundan bir öğüt alırsınız."},{"n":58,"t":"İyi arazi, Rabbinin izniyle bitki verir. Kötü olanı ise, pek yararlı bir şey vermez. Şükreden bir topluluk için ayetleri böyle açıklarız. Nuh"},{"n":59,"t":"Nuh'u halkına gönderdik: \"Ey halkım, ALLAH'a kulluk edin. O'ndan başka bir tanrınız yoktur. Sizin için büyük günün azabından korkarım,\" dedi."},{"n":60,"t":"Halkının ileri gelenleri, \"Seni apaçık bir sapıklık içinde gürüyoruz,\" dediler."},{"n":61,"t":"Dedi ki: \"Halkım, bende bir sapıklık yoktur; ancak ben evrenlerin Rabbi tarafından gönderilmiş bir elçiyim.\""},{"n":62,"t":"\"Size Rabbimin mesajını iletiyor ve size öğüt veriyorum. Sizin bilmediklerinizi ALLAH aracılığıyla biliyorum.\""},{"n":63,"t":"\"Sizi uyarmak için ve erdemli bir hayat sürüp merhamet edilmeniz için sizden bir adama Rabbinizden bir mesajın gelmesine mi şaştınız?\""},{"n":64,"t":"Onu yalanladılar. Bunun üzerine onu ve gemide beraberinde bulunanları kurtardık. Ayetlerimizi yalanlayanları ise boğduk. Onlar kör bir halktı. Hud"},{"n":65,"t":"Ad halkına da kardeşleri Hud'u gönderdik. \"Halkım, ALLAH'a kulluk edin. O'ndan başka bir tanrınız yoktur. Erdemli olmayacak mısınız,\" dedi."},{"n":66,"t":"Halkından ileri gelen inkarcılar, \"Biz seni beyinsizlik içinde görüyoruz. Biz seni yalancı sanıyoruz.\""},{"n":67,"t":"Dedi ki: \"Ey halkım, ben beyinsiz değilim; fakat ben, evrenlerin Rabbinden bir elçiyim.\""},{"n":68,"t":"\"Size Rabbimin mesajını iletiyorum. Sizin için güvenilir bir öğütçüyüm.\""},{"n":69,"t":"\"Sizi uyarmak amacıyla Rabbinizden bir mesajın aranızdan bir adama gelmesine mi şaştınız? Nuh'un halkından sonra sizi varisler yaptığını ve yaratılışta sizi onlardan güçlü kıldığını hatırlayın. Başarmanız için ALLAH'ın nimetlerini düşünün.\""},{"n":70,"t":"Dediler ki: \"Sadece ALLAH'a kulluk edelim ve atalarımızın taptıklarını terkedelim diye mi bize geldin? Doğru sözlü isen bizi kendisiyle tehdit ettiğin şeyi getir bakalım.\""},{"n":71,"t":"Dedi ki: \"Rabbinizden bir azap ve öfkeye mahkum edilmiş bulunuyorsunuz. Sizin ve atalarınızın uydurduğu ve ALLAH'ın kendilerine hiçbir güç vermediği isimler konusunda mı benimle tartışıyorsunuz? Bekleyiniz, ben de sizinle birlikte bekleyenlerdenim.\""},{"n":72,"t":"Bizden bir rahmet olarak, onu ve onunla birlik olanları kurtardık. Ayetlerimizi yalanlayarak inanmıyanların da ardını kestik. Salih"},{"n":73,"t":"Semud halkına da kardeşleri Salih'i gönderdik. Dedi ki: \"Ey halkım, ALLAH'a kulluk edin. O'ndan başka bir tanrınız yoktur. Rabbinizden, size bir beyyine (kanıt) gelmiştir. Şu ALLAH'ın devesi sizin için bir işaret olacaktır. Onu bırakın, ALLAH'ın toprağında otlasın. Ona bir zarar vermeyin; yoksa sizi acı bir azap yakalar.\""},{"n":74,"t":"\"Ad halkından sonra sizi varisler kıldığını hatırlayın. Sizi yeryüzüne yerleştirdi. Düzlüklerinde köşkler kurup dağlarında evler yontuyorsunuz. ALLAH'ın nimetlerini hatırlayın da yeryüzünde bozgunculuk yaparak karışıklık çıkarmayın.\" Elçiyi Mesajından Tanıyorlar"},{"n":75,"t":"Halkının büyüklük taslayan ileri gelenleri, aşağılayıp zulmettikleri inananlara, \"Salih'in gerçekten Rabbi tarafından gönderilmiş olduğunu nereden biliyorsunuz,\" dediler. Onlar da: \"Biz onun getirdiği mesaja inanıyoruz,\" dediler."},{"n":76,"t":"Büyüklük taslayanlar, \"Biz, sizin inandığınız şeyi inkar ediyoruz,\" dediler."},{"n":77,"t":"Deveyi işkence ederek kestiler ve Rab'lerinin emrine baş kaldırdılar: \"Salih, gerçekten elçilerden birisi isen, bizi tehdit ettiğin azabı başımıza getir,\" dediler."},{"n":78,"t":"Bunun üzerine, onları o sarsıntı yakaladı; evlerinde dizüstü çöküverdiler."},{"n":79,"t":"O da onlardan yüz çevirdi ve \"Ey halkım, size Rabbimin elçiliğini ilettim, size öğüt verdim; fakat siz öğüt verenleri sevmiyorsunuz,\" dedi. Lut, Homoseksüelliği Savunanları Uyardı"},{"n":80,"t":"Ve Lut'u da gönderdik. Halkına dedi ki: \"Sizden önce hiç kimsenin kıramadığı bir günahın rekorunu mu kırıyorsunuz?\""},{"n":81,"t":"\"Siz kadınları bırakıp erkeklere cinsel duygularla yöneliyorsunuz. Siz sınırı aşan bir topluluksunuz!\""},{"n":82,"t":"Halkının cevabı, ancak şunları söylemek oldu: \"Onları kentinizden çıkarın. Bunlar çok temiz insanlarmış!\""},{"n":83,"t":"Onu ve ailesini kurtardık. Karısı hariç. O geride kalanlardan oldu."},{"n":84,"t":"Üstlerine bir yağmur yağdırdık. Suçluların sonuna bak! Şuayb: Yolsuzluğa Karşı Mücadele Verdi"},{"n":85,"t":"Medyen'e de kardeşleri Şuayb'ı gönderdik. Dedi ki: \"Ey halkım, ALLAH'a kulluk edin. O'ndan başka tanrınız yoktur. Rabbinizden size açık bir kanıt gelmiş bulunuyor. Ölçü ve tartıyı tam uygulayın. Halkın hakkını yemeyin. Düzeltildikten sonra yeryüzünde bozgunculuk yapmayın. İnanıyorsanız bunlar sizin için daha hayırlıdır.\""},{"n":86,"t":"\"ALLAH'ın yolunu eğriltmek ve inananları tehdit edip ondan çevirmek için her yolun başına oturmayın. Sayıca az iken sizi nasıl da çoğalttığını düşünün. Bozguncuların sonunun nasıl olduğuna bir bakın.\""},{"n":87,"t":"\"Madem ki sizden bir kısmı benimle gönderilen mesaja inanmış, bir kısmı da inanmamış bulunuyor, öyleyse ALLAH aramızda hükmedinceye kadar sabredin. O, hükmedenlerin en iyisidir.\" Sahtekar Din Liderlerinin Tehditlerine Karşı"},{"n":88,"t":"Halkının büyüklük taslayan ileri gelenleri, \"Şuayb, ya seni ve seninle beraber inananları kentimizden süreceğiz ya da dinimize geri dönersin!,\" dediler. O da şöyle dedi: \"Biz istemesek de mi?\""},{"n":89,"t":"\"ALLAH bizi sizin dininizden kurtardıktan sonra ona dönersek ALLAH'a yalan yakıştırmış oluruz. Rabbimiz ALLAH dilemedikçe ona tekrar dönmemiz söz konusu olamaz. Rabbimiz her şeyi bilgisiyle kuşatmıştır. Biz yalnız ALLAH'a güvendik. Bizimle halkımızın arasını hak ile aç ey Rabbimiz. Sen açığa çıkaranların en hayırlısısın."},{"n":90,"t":"Halkının ileri gelen inkarcıları, \"Şuayb'a uyarsanız kaybedenlerden olursunuz,\" dediler."},{"n":91,"t":"Bunun üzerine onları bir sarsıntı yakaladı da evlerinde diz üstü çöküverdiler."},{"n":92,"t":"Şuayb'ı yalanlayanlar sanki hiç orada yaşamamışlar gibi yok oldular. Şuayb'ı yalanlayanlar, asıl kaybedenler onlar oldular."},{"n":93,"t":"Onlardan yüz çevirdi ve \"Ey halkım, size Rabbimin mesajını ilettim, öğüt verdim. İnkarcı bir topluluğa nasıl acırım?\" Nimetleri Kanıksayanlar Onları Kaybederler"},{"n":94,"t":"Her ne zaman bir ülkeye bir peygamber gönderdiysek, yalvarsınlar diye halkını darlık ve sıkıntıya uğrattık."},{"n":95,"t":"Sonra kötülüğün yerine iyiliği getirdik. Ne var ki anlayışlarını yitirdiler: \"Sıkıntı ve refah atalarımıza da dokunmuştu,\" dediler. Bunun üzerine, haberleri olmadan onları ansızın yakaladık. Halkın Çoğunluğu Yalnış Seçim Yapıyor"},{"n":96,"t":"Ülkelerin halkları inanıp erdemli davransalardı, göklerden ve yerden üzerlerine bolluk kapısını açardık. Ama yalanladılar ve bunun üzerine kazandıklarıyla birlikte onları yakaladık."},{"n":97,"t":"Ülkelerin halkları, azabımızın geceleyin onlar uyurlarken kendilerine gelmeyeceğinden emin mi oldular?"},{"n":98,"t":"Ülkelerin halkları, azabımızın gündüzün onlar oynarlarken kendilerine gelmeyeceğinden emin mi oldular?"},{"n":99,"t":"ALLAH'ın planından emin mi oldular? Kaybedenlerden başkası ALLAH'ın planından emin olmaz. 100. Önceki nesillerin yerine yeryüzüne varis olanlara belli olmadı mı ki, eğer dilesek onları da günahlarıyla cezalandırarak kalplerini mühürleriz de işitemezler. 101. Bunlar, sana haberlerini aktardığımız toplumlardır. Elçileri, onlara apaçık delillerle gitmişlerdi. Ama daha önceden yalanladıklarına inanacak değillerdi. ALLAH kafirlerin kalplerini böyle damgalar. 102. Çoğunu, verdikleri sözü tutanlar olarak bulmadık, aksine çoğunu yoldan çıkmış bulduk. Musa Zamanının Güçlü Diktatörüne Meydan Okudu 103. Sonra, onların ardından Firavun ve erkanına Musa'yı ayet ve mucizelerimizle gönderdik; fakat ayet ve mucizelerimize karşı haksızlık ettiler. Bozguncuların sonunun nasıl olduğuna dikkat et! 104. Musa: \"Firavun, ben alemlerin Rabbinden bir elçiyim.\" 105. \"ALLAH hakkında gerçeğin dışında bir şey söylememek benim görevimdir. Rabbinizden size bir kanıt ile geldim; İsrail oğullarını benimle birlikte salıver.\" 106. Dedi: \"Bir ayet (mucize) ile gelmişsen ve gerçekten doğru sözlüysen getir onu bakalım.\" 107. Asasını attı, iri bir yılan oluverdi. 108. Elini çıkardı, bakanlar için bembeyaz oluverdi. 109. Firavun'un halkından ileri gelenler, durumu tartıştılar ve \"Bu, uzman bir sihirbazdır,\" dediler, 110. \"Sizi yurdunuzdan çıkarmak istiyor. Ne önerirsiniz?\" 111. Dediler ki: \"Onu ve kardeşini beklet ve şehirlere toplayıcılar yolla.\" 112. \"Bütün uzman sihirbazları sana getirsinler.\" 113. Sihirbazlar Firavun'a geldiler ve \"Kazanırsak bize bir ödül var mı,\" dediler. 114. \"Evet,\" dedi, \"Siz benim yakın çevreme de girersiniz.\" 115. Dediler: \"Musa, sen at, yoksa biz atacağız.\" Sihir ve Büyü: Psikolojik Telkin ve İllüzyondan İbaret 116. \"Siz atın!,\" dedi. Onlar atınca, halkın gözünü büyülediler, onları korkuttular ve böylece büyük bir sihir ortaya koydular."}]},{"id":8,"name":"GANİMETLER (ENFAL) SÛRESİ","verses":[{"n":1,"t":"Savaş ganimetleri hakkında senden soruyorlar. De ki: \"Ganimetler, ALLAH'ın ve elçisinindir.\" ALLAH'ı dinleyin, aranızı düzeltin. İnanıyorsanız, ALLAH'a ve elçisine uyun."},{"n":2,"t":"İnananlar öyle kimselerdir ki, ALLAH anıldığında yürekleri titrer, O'nun ayetleri kendilerine okunduğunda inançları artar ve Rab'lerine güvenirler."},{"n":3,"t":"Onlar ki namazı gözetirler ve kendilerine verdiğimiz rızıklardan yardım olarak verirler."},{"n":4,"t":"Böyleleri gerçek inananlardır. Onlar için Rab'leri yanında dereceler, bağışlanma ve tükenmez rızık vardır. İnançlarında Zayıf Olanlar"},{"n":5,"t":"Nitekim Rabbin seni belli bir planın gerçekleşmesi için evinden çıkarmıştı. İnananlardan bir grup bundan hoşlanmamıştı."},{"n":6,"t":"Gerçek ortaya çıkmasına rağmen, göz göre göre ölüme sürükleniyorlarmış gibi seninle onu tartışıyorlardı."},{"n":7,"t":"ALLAH iki gruptan birisini (yenmeyi) size söz vermişti; siz ise, güçsüz olanıyla karşılaşmayı istiyordunuz. Oysa ALLAH kelimeleriyle gerçeği gerçekleştirmek ve kafirlerin ardını kesmek diliyor."},{"n":8,"t":"Ki suçlular hoşlanmasa da hakkı gerçekleştirsin ve haksızlığı ortadan kaldırsın. Tanrı'nın Görülmez Orduları"},{"n":9,"t":"Sizi kurtarması için Rabbinize yalvarıyordunuz, ve O da, \"Ben sizi birbiri ardınca bin melekle destekleyeceğim,\" diye size karşılık vermişti."},{"n":10,"t":"ALLAH bunu, ancak bir müjde olsun ve kalplerinizi yatıştırsın diye yaptı. Zafer yalnız ALLAH'tandır. ALLAH Üstündür, Bilgedir."},{"n":11,"t":"Kendisinden bir güvenlik olarak sizi bir uyuklama bürüyüp yatıştırıyordu. (Susuzluğun oluşturduğu bunalımdan) sizi temizlemek, şeytanın pisliğini (umutsuzluğu) sizden savmak, kalbinizi ikna etmek ve ayaklarınızı pekiştirmek için üzerinize gökten su indiriyordu. Savunma Savaşı"},{"n":12,"t":"Rabbin meleklere, \"Sizinle beraberim, inananları destekleyin. İnkarcıların yüreğine korku salacağım. Vurun boyunlara, vurun onların her parmağına,\" diye vahyediyordu."},{"n":13,"t":"Çünkü onlar ALLAH'a ve elçisine karşı aktif olarak savaştılar. Kim ki ALLAH ve elçisiyle savaşırsa elbette ALLAH'ın cezası çetindir."},{"n":14,"t":"İşte bunu tadın. Kafirler için bir de ateş azabı var."},{"n":15,"t":"Ey inananlar, size karşı düşmanca harekata geçen kafirlerle karşılaştığınızda, onlara arkanızı dönmeyin."},{"n":16,"t":"Kim o gün, savaş taktiği veya başka bir birliğe katılma amacınının dışında sırtını dönüp kaçarsa ALLAH'tan bir gazaba uğramıştır ve yeri de cehennemdir. Ne kötü bir duraktır. Tanrı'nın Kudreti"},{"n":17,"t":"Onları siz öldürmediniz, fakat ALLAH öldürdü. Attığın zaman da sen atmıyordun; ALLAH atıyordu. Fakat böylece inananları güzel bir sınavla ödüllendirir. ALLAH İşitendir, Bilendir."},{"n":18,"t":"Bu yolla, ALLAH, kafirlerin planını bozar."},{"n":19,"t":"Zafer istiyorsanız (ey kafirler), işte size zafer geldi! Saldırmaktan vazgeçerseniz sizin için daha iyi olur. Dönerseniz biz de döneriz ve ordunuz sayıca çok da olsa sizden hiç bir şeyi savamaz. ALLAH inananlarla beraberdir."},{"n":20,"t":"Ey inananlar, ALLAH'a ve elçisine uyunuz. İşittiğiniz halde ondan yüz çevirmeyiniz. Akıllarını Kullanmayanlar"},{"n":21,"t":"İşitmedikleri halde, \"İşittik,\" diyenler gibi olmayın."},{"n":22,"t":"ALLAH yanında, yaratıkların en kötüsü, akıllarını kullanmayan sağır ve dilsizlerdir."},{"n":23,"t":"ALLAH onlarda bir iyilik olduğunu görseydi, onlara işittirirdi. Onlara işittirseydi bile yine yüz çevirerek dönerlerdi."},{"n":24,"t":"Ey inananlar, size hayat verecek şeylere çağırdığında ALLAH'a ve elçisine yanıt verin. Bilin ki ALLAH kişi ile kalbi arasına girer ve O'nun huzuruna toplanacaksınız."},{"n":25,"t":"Sizden sadece zalimlere dokunmayacak olan fitneden sakının. Bilesiniz ki ALLAH'ın cezası çetindir."},{"n":26,"t":"Sayıca az olduğunuz, yeryüzünde ezilip horlandığınız ve insanların sizi kapıp kaçıracaklarından korktuğunuz zamanları hatırlayın. O size barınak sağladı, sizi yardımıyla destekledi ve güzel şeylerden size rızıklar verdi ki şükredesiniz."},{"n":27,"t":"Ey inananlar, ALLAH'a ve elçisine ihanet etmeyin; sorumluklarınıza bile bile ihanet etmiş olursunuz. Para ve Çocuklar Birer Sınavdır"},{"n":28,"t":"Bilesiniz ki mallarınız ve evlatlarınız sizin için bir sınavdır ve ALLAH'ın yanında büyük ödül vardır."},{"n":29,"t":"Ey inananlar, ALLAH'ı dinlerseniz, size doğruyu yanlıştan ayıracak anlayışı verir, kötülüklerinizi örter ve sizi bağışlar. ALLAH Büyük Lütuf Sahibidir. İnkarcıların Planları"},{"n":30,"t":"İnkarcılar seni etkisiz hale getirmek, veya seni öldürmek ya da seni sürmek için planlar yapıyorlardı. Onlar plan kuruyorlarsa ALLAH da plan kuruyor. ALLAH plan kuranların en ustasıdır."},{"n":31,"t":"Ayetlerimizi dinledikleri zaman, \"İşittik,\" diyorlardı, \"İstesek biz de bunun bir benzerini getiririz. Bu, geçmişlerin efsanelerinden başka bir şey değil.\""},{"n":32,"t":"Hatta, \"Rabbimiz, bu senden gelen bir gerçek ise, üstümüze gökten taşlar yağdır, veya başımıza acıklı bir azap getir,\" diyorlardı."},{"n":33,"t":"Sen onların arasında bulunduğun sürece ALLAH onlara azap edecek değildir. Onlar, bağışlanma dilerlerken de ALLAH onları cezalandıracak değildir."},{"n":34,"t":"Başkalarını Kutsal Mescid'den menederlerken neden ALLAH'ın azabını haketmesinler? Oysa onlar onun koruyucuları değiller. Onun gerçek koruyucuları inananlardır; ancak çokları bunu bilmez. Kuran'dan Önce de Namaz Kılınıyordu"},{"n":35,"t":"Onların, Kabe'deki namazları hile ve menetmekten başka bir şey değil. İnkarınızdan dolayı azabı tadın."},{"n":36,"t":"İnkar edenler, insanları ALLAH yolundan menetmek için paralarını harcarlar ve daha da harcamaya devam edecekler. Fakat bu, sonradan kendileri için bir üzüntü kaynağı olacak ve ardından yenilecekler. İnkar edenler cehenneme sürüleceklerdir."},{"n":37,"t":"Böylece ALLAH kötüyü iyiden ayırdeder, kötüleri üst üste koyup topluca yığar ve cehenneme yollar. İşte kaybedenler onlardır."},{"n":38,"t":"İnkar edenlere söyle: \"Son verirlerse geçmişte yaptıkları bağışlanacaktır. Dönerlerse, daha öncekilerin sünneti (yasası) geçerlidir.\""},{"n":39,"t":"Baskı ve zulmu ortadan kaldırıncaya ve dini sadece ALLAH'a ait kılıncaya dek onlarla savaşın. Düşmanlığa son verirlerse, elbette ALLAH yaptıklarınızı Görür."},{"n":40,"t":"Dönerlerse, bilin ki sahibiniz ALLAH'tır. O en iyi Mevla (Egemen/Dost/Koruyucu) ve en iyi Yardımcıdır. * 8:40 Bak 2:286."},{"n":41,"t":"Ayırım gününde, iki ordunun karşılaştığı günde kulumuza indirdiğimize ve ALLAH'a inanıyorsanız, bilin ki elinize geçen her ganimetin beşte biri ALLAH'ın ve Elçisinindir. Bu pay, akrabalar, öksüzler, yoksullar ve yolda kalmışların hakkıdır. ALLAH herşeye Güç Yetirendir. Tanrı Herşeyi Kontrol Eder ve İnananlar İçin Plan Kurar"},{"n":42,"t":"Hani siz vadinin beri yamacında, onlar da vadinin öte yamacında mevzilenmişti. Kervan da sizden daha aşağıda idi. Bu karşılaşmayı siz kararlaştırsaydınız karşılaşma konusunda anlaşmazlığa düşecektiniz. Oysa ALLAH, yapılması önceden planlanmış bir işi gerçekleştirmekte idi. Böylece, yok edilen, apaçık bir delille yok edilsin, yaşayan da apaçık bir delille yaşatılsın. ALLAH İşitendir, Bilendir."},{"n":43,"t":"ALLAH onları rüyanda sana az gösteriyordu. Onları sana çok gösterseydi, dağılacak ve o konuda çekişip duracaktınız. Fakat ALLAH (sizi) kurtardı. O, göğüslerin özünü bilendir."},{"n":44,"t":"Zamanı gelip kendileriyle karşılaştığınızda sizin gözlerinizde onları az gösteriyor, onların da gözlerinde sizi az gösteriyordu ki ALLAH önceden planlanmış işi gerçekleştirsin. İşler, sonunda ALLAH'a döner."},{"n":45,"t":"Ey inananlar bir ordu ile karşılaştığınızda dayanın ve ALLAH'ı çokça anın ki başarasınız. Çekişip Bölünmeyin"},{"n":46,"t":"ALLAH'a ve elçisine uyun, çekişmeyin, yoksa zayıflayıp gücünüzü yitirirsiniz. Güçlüklere karşı direnin. Elbette ALLAH sabredenlerle beraberdir."},{"n":47,"t":"ALLAH'ın yoluna engel olmak amacıyla, halka gösteriş yaparak yurtlarından çıkan o kendini beğenmişler gibi olmayın. ALLAH yaptıklarını çepeçevre Kuşatır. Şeytan Dostlarını Yarı Yolda Bırakır"},{"n":48,"t":"Şeytan, işlerini onlara süslemiş ve: \"Bu gün halktan kimse sizi yenemez, ben sizin yanınızdayım,\" demişti. İki ordu yüz yüze gelince de, topukları üzerine geri dönüp, \"Sizinle bir ilgim yok, sizin görmediğinizi görüyorum ve ALLAH'tan korkarım. ALLAH'ın cezası çetindir,\" demişti."},{"n":49,"t":"İkiyüzlüler ve kalplerinde hastalık bulunanlar, \"Bunları dinleri aldatmış,\" diyorlardı. Kim ALLAH'a güvenirse, kuşkusuz ALLAH Üstündür, Bilgedir."},{"n":50,"t":"İnkar edenlerin canlarını melekler alırken bir görseydin! Yüzlerine ve arkalarına (saldıran ve kaçan düşmanlarınıza) vuruyorlardı: \"Tadın yakıcı azabı!\""},{"n":51,"t":"\"Bu, ellerinizin yaptığına karşılıktır. ALLAH elbette kullara zalim değildir.\""},{"n":52,"t":"Tıpkı Firavun'un yandaşlarının ve onlardan öncekilerin gidişi gibi... ALLAH'ın ayetlerini inkar ettiler. Günahlarından ötürü ALLAH da onları yakalayıp cezalandırdı. ALLAH Güçlüdür, cezası çetindir. Toplumsal Problemlerin Çözümü Topluma Bağlıdır"},{"n":53,"t":"Zira, bir topluluk kendilerini değiştirmedikçe, ALLAH onlara verdiği nimetleri değiştirecek değildir. ALLAH İşitendir, Bilendir."},{"n":54,"t":"Örneğin, Firavun'un yandaşları ve onlardan öncekiler gibi. Rab'lerinin ayetlerini yalanladılar. Biz de günahlarından ötürü onları yıkıma uğrattık. Firavun'un yandaşlarını suda boğduk. Hepsi de zalim idiler."},{"n":55,"t":"ALLAH yanında yaratıkların en kötüsü kafirlerdir; onlar inanmazlar. Savaş ve Barış"},{"n":56,"t":"Onlar, sen kendileriyle anlaşma yaptığın halde her defasında anlaşmalarını bozanlardır. Onlar erdemli davranmazlar."},{"n":57,"t":"Savaşta onları yakalarsan, onları arkalarındakilere ibret olacak şekilde darmadağın et. Belki ders alırlar."},{"n":58,"t":"Bir topluluğun ihaneti seni endişelendiriyorsa, sen de aynı şekilde (diplomatik ilişkiyi kesip) at. Kuşkusuz ALLAH hainleri sevmez."},{"n":59,"t":"Kafirler, kurtulduklarını sanmasınlar. Kaçamazlar."},{"n":60,"t":"Onlar için elinizden gelen kuvvet ve atlı birlikler (savaş araçları) hazırlayıp seferber edin. Böylece onlarla ALLAH'ın düşmanlarını, düşmanlarınızı ve onlardan başka bilmediğiniz, ancak ALLAH'ın bildiği kimseleri caydırırsınız. ALLAH yolunda ne harcarsanız size tam olarak ödenir ve hiç haksızlığa uğratılmazsınız."},{"n":61,"t":"Onlar barışa eğilim gösterirlerse sen de ona eğilim göster ve ALLAH'a güven. O, İşitendir, Bilendir. Tanrı İnananlar İçin Yeterlidir"},{"n":62,"t":"Seni aldatmak isterlerse, ALLAH sana yeter. O ki seni yardımıyla ve inananlarla destekledi."},{"n":63,"t":"Ve onların kalplerini uzlaştırdı. Sen, yeryüzünde bulunanların hepsini harcasaydın bile kalplerini uzlaştıramazdın. Ancak, onların kalplerini ALLAH uzlaştırdı. O, Üstündür, Bilgedir."},{"n":64,"t":"Ey peygamber, ALLAH sana ve seni izleyen inananlara yeter. Standartlar ve Savaş Sonrası Hukuk"},{"n":65,"t":"Ey peygamber, inananları savaşa özendir. Sizden dirençli yirmi kişi olsa, iki yüz kişiyi yenebilir. Sizden yüz kişi, kafirlerden bin kişiyi yenebilir. Çünkü onlar, anlamayan bir topluluktur."},{"n":66,"t":"Ancak, ALLAH sizde zayıflık bulunduğunu bildiğinden şimdi sizden yükü hafifletti. Sizden dirençli yüz kişi olsa, iki yüz kişiyi yenebilir. Sizden bin kişi olsa, ALLAH'ın izniyle iki bin kişiyi yenebilir. ALLAH sabredip direnenlerle beraberdir. Kölecilik Yasak"},{"n":67,"t":"Hiç bir peygambere, yeryüzünde savaşa katılmaksızın esirler edinmesi yakışmaz. Siz bu dünyanın geçici malını istiyorsunuz; ALLAH ise (sizin için) ahireti ister. ALLAH Üstündür, Bilgedir."},{"n":68,"t":"ALLAH'ın daha önce koyduğu bir yasa olmasaydı aldıklarınızdan ötürü size büyük bir azap dokunacaktı."},{"n":69,"t":"Artık ele geçirdiğiniz ganimetleri helal ve temiz olarak yiyebilirsiniz. ALLAH'ı dinleyin. ALLAH Bağışlayandır, Rahimdir. Esirlere İyi Davranın"},{"n":70,"t":"Ey peygamber, elinizde bulunan esirlere de ki: \"ALLAH kalbinizde bir iyilik bilse, yitirdiklerinizden daha iyisini size verir ve sizi bağışlar. ALLAH Bağışlayandır, Rahimdir."},{"n":71,"t":"Yok, sana ihanet etmek istiyorlarsa, zaten daha önce ALLAH'a ihanet etmişlerdi. Bunun üzerine onları yenik düşürdü. ALLAH Bilendir, Bilgedir. Uluslararası Anlaşmalar Bağlayıcıdır"},{"n":72,"t":"İnananlar, ALLAH yolunda göç edenler, mallarıyla ve canlarıyla cihad edenler ve onları barındırıp onlara yardım edenler birbirlerinin dostudur. İnandığı halde sizinle birlikte göç etmeyenler göç edinceye kadar onlardan sorumlu değilsiniz. Ancak onlar, din bağından ötürü sizden yardım isterlerse, aranızda anlaşma bulunan bir topluma karşı olmaması koşuluyla kendilerine yardım etmelisiniz. ALLAH yaptıklarınızı Görendir."},{"n":73,"t":"İnkar edenler de birbirlerinin dostudur. Bu emirleri uygulamazsanız, yeryüzünde kaos ve büyük bir fesad olur."},{"n":74,"t":"İnananlar, ALLAH yolunda göç edip çaba gösterenler ve onları barındırıp yardım edenler, işte bunlar gerçek inananlardır. Onlar için bağışlanma ve bol rızık vardır."},{"n":75,"t":"Sonradan inananlar, göç edenler ve sizinle birlikte çaba gösterenler de sizdendir. ALLAH'ın Kitabına göre akrabalar birbirlerine önceliklidir. ALLAH herşeyi Bilendir"}]},{"id":9,"name":"ÜLTİMATOM (BARA'E) SÛRESİ*[1]","verses":[{"n":1,"t":"Bu, ALLAH ve elçisinden, kendileriyle anlaşma yapmış bulunduğunuz putperestlere bir ültimatomdur:"},{"n":2,"t":"Yeryüzünde dört ay daha dolaşın, bilin ki siz ALLAH'ı aciz bırakamazsınız ve ALLAH inkarcıları rezil eder."},{"n":3,"t":"Bu, aynı zamanda, ALLAH ve elçisinden tüm halka, büyük hac günü yayımlanmış bir bildiridir: ALLAH putperestlerden uzaktır, elçisi de... Tevbe ederseniz sizin için daha iyidir. Dönerseniz, bilin ki siz ALLAH'ı aciz bırakamazsınız. İnkarcılara acı bir azabı müjdele."},{"n":4,"t":"Ancak, kendileriyle yaptığınız anlaşmanın koşullarına eksiksiz uyan ve size karşı başkalarıyla işbirliğinde bulunmayan putperestlerin anlaşmasını tanıdığınız süreye kadar uygulayın. ALLAH erdemlileri sever."},{"n":5,"t":"Kutsal aylar çıkınca, (hâlâ barışa yanaşmıyorlarsa) o putperestleri yakaladığınız yerde öldürün. Onları yakalayın, onları kuşatın ve her hareketlerini izleyin. Tevbe edip namaz kılar ve zekat verirlerse yollarını serbest bırakın. ALLAH Bağışlayandır, Rahimdir."},{"n":6,"t":"Putperestlerden biri sizden geçiş emniyeti dilerse ona koruma sağla ki ALLAH'ın sözünü işitsin; sonra onu kendisinin güvenlik bölgesine ulaştır. Çünkü onlar bilgisiz bir topluluktur."},{"n":7,"t":"Putperestlerin ALLAH ve elçisi yanında nasıl bir anlaşması olabilir ki? Kutsal Mescid'de sizinle anlaşma yapmış olanlar hariç. Onlar sizin haklarınızı gözettikleri sürece siz de onların haklarını gözetin. ALLAH erdemlileri sever."},{"n":8,"t":"Nasıl olabilir ki? Size üstün gelselerdi ne bir akrabalık ilişkisini gözetirlerdi, ne de bir anlaşmayı... Ağızlarıyla sizi pasifleştirecek hoş sözler söylerler, fakat kalpleri tersini ister. Çokları yoldan çıkmıştır."},{"n":9,"t":"ALLAH'ın ayetlerini az bir fiyata satıp onun yolundan saptılar. Yaptıkları ne kadar da kötüdür."},{"n":10,"t":"İnanmış birisi hakkında ne bir akrabalık bağı ne de bir anlaşma gözetmezler; saldırganlar ve haddi aşanlar onlardır."},{"n":11,"t":"Tevbe ederlerse, namaz kılar ve zekat verirlerse din kardeşleriniz olurlar. Bilenlere ayetleri böyle açıklarız."},{"n":12,"t":"Anlaşma yaptıktan sonra andlarını bozar ve dininize saldırırlarsa, o inkarcılığın önderleriyle savaşın; çünkü onların andı artık geçersizdir. Belki vazgeçerler."},{"n":13,"t":"Andlarını bozan, elçiyi sürmeye yeltenen ve sizinle (savaşı) ilk defa başlatan topluluğa karşı savaşmıyacak mısınız? Yoksa onlardan korkuyor musunuz? İnanıyorsanız asıl çekinmeniz gereken ALLAH'tır."},{"n":14,"t":"Onlarla savaşın ki, ALLAH ellerinizle onları cezalandırıp rezil etsin, sizi zafere ulaştırsın ve inanan toplumun göğsünü ferahlatsın,"},{"n":15,"t":"Yüreklerinin öfkesini gidersin. ALLAH dilediğinin tevbesini kabul eder. ALLAH Bilendir, Bilgedir. Kaçınılmaz Test"},{"n":16,"t":"ALLAH, içinizden kendisi uğrunda cihad edenleri, ALLAH'tan, elçisinden ve inananlardan başkasını yakın dost edinmeyenleri bilip ayırmadan bırakılacağınızı mı sandınız? ALLAH yaptıklarınızı Haber Alır."},{"n":17,"t":"Putperestler, kendi inkarlarına bizzat tanık oldukları halde, ALLAH'ın mescidlerini sıkça ziyaret etmemeli. İşleri boşa çıkmıştır. Onlar ateşte ebedidirler."},{"n":18,"t":"ALLAH'ın mescidlerini, ancak ALLAH'a ve ahiret gününe inananlar, namazı gözetenler, zekatı verenler ve ALLAH'tan başkasından korkmayanlar sıkça ziyaret ederler. Onlar, doğru yolu bulanlardandır. Araplara Bir Soru"},{"n":19,"t":"Hacılara su verme ve Kutsal Mescid'i ziyarete hazır bulundurma işini, ALLAH'a ve ahiret gününe inanma, namazı gözetme, zekat verme ve ALLAH yolunda cihad etme ile bir mi tutuyorsunuz? ALLAH yanında onlar bir değildir. ALLAH zalim toplumu doğruya ulaştırmaz. Müjde"},{"n":20,"t":"İnananlar, göç edenler, paralarıyla canlarıyla ALLAH yolunda çaba gösterenler için ALLAH yanında daha büyük bir derece vardır. Onlar kazananlardır."},{"n":21,"t":"Rableri onlara, kendisinden bir rahmet, bir onama ve içinde ebedi nimetlerin bulunduğu cennetleri müjdeler."},{"n":22,"t":"Orada ebedi kalıcılar. Büyük ödül ALLAH katındadır. Bir Seçim Yapmak Durumunda Kalırsanız"},{"n":23,"t":"Ey inananlar, inkarı imana tercih ettikleri taktirde ana babalarınızı ve kardeşlerinizi dost edinmeyin. Kim onları dost edinirse onlar zalimlerdir."},{"n":24,"t":"De ki: \"Ana babalarınız, çocuklarınız, kardeşleriniz, eşleriniz, aileniz, kazandığınız paralar, bozuk gitmesinden korktuğunuz iş ve hoşlandığınız evler ALLAH ve elçisinden ve O'nun yolunda çaba göstermekten daha sevgili ise, ALLAH emrini getirinceye kadar bekleyiniz.\" ALLAH yoldan çıkmış toplumları doğruya iletmez. Huneyn Savaşı: Kelle Sayısına Güvenmek"},{"n":25,"t":"ALLAH bir çok durumda size yardım etti. Huneyn günü sayısal çokluğunuz sizi böbürlendirmişti. Fakat sayınızın size hiç bir yararı da olmamıştı. Nitekim, tüm genişliğine rağmen yeryüzü size dar gelmiş ve sonunda dönüp kaçmıştınız."},{"n":26,"t":"Sonra ALLAH, elçisi ve inananların üzerine tarafından güven ve rahatlık indirdi, ek olarak, görmediğiniz ordular indirdi ve böylece kafirleri cezalandırdı. Kafirlerin cezası işte budur."},{"n":27,"t":"Nitekim ALLAH, sonunda dilediğinin tevbesini kabul eder. ALLAH Bağışlayandır, Rahimdir."},{"n":28,"t":"Ey inananlar, putperestler pistir; bu yıldan sonra Kutsal Mescid'e yaklaşmasınlar. Yoksulluğa düşmekten korkuyorsanız, (bilin ki) ALLAH dilerse sizi kendi lütfuyla zengileştirecektir. ALLAH Bilendir, Bilgedir."},{"n":29,"t":"Kendilerine kitap verilenler arasından, ALLAH'a ve ahiret gününe inanmıyan, ALLAH'ın ve elçisinin yasakladığını yasaklamıyan ve gerçek dine uymayan kimselerle boyunlarını eğip elleriyle vergi verinceye kadar savaşın."},{"n":30,"t":"Yahudiler: \"Uzeyr ALLAH'ın oğludur,\" dediler. Hıristiyanlar da, \"Mesih ALLAH'ın oğludur,\" dediler. Bu, ağızlarından çıkan sözleridir. Önceden inkar etmiş olanların sözlerini taklid ediyorlar. ALLAH onları mahkum eder. Nasıl da çevriliyorlar? Din Bilginlerinin Öğretilerini İzleyenler"},{"n":31,"t":"Din bilginlerini, din adamlarını ve Meryem oğlu Mesih'i ALLAH'tan ayrı rabler edindiler. Oysa, yalnız tek Tanrı'ya kulluk etmekle emredilmişlerdi. O'ndan başka tanrı yoktur. O, eş koştukları kimselerden de çok Yücedir."},{"n":32,"t":"ALLAH'ın ışığını ağızlarıyla söndürmek isterler. Kafirler istemese de ALLAH ışığını tamamlayacaktır."},{"n":33,"t":"O, elçisini hidayetle ve gerçek dinle gönderdi ki onu tüm dinlere üstün kılsın. Putperestler istemese de..."},{"n":34,"t":"Ey inananlar, din bilginlerinin ve din adamlarının çoğu halkın parasını hakketmeden yerler ve ALLAH'ın yolundan saptırırlar. Altın ve gümüşü yığıp ALLAH yolunda harcamayanlara acı bir azap müjdele."},{"n":35,"t":"Gün gelir o biriktirdikleri altınlar ve paralar cehennem ateşinde ısıtılarak onlarla alınları, yanları ve sırtları dağlanır: \"Kendiniz için biriktirdiğiniz işte budur. Biriktirdiğinizi tadın.\" Tanrı'nın Sistemi: Bir Yılda On İki Ay"},{"n":36,"t":"Gökleri ve yeri yarattığı gün ALLAH'ın kitabında ayların sayısı, ALLAH'a göre on ikidir.*40 Bunlardan dördü ise kutsaldır. İşte kusursuz din budur; o aylarda (savaşarak) kendinize zulmetmeyiniz. Ama putperestler sizinle toptan savaşırlarsa siz de onlarla toptan savaşın.**41 Bilesiniz ki ALLAH erdemli davrananların yanındadır."},{"n":37,"t":"Kutsal Ayların yerini değiştirmek inkarın ileri noktasıdır. İnkarcılar onunla saptırılırlar. ALLAH'ın kutsal saydığı ayların sayısına denk düşürmek amacıyla onu bir yıl helal, bir yıl da kutsal sayarlar. Böylece, ALLAH'ın kutsal kıldığı ayların kutsallığını çiğnerler. İşledikleri kötülükler, gözlerinde güzel görünüyor. ALLAH inkarcı topluluğu doğruya ulaştırmaz."},{"n":38,"t":"Ey inananlar, size ne oldu ki, \"ALLAH yolunda harekete geçin,\" dendiği zaman yere çakılıp kaldınız? Ahiret yerine bu dünya hayatına mı razı oldunuz? Dünya hayatının nimetleri ahiret hayatına oranla pek azdır."},{"n":39,"t":"Harekete geçmezseniz sizi acıklı bir azapla cezalandırarak yerinize başka bir toplumu geçirir. Siz O'na asla zarar veremezsiniz. ALLAH her şeye Gücü Yetendir. Tanrı'nın Görünmez Orduları"},{"n":40,"t":"Siz ona yardım etmezseniz, ALLAH ona yardım etmişti. (Örneğin) kafirler onu, ikinin ikincisi olarak çıkarmışlardı. Hani ikisi mağarada iken, arkadaşına, \"Üzülme, ALLAH bizimle beraberdir,\" diyordu... ALLAH ona huzur ve güven indirdi; görmediğiniz ordularla destekleyerek inkarcıların sözünü alçalttı. Yüce olan, yalnızca ALLAH'ın sözüdür. ALLAH Üstündür, Bilgedir."},{"n":41,"t":"İster hafif ister ağır olarak savaşa çıkınız. Paralarınızla ve canlarınızla ALLAH yolunda cihad edin. Bu sizin için daha iyidir, bir bilseydiniz."},{"n":42,"t":"Yakın bir menfaat ve orta uzunlukta bir yolculuk olsaydı seni izleyeceklerdi; ancak zorluk onlara fazla geldi. ALLAH'a yemin edeceklerdir: \"Gücümüz yetseydi sizinle birlikte çıkacaktık.\" Böylece kendilerini mahfediyorlar. ALLAH onların yalancı olduklarını bilir."},{"n":43,"t":"ALLAH seni affetti: Doğrular ve yalancılar sana belli olmadan önce neden onlara izin verdin?"},{"n":44,"t":"ALLAH'a ve ahiret gününe inananlar, paralarıyla ve canlarıyla çaba göstermekten (kaçmak için) senden izin istemezler. ALLAH erdemlileri hakkıyla Bilir."},{"n":45,"t":"Ancak ALLAH'a ve ahiret gününe inanmıyanlar senden izin ister. Kalpleri kuşku ile doludur. Onlar kuşkuları içinde bocalamaktadırlar."},{"n":46,"t":"Savaşa çıkmayı istemiş olsalardı, onun için bir hazırlık yaparlardı. Fakat ALLAH onların katkısını istemedi ve onları yüreksiz ve isteksiz yaptı. Kendilerine, \"Oturanlarla birlikte oturun!,\" denildi."},{"n":47,"t":"Sizinle çıksalardı, size yalnız karışıklık katarlardı, aranıza fitne ve çekişme sokarlardı. İçinizde de onlara kulak verenler var. ALLAH zalimleri çok iyi Bilir."},{"n":48,"t":"Daha önce de kargaşalık çıkarmayı arzulamışlardı ve senin işlerini tersine çevirmişlerdi. Nihayet gerçek geldi ve ALLAH'ın yasası, onlara rağmen egemen oldu."},{"n":49,"t":"Onlardan bazıları, \"Bana izin ver, beni sıkıntıya sokma,\" diyor. Onlar zaten bu tavırlarıyla sıkıntının içine düşmüşlerdir; kafirleri cehennem kuşatmaktadır."},{"n":50,"t":"Sana bir iyilik dokunsa onları üzer, sana bir kötülük dokunsa, \"Biz önceden önlem almıştık,\" derler ve sevinç içinde dönüp giderler."},{"n":51,"t":"De ki: \"ALLAH'ın bizim için yazdığından başkası bize dokunmaz. O'dur bizim mevlamız, sahibimiz. İnananlar, ALLAH'a güvensinler.\" * 9:51 Bak 2:286."},{"n":52,"t":"De ki: \"Biz sizin için, ALLAH'ın, ya kendi tarafından veya bizim elimizle sizi cezalandırmasını umarken siz bizim için ancak iki güzelden birini (gazilik veya şehitlik) umabilirsiniz. Umutla bekleyin, biz de umutla bekliyoruz."},{"n":53,"t":"De ki: \"Yoksullara ister gönüllü, ister gönülsüz yardım edin; sizden kabul edilmeyecektir. Çünkü siz yoldan çıkmış bir topluluksunuz.\" Muhammed'i Reddedenler Namaz Kılmaktaydılar"},{"n":54,"t":"Yardımlarının kabul edilmesine engel sadece şudur: ALLAH'ı ve elçisini inkar ettiler, namaza ancak üşenerek yaklaşırlar ve yardımları da isteksiz yaparlar."},{"n":55,"t":"Onların paraları ve çocukları seni etkilemesin. ALLAH bunlarla, onları dünya hayatında cezalandırmayı ve canlarının inkarcı olarak çıkmasını istiyor."},{"n":56,"t":"Sizden olduklarına dair ALLAH'a yemin ederler; oysa sizden değiller, onlar anlaşmazlık çıkaran bir topluluktur."},{"n":57,"t":"Nitekim onlar, sığınacak bir yer, mağaralar yahut girilecek bir yer bulsalardı panik içinde oraya yönelirlerdi-"},{"n":58,"t":"Onların bir kısmı, sadakaların dağıtımı konusunda seni eleştiriyor; kendilerine ondan verilince razı oluyorlar, ancak ondan kendilerine verilmeyince öfkeleniyorlar."},{"n":59,"t":"Onlar, ALLAH'ın ve elçisinin kendilerine verdikleri paya razı olmalı ve \"ALLAH bize yeter. ALLAH elçisi yoluyla kendi lütfundan bize verecektir. Biz sadece ALLAH'ı arzularız,\" demeliydiler. Toplumsal Yardımların Dağıtımı"},{"n":60,"t":"Sadakalar, ALLAH'tan bir yükümlülük olarak, yoksullara, düşkünlere, bu konuda çalışan görevlilere, sempatizanlara, kölelerin özgürlüğü için, borçlulara, ALLAH yoluna ve yolda kalmışlara verilmeli. ALLAH Bilendir, Bilgedir."},{"n":61,"t":"Onlardan kimi de, \"O (haber toplayan) bir kulaktır,\" diyerek peygamberi incitiyorlar. De ki: \"O, sizin için bir hayır kulağıdır. O, ALLAH'a inanır ve inananlara güvenir. İçinizdeki inananlar için de bir rahmettir. ALLAH'ın elçisini incitenler için acı bir azap vardır."},{"n":62,"t":"Sizi hoşnud etmek için ALLAH'a yemin edip dururlar. Gerçekten inanıyorlarsa bilmelidirler ki ALLAH ve elçisi hoşnud edilmeye daha layıktır. Allah ve Elçisine Karşı Gelmenin Cezası; İkiyüzlüler"},{"n":63,"t":"Bilmediler mi ki, kim ALLAH ve elçisine karşı gelirse, içinde ebedi kalacağı cehenneme mahkum olur. Bu büyük bir aşağılanmadır."},{"n":64,"t":"İkiyüzlüler, kalplerindekini kendilerine haber verecek bir surenin inmesinden çekiniyorlar. De ki: \"Alay edin bakalım, ALLAH korktuğunuz şeyi açığa çıkaracak.\""},{"n":65,"t":"Kendilerine sorarsan, \"Biz sadece şakalaşıp oynuyorduk,\" derler. De ki: \"Siz, ALLAH ile, ayetleriyle ve elçisiyle mi alay ediyorsunuz?\""},{"n":66,"t":"Özür dilemeyiniz. Siz inandıktan sonra inkar ettiniz. Sizden bir kısmını affetsek bile, suç işlemiş oldukları için bir kısmını cezalandıracağız."},{"n":67,"t":"İkiyüzlü erkekler ve ikiyüzlü kadınlar birbirlerindendir. Onlar, kötülüğü öğütlerler, iyilikten menederler. Elleri sıkıdır. Onlar ALLAH'ı unuttular, O da onları unuttu. İkiyüzlüler, iyice yoldan çıkmış olanlardır."},{"n":68,"t":"ALLAH, ikiyüzlü erkeklere, ikiyüzlü kadınlara ve kafirlere ebedi kalacakları cehennem ateşini söz verir. O onlara yeter. ALLAH onları lanetlemiştir ve onlar için tükenmez bir azap vardır. Tanrı'nın Sistemi Değişmez"},{"n":69,"t":"Tıpkı sizden öncekilere benziyorsunuz; sizden daha güçlüydüler, sizden daha çok mal ve çocuklara sahiptiler. Kendilerine düşen paydan hoşlandılar, sizden öncekilerin kendi paylarından hoşlanmaları gibi siz de kendi payınızdan hoşlandınız. Kendilerini kaptıranlar gibi siz de kaptırdınız. Onlar, işleri dünya ve ahirette boşa çıkmış kimselerdir. Onlar, kaybedenlerdir. Kaybedenler"},{"n":70,"t":"Nuh'un halkı, Ad, Semud, İbrahim'in halkı, Medyen sakinleri ve altüst olmuş ülkelerin (Sadom ve Gomore) halkları gibi kendilerinden öncekilerin haberleri onlara ulaşmadı mı? Elçileri kendilerine apaçık belgelerle gitmişlerdi. ALLAH onlara zulmediyor değildi, aksine onlar kendi kendilerine zulmediyorlardı. Kazananlar"},{"n":71,"t":"İnanan erkekler ve inanan kadınlar birbirlerinin dostudur. İyiliği emrederler, kötülükten menederler, namazı gözetirler, zekatı verirler, ALLAH'a ve elçisine uyarlar. İşte onlara ALLAH rahmet edecektir. ALLAH Üstündür, Bilgedir."},{"n":72,"t":"ALLAH, inanan erkeklere ve inanan kadınlara içinden ırmaklar akan ebedi kalacakları cennetler ve Adn cennetlerinde güzel evler söz vermiştir. ALLAH'ın hoşnud olması ise hepsinden daha büyük bir şeydir. İşte en büyük kurtuluş budur. Kafirlere Karşı"},{"n":73,"t":"Ey peygamber, kafirler ve ikiyüzlülerle mücadele et ve onlara karşı güçlü ve sert ol. Varacakları yer cehennemdir. Ne kötü bir dönüş yeridir orası!"},{"n":74,"t":"İnkar sözlerini konuşmalarına ve teslim olduktan sonra inkar etmelerine rağmen, onları söylemediklerine dair ALLAH'a yemin ediyorlar. Aslında, hiç bir zaman ulaşamadıkları gerçeğe karşı durdular. ALLAH ve elçisi O'nun lütfuyla kendilerini zenginleştirdikten sonra öc almaya kalktılar! Tevbe ederlerse kendileri için iyi olur. Yüz çevirirlerse, ALLAH onları dünya ve ahirette acı bir azapla cezalandırır; yeryüzünde ne bir dostları ne de bir yardımcıları olur."},{"n":75,"t":"Hatta bazıları, \"Bize lütfundan verirse, paramızı yardım için harcayacağız ve dürüst insanlardan olacağız,\" diye ALLAH'a söz verdiler."},{"n":76,"t":"Fakat, onlara kendi lütfundan verince, cimrileştiler ve yüz çevirerek döndüler."},{"n":77,"t":"ALLAH'a verdikleri sözden caydıkları ve yalan söyledikleri için kendisiyle karşılacakları güne kadar kalplerine iki yüzlülük soktu."},{"n":78,"t":"Bilmezler mi ki, ALLAH onların hem gizlediklerini hem açıkladıklarını bilir ve ALLAH tüm gizlileri Bilendir?"},{"n":79,"t":"Gönüllü olarak yardımda bulunan inananların cömertliklerini eleştirenler ve aynı zamanda fazla veremiyen yoksullarla da alay edenler yok mu, ALLAH onları küçük düşürür. Onlar için acıklı bir azap vardır. Şeytanın En Etkili Oltası: Şefaat Hikayesi"},{"n":80,"t":"İster onlar için bağışlanma dile, ister bağışlanma dileme. Onlar için yetmiş kere bağışlanma dilesen bile ALLAH onları bağışlamıyacaktır. Çünkü onlar ALLAH ve elçisini yalanladılar. ALLAH yoldan iyice çıkmış toplumları doğruya iletmez."},{"n":81,"t":"Geride kalanlar, ALLAH elçisinin ardındaki yerlerini beğendiler, ALLAH yolunda paralarıyla, canlarıyla çaba göstermekten hoşlanmadılar ve: \"Bu sıcakta harekete geçmeyin,\" dediler. \"Cehennem ateşi daha sıcaktır,\" de. Bir anlasalardı!"},{"n":82,"t":"Kazandıklarına karşılık az gülüp çok ağlasınlar."},{"n":83,"t":"Sefere çıkma konusunda onlardan bir grubun senden izin isteyecekleri bir fırsatı ALLAH sana tekrar verse, \"Benimle birlikte ebediyyen harekata çıkmayacaksınız, ve benimle birlikte hiçbir düşmanla savaşmayacaksınız. Çünkü siz, ilk başta oturmayı seçmiştiniz. Öyle ise, geri kalanlarla beraber oturun,\" de."},{"n":84,"t":"Onlardan ölen birisi için namaz kılma, mezarı başında da durma. Çünkü onlar ALLAH'a ve elçisine karşı geldiler ve yoldan çıkmışlar olalarak öldüler. Dünyevi Varlıklar Aldatabilir"},{"n":85,"t":"Paraları ve çocukları seni etkilemesin. ALLAH bunlarla, onları dünyada cezalandırmayı ve canlarının inkarcılar olarak çıkmasını ister."},{"n":86,"t":"\"ALLAH'a inanın, elçisiyle birlikte cihad edin,\" diye bir sure indiği zaman, onların güçlü ve varlıklı olanları bile senden izin istediler ve, \"Bizi bırak oturanlarla beraber olalım,\" dediler."},{"n":87,"t":"Geride kalanlarla birlikte olmaya razı oldular. Sonunda kalpleri mühürlendi. Bundan ötürü anlayamazlar. İnananlar, Cihad İçin İsteklidirler"},{"n":88,"t":"Fakat elçi ve beraberinde bulunanlar, paralarıyla ve canlarıyla cihad ettiler. Tüm iyilikleri onlar hakketmiştir. Kazananlar onlardır."},{"n":89,"t":"ALLAH onlara ebedi kalacakları ve içinden ırmaklar akan cennetler söz vermiştir. Bu, en büyük başarıdır."},{"n":90,"t":"Araplardan özür uyduranlar, izin almak için sana geldiler. ALLAH ve elçisini yalanlayanlar böylece oturdular. İnkarcılarına acı bir azap dokunacaktır."},{"n":91,"t":"ALLAH'a ve elçisine içten bağlı oldukları taktirde, zayıflara, hastalara ve yardım için verecek bir şeyi bulunmayanlara bir ayıplama yoktur. İyi davrananlar kınanamaz. ALLAH Bağışlayandır, Rahimdir."},{"n":92,"t":"Aynı şekilde, kendilerini bindirmen için sana geldiklerinde, \"Sizi bindirecek bir taşıt bulamıyorum,\" dediğin ve mali yetersizliklerinden dolayı üzüntüden gözlerinden yaş akarak geri dönenler de kınanamaz."},{"n":93,"t":"Yalnız, zengin oldukları halde senden izin isteyenler kınanabilir. Geride kalanlarla birlikte olmayı istediler, ALLAH da kalplerini damgaladı. Bunun için bilmezler. Zorlu Anlar İkiyüzlüleri Açığa Çıkarır"},{"n":94,"t":"(Savaştan gelip) kendilerine döndüğünüzde size özürler sayarlar. De ki: \"Boşuna özür saymayın; size artık inanmayız, ALLAH durumunuzu bize bildirmiş bulunuyor. ALLAH ve elçisi sizin işlerinizi görecek ve sonra da gizliyi ve açığı Bilenin huzuruna döndürüleceksiniz. O yaptıklarınız her şeyi size bildirecektir."},{"n":95,"t":"Onlara döndüğünüzde, kendilerinden vazgeçesiniz diye ALLAH'a yemin ederler. Onlardan vazgeç. Onlar kirlidir. Kazandıklarına karşılık, yerleri cehennemdir."},{"n":96,"t":"Kendilerinden hoşnut olasınız diye yemin ediyorlar. Onlardan hoşnut olsanız bile ALLAH yoldan çıkmış toplumlardan hoşnud olmaz. Araplar"},{"n":97,"t":"Araplar inkarcılıkta ve ikiyüzlülükte en aşırıdırlar. ALLAH'ın elçisine indirdiğini tanımamaya da en yakındırlar. ALLAH Bilendir, Bilgedir."},{"n":98,"t":"Bazı Araplar, yardımlarını bir kayıp ve angarya sayar ve sizin için felaketler gözetlerler. En kötü felaketler onlar içindir. ALLAH İşitendir, Bilendir."},{"n":99,"t":"Araplardan, ALLAH'a ve ahiret gününe inananlar da vardır. Harcadıklarını ise ALLAH'a yaklaştıracak bir vesile ve elçiye destek sayarlar. Gerçekten o, onlar için bir yaklaşma vesilesidir. ALLAH onları rahmetine sokacaktır. ALLAH Bağışlayandır, Rahimdir."}]},{"id":10,"name":"YUNUS (YUNUS) SÛRESİ","verses":[{"n":1,"t":"A.L.R. Bunlar (bu harfler), hikmet sahibi Kitab'ın mucizeleridir."},{"n":2,"t":"Kendilerinden bir adama: \"İnsanları uyar ve inananlara Rab'leri katında önemli bir yere sahip olduklarını müjdele,\" diye vahyetmemiz halka garip mi geliyor? İnkarcılar, \"Bu, apaçık bir büyücüdür,\" dediler."},{"n":3,"t":"Gökleri ve yeri altı günde yaratan ve sonra tüm otoriteyi kuran Rabbiniz (sahibiniz) ALLAH'tır. Her işi yönetir. İzni olmadan hiç kimse aracılık (şefaat) edemez. Rabbiniz ALLAH budur, O'na kulluk edin. Öğüt almaz mısınız?"},{"n":4,"t":"Hepinizin dönüşü O'nadır. Bu, ALLAH'ın verdiği gerçek sözdür. O, yaratılışı başlatır ve sonra tekrarlar; böylece inanıp erdemli işler yapanları adaletle ödüllendirir. Kafirlere ise, inkarlarından ötürü sıcak bir içecek ve acı bir azap vardır."},{"n":5,"t":"O, güneşi bir ışık kaynağı, ayı da bir ışık yaptı. Yılların sayısını ve hesabı bilmeniz için ona evreler düzenleyip belirledi. ALLAH bunları ancak bir gerçek için yaratmıştır. Bilen bir topluma ayetleri böyle açıklar."},{"n":6,"t":"Gecenin gündüzle yer değiştirmesinde ve ALLAH'ın göklerde ve yerde yarattığı şeylerde erdemli bir toplum için deliller ve ibretler vardır. Dünyaya Düşkün Olmak"},{"n":7,"t":"Bizimle karşılaşmayı ummayanlar, dünya hayatını sevip ona bağlananlar ve ayetlerimizden gafil olanlar..."},{"n":8,"t":"İşte onların yeri, kazandıklarından ötürü ateştir. Tanrı, İnananları Doğruya İletir"},{"n":9,"t":"İnanıp erdemli işler yapanlara gelince, Rab'leri inançlarından dolayı onları doğruya iletir. Nimet cennetlerinde ayaklarının altından ırmaklar akar."},{"n":10,"t":"Oradaki duaları: \"Tanrımız, sen yücesin\", oradaki selamlaşmaları: \"Selam,\" ve dualarının sonu da: \"Evrenlerin Rabbi ALLAH'a övgüler olsun,\" dur."},{"n":11,"t":"İnsanların iyiliği acele istemeleri gibi, ALLAH da onlara azabı acele verse idi, süreleri bitirilmiş olurdu. Bizimle karşılaşmayı ummayanları, azgınlıkları içinde şaşkın durumda bırakırız."},{"n":12,"t":"İnsana bir zarar dokundu mu, yanı üzerine yatarken veya ayaktayken veya oturmuşken bizi çağırır. Ona zarar veren şeyi kendisinden giderdik mi, sanki kendisine dokunan o zarardan dolayı bizi hiç çağırmamış gibi davranır. Sınırı aşanlara, yaptıkları işler işte böyle süslü gösterilir."},{"n":13,"t":"Sizden önceki nice nesilleri, zulmettikleri zaman yok etmişizdir. Elçileri kendilerine açık delillerle gitmişlerdi, ancak onlar inanmayı reddetmişlerdi. Suçlu toplumları böyle cezalandırırız. Şimdi Sıra Sizin"},{"n":14,"t":"Sonra, ne yapacağınızı görmek için onların yerine sizi yeryüzüne varis kıldık."},{"n":15,"t":"Onlara apaçık olan ayetlerimiz okunduğu zaman, bize kavuşmayı ummayanlar, \"Bundan başka bir Kuran getir, yahut onu değiştir!,\" derler. De ki: \"Onu kendi tarafımdan değiştiremem. Ben yalnız bana vahyedilene uyarım. Rabbime karşı gelirsem, büyük günün azabından korkarım.\""},{"n":16,"t":"De ki: \"ALLAH dilemeseydi onu size okuyamazdım ve sizin de ondan haberiniz olmazdı. Bundan önce bir ömür boyu aranızda yaşadım. Anlamaz mısınız?\""},{"n":17,"t":"ALLAH'a yalan uydurup iftira eden, veya mucize ve ayetlerini yalanlayandan daha zalim kim olabilir? Suçlular onmaz."},{"n":18,"t":"ALLAH'ı bırakıp, kendilerine ne zarar ne de yarar veremiyenlere tapıyorlar ve \"Bunlar, ALLAH yanında bize şefaat edecekler,\" diyorlar. De ki: \"ALLAH'ın göklerde ve yerde bilmediği şeyleri mi O'na bildiriyorsunuz? O çok yücedir, ortak koştuklarınızdan uzaktır.\""},{"n":19,"t":"İnsanlar bir tek toplumdu; sonra anlaşmazlığa düştüler. Rabbinin vermiş olduğu bir sözü olmasaydı, anlaşmazlığa düştükleri konuda hemen aralarında hüküm verilecekti. Kuran'ın Mucizesi Muhammed'den Sonra Açığa Çıkacak"},{"n":20,"t":"\"O'na Rabbinden bir mucize indirilmeli değil mi,\" diyorlar. De ki: \"Gizemler ALLAH'ın yanındadır; öyleyse bekleyin, ben de sizinle birlikte beklemekteyim.\""},{"n":21,"t":"Kendilerine dokunan bir sıkıntıdan sonra insanlara bir rahmet tattırdığımız zaman, ayet ve mucizelerimize karşı hemen bir plan düzenlerler. De ki: \"Plan yapmada ALLAH daha hızlıdır. Elçilerimiz, düzenlediğiniz tüm planları kaydetmektedir.\""},{"n":22,"t":"Sizi karada ve denizde yürüten O'dur. (Düşünün ki) Gemidesiniz... Bir meltemle yolcuları alıp götürdüğü zaman gemiden memnundurlar. Aniden şiddetli bir fırtınaya yakalanırlar. Her yönden gelen dalgaların arasında tümüyle kuşatıldıklarını sandıkları an, dini sadece ALLAH'a ait kılarak, \"Bizi bundan kurtarırsan şükredenlerden olacağız,\" diye yalvarırlar."},{"n":23,"t":"Onları kurtarınca da yeryüzünde haksız yere taşkınlık yapmaya başlarlar. Ey insanlar, taşkınlığınız kendinize karşıdır. Dünya hayatının geçici zevkine düşkünsünüz; halbuki dönüşünüz bizedir ve yapmış olduğunuz her şeyi size haber veririz. İnsanlık Bilim ve Teknolojinin Zirvesindeyken"},{"n":24,"t":"Dünya hayatı, tıpkı şu örnek gibidir; gökten indirdiğimiz su insanların ve hayvanların yediği bitkilerin yapısına karışır. Bu durum, yeryüzünün süslenip bezendiği ve halkının da artık doğaya egemen olduklarını sandıkları ana kadar sürer. Nihayet geceleyin veya gündüzün ona emrimiz gelir. Sanki bir önceki gün hiç bir şeye sahip değilmiş gibi onu kökünden biçilmiş bir duruma sokarız. Düşünen bir toplum için ayetleri böyle açıklarız.*42"},{"n":25,"t":"ALLAH barış yurduna çağırır ve dilediğini doğru bir yola iletir. Cennet ve Cehennem"},{"n":26,"t":"Güzel davrananlara daha fazlası vardır. Yüzlerini ne bir yoksunluk ne de bir aşağılanma duygusu kaplar. Onlar cennet halkıdır. Orada ebedi kalıcıdırlar."},{"n":27,"t":"Kötülük ve günah kazananlara ise kötülüğünün aynısıyla karşılık verilir. Yüzlerini bir aşağılanma duygusu kaplar. ALLAH'tan başka bir koruyucuları yoktur. Yüzleri sanki karanlık geceden bir parçayla bürünmüştür. Onlar ateş halkıdır; onlar orada ebedi kalacaklardır. Ortak Koşulanlar Müşriklere Sahip Çıkmazlar"},{"n":28,"t":"Onları bir araya topladığımız gün, ortak koşanlara; \"Siz ve ortaklarınız haydi yerinize!,\" diyerek birbirlerinden ayırırız. Ortakları ise: \"Siz bize kulluk etmiyordunuz,\" derler."},{"n":29,"t":"\"Bizimle sizin aranızda ALLAH tanıktır ki, biz sizin kulluk etmenizden habersizdik.\""},{"n":30,"t":"İşte orada her can, geçmişte yapmış olduğunu bulur. Gerçek Mevlaları olan ALLAH'a döndürülürler. Uydurdukları (ortaklar) ise kendilerinden uzaklaşıp kaybolur. * 10:30 Müminler sadece Tanrı'yı mevla (efendi/koruyucu) edinir. Bak 2:286. Müşrikler Tanrı'ya İnanıyorlar"},{"n":31,"t":"De ki, \"Size gökten ve yerden kim rızık veriyor? İşitme ve görme duyularınızı kim kontrol ediyor? Ölüden diriyi, diriden ölüyü kim çıkarıyor? Tüm işleri kim yönetiyor?\" \"ALLAH,\" diyecekler. De ki: \"Öyleyse neden erdemli davranmıyorsunuz?\""},{"n":32,"t":"İşte Gerçek Rabbiniz ALLAH budur. Öyleyse gerçekten (yüz çevirmenizden) sonra sapıklıktan başka ne kalır? Nasıl da (bunları düşünmekten) çevriliyorsunuz?"},{"n":33,"t":"Yoldan çıkmış olanların inanmıyacağına dair Rabbinin sözü işte böyle gerçekleşir. Ortak Koştuğunuz Peygamberler ve Din Adamları"},{"n":34,"t":"De ki, \"Ortaklarınızdan hangisi yaratmayı başlatıp tekrarlayabilir?\" De ki: \"ALLAH yaratmayı başlatır ve onu tekrarlar. Nasıl da çevriliyorsunuz?\""},{"n":35,"t":"De ki \"Ortaklarınızdan hangisi gerçeğe ulaştırabilir?\" De ki, \"ALLAH gerçeğe ulaştırır. Gerçeğe ulaştıran mı uyulmaya daha yaraşır, yoksa gerçeğe ulaştırılmadıkça gerçeği bulamıyan mı? Ne biçim hüküm veriyorsunuz?\""},{"n":36,"t":"Onların çoğu, ancak zanna uyarlar. Zan ise gerçeğin yerini tutamaz. ALLAH onların yaptıklarını Bilendir. Bilgisini Kavramadıkları Kuran'ı Eleştiren Fanatikler"},{"n":37,"t":"Bu Kuran, ALLAH'tan başkası tarafından düzenlenen bir kitap değildir. Ancak kendisinden öncekileri onaylayan ve kitabın (yasaların) detaylı bir açıklamasıdır. Bunda kuşkunuz olmasın; evrenlerin Rabbindendir."},{"n":38,"t":"\"Onu uydurdu\" mu diyorlar? De ki: \"Doğru sözlüler iseniz, buna benzer bir sure getirin ve ALLAH'tan başka çağırabildiklerinizi çağırın.\""},{"n":39,"t":"Hayır, onlar bilgisini kavramadan ve asıl anlamına ulaşmadan onu yalanladılar. Kendilerinden öncekiler de böyle yalanladı. Zalimlerin sonuna dikkatle bak."},{"n":40,"t":"Onlardan kimi buna inanır, kimi de inanmaz. Rabbin bozgunculuk yapanları daha iyi bilir."},{"n":41,"t":"Seni yalanlarlarsa de ki: \"Benim yaptığım bana, sizin yaptığınız ise size! Siz benim yaptığımdan sorumlu değilsiniz, ben de sizin yaptığınızdan sorumlu değilim.\""},{"n":42,"t":"Onlardan seni dinleyenler de var; akıllarını kullanmayan sağırlara sen mi işittireceksin?"},{"n":43,"t":"Onlardan sana bakanlar da var; görüşü olmayan körleri sen mi doğruya ileteceksin?"},{"n":44,"t":"ALLAH insanlara hiç zulmetmez; ancak insanlar kendi kendilerine zulmederler."},{"n":45,"t":"Onları topladığımız gün, sanki gündüzden bir saat kadar (dünyada) kalmışlar gibi birbirlerini tanırlar. ALLAH ile karşılaşmayı yalanlayanlar kaybedenlerdir. Doğruyu da bulmamışlardır."},{"n":46,"t":"Onlara söz verdiklerimizin bir kısmını sana göstersek de veya canını alsak da, onların son dönüş yeri bizedir. Sonra ALLAH onların yaptıkları her şeye de tanıktır. Her Topluma"},{"n":47,"t":"Her bir toplum için bir elçi vardır. Elçileri geldiği zaman adaletle yargılanırlar ve hiç zulmedilmezler."},{"n":48,"t":"\"Bu söz ne zaman gerçekleşecek,\" diyorlar. Elçinin Hiç Bir Gücü Yoktur"},{"n":49,"t":"De ki: \"ALLAH'ın dilemesi dışında, ben kendime dahi ne bir zarar ne de bir yarar verme gücüne sahip değilim. Her toplumun bir süresi vardır. Süreleri bitince ne bir saat geciktirilir ne de öne alınırlar."},{"n":50,"t":"De ki: \"O'nun azabı ister gece veya gündüz gelsin, ama neden suçlular o konuda acele içindedirler?\""},{"n":51,"t":"\"Gerçekleştikten sonra mı ona inanacaksınız? Öyleyse neden onu şimdi çabuk isteyip duruyorsunuz?\""},{"n":52,"t":"Sonra zulmedenlere: \"Ebedi azabı tadın,\" denir, \"Kazandığınızdan başka bir karşılık mı bekliyordunuz?\""},{"n":53,"t":"\"Bu sahiden doğru mudur,\" diye senden haber bekliyorlar. De ki: \"Elbette, Rabbime andolsun o gerçektir ve siz onu engelleyemezsiniz!\" İnancın Değeri"},{"n":54,"t":"Zulmetmiş bir can yeryüzündeki her şeye sahip olsa, onu fidye olarak vermek isteyecektir. Azabı gördüklerinde derin pişmanlık duyacaklar. Adaletle yargılanacaklar ve onlara zulmedilmeyecektir."},{"n":55,"t":"Göklerde ve yerde olanlar elbette ALLAH'ındır. ALLAH'ın sözü tamamıyla gerçektir; fakat onların çoğu bilmez."},{"n":56,"t":"O diriltir ve öldürür. O'na döndürüleceksiniz."},{"n":57,"t":"Ey halk, Rabbinizden size bir öğüt, gönülleri sıkan her şeye karşı bir şifa, inananlara bir yol gösterici ve bir rahmet gelmiş bulunuyor."},{"n":58,"t":"De ki, \"Sadece, ALLAH'ın lütfu ve rahmetiyle sevinsinler. Bu, topladıkları herşeyden daha hayırlıdr.\" Besinlerle İlgili Mezheplerin Uydurduğu Haramlar"},{"n":59,"t":"De ki, \"ALLAH'ın size indirdiği rızıkların bir kısmını helal, bir kısmını da haram ettiğinizi görmez misiniz?\" De ki, \"ALLAH mı size izin verdi, yoksa ALLAH'a iftira mı ediyorsunuz?\""},{"n":60,"t":"ALLAH adına yalan uyduranlar diriliş gününü düşünmezler mi? ALLAH insanlara karşı bol lütuf sahibidir; ancak onların çoğu şükretmez. Her An Tanrı'yı Hissetmek ve Mutluluk"},{"n":61,"t":"Ne durumda bulunursanız bulunun, Kuran'dan ne okursanız okuyun, hangi işi yaparsanız yapın, siz onlarla uğraşırken biz mutlaka size tanık oluruz. Göklerde ve yerde bulunan bir atom ağırlığı bile Rabbinin kontrolünün dışına çıkamaz. Atomdan da küçük olsun büyük olsun, her şey apaçık bir kitapta kayıtlıdır."},{"n":62,"t":"ALLAH'ın dostları için ne bir korku vardır, ne de üzülürler."},{"n":63,"t":"Onlar ki, inandılar ve erdemli davrandılar."},{"n":64,"t":"Dünya hayatında da ahirette de mutluluk onlarındır. ALLAH'ın kelimeleri (verdiği söz) değişmez. İşte bu, en büyük zaferdir.*43"},{"n":65,"t":"Sözleri seni üzmesin. Üstünlük tümüyle ALLAH'a aittir. O İşitendir, Bilendir."},{"n":66,"t":"Göklerde ve yerde ne varsa ALLAH'ındır. ALLAH'tan başkalarına yalvaranlar aslında koştukları ortakları izlememektedirler. Onlar sadece tahmin yürütüyorlar ve sadece saçmalıyorlar."},{"n":67,"t":"O ki geceyi sizin dinlenmeniz için elverişli, gündüzü de aydınlık kıldı. Dinleyen bir topluluk için bunda deliller vardır."},{"n":68,"t":"\"ALLAH çocuk edindi!,\" dediler. O bundan çok yücedir. O, hiç bir şeye ihtiyacı olmayandır. Göklerde ve yerde ne varsa O'nundur. Sizin bu konuda hiç bir kanıtınız yoktur. ALLAH hakkında bilmediğiniz bir şeyi mi söylüyorsunuz?"},{"n":69,"t":"De ki: \"ALLAH hakkında yalan uyduranlar başarıya ulaşamazlar.\""},{"n":70,"t":"Dünyada paylarını alırlar, sonra dönüşleri bizedir. Sonra da inkarlarından ötürü onlara şiddetli azabı tattırırız. Nuh"},{"n":71,"t":"Onlara Nuh'un tarihini anlat. Halkına şunları demişti: \"Ey halkım, durumum ve ALLAH'ın ayetlerini hatırlatmam size ağır geldiyse, ben ALLAH'a güveniyorum. Ortaklarınız ve liderlerinizle birlikte toplanın, pişman olmayacağınız son kararınızı alın ve bekletmeden bana karşı uygulayın.\""},{"n":72,"t":"\"Yüz çevirirseniz, halbuki ben sizden her hangi bir ücret istememiştim. Benim ücretim ancak ALLAH'ın üzerinedir. Müslümanlardan olmakla emredildim.\""},{"n":73,"t":"Onu yalanladılar. Bunun üzerine onu ve gemide onunla beraber olanları kurtardık. Onları (yeryüzünün) yöneticileri yaptık. Ayetlerimizi yalanlayanları ise boğduk. Uyarılanların akıbetine dikkat et. İnsanlar İşledikleri İlk Günahta Israr Ediyorlar"},{"n":74,"t":"Sonra onun ardından, elçiler gönderdik, halklarına apaçık deliller getirdiler. Geçmişte yalanlamış bulunduklarına inanacak değillerdi. Azgınların kalplerini böyle damgalarız. Musa ve Harun Firavun'a Mesajı İletiyor"},{"n":75,"t":"Sonra onların ardından Musa ve Harun'u Firavun'a ve konseyine mucizelerimizle gönderdik. Fakat büyüklük tasladılar ve suçlu bir topluluk oldular."},{"n":76,"t":"Tarafımızdan kendilerine gerçek gelince, \"Bu apaçık bir büyüdür,\" dediler."},{"n":77,"t":"Musa, \"Size gelen gerçeği böyle mi nitelendiriyorsunuz? Bu bir büyü müdür? Oysa büyücüler başarıya ulaşamaz.\""},{"n":78,"t":"Dediler: \"Sen, yeryüzünde büyüklük ikinize kalsın diye, atalarımızı üzerinde bulduğumuz şeyden bizi çevirmek için mi bize geldin? Biz size asla inanmayız.\""},{"n":79,"t":"Firavun, \"Tüm uzman büyücüleri bana getirin!,\" dedi."},{"n":80,"t":"Büyücüler gelince, Musa onlara, \"Ne atacaksanız atın!,\" dedi."},{"n":81,"t":"Onlar atınca, Musa: \"Sizin bu getirdiğiniz bir büyüdür. ALLAH elbette onu boşa çıkaracaktır. ALLAH bozguncuların işlerini düzeltmez,\" dedi."},{"n":82,"t":"ALLAH sözleriyle hakkı gerçekleştirir. Suçlular hoşlanmasa da... Firavun Irkçı Bir Despottu"},{"n":83,"t":"Firavun ve erkanının işkence ve baskısından korktukları için Musa'ya, halkından ancak bir kaç kişi inandı. Firavun, yeryüzünde haddi çok aşan bir tiran idi."},{"n":84,"t":"Musa: \"Ey halkım, eğer gerçekten ALLAH'a inanmış ve O'na teslim olmuş iseniz O'na güvenin.\""},{"n":85,"t":"Dediler ki: \"ALLAH'a güvendik. Rabbimiz, bizi zalim halkın baskısına maruz bırakma.\""},{"n":86,"t":"\"Rahmetinle bizi inkarcı halktan kurtar.\" Baskı Dönemlerinde Evleri Mescid Olarak Kullanın"},{"n":87,"t":"Musa'ya ve kardeşine: \"Halkınız için Mısır'da evler hazırlayın. Evlerinizi tapınak yapın ve namazı gözetin. İnananları müjdeleyin,\" diye vahyettik. Zalimlere Beddua"},{"n":88,"t":"Musa dedi ki: \"Rabbimiz, sen Firavun ve konseyine dünya hayatında lüks ve mal verdin. Rabbimiz, senin yolundan saptırsınlar diye mi? Rabbimiz, onların mallarını silip süpür ve acı azabı görünceye kadar inanmasınlar diye kalplerini katılaştır.\""},{"n":89,"t":"Dedi ki: \"İkinizin duası kabul edilmiştir. Doğru olun ve bilmeyenlerin yolunu izlemeyin.\" Artık Çok Geç"},{"n":90,"t":"İsrail oğullarını denizden geçirdik. Firavun ve ordusu ise küstahça ve düşmanca arkalarına düştü. Boğulmak üzereyken, \"İsrail oğullarının inandığından başka tanrı olmadığına inandım, ben müslümanım,\" dedi."},{"n":91,"t":"\"Çok geç! Daha önce baş kaldırmış ve bozgunculardan olmuştun.\""},{"n":92,"t":"\"Senden sonraki kuşaklara ibret olman için bugün senin cesedini koruyacağız. Ne var ki insanların çoğunluğu işaretlerimizden habersizdirler.\""},{"n":93,"t":"İsrail oğullarına onurlu bir yer bağışladık ve onlara güzel rızıklar verdik. Fakat, kendilerine ilim geldikten sonra ayrılığa düştüler. Rabbin, diriliş günü, ayrılığa düştükleri konuda aralarında hüküm verecektir. Kuşkun Varsa Araştır, Bilenlerden Sor"},{"n":94,"t":"Sana indirdiğimiz hakkında bir kuşkun varsa, kitabı (senden) önce okumuş olanlara sor. Sana Rabbinden gerçek gelmiş bulunuyor. Şüphecilerden olma."},{"n":95,"t":"Sakın, ALLAH'ın ayetlerini yalanlayanlardan olma. Yoksa kaybedenlerden olursun."},{"n":96,"t":"Rabbinin kararıyla mahkum edilenler inanmazlar."},{"n":97,"t":"Onlara her çeşit mucize gelse bile, acı azabı görünceye kadar (inanmazlar). İnanan Toplumlar Refah ve Huzur İçinde Olurlar"},{"n":98,"t":"Hangi toplum inanırsa, inancı ona yarar sağlar. Örneğin; Yunus'un halkı: İnandıkları zaman, bu dünya hayatındaki aşağılayıcı azabı kendilerinden kaldırdık. Bir süreye kadar onları nimetlerle yaşattık."},{"n":99,"t":"Rabbin dileseydi, yeryüzündekilerin hepsi inanırdı. Öyleyse, sen mi halkı inanmaları için zorlayacaksın? 100. Hiç bir kişi ALLAH'ın izni olmadan inanamaz ve O, akıllarını kullanmayanları rezilliğe mahkum eder. 101. De ki: \"Göklerde ve yerde neler var, bir bakın! İnanmıyan bir topluma deliller ve uyarılar kâr etmez.\""}]},{"id":11,"name":"HUD (HUD) SÛRESİ","verses":[{"n":1,"t":"A.L.R. (Bu) öyle bir kitaptır ki, Bilge ve her şeyden Haberdar biri tarafından ayetleri sağlamlaştırılmış ve sonra da açıklanıp detaylanmıştır. Kuran: Uyarıcı ve Müjdeci"},{"n":2,"t":"Ki ALLAH'tan başkasına tapmayasınız. Kuşkusuz ben, O'ndan size bir uyarıcı ve bir müjdeciyim."},{"n":3,"t":"Rabbinizin bağışlamasını dileyip O'na tevbe etmelisiniz. O zaman, sizi belli bir süreye kadar güzelce geçindirir ve lütfu hakkeden herkese lütfundan verir. Dönerseniz, sizin için büyük günün azabından korkarım."},{"n":4,"t":"Dönüşünüz ALLAH'adır. O her şeye Gücü Yetendir."},{"n":5,"t":"Onlar, göğüslerindekini bilinç altına itip O'ndan gizlemek isterler. İyi bilin ki elbiselerini büründükleri zaman dahi onların gizlediklerini ve açıkladıklarını bilir. O, gizli düşünceleri bilendir. Her Şey Büyük Bir Plana Göredir"},{"n":6,"t":"Yeryüzündeki hiç bir yaratık yoktur ki rızkı ALLAH tarafından garanti edilmesin. Onların konaklarını ve uğrak yerlerini bilir. Tüm bunlar apaçık bir kitaptadır."},{"n":7,"t":"O, hanginizin daha iyi iş yaptığını test etmek için gökleri ve yeri altı günde yaratandır.*44 Egemenliği suyun üzerinde idi.* Buna rağmen, kafirlere, \"Siz ölümden sonra diriltileceksiniz,\" desen, kafirler, \"Bu, ancak açık bir büyüdür (kandırıcı bir sözdür),\" diyeceklerdir."},{"n":8,"t":"Onlardan azabı belli bir süre için ertelesek, \"Onu tutan nedir,\" derler. Doğrusu, onlara geldiği gün, kendilerinden geri çevrilemez ve alay ettikleri şey kendilerini kuşatacaktır."},{"n":9,"t":"İnsana kendimizden bir rahmet tattırsak ve sonra ondan çekip alsak, umutsuzlaşır, nankörleşir."},{"n":10,"t":"Kendisine dokunan zararlardan sonra ona nimetler tattırsak, \"Kötülükler benden gitti,\" der. Bu kez sevinçlidir, kibirlidir."},{"n":11,"t":"Sabredenler ve erdemli işler yapanlar için ise bir bağışlanma ve büyük bir ödül vardır."},{"n":12,"t":"\"Ona bir hazine, yahut onunla birlikte bir melek inmeli değil miydi,\" dedikleri için belki göğsün daralacak ve sana vahyedilenin bir kısmını terkedeceksin. Sen yalnız bir uyarıcısın; ALLAH her şeyi kontrol edendir. Kuran: Taklidi İmkansız"},{"n":13,"t":"\"Onu (Kuran'ı) o uydurdu\" mu diyorlar? De ki: \"Haydi ona benzer, uydurulmuş on sure getirin. ALLAH'tan başka tüm dostlarınızı da çağırın, doğru sözlülerseniz!\""},{"n":14,"t":"Size cevap veremedilerse bilesiniz ki o ALLAH'ın bilgisiyle indirilmiştir ve O'ndan başka tanrı yoktur. Artık müslüman olacak mısınız?"},{"n":15,"t":"Kim dünya hayatını ve lüksünü ararsa, yaptıklarının karşılığını orada tam öderiz ve onlar orada hiç bir eksikliğe uğratılmazlar."},{"n":16,"t":"Bunlar için ahirette, yalnız ateş vardır. Yaptıklarının hepsi orada boş çıkmıştır. Bütün yaptıkları geçersizdir. Musa'nın Kitabında da 19 Kodu"},{"n":17,"t":"Daha önce Musa'nın kitabı bir önder ve rahmet iken, şimdi Rab'lerinden gelen bir tanığın ilettiği kesin bir kanıta* sahip olanlar varya işte onlar ona inanırlar. Hangi grup onu inkar ederse yeri ateştir. Ondan hiç bir kuşkun olmasın. O, Rabbinden gelen bir gerçektir. Ne var ki halkın çoğunluğu inanmaz."},{"n":18,"t":"Uydurmaları ALLAH'a yakıştırandan daha zalim kim olabilir? Onlar Rab'lerinin huzuruna çıkarılır ve tanıklar: \"İşte Rab'leri hakkında yalan uyduranlar bunlardır,\" diyecekler. ALLAH'ın laneti zalimleredir."},{"n":19,"t":"Onlar ki ALLAH'ın yolundan alıkoyarlar ve onu çarpıtmak isterler. Onlar ahireti de inkar ederler."},{"n":20,"t":"Onlar, yeryüzünde kaçamazlar ve ALLAH'tan başka dost ve sahipleri yoktur. Onlar için azap katlanır. Çünkü onlar işitemediler, göremediler."},{"n":21,"t":"Onlar, kişiliklerini yitirenlerdir. Uydurdukları şeyler bile kendilerini terkedip kaybolmuştur."},{"n":22,"t":"Hiç kuşku yok ki, ahirette en çok kaybedenler onlardır. İnananlar"},{"n":23,"t":"İnanıp erdemli davrananlar ve Rab'lerine gönülden boyun eğenler ise cennet halkıdır. Onlar orada ebedi kalıcıdır."},{"n":24,"t":"Her iki grubun örneği, kör ve sağır olan biri ile gören ve işiten biri gibidir. Durumları bir midir? Öğüt almaz mısınız? Nuh ve Aristokrat İnkarcılar"},{"n":25,"t":"Nuh'u halkına gönderdik: \"Ben sizin için apaçık bir uyarıcıyım,\""},{"n":26,"t":"\"ALLAH'tan başkasına kulluk etmeyin. Acı bir günün azabına uğramanızdan korkarım.\""},{"n":27,"t":"Halkından inkar eden ileri gelenler, \"Seni sadece bizim gibi bir insan olduğunu görüyoruz ve aramızdaki sığ görüşlü ayak takımının dışında kimsenin seni izlemediğini görüyoruz. Sizin bizden herhangi bir üstünlüğünüzü de görmüyoruz. Tersine, biz sizin yalancı olduğunuzu sanıyoruz,\" dediler."},{"n":28,"t":"Dedi ki: \"Ey halkım, ya ben Rabbimden gelen kesin bir kanıta sahip isem ve bana bir rahmet vermiş de bunlar gözünüze görünmüyorsa? Siz onu istemezken sizi ona biz mi zorlayacağız?\""},{"n":29,"t":"\"Ey halkım, buna karşılık sizden herhangi bir para istemiyorum. Ücretim ancak ALLAH'tan gelir. İnananları da kovamam; onlar, Rab'leriyle karşılacaklar. Fakat, sizi cahillik eden bir topluluk olarak görüyorum.\""},{"n":30,"t":"\"Ey halkım, onları kovarsam ALLAH'a karşı kim bana yardım edecek? Düşünmez misiniz?\" Tüm Güç Tanrı'ya Aittir"},{"n":31,"t":"\"ALLAH'ın hazinelerinin yanımda olduğunu söylemiyorum, gizliyi bilmiyorum, melek olduğumu da ileri sürmüyorum. Gözlerinizin horladığı kimselere ALLAH'ın bir iyilik bağışlamıyacağını da söylemiyorum. Onların gizli düşüncelerini ALLAH daha iyi bilir. Aksi taktirde zalimlerden olurum.\""},{"n":32,"t":"Dediler ki: \"Ey Nuh, sen bizimle tartıştın ve bizimle tartışmayı uzattın. Doğru sözlü isen haydi bizi tehdit ettiğin şeyi getir bakalım.\""},{"n":33,"t":"Dedi ki: \"Onu, dilerse, sizin başınıza ancak ALLAH getirebilir. Siz engel olamazsınız.\""},{"n":34,"t":"\"ALLAH azmanızı dilemişse, ben size öğüt vermek istesem de size o öğüdümün bir yararı olmayacaktır. O' dur Rabbiniz ve siz O'na döndürüleceksiniz.\""},{"n":35,"t":"\"Bunu (bu aktarılan tarihsel tartışmayı) o uydurdu\" mu diyorlar? (Ey Muhammed) De ki: \"Onu ben uydurmuş isem, suçumdan ben sorumlu olacağım, ve sizin işlediğiniz suçlarla da benim bir ilişkim yok.\""},{"n":36,"t":"Nuh'a vahyedildi: \"Şu ana kadar inanmış olanların dışında artık halkından hiç kimse inanmıyacaktır. Onların tavırları seni üzmesin.\""},{"n":37,"t":"\"Gözetimimiz altında vahyimizle gemiyi yap. Zalimler için bana baş vurma; onlar suda boğulacaklardır.\" Tufan"},{"n":38,"t":"Gemiyi yapıyorken, halkının ileri gelenleri her yanından geçişte onunla alay ediyorlardı. Dedi ki: \"Bizimle alay ediyorsanız, sizin bizimle alay ettiğiniz gibi biz de sizinle alay ediyoruz.\""},{"n":39,"t":"\"Alçaltıcı azabın kime geleceğini ve kimin kalıcı azaba mahkum olacağını yakında bileceksiniz.\""},{"n":40,"t":"Nihayet emrimiz gelip de gök kaynayıp taşınca, kendisine dedik ki: \"Her türden birer çifti, daha önce mahkum edilmiş olanlar hariç, çoluk çocuğunu ve inananları ona yükle.\" Kendisiyle birlikte inanmış olanlar zaten bir kaç kişiydi."},{"n":41,"t":"Dedi ki: \"Gemiye binin. Akması ve durması ALLAH'ın adıyladır. Rabbim çok Bağışlayandır, Rahimdir.\""},{"n":42,"t":"Gemi, onları tepeler gibi dalgaların arasından geçirirken, Nuh bir kenarda ayrı duran oğluna seslendi: \"Yavrum, gel bizimle birlikte bin. Kafirlerle birlik olma.\""},{"n":43,"t":"O ise, \"Beni sudan koruması için bir tepeye sığınacağım,\" dedi. (Nuh): \"Bugün ALLAH'ın yargısından koruyacak hiç bir şey yoktur; ancak O'nun acıdıkları hariç,\" dedi. Dalgalar ikisi arasından geçti; o, boğulanların arasındaydı."},{"n":44,"t":"Ve denildi ki: \"Ey toprak suyunu yut, ey gök sen de tut.\" Su yatıştı, karar yerine getirildi, Cudi (Judea) üzerine oturdu ve \"Zalimler uzak olsunlar!,\" dendi."},{"n":45,"t":"Nuh Rabbine seslendi: \"Ey Rabbim, oğlum benim ailemdendir, Senin verdiğin söz ise elbette gerçektir ve Sen, yargıda bulunanların en iyisisin.\" Şefaat Hikayesi"},{"n":46,"t":"Dedi ki: \"Ey Nuh, o senin ailenden olamaz. Bilmediğin bir konuda benden istekte bulunman erdemli bir tavır değildir. Cahillerden olmamanı sana öğütlerim.\"*45"},{"n":47,"t":"Dedi ki: \"Rabbim, bilgim olmayan bir konuda sana yalvardığım için sana sığınırım. Beni bağışlamaz ve bana acımazsan kaybedenlerden olurum.\""},{"n":48,"t":"Dendi ki: \"Ey Nuh, sana ve seninle birlikte olan uluslara bizden barış ve bereketlerle in. Ayrıca öyle uluslar var ki onları bir süre yaşatacağız ve sonra onlara bizden acı bir azap dokunacaktır.\""},{"n":49,"t":"Bunlar, sana vahyettiğimiz gayb haberleridir. Ne sen, ne de senin halkın bundan önce onları bilmezdi. Sabret. Sonuç, erdemlilerindir. Hud ve Ad Halkı"},{"n":50,"t":"Ad halkına da kardeşleri Hud'u... Dedi ki: \"Ey halkım, ALLAH'a kulluk edin. O'ndan başka tanrınız yoktur. Siz ancak uyduruyorsunuz.\""},{"n":51,"t":"\"Ey halkım, buna karşılık olarak sizden herhangi bir ücret te istemiyorum. Benim ücretim, beni ilk yaratandan başkasına düşmez. Aklınızı kullanmıyor musunuz?\""},{"n":52,"t":"\"Ey halkım, Rabbinizden bağışlanma dileyin, sonra O'na yönelin ki gökten üzerinize bol rahmet yağdırsın, gücünüze güç katsın. Suçlular olarak yüz çevirmeyin!\""},{"n":53,"t":"Dediler ki: \"Ey Hud, sen bize kesin bir kanıt ile gelmedin. Biz, sırf senin sözünle dinimizi bırakacak değiliz, sana inanacak değiliz.\""},{"n":54,"t":"\"Senin tanrılarımızdan biri tarafından çarpıldığını söyleriz,\" dedi ki: \"ALLAH'ı tanık tutuyorum, siz de tanık olun ki ben uzağım sizin ortak koştuğunuz \""},{"n":55,"t":"\"O'ndan başkalarından. Haydi, topunuz birleşip bana karşı plan hazırlayın. Hiç de beklemeyin.\""},{"n":56,"t":"\"Ben, Rabbim ve Rabbiniz olan ALLAH'a güvendim. O'nun kontrol etmediği hiç bir yaratık yoktur. Rabbim dosdoğru yolun üzerindedir.\""},{"n":57,"t":"\"Yüz çevirirseniz, artık ben, kendisiyle gönderildiğim mesajı size bildirdim. Rabbim yerinize başka bir halk geçirecek ve siz O'na hiç bir zarar veremezsiniz. Benim Rabbim her şeyi Gözetip Kontrol Edendir.\""},{"n":58,"t":"Emrimiz gelince Hud'u ve beraberindeki inananları bizden bir rahmetle kurtardık. Onları dehşetli bir azaptan kurtardık."},{"n":59,"t":"İşte Ad (halkı) böyleydi. Rab'lerinin ayetlerini reddettiler, elçilerine isyan ettiler ve her inatçı zorbanın emrini izlediler."},{"n":60,"t":"Bunun üzerine, hem dünya hayatında ve hem diriliş gününde bir lanete uğradılar. Kısacası, Ad halkı, Rab'lerine karşı çıktı. Hud'un halkı Ad yok olmuştur. Salih, Semud Halkına Tüm Elçilerin ve İnananların Ortak Mesajını İletiyor 61. Semud'a da kardeşleri Salih'i... Dedi ki: \"Ey halkım, ALLAH'a kulluk edin, O'ndan başka tanrı yoktur. Sizi yerden çıkarıp yaratan, sizi oraya yerleştiren O'dur. Öyleyse O'ndan bağışlanma dileyin ve sonra O'na yönelin. Kuşkusuz Rabbim Yakındır, Yanıtlayandır.\""},{"n":62,"t":"Dediler ki: \"Ey Salih, sen bundan önce, aramızda popüler bir umut kaynağıydın. Atalarımızın tapmış olduklarından sen şimdi bizi men mi ediyorsun? Biz, senin bizi çağırdığın şeylerden kuşku içindeyiz.\""},{"n":63,"t":"Dedi ki: \"Ey halkım, ya ben Rabbimden kesin bir delile sahipsem ve kendisinden bana rahmet vermişse? O'na isyan edecek olursam beni ALLAH'tan kim kurtarabilir? Siz ancak benim kayıplarımı arttırabilirsiniz?\""},{"n":64,"t":"\"Ey halkım, ALLAH'ın bu devesi sizin için bir ayettir. ALLAH'ın toprağında bırakın otlansın. Ona kötülük dokundurmayın. Yoksa sizi yakın bir azap yakalar.\""},{"n":65,"t":"Fakat, onu işkenceyle kestiler. \"Yurdunuzda yaşamanız için üç gününüz var. Bu, yalan olmayan bir sözdür,\" dedi."},{"n":66,"t":"Emrimiz gelince, Salih'i ve beraberinde inanmış olanları bizden bir rahmet ile o günün rezilliğinden kurtardık. Rabbin, kuşkusuz Güçlü ve Üstündür."},{"n":67,"t":"Zalimleri korkunç bir ses yakaladı, yurtlarında çöküp kaldılar."},{"n":68,"t":"Sanki orada hiç yaşamamışlardı. Doğrusu Semud (halkı) Rab'lerine karşı geldi; Semud yok olup gitti. İbrahim ve Lut"},{"n":69,"t":"Elçilerimiz İbrahim'e müjdeyi götürdüklerinde \"Selam!\" (Barış olsun) dediler. O da \"Selam!,\" dedi ve hemen (onlara) kızartılmış bir buzağı sundu."},{"n":70,"t":"Ellerinin ona uzanmadığını görünce, durumlarını beğenmedi; içine bir korku düştü. \"Korkma,\" dediler, \"Biz Lut'un halkına gönderilmiş bulunuyoruz.\""},{"n":71,"t":"Ayakta duran karısı (bu habere sevinip) gülünce biz de ona İshak'ı ve İshak'ın ardından Yakub'u müjdeledik."},{"n":72,"t":"\"Vay başıma gelenler,\" dedi, \"Ben bir yaşlı kadın ve kocam da ihtiyar bir adam iken çocuk mu doğuracağım? Bu çok garip bir şey!\""},{"n":73,"t":"\"ALLAH'ın işine mi şaşıyorsun,\" dediler, \"ALLAH'ın rahmeti ve bereketi sizin üzerinizedir ey ev halkı. O Övgüye En Layıktır, Yücelerin Yücesidir.\""},{"n":74,"t":"İbrahim'den korku gidip kendisine bu müjde verilince Lut halkı hakkında bizimle tartışmaya başladı."},{"n":75,"t":"Doğrusu, İbrahim çok yumuşak, çok duygulu ve sürekli (Tanrı'ya) yönelen biriydi."},{"n":76,"t":"\"Bundan vazgeç İbrahim. Rabbinin emri gelmiş bulunuyor; onlar önlenemez bir azaba mahkum olmuşlardır.\" Homoseksüel İlişkiler Kınanıyor Azgınlar Yanardağ Patlamasıyla Cezalandırılıyor"},{"n":77,"t":"Elçilerimiz Lut'a gelince, onlara kötü davranıldı. Bu durum (Lut'un) canını sıktı ve (kendi kendine), \"Bu, zor bir gün olacak,\" dedi."},{"n":78,"t":"Halkı koşarak oraya geldiler; günah işlemeyi adet haline getirmişlerdi. \"Ey halkım, işte kızlarım, onlar sizin için daha temizdir. ALLAH'ı sayın, konuklarım önünde beni rezil etmeyin. İçinizde aklı başında bir adam yok mu,\" dedi."},{"n":79,"t":"\"Bilirsin ki senin kızlarına bizim bir ihtiyacımız yok. Sen bizim ne istediğimizi iyi bilirsin,\" dediler."},{"n":80,"t":"(Lut:) \"Keşke size gücüm yetseydi veya güçlü dostlara sahip olsaydım,\" dedi."},{"n":81,"t":"(Melekler) \"Ey Lut,\" dediler, \"Biz, Rabbinin elçileriyiz. Onlar sana dokunamazlar. Aileni gecenin bir anında yürüyüşe çıkart, sizden hiç kimse geriye bakmasın; fakat senin karın istisna. Ötekilerin başına gelecek olanlar onun da başına gelecektir. Onların belirlenmiş zamanı sabahtır. Sabah yakın değil mi?\""},{"n":82,"t":"Emrimiz gelince onun üstünü altına getirdik, üzerlerine sertleşmiş kat kat taş yağdırdık."},{"n":83,"t":"Zalimleri bulsun diye Rabbin tarafından belirlenmiş (taşlar)... Şuayb: Halkını Ekonomik ve Sosyal Reforma Çağırıyor"},{"n":84,"t":"Medyen'e de kardeşleri Şuayb'ı... Dedi ki: \"Ey halkım, ALLAH'a kulluk edin, O'ndan başka tanrınız yoktur. Ölçüyü tartıyı eksik tutmayın. Sizi refah içinde görüyorum ve sizin için, kuşatıcı bir günün azabından korkuyorum.\""},{"n":85,"t":"\"Ey halkım, ölçüyü ve tartıyı adaletle tam uygulayın. Halkın hakkını eksik vermeyin ve yeryüzünde bozgunculuk yaparak kötülük işlemeyin.\""},{"n":86,"t":"\"İnanıyorsanız, ALLAH'ın (helal) bıraktığı, sizin için daha iyidir. Ben sizin üzerinize bekçi değilim.\""},{"n":87,"t":"Dediler ki: \"Şuayb, atalarımızın tapmış olduklarını veya ticaretimizi dilediğimiz gibi çevirmekten vazgeçmemizi, senin namazın mı gerektiriyor? Sen aslında yumuşak huylusun, akıllısın.\""},{"n":88,"t":"\"Halkım,\" dedi, \"Bakın, ya ben Rabbimden kesin bir kanıta sahip isem ve bana kendisinden güzel bir nimet bağışlamışsa...? Sizi bazı şeylerden yasaklamam, size zıt gitmek istediğim için değildir. Ben ancak, gücüm yettiğince reform yapmak istiyorum. Başarım ancak ALLAH'tandır. O'na güvendim ve O'na yöneliyorum.\""},{"n":89,"t":"\"Halkım, bana karşı çıkışınız, sakın sizi Nuh halkının, veya Hud halkının, yahut Salih halkının başına gelenler gibi bir felakete uğratmasın. Üstelik, Lut halkı sizden pek uzakta değil.\""},{"n":90,"t":"\"Rabbinizden bağışlanma dileyin, sonra O'na tevbe edin. Kuşkusuz Rabbim Rahimdir, Sevendir.\""},{"n":91,"t":"\"Şuayb,\" dediler, \"Senin söylediklerinin bir çoğunu anlamıyoruz. Üstelik biz, seni aramızda güçsüz görüyoruz. Kabilen olmasaydı seni taşlardık. Senin bize karşı herhangi bir üstünlüğün yoktur.\""},{"n":92,"t":"Dedi ki: \"Ey halkım, kabilem size göre ALLAH'tan daha mı üstündür ki O'na sırt çevirdiniz? Rabbim, sizin tüm yaptıklarınızı Kuşatandır.\""},{"n":93,"t":"\"Halkım, elinizden geleni yapın; ben de yapacağım. Alçaltıcı azabın kime geleceğini ve kimin yalancı olduğunu ileride bileceksiniz. Umutla bekleyin, ben de sizinle birlikte umutla bekliyorum.\""},{"n":94,"t":"Emrimiz gelince Şuayb'ı ve kendisiyle beraber inanmış olanları bizden bir rahmetle kurtardık. Zulmedenleri korkunç gürültü yakaladı; yurtlarında çöküp kaldılar."},{"n":95,"t":"Sanki orada hiç yaşamamışlar gibi... Semud, nasıl yok edildiyse, Medyen de öylece yok edildi. Musa"},{"n":96,"t":"Musa'yı ayetlerimizle (mucize ve vahyimizle) ve kesin bir yetkiyle gönderdik"},{"n":97,"t":"Firavun ve konseyine... Ancak onlar Firavun'un buyruğuna uydular. Firavunun buyruğu ise akıllıca değildi."},{"n":98,"t":"Diriliş gününde halkına öncülük edip onları ateşe sokacaktır. Girdikleri yer ne kötü bir mekandır!"},{"n":99,"t":"Burada da, ahirette de peşlerine lanet takılmıştır. Aldıkları armağan ne kötü armağandır! Alınacak Dersler 100. Sana bu aktardıklarımız, o kentlerin haberlerindendir. Onlardan kimi hala ayakta, kimi de biçilmiştir. 101. Biz onlara zulmetmedik, onlar kendi kendilerine zulmettiler. Rabbin emri geldiği zaman, ALLAH'tan başka yalvardıkları tanrıları onları hiç bir şeyden kurtaramadı. Aslında, onların yalnızca ziyanlarını arttırdı. 102. İşte Rabbin, zulmetmekte olan kentleri yakaladığı zaman böyle yakalar. O'nun yakalaması acıdır, çetindir. 103. Ahiret azabından korkanlar için bunda bir ders vardır. Halkın toplandığı bir gündür o. Tanık olunan bir gündür o. 104. Onu ancak sayılı bir süre için erteliyoruz. 105. O gün geldiği zaman, hiç kimse O'nun izni olmadan konuşamaz. Onlardan kimi talihsiz, kimi de mutludur. 106. Talihsizler ateştedir. Onlar orada sızlayıp inlerler. 107. Gökler ve yer durduğu sürece orada kalıcıdırlar; ancak Rabbin dilerse başka. Rabbin, dilediğini Yapandır. 108. Mutluluğu hakkedenler ise, gökler ve yer kaldığı sürece cennette kalıcıdırlar. Rabbinin dilerse başka. Kesintisiz bir ödüldür bu."}]},{"id":12,"name":"YUSUF (YUSUF) SÛRESİ","verses":[{"n":1,"t":"A.L.R. Bu (harfler), apaçık kitabın mucizeleridir."},{"n":2,"t":"Onu Arapça bir Kuran olarak indirdik ki anlayasınız. * 12:2 Bu ayetin farklı bir anlamı için bak 43:3."},{"n":3,"t":"Sana bu Kuran'ı vahyederek, sana en güzel bir anlatımla tarihi aktarıyoruz. Sen daha önce bundan habersizdin. Rüyayla Başlayan Gerçek Bir Hayat Hikayesi"},{"n":4,"t":"Yusuf, bir zamanlar babasına: \"Babacığım, on bir gezegeni, güneşi ve ay'ı gördüm, onların bana secde ettiklerini gördüm,\" dedi."},{"n":5,"t":"(Babası Yakup:) \"Yavrum,\" dedi, \"Rüyanı kardeşlerine anlatma, olur ki sana karşı bir plan kurarlar. Çünkü şeytan, insana apaçık bir düşmandır."},{"n":6,"t":"\"Böylece Rabbin seni seçmekte, sana rüyaların yorumunu öğretmekte ve daha önceki ataların İbrahim ve İshak'a nimetini tamamladığı gibi sana ve Yakup ailesine de tamamlamaktadır. Rabbin Bilendir, Bilgedir.\""},{"n":7,"t":"Dileyenler için, Yusuf ve kardeşlerinde dersler vardır:"},{"n":8,"t":"(Kardeşleri) demişlerdi ki: \"Babamız, Yusuf ve (öz) kardeşini bizden daha çok seviyor, biz ise çoğunluğuz. Babamız açıkça yanlış bir tutum içindedir. Kıskanç Duyguların Şeytani Fısıltısı"},{"n":9,"t":"\"Yusuf'u öldürün, ya da onu bir uzak yere yollayın ki babanızın ilgisi sizde odaklansın. Daha sonra da erdemli bir topluluk olursunuz.\""},{"n":10,"t":"Onlardan birisi şöyle dedi: \"Yusuf'u öldürmeyin, onu kuyunun dibine atın. Böyle yaparsanız kervanlardan biri onu bulup götürebilir.\""},{"n":11,"t":"Dediler ki: \"Ey babamız, neden Yusuf hakkında bize güvenmiyorsun? Oysa biz onun candan dostlarıyız.\""},{"n":12,"t":"\"Onu bizimle birlikte yolla ki koşup oynasın. Kuşkusuz biz onu koruyacağız.\""},{"n":13,"t":"Dedi ki: \"Onu götürmeniz beni endişelendirir. Korkarım ki haberiniz yokken onu kurt yer.\""},{"n":14,"t":"Dediler ki: \"Biz kalabalık bir grup olduğumuz halde onu kurt yerse, o zaman gerçekten kaybedenler oluruz.\" Allah, İnananlara Güvence Verir"},{"n":15,"t":"Onu götürdükleri ve kuyunun dibine atmak için topluca karar verdikleri sırada biz ona: \"(Üzülme) Onların bu yaptıklarını, hiç farkında olmayacakları bir anda onlara anlatacaksın,\" diye vahyettik."},{"n":16,"t":"Akşamleyin ağlayarak babalarına geldiler."},{"n":17,"t":"\"Ey babamız,\" dediler, \"Gittik, yarışıyorduk. Yusuf'u da eşyamızın yanında bırakmıştık. Sonunda onu kurt yedi. Doğru konuşsak bile sen bize inanmıyacaksın.\""},{"n":18,"t":"Gömleğine yalandan kan bulaştırmışlardı. Dedi ki: \"Doğrusu, egonuz sizi bir işe sürüklemiş. Bana düşen (bu acıya) güzelce dayanmaktır. Sizin komplonuza karşı ancak ALLAH'tan yardım istenir.\" Yusuf Mısır'a Götürülüyor"},{"n":19,"t":"Oradan geçmekte olan bir kervan, sucularını gönderdi, kovasını sarkıtınca: \"Müjde, burada bir erkek çocuğu var!,\" dedi. Onu ticari bir mal olarak sakladılar. ALLAH onların yaptıklarını biliyordu."},{"n":20,"t":"Ona ihtiyaçları olmadığı için ucuz bir fiyata, bir kaç dirheme sattılar."},{"n":21,"t":"Onu Mısır'da satın alan kişi, karısına, \"Ona iyi bak, olur ki bize yararı dokunur, ya da onu evlat ediniriz,\" dedi. Böylece Yusuf'u yeryüzünde yerleştirip ona rüyaların yorumunu öğretiyorduk. ALLAH işini sonuçlandırandır; fakat halkın çoğu bunu bilmez."},{"n":22,"t":"Büyüyüp erginleşince ona bilgelik ve bilgi verdik. Güzel davrananları böyle ödüllendiririz. Sınanıyor"},{"n":23,"t":"Evinde bulunduğu kadın onu baştan çıkarmak istedi, kapıları kitledi ve: \"Tümüyle sana aidim,\" dedi. Dedi ki: \"ALLAH'a sığınırım. O benim Rabbimdir (efendimdir), ki bana iyi bir yer verdi. Zalimler başarmaz.\""},{"n":24,"t":"Kadın onu çok arzulamıştı, Rabbinin işaretini görmeseydi o da onu çok arzulamıştı. Böylece kötülük ve fenalığı ondan çevirdik. O, katışıksız kullarımızdandı."},{"n":25,"t":"Kapıya doğru koşuştular. Kadın onun gömleğini arkadan çekip yırttı. Kapının yanında kadının beyiyle karşılaştılar. Kadın: \"Karına tecavüz etmek isteyen kişinin ya hapsedilmesi veya acı bir azapla cezalandırılması gerekmez mi,\" dedi. Kanıtlar Suçluyu Ele Veriyor"},{"n":26,"t":"Dedi ki: \"Aslında senin karın beni baştan çıkarmak istedi.\" Aileden bir tanık: \"Gömleği ön taraftan yırtılmışsa kadın doğruyu söylüyor, o ise bir yalancıdır.\""},{"n":27,"t":"\"Yok eğer gömleği arkadan yırtılmışsa, o zaman kadın yalancı, o doğru sözlüdür,\" diye tanıklıkta bulundu."},{"n":28,"t":"Gömleğinin arkadan yırtılmış olduğunu görünce, \"Bu, siz kadınların planıdır. Planınız müthiştir,\" dedi."},{"n":29,"t":"\"Yusuf, sen bu olayı unut. Sen de (ey kadınım) günahından dolayı bağışlanma dile. Sen hata işledin.\""},{"n":30,"t":"Şehirde bir takım kadınlar: \"Valinin karısı hizmetçisini baştan çıkarmaya çalışıyor,\" dediler, \"Ona çılgıncasına aşık. Onu açık bir sapıklık içinde görüyoruz.\" Yusuf'un Çekiciliği"},{"n":31,"t":"Kadın, onların dedikodusunu işitince onları davet etti. Onlar için konforlu yerler hazırladı. Her birine birer bıçak verdi. (Kadınlar, meyvelerini soymakla meşgul iken Yusuf'a:) \"Onların huzuruna çık,\" dedi. Kadınlar onu görünce, öyle etkilendiler ki ellerini kestiler ve: \"ALLAH korusun, bu bir insan değil; bu ancak asil bir melektir,\" dediler."},{"n":32,"t":"(Kadın:) \"İşte siz beni bunun için suçlamıştınız. Onu baştan çıkarmak istedim, ancak (iffetini) koruyup beni reddetti. Kendisine emrettiğimi yapmazsa hapishaneye atılacak ve aşağılanacaktır,\" dedi."},{"n":33,"t":"(Yusuf:) \"Rabbim, hapishane, onların beni çağırdığı şeyden daha iyidir. Planlarını benden savmazsan onlara meyledip cahillerden olurum,\" dedi."},{"n":34,"t":"Rabbi onun duasına yanıt verdi ve kadınların planlarını ondan savdı. O İşitendir, Bilendir."},{"n":35,"t":"Sonra, (vali ve adamları Yusuf'un suçzuzluğuna dair) kanıtları görmelerine rağmen, onu belli bir süreye kadar hapishaneye atmayı uygun gördüler. Hapishanede"},{"n":36,"t":"Onunla birlikte hapishaneye iki genç adam da girdi. Onlardan biri: \"(Rüyamda) kendimi şarap yaparken gördüm,\" dedi. Diğeri: \"Ben de başımın üzerinde ekmek taşırken kendimi gördüm, onu kuşlar yiyordu. Bunların yorumunu bize bildir. Seni iyilerden görüyoruz.\""},{"n":37,"t":"\"Size ayrılan karavana yemeği elinize geçmeden önce size onun yorumunu bildirebilirim. Bunlar, Rabbimin bana öğrettiği şeylerdendir. Ben, ALLAH'a inanmıyan bir toplumun dinini terketmiş bulunuyorum, onlar ahiret konusunda da inkarcıdırlar.\""},{"n":38,"t":"\"Ben, atalarım İbrahim, İshak ve Yakub'un dinine uydum. ALLAH'a herhangi bir şeyi ortak koşmak bize yakışmaz. Bu, ALLAH'ın bize ve halka olan lütfudur. Ancak insanların çoğu şükretmez.\" Tanrı'dan Başka Rabb (Efendi) Yok"},{"n":39,"t":"\"Ey hapishane arkadaşlarım, çeşitli rabler mi daha iyidir, yoksa Tek ve her şeye Egemen olan ALLAH mı?\""},{"n":40,"t":"\"O'ndan başka taptıklarınız, sizin ve atalarınızın uydurduğu isimlerden ibarettir. ALLAH onlara her hangi bir güç vermemiştir. Hüküm, ancak ALLAH'ındır. Yalnızca kendisine kulluk etmenizi emretmiştir. Dosdoğru din işte budur. Ne var ki halkın çoğu bunu bilmiyor.\""},{"n":41,"t":"\"Hapishane arkadaşlarım, biriniz rabbine (efendisine) şarap sunacak, diğeriniz ise çarmıha gerilecek ve kuşlar onun başından yiyecek. Sorduğunuz iş çözülmüştür.\""},{"n":42,"t":"O ikisinden, kurtulacağını öngürdüğü kimseye, \"Beni rabbinin yanında an,\" dedi. Rabbini anmayı Şeytan ona (Yusuf'a) unutturunca hapiste birkaç yıl daha kaldı.*46"},{"n":43,"t":"Kıral dedi ki: \"Rüyamda yedi semiz inek görüyorum, onları yedi zayıf inek yiyor; ayrıca yedi yeşil ve yedi kuru başak... Ey seçkinler, rüyaların yorumunu yapabiliyorsanız bu rüyamı bana çözüverin.\""},{"n":44,"t":"\"Karmakarışık rüyalardır bunlar. Biz böyle rüyaların yorumunu bilmeyiz,\" dediler."},{"n":45,"t":"O iki kişiden kurtulmuş olanı, nice zaman sonra hatırladı ve, \"Beni (Yusuf'a) gönderirseniz size onun yorumunu bildireceğim,\" dedi. Yusuf, Kralın Rüyasını Yorumluyor"},{"n":46,"t":"(Zindana gidip:) \"Yusuf, ey can arkadaşım, bize yedi sıska inek tarafından yenen yedi semiz inek, yedi yeşil ve kuru başak hakkında açıklama getir de halka bilgi vereyim.\""},{"n":47,"t":"Dedi ki: \"Yedi yıl boyunca ekip biçtiğinizi, yediğiniz az bir kısmının dışında, başaklarında bırakıp depolayın.\""},{"n":48,"t":"\"Sonra, onun ardından yedi kurak (yıl) gelecek ve sizin depoladığınızın az bir bölümü hariç, o yıllar için önceden biriktirdiklerinizi yiyip bitirecektir.\""},{"n":49,"t":"\"Ondan sonra ise öyle bir yıl gelir ki onda halk ferahlanacak ve onda (meyve) sıkıp, (hayvan) sağacaklar.\""},{"n":50,"t":"Kral, \"Onu bana getirin,\" dedi. Elçi ona gelince (Yusuf,) \"Rabbine dön ve parmaklarını kesen kadınların durumunu ondan sor. Kuşkusuz benim Rabbim, onların entrikalarını bilir,\" dedi. Yusuf'u Hapishaneye Sokturan Kadın Yeniden Açılan Duruşmada İtirafta Bulunuyor"},{"n":51,"t":"(Kral kadınlara:) \"Yusuf'u baştan çıkarmak isterken durumunuz neydi?\" Kadınlar, \"ALLAH korusun; biz ondan bir kötülük görmedik!,\" dediler. Bunun üzerine, valinin karısı şöyle dedi: \"Gerçek artık ortaya çıktı. Onu ben yoldan çıkarmaya çalışmıştım. O doğru konuşuyor.\""},{"n":52,"t":"\"Umarım ki arkasında kendisine ihanet etmediğimi bilir, zira ALLAH hainlerin planını onaylamaz.\""},{"n":53,"t":"\"Suçsuz olduğumu ileri sürmüyorum. Kuşkusuz ego, kötülüğü arzular. Ben ancak Rabbimin merhametini umuyorum; Rabbim Bağışlayandır, Rahimdir.\" Yusuf, Mısır'ın Maliye Bakanı Oluyor"},{"n":54,"t":"Kral dedi ki: \"Getirin onu, yanımda çalışması için onu atayayım\" Kendisiyle konuşup görüşünce, \"Sen artık bugün yanımızda önemli bir makamı olan güvenilir birisin,\" dedi."},{"n":55,"t":"Dedi ki: \"Beni ülkenin maliye işlerinin başına getir. Kuşkusuz ben iyi korur, iyi bilirim,\" dedi."},{"n":56,"t":"Böylece Yusuf'u o ülkede yerleştirdik. Dilediği gibi hareket edebiliyordu. Dilediğimiz kimseye rahmetimizi yağdırırız. Güzel davrananları ödülsüz bırakmayız."},{"n":57,"t":"İnananların ve erdemli davrananların ahiret ödülü elbette daha da iyidir. Yusuf'un Kardeşleri, Kıtlık Yıllarında Filistin'den Mısır'a Erzak Satın Almaya Geliyorlar"},{"n":58,"t":"Yusuf'un kardeşleri gelip onun huzuruna girdiler. (Yusuf) onları tanıdı; ancak onlar onu tanımadı."},{"n":59,"t":"Yüklerini hazırlatınca şöyle dedi: \"Baba tarafından olan kardeşinizi getirin. Görmüyor musunuz ben ölçüyü tartıyı tam, evsahipliğini de iyi yapıyorum.\""},{"n":60,"t":"\"Onu bana getirmezseniz, artık benden ölçülüp tartılacak bir şey beklemeyin ve bana yaklaşmayın.\""},{"n":61,"t":"Dediler ki: \"O'nun hakkında babasını ikna etmeye çalışacağız. Kuşkun olmasın ki buna çalışacağız.\""},{"n":62,"t":"(Yusuf) Emri altındakilere de şöyle emir verdi: \"Ailelerine döndüklerinde bulmaları için, takas eşyalarını yüklerinin içine sokun, belki böylece geri dönerler.\""},{"n":63,"t":"Babalarına döndüklerinde, \"Ey babamız,\" dediler, \"Bundan böyle bize erzak yasaklandı. Kardeşimizi bizimle yolla da erzak alalım. Biz onu koruruz,\" dediler."},{"n":64,"t":"\"Daha önce kardeşi için size nasıl güvendiysem şimdi de onun içinde mi size güveneyim? ALLAH en iyi Koruyucudur ve O, Merhametlilerin Merhametlisidir.\""},{"n":65,"t":"Erzak yüklerini açınca, eşyalarının kendilerine geri verilmiş olduğunu gördüler ve, \"Ey babamız, daha ne isteriz? İşte eşyalarımız bize geri verilmiş. Ailemizin geçimini sağlar, kardeşimizi korur ve bir deve yükü daha erzak alırız. Bu, kolay bir iştir,\" dediler."},{"n":66,"t":"\"Hepiniz kuşatılıp engellenmedikçe onu bana getireceğinize dair bana, ALLAH adına sağlam bir söz vermezseniz, onu sizinle beraber göndermem. Onlar ona söz verince, \"Söylediklerimize ALLAH tanıktır,\" dedi. Tehlikelere Karşı Önlem"},{"n":67,"t":"Dedi ki: \"Yavrularım, bir tek kapıdan girmeyin; farklı kapılardan girin. Ne var ki, ALLAH'ın önceden belirlediği şeyden sizi kurtaramam. Hüküm ALLAH'ındır ancak. Ben O'na güvendim. Güvenenler O'na güvenmeli.\""},{"n":68,"t":"Babalarının kendilerine emrettiği yerlerden girdiler. Bu, onları ALLAH'ın hiç bir takdirinden kurtaramazdı; ancak Yakup onlardan bunu istemekte özel bir nedene sahipti. O, kendisine öğrettiğimiz belli bir bilgiye sahipti; fakat halkın çoğu bilmez."},{"n":69,"t":"Yusuf'un huzuruna girdiklerinde, kardeşini yanına yaklaştırdı ve, \"Ben senin kardeşinim; onların yaptıklarına üzülme,\" dedi. Yusuf, Öz Kardeşini Yanında Tutmak İçin Plan Uyguluyor"},{"n":70,"t":"Onların erzak yükünü hazırlatınca bir su kabını kardeşinin torbasına koydu. Daha sonra bir ünleyici şöyle seslendi: \"Ey kervan siz hırsızlarsınız.\""},{"n":71,"t":"Onları karşılayarak, \"Neyi kaybettiniz,\" dediler."},{"n":72,"t":"\"Kralın su tasını kaybettik. Kim onu getirirse ona bir deve yükü ödül verilecektir. Ben bunu garantiliyorum.\""},{"n":73,"t":"Dediler ki: \"ALLAH'a andolsun, siz de bilirsiniz ki biz bu ülkede bozgunculuk çıkarmaya gelmedik, biz hırsız da değiliz.\""},{"n":74,"t":"Dediler: \"Peki, yalan söylüyorsanız onun cezası nedir?\""},{"n":75,"t":"\"Onun cezası,\" dediler, \"Kimin torbasında bulunursa o kişi alıkonur. Biz zalimleri böyle cezalandırırız.\""},{"n":76,"t":"(Yusuf) kardeşinin yükünden önce onların yüklerinden başladı ve sonra su kabını kardeşinin yükünden çıkardı. Biz Yusuf'a böyle bir planı öğretmiştik. Kralın yasasını uygulasaydı kardeşini alıkoyamazdı; ALLAH dilese başka.*47 Dilediğimizi derecelerle yükseltiriz. Her bilenin üstünde daha iyi bir bilen vardır."},{"n":77,"t":"\"O çalmışsa, daha önce kardeşi de çalmıştı,\" dediler. Yusuf onlara belli etmeden: \"Siz gerçekten kötüsünüz. ALLAH anlattığınızın içyüzünü bilir,\" diye söylendi."},{"n":78,"t":"Dediler ki: \"Sayın ekselans, onun oldukça yaşlı bir babası var; onun yerine bizden birimizi al. Biz seni iyilik edenlerden olduğunu görüyoruz.\""},{"n":79,"t":"Dedi ki: \"Yanında eşyamızı bulduğumuz kimseden başkasını alıkoymaktan ALLAH'a sığınırız, o zaman biz zalimlerden oluruz.\""},{"n":80,"t":"Ondan ümitlerini kesince, danışmak üzere bir kenara çekildiler. Büyükleri: \"Babanızın sizden ALLAH adına bir söz aldığını ve daha önce Yusuf konusunda da sınırı aşmış olduğunuzu bilmez misiniz? Babam bana izin verinceye, yahut ALLAH hakkımda hüküm verinceye kadar buradan ayrılmayacağım. O, en iyi Hükmedendir,\" dedi,"},{"n":81,"t":"\"Babanıza dönün ve şunları söyleyin: 'Ey babamız, oğlun hırsızlık yaptı. Biz ancak bildiğimiz şeye tanıklık ediyoruz. Gizli işlenen bir şeyi önleyemezdik.'\""},{"n":82,"t":"'Bulunduğumuz topluluğa ve beraber geldiğimiz kervana sor. Biz doğruyu anlatıyoruz.' \""},{"n":83,"t":"\"Hayır, egonuz sizi bir işe sürüklemiş. Bana düşen artık güzelce sabretmektir. Olur ki ALLAH, bana onları topluca getirir. O, Bilendir, Bilgedir,\" dedi."},{"n":84,"t":"Onlardan yüz çevirdi ve, \"Vah, yazık oldu Yusuf'a!,\" dedi. Üzüntüden gözlerine ak düştü, acısını içine gömdü."},{"n":85,"t":"Dediler ki: \"ALLAH'a andolsun, Yusuf'u anmaya devam edersen ya hasta düşeceksin veya öleceksin.\""},{"n":86,"t":"\"Ben kahrımı ve tasamı ancak ALLAH'a şikayet ederim, sizin bilmediğinizi ALLAH'tan biliyorum,\" dedi."},{"n":87,"t":"\"Oğullarım, gidin, Yusuf'u ve kardeşini araştırın. ALLAH'ın rahmetinden umut kesmeyin. İnkarcılardan başkası ALLAH'ın rahmetinden umut kesmez.\" İsrail Mısır'a Gidiyor"},{"n":88,"t":"(Yusuf'un) Huzuruna girince, \"Sayın ekselans, bize ve ailemize darlık dokundu; bu yüzden değersiz bir eşya ile geldik. Ama sen bize tam ölçü ver, bize yardımda bulun. ALLAH sadaka verenleri ödüllendirir,\" dediler."},{"n":89,"t":"\"Sizler cahiller iken, Yusuf ve kardeşine neler yaptığınızı biliyor musunuz,\" dedi."},{"n":90,"t":"\"Yoksa sen, sen gerçekten Yusuf musun,\" dediler. \"Ben Yusuf'um, bu da kardeşimdir. ALLAH bize iyilikte bulundu. Kim erdemli davranır ve sabrederse elbette ALLAH güzel davrananları ödülsüz bırakmaz,\" dedi."},{"n":91,"t":"\"ALLAH'a andolsun ki ALLAH seni bizden üstün tutmuştur. Biz gerçekten hatalıydık,\" dediler."},{"n":92,"t":"Dedi ki: \"Bugün size kınama yoktur. ALLAH sizi affetsin. O, merhametlilerin En Merhametlisidir.\""},{"n":93,"t":"\"Bu gömleğimi götürün ve onu babamın yüzüne atın; gözü açılsın. Tüm ailenizle birlikte bana gelin.\""},{"n":94,"t":"Kervan (Mısır'dan) ayrılınca babaları, \"Beni bunamış saymayın, Yusuf'un kokusunu işitiyorum,\" dedi."},{"n":95,"t":"\"ALLAH'a andolsun sen hâlâ eski şaşkınlığın içindesin,\" dediler."},{"n":96,"t":"Müjdeci gelip de onu (gömleği) onun yüzüne atınca, tekrar görmeye başladı ve şöyle dedi: \"ALLAH'tan sizin bilmediğiniz şeyleri biliyorum dememiş miydim?\""},{"n":97,"t":"Dediler ki: \"Ey babamız, günahlarımızın bağışlanmasını dile. Biz gerçekten yanlış davrandık.\""},{"n":98,"t":"Dedi ki: \"Sizin için Rabbimden bağışlanma dileyeceğim; O, Bağışlayandır, Rahimdir.\"*48"},{"n":99,"t":"Yusuf'un yanına vardıklarında, anababasını kucakladı ve: \"ALLAH'ın izniyle güven içinde Mısır'a girin,\" dedi. 100. Ana ve babasını tahtın üzerine kaldırdı. Hepsi onun için secdeye kapandılar. Dedi ki: \"Babacığım, bu, önceden görmüş bulunduğum rüyanın gerçekleşmesidir. Rabbim onu gerçekleştirdi. şeytan, benimle kardeşlerimin arasını açtıktan sonra O beni hapishaneden çıkararak ve sizi çölden getirerek bana iyilikte bulundu. Gerçekten Rabbim dilediğine karşı çok şefkatlidir. O, Bilendir, Bilgedir.\" 101. \"Rabbim, sen bana hükümranlık verdin ve rüyaların yorumunu öğrettin. Yeri ve göğü ayırarak yaratansın. Dünya ve ahirette sensin benim Velim (sahibim). Canımı Müslüman olarak al ve beni iyilere kat.\" 102. Bunlar, sana vahyettiğimiz geçmişin haberleridir. Onlar topluca karar alıp düzen kurarlarken sen onların yanında değildin. Halkın Çoğunluğu İnançsızdır 103. Ne kadar istesen de halkın çoğunluğu inanmıyacaktır. 104. Halbuki sen onlardan herhangi bir ücret te istemiyorsun. Bu, sadece halka bir uyarıdır. 105. Göklerde ve yerde nice deliller var ki yanından dikkatsizce geçerler. İnananların da Çoğunluğu Müşriktir 106. Onların da çoğu, ortak koşmadan ALLAH'a inanmaz. 107. Onlar, ALLAH tarafından kuşatıcı bir azabın kendilerine çatmasından, yahut dünyanın sonunun (Saat) aniden kendilerine gelmesinden emin mi oldular? 108. De ki, \"Benim yolum şudur: Açık bir delille ALLAH'a çağırırım, aynı şekilde beni izleyenler de... ALLAH Yücedir, ben ortak koşan birisi değilim.\" 109. Senden önce, kentler halkının arasından (seçip) vahyettiğimiz adamlardan başkasını göndermedik.*49 Yeryüzünü dolaşıp kendilerinden öncekilerin akıbetine bakmazlar mı? Erdemliler için ahiret yurdu daha iyidir; anlamaz mısınız? * 12:109 Burada \"adam\" olarak çevirdiğimiz \"rical\" kelimesi \"erkek\" veya \"iki ayak üzerinde yürüyen/insan\" anlamlarına gelir. Bak: 2:239; 7:46-48; 22:27; 39:29; 72:5. 110. Ne zaman ki elçiler umutlarını kestiler ve kendilerinin yalancı çıkarıldığını sandılar, işte o zaman onlara zaferimiz geldi. Nitekim, dilediğimiz kurtulur. Azabımız suçlular topluluğundan geri çevrilemez. Kuran, Bir Uydurma Hadis Değildir; Tanrı'nın Bizim İçin Gerekli Gördüğü Her şeyi İçerir 111. Onların tarihinde, bilinç sahipleri için bir ders vardır. Bu, uydurma bir hadis değil; fakat kendisinden öncekilerin doğrulayıcısı, herşeyin detaylı açıklaması* ve inananlar için bir hidayet ve Rahmettir. * 12:111 Bak 31:6; 33:38; 45:6. ** 12:111 Bak 11:1."}]},{"id":13,"name":"GÖK GÜRLEMESİ (RA'D) SÛRESİ","verses":[{"n":1,"t":"A.L.M.R. Bu (harfler), kitabın mucizeleridir. Rabbinden sana indirilen, gerçektir; fakat halkın çoğu inanmaz."},{"n":2,"t":"Görebileceğiniz bir direk olmadan gökleri yükselten, sonra tüm yönetime egemen olan, güneşi ve ayı buyruk altına alan ALLAH'tır. Hepsi belli bir süre için akıp gitmektedir. Tüm işleri kontrol eder ve ayetleri detaylı olarak açıklar ki Rabbinizle kavuşma konusunda kuşkunuz kalmasın."},{"n":3,"t":"O ki yeryüzünü inşa edip üzerine sağlam dağlar, ırmaklar ve erkekli dişili yarattığı her çeşit meyveyi yerleştirdi. Geceyi gündüze bürüyor. Düşünen bir toplum için elbette bunda işaretler ve dersler vardır."},{"n":4,"t":"Yeryüzünde, birbirine komşu toprak parçaları, üzüm bağları, ekinler, çatallı ve çatalsız hurmalıklar vardır. Bunların hepsi aynı su ile sulanmalarına rağmen lezzetçe birbirinden farklı kılmışızdır. Aklını kullanan bir toplum için elbette bunda işaretler ve dersler vardır. Kurtuluş İçin Ahirete İnanmak Gerekir"},{"n":5,"t":"Şaşacaksan, onların şu sözlerine şaşmalısın: \"Biz toprak olduktan sonra yeniden mi yaratılacağız?\" İşte onlar, Rab'lerini inkar edenlerdir. Onlar, boyunlarına prangalar hakedenlerdir. Onlar ateşin halkıdır; nitekim orada ebedi kalıcıdırlar."},{"n":6,"t":"İyilik isteyeceklerine, başlarına hemen bir felaket getirmeni isterler; oysa kendilerinden önce örnekler gelip geçti. Rabbin, işledikleri zulme rağmen halka karşı bağışlayıcıdır. Rabbinin azabı çetindir."},{"n":7,"t":"İnkarcılar, \"Ona bir mucize inmeli değil miydi,\" diyorlar. Sen ancak bir uyarıcısın. Her toplum için bir Yol Gösterici vardır."},{"n":8,"t":"ALLAH her dişinin yüklendiğini, rahimlerin eksilttiğini ve arttırdığını bilir. O'nun yanında her şey belli bir ölçüye göredir.*50 * 13:8 Bak 4:119."},{"n":9,"t":"Gizliyi ve açığı Bilendir; Büyüktür, Yücedir."},{"n":10,"t":"Sözü ister gizleyin, ister açıklayın, ister gecenin karanlığında saklanın, ister gündüzün ortaya çıkın O'nun için birdir. Toplumsal Sorunların Çözümü: Toplumsal İrade ve Reform"},{"n":11,"t":"(Onların herbiri için) önünden ve ardından nöbetleşerek izleyenler vardır. Onu ALLAH'ın emriyle korurlar. Bir topluluk kendisini değiştirmedikçe ALLAH onların durumunu değiştirmez. ALLAH bir topluluk için fenalık istedi mi, hiç bir güç onu durduramaz; onların O'ndan başka bir koruyup kollayanları da olmaz."},{"n":12,"t":"O, size korku ve umut olarak şimşeği gösteren ve ağır bulutları oluşturandır."},{"n":13,"t":"Gök gürlemesi O'nu överek, melekler de O'nu saygıyla yüceltirler. O, yıldırımları gönderir ve dilediğini onlarla çarpar. Onlar hâlâ ALLAH hakkında tartışıyorlar. O, dayanılmaz güce sahiptir. Şeyhlerden, Velilerden, Türbelerden, Peygamberlerden Medet Umanlar"},{"n":14,"t":"Gerçek dua O'na yöneltilendir. O'nun dışında çağırdıkları ise onlara hiç bir şekilde karşılık veremezler. Tıpkı suya avuçlarını uzatan; ancak ağzına hiç bir şey ulaşmıyan kimse gibi... İnkarcıların duası boşunadır."},{"n":15,"t":"Göklerde ve yerde olan herkes ister istemez ALLAH'a secde eder. Gölgeleri de sabah akşam..."},{"n":16,"t":"De ki: \"Göklerin ve yerin Rabbi kim?\" De ki: \"ALLAH\" De ki: \"O'ndan başka, kendilerine dahi yarar ve zarar veremiyen kimseleri evliyalar mı edindiniz?\" De ki: \"Hiç körle gören bir olur mu, yahut hiç karanlıkla ışık bir olur mu?\" Yoksa ALLAH'ın yarattığı gibi yaratan ortaklar buldular da yaratmalarını birbiriyle mi karıştırdılar? De ki: \"ALLAH her şeyin yaratıcısıdır, O Tektir, Egemendir.\" Hak ve Batıl"},{"n":17,"t":"Gökten bir su indirir, dereler onunla dolar taşar ve sel bol köpük yüklenir. Aynı şekilde, mücevherat yahut eşya yapmak için erittikleri maddelerden de benzer bir köpük elde ederler. ALLAH gerçeği ve batılı böyle bir örnekle tanıtır. Köpük, kaybolup gider; ancak insanlara yarar veren ise yerde kalır. İşte ALLAH örnekleri böyle verir."},{"n":18,"t":"Rab'lerinin çağrısına uyanlar güzeli hak ederler. O'nun çağrısına uymayanlar ise, yeryüzündekilerin hepsine ve bir o kadarına sahip olsalar dahi kurtulmak için hepsini fidye olarak vermeye hazır olacaklardır. Sorgulamanın en kötüsü onlar içindir ve yerleri cehennemdir; ne de felaketli bir konaktır o! İnananlar"},{"n":19,"t":"Sana indirilenin gerçek olduğunu bilen biri, görmeyen gibi midir? Ancak akıl sahipleri öğüt alır."},{"n":20,"t":"Onlar ki ALLAH'a verdikleri sözü yerine getirirler ve sözleşmeyi bozmazlar."},{"n":21,"t":"Onlar ki ALLAH'ın birleştirmesini emrettiği şeyi birleştirirler, Rab'lerini sayarlar ve kötü hesaptan korkarlar."},{"n":22,"t":"Ve onlar ki sadece Rab'lerinin onayını kazanmak için sabredip direnirler, namazı gözetirler, kendilerine verdiğimiz rızıklardan gizli ve açık yardım için harcarlar ve kötülüğü iyilik ile savarlar. Son durağı onlar hak etmişlerdir."},{"n":23,"t":"Adn cennetlerine girerler. Atalarından, eşlerinden ve soylarından iyi olanlar da onunla beraberdir. Melekler de her kapıdan yanlarına varırlar."},{"n":24,"t":"\"Sabrettiğinizden ötürü selam (barış ve huzur) size olsun. Bu ne güzel son durak!\" İnkarcılar"},{"n":25,"t":"ALLAH'a verdikleri sözden sonra sözleşmeyi bozanlar, ALLAH'ın birleştirmeyi emrettiğini birleştirmeyenler ve yeryüzünde bozgunculuk yapanlar laneti hakketmişlerdir ve onlar için kötü bir sonuç vardır. Dünya Hayatı ve Ahiret"},{"n":26,"t":"ALLAH dilediğine rızkı açar veya kısar. Onlar dünya hayatı ile sevindiler, halbuki bu dünya hayatı ahiret ile karşılaştırıldığında bir geçimlikten ibarettir."},{"n":27,"t":"İnkar edenler, \"Ona Rabbinden bir mucize indirilmeli değil miydi,\" diyorlar. De ki: \"ALLAH dileyeni saptırır ve yöneleni doğruya ulaştırır.\""},{"n":28,"t":"Onlar ki inanırlar ve kalpleri ALLAH'ı anmakla huzur bulur. Bilesiniz ki, kalpler ALLAH'ı anmakla yatışır."},{"n":29,"t":"İnanıp erdemli bir hayat sürenler için müjde ve en güzel dönüş yeri vardır. İnkarcıların Bağnazlığı"},{"n":30,"t":"Daha önceki toplumlara olduğu gibi seni de bu topluma gönderdik ki sana vahyettiğimizi onlara okuyasın, halbuki onlar Rahman'a nankörlük ediyorlar. De ki: \"O'dur benim Rabbim; O'ndan başka tanrı yoktur. O'na güvendim; dönüş O'nadır.\""},{"n":31,"t":"Kendisiyle dağlar yürütülen, yahut yeryüzü parçalanan, yahut ölüler dirilten bir Kuran olsaydı bile (onlar yine inanmazdı). Tüm işler ALLAH'ın kontrolündedir. İnananlar hâlâ anlamadılar mı ki ALLAH dileseydi tüm insanları doğruya ulaştırırdı. İnkar edenler, ALLAH'ın sözü yerine gelinceye kadar yaptıklarına karşılık olarak ya başlarına ya da yakınlarına konacak bir felakete uğrayıp duracaklardır. ALLAH sözünden dönmez. Elçiler İlk Başta Alaya Alınırlar"},{"n":32,"t":"Senden önceki elçilerle de alay edildi. İnkarcılara fırsat verdim ve sonunda onları yakaladım. Sonuç nasıldı?"},{"n":33,"t":"Herkesin yaptığını kontrol eden O değil midir? Buna rağmen ALLAH'a ortaklar koştular. De ki: \"Onları (dilediğiniz) isimlerle tanımlayın! Siz O'nun yeryüzünde bilmediği bir şeyi mi O'na haber veriyorsunuz, yoksa boş sözler mi uyduruyorsunuz?\" Aslında, inkarcıların hileleri kendilerine süslü gösterilir ve böylece yoldan saparlar. ALLAH kimi saptırırsa ona doğruyu gösterecek yoktur."},{"n":34,"t":"Onlar dünya hayatında azap hakketmişlerdir. Ahiret azabı ise daha kötüdür. Onları ALLAH'tan kimse kurtaramaz. Cennet Mecazen Anlatılıyor"},{"n":35,"t":"Erdemlilere söz verilen cennetin örneği şudur: Altından ırmaklar akar, yemişi de süreklidir gölgesi de. Bu, erdemlilerin sonudur. Kafirlerin sonu ise ateştir."},{"n":36,"t":"Kendilerine kitap vermiş olduklarımız sana indirilene sevinirler. Bazı gruplar onun bir kısmını inkar ederler. De ki: \"ALLAH'a kul olmakla ve O'na ortak koşmamakla emredildim. O'na çağırırım ve dönüşüm de O'nadır.\" Bilgisayar Çağının Mucizesi"},{"n":37,"t":"Böylece onu Arapça bir yasa olarak indirdik. Sana gelen bilgiden sonra onların keyfine uyarsan ALLAH'a karşı ne bir dostun ne de bir koruyucun olamaz. * 13:37 Bu ayetin farklı bir anlamı için bak 43:3."},{"n":38,"t":"Senden önce elçiler gönderdik ve onlara eşler ve çocuklar verdik. ALLAH'ın izni olmadan hiç bir elçi bir mucize getiremez. Her dönemin bir yazgısı vardır."},{"n":39,"t":"ALLAH dilediğini siler, dilediğini bırakır. Ana Kitap O'nun yanındadır."},{"n":40,"t":"Onlara söz verilenlerin bir kısmını sana göstersek de, senin canını alsak da, sana düşen görev bildirmektir. Hesap ise bize düşer."},{"n":41,"t":"Yeryüzünün uçlarından eksilttiğimizi görmüyorlar mı? ALLAH hüküm verir ve O'nun hükmünü izleyip çevirecek de yoktur. O, en hızlı hesaplıyandır."},{"n":42,"t":"Onlardan öncekiler de düzenler kurdular; halbuki tüm düzenler ALLAH'a aittir. Her kişinin kazandığını bilir. Kafirler de zaferin kime ait olduğunu bileceklerdir."},{"n":43,"t":"İnkar edenler, \"Sen bir elçi değilsin!,\" diyorlar. De ki, \"ALLAH ve kitabın bilgisine sahip olanlar benimle sizin aranızda şahit olarak yeter.\""}]},{"id":14,"name":"İBRAHİM (İBRAHİM) SÛRESİ","verses":[{"n":1,"t":"A.L.R. Bir kitaptır. Onu sana indirdik ki, halkı Rab'lerinin izniyle karanlıklardan aydınlığa çıkarasın, O Güçlü ve Övgüye layık olanın yoluna. . ."},{"n":2,"t":"Yani ALLAH'ın. O ki göklerde ve yerde bulunanların hepsine sahiptir. Hakkettikleri çetin azaptan dolayı vay kafirlerin haline."},{"n":3,"t":"Onlar ki dünya hayatını ahirete yeğlerler, ALLAH'ın yolundan saptırırlar ve onu eğriltmek isterler. Bunlar, alabildiğine sapmışlardır. Elçinin Dili"},{"n":4,"t":"Biz her elçiyi ancak halkının diliyle göndeririz ki onlara bildirebilsin. ALLAH dileyeni/dilediğini saptırır, dileyeni/dilediğini de doğruya ulaştırır. O, Güçlüdür, Bilgedir."},{"n":5,"t":"Musa'yı, \"Halkını karanlıklardan aydınlığa çıkar ve onlara ALLAH'ın günlerini hatırlat,\" diye mucizelerimizle gönderdik. Sabreden ve şükreden herkes için elbette bunda dersler vardır."},{"n":6,"t":"Hani, Musa halkına, \"ALLAH'ın üzerinizdeki nimetini hatırlayın. Size işkencenin en kötüsünü uygulayan, oğullarınızı kesip kadınlarınızı sağ bırakan Firavun'un adamlarından sizi O kurtardı. Bu, Rabbinizden sizin için büyük bir test idi,\" demişti. Şükür ve Nankörlük"},{"n":7,"t":"Rabbin, \"Şükrederseniz size daha bol veririm, ama nankörlük ederseniz azabım çetindir,\" diye bildirmişti."},{"n":8,"t":"Musa: \"Yeryüzünde bulunan herkesle birlikte nankörlük etseniz, bilesiniz ki ALLAH muhtaç değildir, övgüye layıktır,\" demişti. İnsanoğlunun Genel Karakteri"},{"n":9,"t":"Sizden öncekilerin, Nuh, Aad ve Semud halkının ve onlardan sonra gelip de sadece ALLAH'ın bildiği kimselerin haberleri size ulaşmadı mı? Elçileri onlara apaçık delillerle gittiler, fakat onları küçümsediler ve \"Biz getirdiğiniz şeyi inkar ediyoruz ve bizi çağırdığınız mesaj hakkında kuşkumuz ve şüphemiz var,\" dediler. Atalarımızı Körükörüne İzlemek: İnsanlığın Trajedisi"},{"n":10,"t":"Elçileri: \"Gökleri ve yeri yarıp yaratan ALLAH'tan mı kuşkulanıyorsunuz? Günahlarınızı bağışlamak için sizi çağırıyor ve size belli bir süre tanıyor,\" dediler. Onlar da, \"Siz, ancak bizim gibi insanlarsınız, atalarımızın tapmakta olduğu şeyden bizi çevirmek istiyorsunuz. Bize açık bir yetki belgesi getiriniz,\" dediler."},{"n":11,"t":"Elçileri ise kendilerine şöyle dediler: \"Biz, elbette sizin gibi birer insanız. Ancak, ALLAH, kullarından dilediğini seçerek ona lütufta bulunur. ALLAH'ın izni olmadan size bir yetki belgesi getirmemiz olanaksızdır. İnananlar ALLAH'a güvenmeli."},{"n":12,"t":"\"Bize yollarımızı göstermişken neden ALLAH'a güvenmiyelim? Sizin bize yaptığınız eziyete karşı sabırla direneceğiz. Güvenenler ALLAH'a güvenmeli.\""},{"n":13,"t":"İnkarcılar elçilerine, \"Ya bizim dinimize geri dönersiniz ya da sizi yurdumuzdan kovarız!,\" dediler. Rab'leri onlara, \"Zalimleri yok edeceğiz,\" diye vahyetti,"},{"n":14,"t":"\"Onlardan sonra o yurda sizi yerleştireceğiz. Bu, otoriteme saygı duyan ve tehditlerimden korkanlar içindir.\""},{"n":15,"t":"Zafer istediler, böylece her inatçı zorba perişan oldu."},{"n":16,"t":"Ardından da cehennem... Tadı bozuk sudan içirilirler."},{"n":17,"t":"Onu yutmaya çalışır, ama boğazından geçiremez. Ölüm kendisine her yandan gelir, ama ölemiyecek. Ardından da çetin bir azap gelecektir."},{"n":18,"t":"Rab'lerini inkar edenlerin yaptıkları işler, fırtınalı bir günde rüzgarın savurduğu kül gibidir. Kazandıklarından hiç bir şey elde edemezler. İşte gerçek kayıp budur."},{"n":19,"t":"ALLAH'ın gökleri ve yeri belli bir amaç için yarattığını görmez misiniz? Dilerse sizi götürüp, yerinize yeni yaratıklar getirir."},{"n":20,"t":"Bu, ALLAH için güç değildir."},{"n":21,"t":"Hepsi ALLAH'ın huzuruna durduklarında. Zayıflar, büyüklük taslamış olanlara: \"Biz sizin izleyicileriniz idik. Bizi ALLAH'ın azabından bir parça kurtarabilir misiniz,\" dediler. Onlar da: \"ALLAH bize bir yol gösterseydi biz de size gösterirdik. Artık sızlansak da dayansak da bizim için birdir, kaçıp kurtulacak bir yerimiz yok.\" Şeytan Kendisini İzleyenlere Sahip Çıkmaz"},{"n":22,"t":"Karar yayımlandıktan sonra şeytan onlara şöyle dedi: \"ALLAH size gerçeği söz verdi, ben ise size söz verdim ve sözümden caydım. Benim sizin üzerinize herhangi bir gücüm yoktu; ben sizi çağırdım, siz de bana katıldınız. Bundan dolayı beni kınamayın, yalnızca kendinizi kınayın. Ne siz beni kurtarabilirsiniz ne de ben sizi kurtarabilirim. Beni ortak koşmanızı zaten önce de inkar etmiştim. Zalimler için acı bir azap vardır."},{"n":23,"t":"İnanan ve erdemli davrananlar, içinden ırmaklar akan cennetlere sokulmuşlardır. Rab'lerinin izniyle orada sürekli kalırlar. Oradaki dirlik temennileri, \"Selam,\" dır. Doğru ve Yanlış"},{"n":24,"t":"Görmez misin ki ALLAH güzel bir sözü güzel bir ağaca benzetir: Kökü sabit, dalları ise göktedir."},{"n":25,"t":"Rabbinin izniyle her mevsim meyvelerini verir. Öğüt almaları için ALLAH insanlara böyle örnekler verir."},{"n":26,"t":"Kötü bir söz de, yerden koparılmış köksüz kötü bir ağaç gibidir."},{"n":27,"t":"ALLAH inananları dünya hayatında da, ahirette de kanıtlanmış sözle destekler. ALLAH zalimleri ise saptırır ve ALLAH dilediğini yapar."},{"n":28,"t":"ALLAH'ın nimetini nankörlükle karşılayarak halklarını felaket yurduna mahkum edenleri görmedin mi?"},{"n":29,"t":"Cehennemde yanacaklardır. Ne kötü bir duraktır o! Şirk: Kötülüklerin Temel Kaynağı"},{"n":30,"t":"ALLAH'ın yolundan saptırmak için O'na eşler koştular. De ki: \"Biraz eğlenin, son yolculuğunuz ateşe olacaktır.\""},{"n":31,"t":"İnanan kullarıma söyle, alış-verişin ve dostluğun olmadığı gün gelmeden önce namazı gözetsinler, kendilerine verdiğimiz rızıklardan gizli ve açık yardım için versinler."},{"n":32,"t":"ALLAH gökleri ve yeri yaratan, gökten bir su indirip sizin için çeşitli meyvelerden besinler çıkarandır. Koyduğu yasaya göre sizi denizde taşıması için gemileri emrinize verdi. Aynı şekilde ırmakları da emrinize verdi."},{"n":33,"t":"Görevlerini aksatmayan güneşi ve ay'ı hizmetinize sundu, geceyi ve gündüzü de hizmetinize sundu."},{"n":34,"t":"O'ndan ne dilediyseniz size verdi. ALLAH'ın nimetlerini sayarsanız bitiremezsiniz. İnsanoğlu gerçekten çok zalimdir, çok nankördür. İbrahim"},{"n":35,"t":"Bir zamanlar İbrahim demişti ki: \"Rabbim, bu beldeyi güvenli kıl, beni ve çocuklarımı putlara tapmaktan koru.\""},{"n":36,"t":"\"Rabbim, onlar, insanlardan bir çoğunu saptırdılar. Beni izleyenler bendendir. Bana karşı gelenlere gelince, elbette sen Bağışlayansın, Rahimsin.\""},{"n":37,"t":"\"Rabbimiz, ben çocuklarımdan bazısını, Kutsal Evinin yanındaki ekinsiz bir vadiye yerleştirdim. Rabbimiz, onlar namazı gözetsinler diye... İnsanların gönüllerini onlara karşı sempatiyle doldur ve onları ürünlerle rızıklandır ki şükretsinler.\""},{"n":38,"t":"\"Rabbimiz, bizim gizlediğimizi ve açıkladığımızı bilirsin. Yerde ve gökte hiç bir şey ALLAH'a gizli kalmaz.\""},{"n":39,"t":"\"İhtiyarlık çağımda bana İsmail'i ve İshak'ı bahşeden ALLAH'a övgüler olsun. Rabbim, dualarımı işitir.\""},{"n":40,"t":"\"Rabbim, beni namazı gözeten biri kıl, çocuklarımı da... Rabbimiz dualarımı kabul et.\""},{"n":41,"t":"\"Rabbimiz, hesabın görüleceği gün, beni, anamı babamı ve inananları bağışla.\""},{"n":42,"t":"Zalimlerin yapmakta olduklarından ALLAH'ı habersiz sanma. Onları sadece, gözlerin dehşetten donup kalacağı güne kadar ertelemektedir."},{"n":43,"t":"Başları boyunları üstüne kaskatı dikilmiş, göz kapakları kıpırdamaksızın korkudan dolayı zihinleri bomboş bir halde koşuşurlar. Tanrı, Mesajını Elçileri Yoluyla Gönderir"},{"n":44,"t":"Halkı, azabın kendilerine geleceği gün konusunda uyar. Zalimler, \"Rabbimiz bizi yakın bir süreye kadar ertele de senin çağrına katılalım ve elçilere uyalım,\" diyecekler. Oysa daha önce siz, sonunuzun gelmeyeceğine yemin etmemiş miydiniz?"},{"n":45,"t":"Hatta, sizden önce kendilerine zulmetmiş olanların konutlarına yerleşmiştiniz ve onlara yaptıklarımız da size belli olmuştu. Üstelik, size örnekler de vermiştik."},{"n":46,"t":"Onlar planlarını yaptılar, halbuki planları ALLAH'ın kontrolündeydi. Planları dağları yerinden oyanatacak kadar olsa bile..."},{"n":47,"t":"ALLAH'ın, elçilerine verdiği sözden döneceğini sanmayın. ALLAH elbette Üstündür, Öc alandır. Yeni Yer ve Yeni GöklerYaratılıyor"},{"n":48,"t":"Yerin başka bir yer ile göklerin de başka göklerle değiştirildiği, herkesin Tek ve En yüce olan ALLAH'ın huzuruna getirildiği gün...*51"},{"n":49,"t":"O gün suçluları, zincirlere vurulmuş olarak görürsün."},{"n":50,"t":"Giysileri katrandandır ve yüzlerini ateş kaplar."},{"n":51,"t":"Böylece ALLAH herkese yaptığının karşılığını verir. ALLAH hızlı hesap görendir."},{"n":52,"t":"Bu, insanlara bir bildiridir. Bu uyarıyı dinlesinler, O'nun yalnız tek Tanrı olduğunu bilsinler ve akıl sahipleri öğüt alsınlar."}]},{"id":15,"name":"HİCR VADİSİ (HİCR) SÛRESİ","verses":[{"n":1,"t":"A.L.R. Bu (harfler) kitabın ve apaçık Kuran'ın mucizesidir."},{"n":2,"t":"İnkar edenler, keşke müslüman olsaydık diye arzulayacaklardır."},{"n":3,"t":"Bırak onları, yesinler, eğlensinler ve umutlarıyla oyalansınlar; mutlaka öğreneceklerdir."},{"n":4,"t":"Biz hiç bir topluluğu belirlenmiş bir yazgı olmaksızın yok etmeyiz."},{"n":5,"t":"Hiç bir toplum belirlenmiş süresini ne geçebilir, ne de gerisinde kalır."},{"n":6,"t":"Dediler ki: \"Ey kendisine zikir (mesaj) indirilmiş olan, sen bir delisin.\""},{"n":7,"t":"\"Doğru sözlü isen bize melekleri getirsene.\""},{"n":8,"t":"Biz melekleri ancak belli bir amaç için göndeririz, o zaman da kimseye süre tanınmaz. Kuran'ın Mükemmel Korunuşu"},{"n":9,"t":"Kuşkusuz zikri (mesajı) biz, evet biz indirdik ve onu koruyacak da elbette yine biziz."},{"n":10,"t":"Senden önce, geçmiş topluluklara da elçiler gönderdik."},{"n":11,"t":"Onlara her ne zaman bir elçi geldiyse onu alaya aldılar."},{"n":12,"t":"İşte suçluların kalbine böyle (bir tavrı) sokarız."},{"n":13,"t":"Nitekim, ona inanmazlar. Kendilerinden öncekilerin sünneti (adeti) de böyleydi."},{"n":14,"t":"Onlara gökten bir kapı açsak ve onun içinde yükselecek olsalardı,"},{"n":15,"t":"\"Gözlerimiz sarhoş edildi, büyülendik,\" diyeceklerdi."},{"n":16,"t":"Gökte galaksiler yerleştirdik, ve gözleyenler için onları süsledik."},{"n":17,"t":"Ve onları her kovulmuş şeytandan koruduk."},{"n":18,"t":"Ancak onlardan kulak hırsızlığı eden olursa onu alevli bir ateş mermisi kovalar."},{"n":19,"t":"Yeryüzünü genişletip içine sağlam dağlar yerleştirdik ve orada her şeyi mükemmel bir ölçüye göre bitirdik."},{"n":20,"t":"Orada hem sizin için ve hem sizin beslemediğiniz yaratıklar için yaşanacak bir ortam oluşturduk.*52"},{"n":21,"t":"Hiç bir şey yoktur ki onun hazineleri bizim yanımızda olmasın, ancak biz onu belirlenmiş bir ölçüyle indiririz. Rüzgar: Bulutları Toz Parçalarıyla Bitkileri de Çiçek Tozlarıyla Aşılar"},{"n":22,"t":"Rüzgarı aşılayıcı olarak gönderdik; gökten bir su indirip sizi onunla suladık. Oysa siz onu depo edemezdiniz."},{"n":23,"t":"Biz, elbette biz diriltir ve öldürürüz, sonunda asıl varis olanlar da biziz."},{"n":24,"t":"İlerleyenlerinizi de biliriz, geride kalanları da biliriz."},{"n":25,"t":"Onları, senin Rabbin toplayacak. O Bilgedir, Bilendir. İnsan Soyu"},{"n":26,"t":"İnsanı, kurumuş, yıllanmış balçıktan yarattık."},{"n":27,"t":"Cinleri de önceden, içe işleyen parlak ateşten yarattık."},{"n":28,"t":"Rabbin meleklere, \"Kurumuş, yıllanmış balçıktan bir insan yaratacağım,\" demişti."},{"n":29,"t":"\"Onu düzenleyip ona ruhumdan üflediğimde hemen onun için secdeye varın,\" demişti."},{"n":30,"t":"Tüm melekler topluca secde ettiler;"},{"n":31,"t":"Ancak İblis (şeytan) hariç. Secde edenlerle beraber olmayı red etti."},{"n":32,"t":"Dedi ki: \"Seni secde edenlerle beraber olmaktan alıkoyan şey nedir, İblis?\""},{"n":33,"t":"Dedi ki: \"Kurumuş, yıllanmış balçıktan yarattığın insana secde edecek değilim.\""},{"n":34,"t":"(Tanrı:) \"Öyleyse çık oradan; sen kovuldun!\""},{"n":35,"t":"\"Yargı gününe kadar laneti hakkettin,\" dedi."},{"n":36,"t":"\"Rabbim, dirilecekleri güne kadar beni ertele,\" dedi."},{"n":37,"t":"Dedi ki: \"Tamam, sen ertelendin,\""},{"n":38,"t":"\"Bilinen vaktin gününe kadar....\" Şeytanın Sınırlı Etkisi"},{"n":39,"t":"Dedi ki: \"Rabbim, beni yoldan çıkarttığın için, onları yeryüzünde ayartıp topluca saptıracağım.\""},{"n":40,"t":"\"Kendilerini sadece sana adayanlar hariç.\""},{"n":41,"t":"Dedi ki: \"İşte benim değişmez yasam budur.\""},{"n":42,"t":"\"Elbette, sadece bana kulluk edenlere karşı bir gücün yoktur. Ancak sana uyan sapıklara gücün yeter.\""},{"n":43,"t":"\"Cehennem hepsinin buluşma yeridir.\""},{"n":44,"t":"\"Onun yedi kapısı vardır ve her bir kapı için onlardan belli bir pay vardır.\""},{"n":45,"t":"Erdemliler ise bahçeler ve pınarlar içindedir."},{"n":46,"t":"Oraya barış ve güvenlik içinde girin."},{"n":47,"t":"Göğüslerindeki kıskançlığı kaldırırız; kardeşçe karşılıklı yerleştirilmiş koltuklar üzerindedirler."},{"n":48,"t":"Orada onlara hiç bir yorgunluk dokunmaz ve oradan da çıkarılacak değillerdir."},{"n":49,"t":"Kullarıma haber ver ki ben Bağışlayıcıyım, Rahimim."},{"n":50,"t":"Ve azabım da çok acı bir azaptır. Melekler İbrahim'i Ziyaret Ediyor"},{"n":51,"t":"Onlara İbrahim'in konuklarından haber ver."},{"n":52,"t":"Onun yanına varıp, \"Selam!,\" demişlerdi. O da, \"Biz sizden korkuyoruz,\" demişti."},{"n":53,"t":"\"Endişelenme, biz sana bilgin bir oğul müjdesini veriyoruz,\" demişlerdi."},{"n":54,"t":"\"İyice yaşlanmışken beni mi müjdeliyorsunuz! Beni ne ile müjdeliyorsunuz,\" dedi."},{"n":55,"t":"\"Sana gerçeği müjdeledik, umudunu kesme,\" dediler."},{"n":56,"t":"\"Sapıklardan başka Rabbinin rahmetinden kim umut keser,\" dedi."},{"n":57,"t":"\"Ey elçiler, göreviniz nedir,\" dedi."},{"n":58,"t":"\"Biz, suçlu bir topluma gönderildik;\""},{"n":59,"t":"\"Ancak Lut'un ailesi hariç. Hepsini kurtaracağız.\""},{"n":60,"t":"\"Yalnız karısı hariç; onun geride kalanlardan olmasını kararlaştırdık,\" dediler. Lut ve Homoseksuel Halkı"},{"n":61,"t":"Elçiler, Lut'un ailesine geldiklerinde"},{"n":62,"t":"(Lut:) \"Siz, bizce tanınmayan bir topluluksunuz,\" dedi."},{"n":63,"t":"Dediler ki: \" Onların kuşkulandıkları şeyi sana getirdik.\""},{"n":64,"t":"\"Sana gerçeği getirdik, biz elbette doğru konuşuyoruz.\""},{"n":65,"t":"\"Geceleyin ailenle birlikte çık. Arkalarından izle ve hiç biriniz arkaya bakmasın. Size emredilen yere gidin.\""},{"n":66,"t":"'Şu halk, sabahleyin yok edilecektir' şeklindeki emri kendisine bildirdik."},{"n":67,"t":"Kent halkı neşe içinde geldiler."},{"n":68,"t":"\"Bunlar konuklarımdır, sakın beni utandırmayın.\""},{"n":69,"t":"\"ALLAH 'tan korkun, beni rezil etmeyin,\" dedi."},{"n":70,"t":"\"İnsanlarla diyalog kurmaktan seni menetmemiş miydik,\" dediler."},{"n":71,"t":"\"İşte benim kızlarım,\" dedi, \"İlla da istiyorsanız!\""},{"n":72,"t":"Ne yazık ki onlar, sarhoşlukları içinde bocalıyorlardı."},{"n":73,"t":"Tan ağarırken onları felaketli bir gürültü yakaladı."},{"n":74,"t":"Onun altını üstüne getirdik. Üzerlerine çamurdan yapılmış sert taşlar indirdik."},{"n":75,"t":"Bunda, inceleyip araştıranlar için dersler vardır."},{"n":76,"t":"Ve o (yıkıntı kent), yol üzerinde durmaktadır."},{"n":77,"t":"Bunda, inananlar için bir işaret vardır. Eyke Halkı"},{"n":78,"t":"Gerçekten Eyke halkı da zalimlerden idi."},{"n":79,"t":"Onlardan öc aldık. Her ikisi de belgelenmiştir."},{"n":80,"t":"Hicr halkı da elçileri yalanladı."},{"n":81,"t":"Kendilerine ayetlerimizi verdik, fakat ondan yüz çevirdiler."},{"n":82,"t":"Dağlardan güvenli evler yontuyorlardı."},{"n":83,"t":"Sabahleyin onları da o korkunç gürültü yakaladı."},{"n":84,"t":"Kazandıklarının hiç biri onları kurtaramadı. Dünyanın Sonu Açıklanıyor"},{"n":85,"t":"Biz, gökleri, yeri ve aralarındaki şeyleri belli bir amaç için yarattık. O saat (dünyanın sonu) elbette gelecektir, öyleyse onlara güzel ve yumuşak davran."},{"n":86,"t":"Rabbin elbette Yaratandır, Bilendir."},{"n":87,"t":"Biz sana yedi çifti ve büyük Kuran'ı verdik."},{"n":88,"t":"Onlardan (elçilerden) bazılarına verdiklerimizi kıskanma ve onlardan (inkarcılardan) ötürü de üzülme. İnananlara kanatlarını indir. Bazı Ayetleri \"Mensuhtur\" Diyerek İnkar Eden Mezhepçi Bölücüler"},{"n":89,"t":"De ki: \"Ben apaçık bir uyarıcıyım.\""},{"n":90,"t":"Aynı şekilde o bölücülerle de ilgileneceğiz."},{"n":91,"t":"Onlar ki Kuran'ı parçalara ayırdılar."},{"n":92,"t":"Rabbine and olsun ki, hepsinden soracağız"},{"n":93,"t":"Yaptıkları şeylerden."},{"n":94,"t":"Öyleyse sana emredileni açıkça ortaya koy ve müşriklere de aldırma."},{"n":95,"t":"Alay edenlere karşı biz sana yeteriz."},{"n":96,"t":"Onlar ki ALLAH ile beraber başka tanrılar oluşturdular. Yakında bilecekler."},{"n":97,"t":"Söylediklerinden ötürü göğsünün daraldığını biliyoruz."},{"n":98,"t":"Rabbini yüceltip coşkuyla an ve yerlere kapan."},{"n":99,"t":"Rabbine kulluk et ki kesin bir inanca sahip olasın."}]},{"id":16,"name":"ARI (NAHL) SÛRESİ","verses":[{"n":1,"t":"ALLAH'ın emri gelmiş bulunuyor, öyleyse acele etme.*53 Onların ortak koştuklarından uzaktır, yücedir."},{"n":2,"t":"Kullarından dilediğine, melekleri vahiyle indirerek, emrini iletir: \"İnsanları uyarın: Benden başka tanrı yoktur ve beni dinleyin.\""},{"n":3,"t":"Gökleri ve yeri belli bir amaç için yaratmıştır. Ortak koştuklarından çok yücedir."},{"n":4,"t":"İnsanı küçük bir damladan yarattı, fakat buna rağmen o, apaçık bir düşman kesildi."},{"n":5,"t":"Ve, çiftlik hayvanlarını da sizin için yarattı, onlarda ısıtma ve diğer yararlar vardır ve onlardan yersiniz."},{"n":6,"t":"Ayrıca boş zamanlarınızda ve seyahatlerinizde sizin için onlarda bir konfor ve zevk vardır. Tanrı'nın Nimetleri"},{"n":7,"t":"Ve sizin yüklerinizi de, kendi kendinize ancak zorlukla varacağınız bölgelere taşırlar. Rabbiniz elbette Rauf'tur, Rahimdir."},{"n":8,"t":"Binmeniz ve eğlenmeniz için atları, katırları ve eşekleri yarattı ve daha bilmediğiniz bir çok şeyi de yaratır. * 16:8 Tren, otomobil, helikopter, uçak, uzay gemisi gibi bu ayette işaret edilen tüm modern taşıt araçları, Tanrı tarafından yaratılmışlardır. Zira bunların yaratılması için gerekli olan insan beyni, fizik, kimya yasaları ve maddelerin hepsi Tanrı'nın birer yaratığıdır. Bak 37:96."},{"n":9,"t":"Yolları göstermek ALLAH'a aittir; bazısı eğridir. Dileseydi hepinizi doğruya iletirdi."},{"n":10,"t":"O ki gökten bir su indirdi, ondan içersiniz ve yine yararlandığınız ağaçları onunla sularsınız."},{"n":11,"t":"Onunla sizin için ekin, zeytin, hurma ağaçları, üzümler ve her çeşit meyveler bitirmektedir. Düşünen bir toplum için bunda elbette bir ayet (ders) vardır."},{"n":12,"t":"Geceyi, gündüzü, güneşi ve ayı hizmetinize sundu. Yıldızlar da O'nun emri altındadır. Aklını kullanan bir toplum için elbette bunda işaretler vardır."},{"n":13,"t":"Ve sizin için yeryüzünde yarattığı rengarenk nesneleri de... Düşünen bir toplum için elbette bunda bir ders vardır."},{"n":14,"t":"O ki denizi emrinize sunmuştur; ondan taze et yersiniz, ondan giyim ve takı için süsler çıkarırsınız. Gemilerin denizi yara yara akıp gittiğini görürsünüz. Böylece O'nun lütfunu ararsınız ve belki ona şükredersiniz."},{"n":15,"t":"Ve sarsılmamanız için yeryüzüne denge sağlayıcılar yerleştirdi, yolu bulmanız için de nehirler, yollar,"},{"n":16,"t":"Ve göze çarpan işaretler... Yıldızlarla da yol bulurlar."},{"n":17,"t":"Yaratan, yaratamıyan gibi olur mu? Düşünmez misiniz?"},{"n":18,"t":"ALLAH'ın nimetini saysanız bitiremezsiniz. ALLAH Bağışlayandır, Rahimdir."},{"n":19,"t":"ALLAH gizlediklerinizi de açıkladıklarınızı da bilir. Ölmüş Peygamberler ve Evliyalar"},{"n":20,"t":"ALLAH'ın dışında çağırdıkları kişiler hiç bir şey yaratamazlar, aksine kendileri yaratılmışlardır."},{"n":21,"t":"Ölüdürler, diri değildirler. Ne zaman dirileceklerini de bilmezler."},{"n":22,"t":"Tanrınız bir tek tanrıdır. Ahirete inanmıyanların kalpleri inkarcıdır ve onlar büyüklük taslarlar."},{"n":23,"t":"Kuşkusuz ALLAH onların gizlediklerini de açığa vurduklarını da bilir. O, büyüklük taslayanları sevmez."},{"n":24,"t":"Kendilerine, \"Rabbiniz ne indirdi,\" denildiğinde, \"Geçmişlerin efsanelerini...,\" diye yanıtlarlar. * 16:24 Bu ayet Kuran'ı efsane diye inkar edenler hakkında olduğu gibi hadis kitaplarında derlenen geçmişlerin efsanelerini \"vahiy\" diyerek Kuran'a eş koşan modern müşrikler için de geçerlidir."},{"n":25,"t":"Diriliş gününde kendi günahlarının tamamını, ayrıca saptırdıkları kimselerin günah yüklerinden de bir payı yüklenirler. Yükleri ne de kötüdür."},{"n":26,"t":"Kendilerinden öncekiler de tuzak kurmuşlardı; ancak ALLAH, binalarını temelinden yıkmış, üzerlerindeki tavan başlarına çökmüştü; azap onlara ummadıkları yerden gelmişti."},{"n":27,"t":"Sonra, diriliş gününde onları rezil eder ve, \"Uğrunda tartışıp mücadele verdiğiniz 'ortaklarım' nerede,\" der. Kendilerine bilgi verilenler de şöyle derler: \"Bu gün rezillik ve kötülük kafirleredir.\""},{"n":28,"t":"Onlar ki, nefislerine zulmedip dururlarken melekler canlarını alır. Sonunda teslim olup \"Biz herhangi bir kötülük yapmıyorduk,\" derler. Hayır, ALLAH sizin yaptıklarınızı iyi bilir."},{"n":29,"t":"İçinde sürekli kalacağınız cehennemin kapsından girin. Kibirlenenlerin yeri ne kötüdür."},{"n":30,"t":"Erdemlilere, \"Rabbiniz ne indirdi,\" denir. \"İyilik,\" diye karşılık verirler. Bu dünyada güzel davrananlar için güzellik vardır. Ahiret yurdu ise daha hayırlıdır. Erdemlilerin yurdu ne de iyidir."},{"n":31,"t":"İçlerinden ırmaklar akan Adn cennet (bahçe) lerine girerler. Orada her diledikleri şeyi bulurlar. ALLAH erdemlileri işte böyle ödüllendirir."},{"n":32,"t":"İyi durumdayken melekler canlarını almaya geldiklerinde, \"Selam size olsun. Yaptıklarınızın karşılığı olarak cennete giriniz,\" derler."},{"n":33,"t":"Kendilerine meleklerin gelmesini, yahut Rabbinin emrinin gelmesini mi bekliyorlar? Kendilerinden öncekiler de aynı şekilde davranmışlardı. Onlara ALLAH zulmetmedi, onlar kendi kendilerine zulmettiler."},{"n":34,"t":"Yapmış olduklarının kötü sonuçları onlara dokundu ve alaya almış oldukları şeyler onları kuşattı. İnandıkları Şirk Dinini Tanrı'ya Malederler"},{"n":35,"t":"Ortak koşanlar, ALLAH dilemeseydi ne biz, ne de atalarımız O'ndan başka bir şeye tapmaz ve O'nun haram ettiğinden başkasını da haram kılmazdık. Kendilerinden öncekiler de böyle davranmıştı. Elçinin açıkça bildirmekten başka bir görevi mi var? * 16:35 Bak 6:23,148."},{"n":36,"t":"Her bir toplum içinde, \"ALLAH'a kulluk edin ve putperestlikten sakının,\" diyen bir elçi gönderdik. Onlardan kimine ALLAH yol gösterdi, kimi de sapıklıkta kalmağa mahkum oldu. Yeryüzünü dolaşın ve yalanlayanların sonunun nasıl olduğuna dikkat edin."},{"n":37,"t":"Doğruyu bulmaları için ne kadar uğraşsan da, ALLAH saptırdığını doğruya ulaştırmaz. Onların bir yardımcısı da olmaz."},{"n":38,"t":"\"ALLAH ölmüş olanı diriltmez diye tüm güçleriyle ALLAH'a yemin ederler. Hayır, O'nun verdiği gerçek bir sözdür o. Ancak insanların çoğu bunu bilmiyor."},{"n":39,"t":"Anlaşmazlığa düştükleri konuları onlara açıklasın ve kafirler de kendilerinin yalancı olduğunu öğrensin."},{"n":40,"t":"Bir şeyin olmasını istediğimiz zaman ona sadece \"Ol,\" deriz ve o da olur. * 16:40 Nitekim tüm evren \"ani\" bir patlamayla yaratıldı. Bak 21:30."},{"n":41,"t":"Zulme uğradıktan sonra ALLAH uğrunda göç edenleri, dünyada güzelce yerleştireceğiz. Ahiret ödüllleri ise daha büyüktür; bir bilseler..."},{"n":42,"t":"Onlar, sabrederek Rab'lerine güvenenlerdir."},{"n":43,"t":"Senden önce, adamlardan/iki ayak üzerinde yürüyenlerden başkasını elçi olarak göndermedik; onlara vahyettik. Bilmiyorsanız uzmanlara sorun."},{"n":44,"t":"Belgeler ve kitaplarla... Sana bu mesajı indirdik ki, kendilerine indirileni halka açıklayasın (bildiresin) ve onlar da düşünsünler. * 16:44 Allah tarafından açıklanmış (75:19), anlaşılması kolaylaştırılmış (54:17, 22) apaçık bir kitabın (5:15; 12:1; 26:195; 44:6) elçi tarafından açıklanması demek, gizlenmeyip insanlara bildirilmesi demektir. Bak: 2:159-160; 3:187 ve 16:64."},{"n":45,"t":"Kötülük planlıyanlar, ALLAH'ın kendilerini yerin dibine geçirmeyeceğinden, yahut ummadıkları bir yerden kendilerine azabın gelmiyeceğinden emin mi oldular?"},{"n":46,"t":"Yahut (yataklarında) dönüp dururlarken kendilerini yakalamayacağından..? Onlar kurtulamazlar."},{"n":47,"t":"Yahut onları korku ve endişe içinde iken yakalamayacağından..? Rabbiniz elbette Şefkatlidir, Rahimdir. Yerkürenin Dönüşünü Siz Kontrol Etmiyorsunuz"},{"n":48,"t":"ALLAH'ın yarattığı şeylere bakmıyorlar mı ki, gölgeleri ALLAH'a secde ederek sağdan ve soldan sürünerek gidip gelir."},{"n":49,"t":"Göklerde ve yerde bulunan tüm yaratıklar ve melekler ALLAH'a secde ederler ve büyüklük taslamazlar. * 16:49 İnsan vucudu, ister inanan birisine ister inkarcı birisine ait olsun, tümüyle Tanrı'ya teslim olmuş bir müslümandır. Bak 13:15."},{"n":50,"t":"Kendilerinden çok yüce olan Rab'lerini sayarlar ve kendilerine emredileni uygularlar."},{"n":51,"t":"ALLAH, \"İki tanrı edinmeyin, O'ndan başka tanrı yoktur. Sadece benden çekinin,\" demiştir. Dinin Tek Kaynağı"},{"n":52,"t":"Göklerde ve yerde ne varsa O'nundur. Din de sürekli sadece O'nundur. ALLAH'tan başkasını mı sayıyorsunuz? * 16:52 Bak 39:11"},{"n":53,"t":"Size ulaşan her nimet ALLAH'tandır. Nitekim, bir sıkıntıya uğradığınızda sadece O'na yalvarırsınız."},{"n":54,"t":"Ne var ki, sizden o sıkıntıyı kaldırdığı zaman, sizden bir grup hemen Rab'lerine ortak koşmaya başlar,"},{"n":55,"t":"Kendilerine verilene nankörlük ederek... Keyfinize bakın; yakında mutlaka bileceksiniz!"},{"n":56,"t":"Kendilerine verdiğimiz rızıklardan bilinçsizlere bir pay ayırırlar. ALLAH'a andosun ki siz bu uydurduğunuz şeylerden sorulacaksınız. Kız Çocuklarını Erkeklerden Aşağı Görenler"},{"n":57,"t":"Yüce ALLAH'a kızları ayırıyorlar; kendilerine de hoşlandıklarını..."},{"n":58,"t":"Onlardan birine dişi müjdelendiği zaman, büyük bir öfkeyle yüzü kapkara kesilir."},{"n":59,"t":"Kendisine müjdelenen 'kötülükten' utanarak halkından kendini gizlemeye çalışır. Şimdi onu utana utana tutsun mu, yoksa toprağa mı gömsün! Ne kötü yargıda bulunuyorlar."},{"n":60,"t":"Ahirete inanmıyanlar kötü örneği oluştururlar; halbuki en yüce örnekler ALLAH'ındır. O Üstündür, Bilgedir."},{"n":61,"t":"ALLAH zulümlerinden dolayı insanları cezalandırsaydı orada bir yaratık bırakmazdı; ne var ki onları belli bir süreye kadar erteler. Sürelerinin sonu geldiği zaman da ne bir saat öne alınırlar, ne de ertelenirler."},{"n":62,"t":"Hoşlanmadıkları şeyleri ALLAH'a malediyorlar ve kendilerinin iyi hakkettikleri yalanını dillerinde geveliyorlar. Elbette, ateşe terkedilecekler."},{"n":63,"t":"ALLAH'a andolsun ki senden önceki toplumlara da elçiler gönderdiğimizde şeytan işlerini onlara güzel gösterdi. Nitekim onların velisi (yakın arkadaşı) bugün odur. Onlar acı bir azaba mahkum olmuşlardır."},{"n":64,"t":"Sana bu kitabı indirdik ki, anlaşmazlığa düştükleri konuları kendilerine bildiresin.*54 Bu kitap, inanan bir topluluk için bir yol göstericidir, bir rahmettir. * 16:64 Hadis ve Sünneti Tanrı'nın hükmüne eş koşanlar bu ayetteki \"litübeyyine\" kelimesinin anlamını saptırırlar. Türkçedeki \"açıklama\" kelimesi gibi iki anlama gelen bu sözcüğün Kuran'ın açık ayetleriyle çelişen anlamını tercih edenler 3:7 ayetinde haber verilirler. Benzer ifade için bak 2:159-160; 3:187 ve 16:44. Besin Maddelerindeki İşaretler"},{"n":65,"t":"ALLAH gökten bir su indirir ve onunla yeryüzünü ölümünden sonra diriltir. Dinleyen bir toplum için bunda bir işaret vardır."},{"n":66,"t":"Sizin için çiftlik hayvanlarında da dersler vardır. İçmeniz için karınlarından, yani sindirilmiş yiyecek ile kan arasından çıkan bir maddeyi size sunuyoruz: İçimi lezzetli saf süt."},{"n":67,"t":"Ve hurma ağaçlarının meyvelerinden, üzümlerden hem sarhoş edici içkiler ve hem de güzel bir rızık elde edersiniz. Akleden bir toplum için bunda bir işaret vardır.*55 * 16:67 Tanrı'nın bağışladığı nimetlerden yararlanmak, yahut zarar görmek seçimimize bağlıdır. Nükleer enerjiyi hem bomba hem de enerji santrali için kullanabiliriz; ateşle elimizi de yakabiliriz, yiyeceklerimizi de pişirebiliriz. Kuran, alkollü içkeler ile meyve sularını karşılaştırarak bu seçime dikkat çeker. Arı"},{"n":68,"t":"Ve Rabbin arıya vahyetti: \"Dağlardan, ağaçlardan ve kurdukların (kovanlar) dan evler edin,\""},{"n":69,"t":"\"Sonra, her çeşit meyveden ye ve Rabbinin planını aynen izle.\" Karınlarından, insanlar için şifa içeren çeşitli renklerden bir içecek çıkar. Düşünen insanlar için bunda bir işaret vardır."},{"n":70,"t":"Ve sizi ALLAH yarattı, sonra da yaşamınıza son verir. Sizden bazıları hayatın en kötü zamanına kadar yaşatılır ki bilgiden sonra hiçbir şeyi bilmesin. ALLAH Bilendir, Her Şeye Gücü Yetendir."},{"n":71,"t":"ALLAH rızık (varlık) açısından sizi birbirinize üstün kılmıştır. Nitekim, üstün kılınanlar, emirleri altındakilerle varlıklarını eşit paylaşmazlar. ALLAH'ın nimetini mi reddediyorlar? * 16:71 Bu ayet şöylece de çevrilebilir: \". . . Üstün kılınanlar, emirleri altındakilere kendi rızıklarını vermezler. Aslında rızıkta onların hepsi eşittir (hepsi de Tanrı tarafından rızıklandırılırlar). . .\""},{"n":72,"t":"Ve ALLAH kendi cinsinizden sizin için eşler yarattı, eşlerinizden de sizin için çocuklar ve torunlar yarattı ve size güzel rızıklar verdi. Böyleyken onlar batıla inanıp ALLAH'ın nimetine nankörlük mü ediyorlar?"},{"n":73,"t":"ALLAH'ı bırakıp, kendilerine göklerden ve yerden rızık sağlamıyan aciz kişilere kulluk ediyorlar."},{"n":74,"t":"Öyleyse, ALLAH'a örnekler vermeyiniz; siz bilmezken ALLAH bilir. Zenginlik ve Özgürlük, Fakirlik ve Tutsaklık"},{"n":75,"t":"ALLAH, hiçbir şeye gücü yetmeyen, sahiplenilmiş bir köle ile kendi tarafımızdan güzelce rızıklandırdığımız, o rızıktan gizli ve açık yardım için harcayan kişiyi örnek olarak verir. Bu ikisi hiç bir olur mu? Övgü ALLAH'adır, ancak çokları bilmezler."},{"n":76,"t":"ALLAH şu iki adamı da örnek verir: Birisi bir şey yapacak yeteneğe sahip olmayıp tümüyle efendisine/sahibine bağımlıdır, onu ne işe koşsa bir şey beceremez. İşte böyle bir kişi ile doğru yol üzerinde bulunup adaleti uygulayan kişi hiç bir olur mu? * 16:76 Bak 2:286."},{"n":77,"t":"Göklerin ve yerin gizemleri ALLAH'a aittir. Saat, (dünyanın sonu) bir göz kırpması kadar veya daha kısadır. ALLAH her şeye Gücü Yetendir."},{"n":78,"t":"ALLAH sizi annelerinizin karnından çıkardığı zaman bir şey bilmiyordunuz. Size işitme, görme duyuları ve beyinler verdi ki şükredesiniz."},{"n":79,"t":"Göğün atmosferine uygun yaratılmış kuşları görmüyorlar mı? Onları ALLAH'tan başkası tutmaz. Bunda inanan bir toplum için elbette ayetler vardır."},{"n":80,"t":"Ve ALLAH evlerinizi sizin için barınaklar yaptı. Çiftlik hayvanlarının derilerinden, yolculuk günü ve ikamet günü kullanacağınız portatif evler sağladı. Yünlerinden, kürklerinden ve kıllarından da bir süreye kadar giyip döşeyeceğiniz eşyalar çıkardı."},{"n":81,"t":"Ve ALLAH yarattığı şeylerden sizin için gölgeler oluşturdu. Sizin için dağları sığınak yaptı. Sizi sıcaktan koruyacak elbiseler ve sizi savaşlarınızda koruyacak elbiseler hazırladı. Teslim olasınız diye nimetlerini size böyle tamamlıyor."},{"n":82,"t":"Yüz çevirirlerse, sana düşen, yalnızca (mesajı) açık bir biçimde iletmektir. Kafirler Nankördürler"},{"n":83,"t":"ALLAH'ın nimetlerini çok iyi tanıdıkları halde onları inkar ederler. Onların çoğu kafirlerdir. Diriliş Gününde"},{"n":84,"t":"Her topluluktan bir tanık gönderdiğimiz gün, inkar edenlere ne izin verilir ne de özürleri kabul edilir."},{"n":85,"t":"Zulmedenler azabı gördükleri zaman artık onlar için hafifletilmez, ertelenmez. Putlaştırılan Peygamberler, Veliler, Ermişler, vb. Kendilerini Tanrı'ya Ortak Koşanlara Sahip Çıkmazlar"},{"n":86,"t":"Ortak koşanlar, ortak koştukları kimseleri gördükleri zaman, \"Rabbimiz, senden başka çağırdığımız ortaklarımız işte bunlardır,\" derler. (Onlar da), \"Siz yalancılarsınız (biz sizin bu suçunuza hiç bir zaman ortak olmadık),\" diye karşılık verirler. * 16:86 Bak 10:28-29."},{"n":87,"t":"O gün tamamıyla ALLAH'a teslim olmuşlardır ve uydurdukları şeyler de kendilerini terketmiştir."},{"n":88,"t":"İnkar edip ALLAH'ın yolundan sapanlar... Yaptıkları bozgunculuktan ötürü azap üstüne azap arttırırız."},{"n":89,"t":"Her topluluk içinden, kendilerine karşı bir tanık gönderdiğimiz, şunlara karşı da seni tanık olarak getirdiğimiz gün... Biz sana bu kitabı, her şeyi açıklayan, bir yol gösterici, bir rahmet ve müslümanlara bir müjde olarak indirdik. * 16:89 Kurtuluşumuz için gerekli her şeyi açıklayan Kuran'ı yeterli görmeyenler hakkında elçinin tanıklığı için bak 25:30."},{"n":90,"t":"ALLAH adaleti, iyilik yapmayı ve akrabaya yardım etmeyi emreder. Kötülükten, fenalıktan ve azgınlıktan ise sizi meneder. Öğüt almanız için sizi böyle aydınlatır. Sözleşmeleri Mutlaka Uygulayınız"},{"n":91,"t":"Anlaşma yaptığınızda ALLAH'ın ahdini yerine getirin. Pekiştirdiğiniz yeminleri bozmayın. ALLAH'ı kendinize kefil kılmıştınız. ALLAH yaptıklarınızı bilir."},{"n":92,"t":"İpliğini sağlamca eğirdikten sonra çözen kadın gibi olmayın. Bir topluluğun diğer bir topluluktan güçlü olmasından yararlanarak yeminlerinizi aranızda kötüye kullanmayın. ALLAH sizi böylece dener. Anlaşmazlığa düştüğünüz konuları diriliş günü size açıklayacak."},{"n":93,"t":"ALLAH dileseydi sizi bir tek toplum kılardı. Ancak, dilediğini saptırır, dilediğine de yol gösterir. Elbette yaptıklarınızdan sorulacaksınız. * 16:93 Ayetin orta cümlesi, \"dileyeni saptırır, dileyene yol gösterir\" biçiminde anlaşılsada sonuç değişmemektedir. Tanrının içtenlikle gerçeği arayanları doğru yola ilettiğini ancak yeterli içtenliğe ve temiz niyete sahip olmayanlarında gerçeği görmesini engellediğini görüyoruz (6:110; 7:146; 21:51; 37:84). Bak 57:22."},{"n":94,"t":"Yeminlerinizi aranızda kötüye kullanmayın ki sağlam basmış ayağınız kayar. ALLAH'ın yolundan saptığınız için perişanlığı tadar ve acı bir azabı hakkedersiniz."},{"n":95,"t":"ALLAH'a verdiğiniz sözü ucuza satmayın. Sizin için ALLAH'ın yanındakiler daha iyidir; bir bilseniz."},{"n":96,"t":"Sizin yanınızda bulunanlar biter; ancak ALLAH'ın yanındakiler ise süreklidir. Güçlüklere karşı direnenlerin ödüllerini, yaptıkları iyiliklere uygun olarak elbette vereceğiz. Mutluluk Garantisi, Şimdi ve Ebedi"},{"n":97,"t":"Erkek olsun, kadın olsun, her kim inançlı olarak iyi bir iş yaparsa ona bu dünyada güzel bir hayat bağışlarız ve yaptıkları iyi işlere karşılık ödüllerini de tam veririz.*56 * 16:97 Ayetteki \"Hu\" ve \"Hum\" zamirleri hem kadını ve hem erkeği kapsamına alıyor. Açık bir neden yokken bu zamirleri sadece erkeklere sınırlamamalı."},{"n":98,"t":"Kuran okuduğunda kovulmuş şeytandan ALLAH'a sığın."},{"n":99,"t":"İnanıp Rab'lerine güvenenlere onun bir gücü yoktur. 100. Onun gücü, kendisini dost edinenlere ve onu Rab'lerine ortak koşanlaradır. 101. Biz bir delilin yerine bir başka delili getirdiğimiz zaman ki ALLAH neyi indirdiğini iyi bilir \"Sen, ancak bir iftiracısın!,\" derler. Gerçekten çokları bilmiyor. 102. De ki, \"İnananları sağlamlaştırsın, müslümanlara bir yol gösterici ve müjde olsun diye Kutsal Ruh onu Rabbinden gerçekle indirdi. Kuran, İncil ve Tevrat'tan Kopya Edilmedi 103. \"Ona bir insan öğretiyor\" biçimindeki sözlerini elbette biliyoruz. Amaçladıkları kişinin dili yabancıdır, bu ise apaçık Arapça bir dildir. 104. ALLAH'ın ayetlerine inanmıyanları ALLAH doğru yola iletmez; onlar için acı bir azap vardır. * 16:103 Kuran'ın dışındaki mukaddes kitaplar kısmen tahrife uğramışlardır. Kuran'ı mevcut Tevrat ve İncil çevirileriyle karşılaştırırsak Kuran'ın orijinalliği ortaya çıkar. Örneğin, Tevrat'ın Çıkış 32:20 ayetiyle Kuran'ın 2:93 ayetini karşılaştırınız. Dr. Maurice Bucaille'nin \"The Bible, the Quran and Science\" (Tevrat-İncil, Kuran ve Bilim) adlı kitabı bu konuda bir klasiktir. Bu ayetin son bölümü şu biçimde de anlaşılabilir: \"Amaçladıkları kişinin dili anlaşılmaz bir dil, bu ise mükemmeldir, apaçıktır.\" Bak 43:3. 105. Yalan uydurup iftira edenler ALLAH'ın ayetlerine inanmıyanlardır. Onlar gerçek yalancılardır. İnanç ve İnkar Niyete Bağlıdır 106. Kalbi imanla dolu olduğu halde (inkara) zorlanan dışında, imandan sonra inkara göğsünü açıp ALLAH'ı inkar edenler ALLAH'tan bir gazabı hakketmişlerdir ve onlar için büyük bir azap vardır. Dünya Hayatına Düşkünlük Allah'tan Uzaklaştırır 107. Çünkü onlar dünya hayatını ahirete tercih ettiler. İnkarcı topluluğu ALLAH doğru yola iletmez. 108. İşte onlar, ALLAH'ın kalplerini, işitme ve görüşlerini mühürlediği kişilerdir. Onlar gafillerdir. 109. Hiç kuşku yok ki onlar ahirette kaybedeceklerdir. 110. Sonra Rabbin, baskıya uğradıktan sonra göç eden, cihad eden ve direnenler için, evet senin Rabbin, kuşkusuz onlar için Bağışlayandır, Rahimdir. 111. O gün herkes gelir kendini kurtarmaya çalışır ve herkese yaptığının karşılığı tam ödenir ve onlara asla zulmedilmez. Helal Nimetleri Yasaklamak Felaket Getirir 112. ALLAH güven içinde başarılı bir topluluğu örnek olarak verir: O topluluğun rızkı kendilerine her taraftan bol miktarda ulaşırdı. Ancak daha sonra, ALLAH'ın nimetlerine karşı nankör davranınca ALLAH onlara açlık ve korku belasını tattırdı. 113. Onlara kendilerinden bir elçi geldi, onu yalanladılar. Sonunda, zulmederlerken onları azap yakaladı. 114. ALLAH'ın size verdiği helal ve güzel rızıklardan yeyin ve ALLAH'ın nimetlerine şükredin; sadece O'na kulluk ediyorsanız. * 16:114 Sadece Allah'a kulluk edenler, O'nun haram etmediğini haram etmezler. Fakat, mollaları, şehyleri, imamları, din adamlarını Tanrı'ya ortak koşanlar, onların Tanrı ve peygamber adına uydurdukları sayısız haramlarla Tanrı'nın bağışladığı bir çok nimeti yasaklayarak nankörlük ederler. Bak 6:145-150 ve 42:21. Sadece Dört Hayansal Yiyecek Haram Kılınmıştır 115. Size yalnızca leş, kan, domuz eti ve ALLAH'tan başkası için adananları haram kılmıştır. Kim (bunları yemek) zorunda kalırsa, istekli olmamak ve sınırı aşmamak koşuluyla ALLAH Bağışlayandır, Rahimdir. 116. Dillerinizin yalan yere nitelendirmesinden ötürü \"Bu helaldir, bu haramdır,\" demeyin. Böylece ALLAH'a yalan yakıştırmış olursunuz. ALLAH'a yalan yakıştıranlar başarıya ulaşamazlar. 117. Kısa süren bu zevkten sonra onlar için acı bir azap vardır. 118. Yahudilere, daha önce sana anlattığımız şeyleri haram kıldık. Biz onlara zulmetmedik; fakat onlar kendi kendilerine zulmediyorlardı. 119. Bunlara rağmen Rabbin, bilgisizlik yüzünden kötülük işledikten sonra ardından tevbe edip düzelenlere, evet senin Rabbin ondan sonra Bağışlayandır, Rahimdir. İbrahim 120. İbrahim, ALLAH'a boyun eğen, monoteist bir öncü idi. Hiç bir vakit ortak koşmadı. 121. O'nun nimetlerine şükredici idi. Onu seçti ve onu doğru yola iletti. 122. Ve ona bu dünyada mutluluk verdik, ahirette ise erdemlilerle birlikte olacaktır. Muhammed, İbrahim'in İzleyicisi 123. Nitekim, İbrahim'in dinini bir monoteist olarak izlemen için sana vahyettik; o asla putperestlerden olmadı. * 16:123 Bu ayet, dini pratiklerin İbrahim peygamberden bize ulaştığını bildirmektedir. Bak 21:73; 22:78. 124. Cumartesi (tatili), sadece onda ayrılığa düşenlere farz kılınmıştı. Rabbin, ayrılığa düştükleri konuda diriliş günü aralarında hüküm verecektir. Mesajı Nasıl İletmeli? 125. Rabbinin yoluna bilgelikle ve güzel bir aydınlatma ile çağır. Onlarla en güzel biçimde tartış. Rabbin, yolundan sapanları ve doğru yolda olanları en iyi bilendir. 126. Karşılık verecekseniz, size verilen karşılığın bir benzeriyle karşılık verin. Sabrederseniz, elbette bu sabredenler için daha hayırlıdır. 127. Sabret, sabrın ancak ALLAH'ın yardımıyladır. Onlar için üzülme ve onların tuzaklarından da endişelenme. 128. ALLAH erdemli davrananlar ve iyilikte bulunanlar ile beraberdir."}]},{"id":17,"name":"İSRAİLOĞULARI (BENİ İSRAİL) SÛRESİ","verses":[]},{"id":18,"name":"MAĞARA (KEHF) SÛRESİ","verses":[]},{"id":19,"name":"MERYEM (MERYEM) SÛRESİ","verses":[]},{"id":20,"name":"TT.H. (TA HA) SÛRESİ","verses":[]},{"id":21,"name":"PEYGAMBERLER (ENBİYA) SÛRESİ","verses":[]},{"id":22,"name":"HAC (HAC) SÛRESİ","verses":[]},{"id":23,"name":"İNANANLAR (MUMİNUN) SÛRESİ","verses":[]},{"id":24,"name":"IŞIK (NUR) SÛRESİ","verses":[]},{"id":25,"name":"YASALAR KİTABI (FURKAN) SÛRESİ","verses":[]},{"id":26,"name":"ŞAİRLER (ŞUARA) SÛRESİ","verses":[]},{"id":27,"name":"KARINCA (NEML) SÛRESİ","verses":[]},{"id":28,"name":"TARİH (KASAS) SÛRESİ","verses":[]},{"id":29,"name":"DİŞİ ÖRÜMCEK (ANKEBUT) SÛRESİ","verses":[]},{"id":30,"name":"ROMALILAR (RUM) SÛRESİ","verses":[]},{"id":31,"name":"LOKMAN (LOKMAN) SÛRESİ","verses":[]},{"id":32,"name":"SECDE (SECDE) SÛRESİ","verses":[]},{"id":33,"name":"PARTİLER (AHZAB) SÛRESİ","verses":[]},{"id":34,"name":"SEBE (SEBE) SÛRESİ","verses":[]},{"id":35,"name":"YARATAN (FATIR) SÛRESİ","verses":[]},{"id":36,"name":"Y.S. (YA SİN) SÛRESİ","verses":[{"n":1,"t":"Y. S."},{"n":2,"t":"Bilge Kuran'a and olsun."},{"n":3,"t":"Sen elbette elçilerden birisin."},{"n":4,"t":"Dosdoğru bir yol üzerinde."},{"n":5,"t":"Bu, Üstün ve Rahim olanın indirdiği bir vahiydir."},{"n":6,"t":"Ataları uyarılmadığından tümüyle habersiz kalmış bir toplumu uyarman için..."},{"n":7,"t":"Çoklarının inanmıyacağına dair söz gerçekleşmiştir."},{"n":8,"t":"Boyunlarına, çenelerine kadar varan prangalar taktık da kafaları yukarıya dikilmiştir."},{"n":9,"t":"Önlerinden bir set ve arkalarından bir set çekerek onları perdeledik; artık göremezler."},{"n":10,"t":"Onları uyarsan da uyarmasan da onlar için birdir; inanmazlar.*67 * 36:10 Bak 57:22-23."},{"n":11,"t":"Sen ancak, mesaja uyan ve yalnız başına iken Rahman'a karşı saygılı olan bir kimseyi uyarabilirsin. Onu bağışlanma ve bol bir ödülle müjdele."},{"n":12,"t":"Ölüleri biz, evet biz diriltiriz, onların yaptıklarını ve (ölümlerinden sonraki) sonuçlarını yazarız. Biz herşeyi apaçık bir kitapta saymışızdır. Elçileri Reddetmek: Kronik Bir Tepki"},{"n":13,"t":"Onlara, bir kent halkının kendilerine gelen elçilere gösterdiği tavrın örneğini ver."},{"n":14,"t":"Onlara iki elçi göndermiştik, ikisini de yalanladılar. Bunun üzerine üçüncü biriyle desteklemiştik. \"Biz size gönderilen elçileriz,\" demişlerdi."},{"n":15,"t":"Dediler ki, \"Siz de bizim gibi insandan başka bir şey değilsiniz. Rahman ise hiçbir şey indirmemiştir. Siz yalan söylüyorsunuz.\""},{"n":16,"t":"Dediler ki, \"Rabbimiz bilir ki biz size gönderildik.\""},{"n":17,"t":"\"Bizim görevimiz, açıkça duyurmaktan ibarettir.\""},{"n":18,"t":"Dediler ki, \"Sizin yüzünüzden uğursuzluğa uğradık. Eğer son vermezseniz sizi taşlarız ve bizden size acı bir ceza dokunacaktır.\""},{"n":19,"t":"Dediler ki, \"Uğursuzluğunuz sizden kaynaklanmaktadır. Size uyarıda bulunulduğu için mi? Siz gerçekten sınırı aşan bir topluluksunuz.\""},{"n":20,"t":"Kentin en uzak yakasından bir adam koşarak, \"Ey halkım,\" dedi, \"Elçilere uyun.\""},{"n":21,"t":"\"Sizden bir ücret istemiyenlere uyun. Onlar doğru yoldadır.\""},{"n":22,"t":"\"Beni yaratana ne diye kulluk etmeyeyim? Siz de O'na döneceksiniz.\""},{"n":23,"t":"\"O'nun dışında tanrılar mı edineyim? Eğer Rahman bana zarar vermek dilese, ne onların şefaati bana bir yarar sağlayabilir ne de beni kurtarabilirler.\""},{"n":24,"t":"\"O zaman tümüyle sapıtmış olurum.\""},{"n":25,"t":"\"Ben sizin Rabbinize inandım; lütfen beni dinleyin.\" İnananların Ölümü: Doğrudan Cennete Giriş"},{"n":26,"t":"(Ölüm anında) Kendisine, \"Cennete gir,\" denir. \"Keşke benim halkım bir bilseydi...\""},{"n":27,"t":"\"Rabbimin beni bağışladığını ve beni ağırladığını...\""},{"n":28,"t":"Ondan sonra biz, halkının üzerine gökten bir ordu indirmedik; indirmeğe gerek duymadık."},{"n":29,"t":"Sadece bir patlama... Hemen donakaldılar. Elçileri Alaya Alma: İnsanlığın Trajedisi"},{"n":30,"t":"Halkın durumu pek yazık. Kendilerine her ne zaman bir elçi gelse onunla alay ederlerdi."},{"n":31,"t":"Kendilerinden önce nice nesilleri yok ettiğimizi ve onların bir daha kendilerine dönmediklerini görmezler mi?"},{"n":32,"t":"Hepsi toplanıp huzurumuza getirileceklerdir. Tanrı'nın İşaretleri"},{"n":33,"t":"Ölü toprak onlar için bir ayettir: Onu diriltiriz ve oradan taneler çıkarırız da ondan yerler."},{"n":34,"t":"Orada hurma ağaçları ve üzümlerden oluşan bağ ve bahçeler yetiştirdik ve pınarlar fışkırttık."},{"n":35,"t":"Ki onun ürünlerinden ve elleriyle yetiştirdiklerinden yesinler. Şükretmiyecekler mi?"},{"n":36,"t":"Yerin bitirdiklerinden, kendi cinslerinden ve daha bilmedikleri nice şeylerden türlü çiftleri yaratan pek yücedir."},{"n":37,"t":"Gece de onlar için bir ayettir: Ondan gündüzü soyarız da onlar karanlıkta kalırlar."},{"n":38,"t":"Güneş belirlenmiş olan rotasında akıp gitmektedir. Bu Üstün ve Bilgin olanın kurduğu bir düzendir."},{"n":39,"t":"Aya da, kuru bir hurma dalına dönüşünceye kadar çeşitli evreler belirledik."},{"n":40,"t":"Ne güneş aya yetişebilir, ne de gece, gündüzü geçebilir. Her biri bir yörüngede yüzmektedir.*68 * 36:40 Güneşin, ayın ve dünyanın yörüngelerindeki hareketlerinden söz eden bu ayetteki \"küllün fi felekin (herbiri bir yörüngede)\" ifadesini oluşturan harfler (K, L, F, Y, F, L, K), tersinden okunduğu zaman da değişmeyen bu simetrik yapısıyla, gök cisimlerinin dairesel / elipsoid yörüngelerini sembolize ediyor. Aynı ifade 21:33 ayetinde de geçer. Kuran ilginç detaylarla doludur (72:1). Bak 4:82. İlk Geminin İcadı"},{"n":41,"t":"Onlar için bir başka ayette, insan soyunu yüklü gemide taşımamızdır."},{"n":42,"t":"Aynı şekilde, sürmeleri için onun bir benzerini yarattık."},{"n":43,"t":"Dileseydik onları boğardık; ne bir çığlıklarına yetişen olurdu, ne de kurtulabilirlerdi."},{"n":44,"t":"Bunun yerine, bizden bir merhamet görürler ve belli bir süreye kadar yaşatılırlar."},{"n":45,"t":"Kendilerine, \"Geçmişinizden ibret alıp ve geleceğiniz için sakının ki merhamet edilesiniz,\" denilmişti."},{"n":46,"t":"Rab'lerinin ayetlerinden bir ayet kendilerine geldiğinde, ondan yüz çevirmeyi adet edinmişlerdi."},{"n":47,"t":"Kendilerine, \"ALLAH'ın size verdiği rızıklardan verin,\" denildiğinde, inkar edenler inananlara, \"ALLAH'ın, dilediği taktirde besleyebileceği kimseleri mi besleyelim? Siz gerçekten iyice sapıtmışsınız,\" derler."},{"n":48,"t":"Aynı zamanda, \"Doğru sözlü iseniz o söz ne zaman gerçekleşecek?\" diye meydan okurlar."},{"n":49,"t":"Çekişip dururlarken kendilerini yakalayacak bir tek patlamayı beklemektedirler."},{"n":50,"t":"Ne bir vasiyet bırakmaya vakit bulurlar ne de ailelerine dönebilirler."},{"n":51,"t":"Boruya üflenince, onlar mezarlarından kalkıp Rab'lerine koşacaklar."},{"n":52,"t":"\"Vay halimize\" derler, \"Yattığımız yerden bizi kim kaldırdı? Bu, Rahman'ın söz verdiği şeydi. Demek elçiler doğru söylemişti.\""},{"n":53,"t":"Sadece bir patlama... Hemen huzurumuza toplanıp getirilirler."},{"n":54,"t":"Bu gün hiç kimseye en ufak bir haksızlık edilmez ve yaptığınızın karşılığından başkasını da görmezsiniz."},{"n":55,"t":"Cennet halkı o gün zevk ve eğlence ile meşguldürler."},{"n":56,"t":"Eşleriyle birlikte gölgeliklerde, koltuklara yaslanmışlardır."},{"n":57,"t":"Onlar için meyveler ve istedikleri her şey vardır."},{"n":58,"t":"Rahim olan Rab'den söz olarak \"selam\" vardır."},{"n":59,"t":"Ey suçlular, siz bugün ayrılın."},{"n":60,"t":"Ey Adem'in çocukları, şeytana tapmayacağınıza dair sizden söz almamış mıydım? O sizin açık düşmanınızdır."},{"n":61,"t":"Bana kulluk edin. Bu en doğru yoldur."},{"n":62,"t":"Buna rağmen o, sizden bir çok nesilleri saptırdı. Hiç aklınızı kullanmaz mıydınız?"},{"n":63,"t":"İşte, size söz verilen cehennem budur!"},{"n":64,"t":"İnkarınızın bir sonucu olarak orada yanınız."},{"n":65,"t":"O gün ağızlarına mühür vururuz da, bizimle elleri konuşur ve yapmış olduklarına da ayakları tanıklık eder."},{"n":66,"t":"Dilesek gözlerini büsbütün silerdik. Yolu bulmaya çalıştıklarında göremezlerdi."},{"n":67,"t":"Dilesek onları oldukları yerde dondurur ne ileri gidebilir ne de geri dönebilirlerdi."},{"n":68,"t":"Kime çok ömür verirsek, yaratılışını tersine çeviririz. Anlamaz mısınız? Kuran Ölüler Üzerine Okunmak İçin Gönderilmedi"},{"n":69,"t":"Ona şiir öğretmiş değiliz, zaten ona uygun düşmez. Bu, ancak bir mesaj ve apaçık bir Kuran'dır."},{"n":70,"t":"Dirileri uyarır ve inkarcıları açığa çıkarır.*69 * 36:70 Kuran'ın dirileri uyarmak için indirilmiş olduğunu bildiren biricik ayetin yer aldığı Ya Sin suresinin, özellikle ölülere okunan bir sure olarak tanınması gariptir. Uydurma hadisleri izleyen \"diriler\", Tanrı'nın inadına, bu ayetleri işitmeyen ölülere okumaktadırlar. Anlamadıkları ve inanmadıkları bir kitabı işitmeyen ölülere okuyanlar dünyanın en anlamsız işini yaptıkları gibi bundan para bile kazanabilmektedirler! Bu, Guinness rekorlar kitabına \"dünyanın en garip işleri\" arasında listeye girmeli."},{"n":71,"t":"Görmezler mi, kendi ellerimizle onlar için çiftlik hayvanlarını yarattık da onlara sahip olmaktadırlar?"},{"n":72,"t":"Onları kendilerine boyun eğdirdik; bir kısmına binmekte bir kısmından da yemektedirler."},{"n":73,"t":"Ve onlar için onlarda başka yararlar ve içecekler vardır. Şükretmiyecekler mi? Güçsüz Putlar"},{"n":74,"t":"ALLAH'tan başka tanrılar edindiler. Belki kendilerine yardım ederler diye."},{"n":75,"t":"Oysa onlara yardım edemezler; hatta tam tersine kendileri onları korumak için nöbet bekleyen askerlerdir."},{"n":76,"t":"Sözleri seni üzmesin. Gizledikleri ve açıkladıkları her şeyi çok iyi biliriz."},{"n":77,"t":"İnsan, kendisini bir damlacıktan yarattığımızı görmez mi ki bize karşı apaçık bir düşman kesilir?"},{"n":78,"t":"Ve yaradılışını unutarak bize örnekli bir soru yöneltti: \"Çürüdükten sonra kemikleri kim diriltecek?\" Yanma: Her Zaman Tanık Olduğumuz Bir Diriliş Olayı*"},{"n":79,"t":"De ki, \"Kim onları ilk kez yarattıysa onları yine O diriltecek. O her türlü yaratmayı bilendir.\""},{"n":80,"t":"O ki, size yeşil (klorofilli) ağaçtan ateş çıkarandır. Nitekim onu yakıyorsunuz.*70 * 36:79-80 Her türlü yaratmayı bilen Tanrı, enerjinin fotosentez yoluyla yeşil bitkilerde depolanması; yıllar ve hatta yüzyıllar sonra, odun, kömür veya petrol olarak yanma olayı ile adeta dirilmesi olayını bir diriliş örneği olarak vermektedir. Bak 4:82."},{"n":81,"t":"Gökleri ve yeri yaratan onların benzerini yaratmaya güç yetiremez mi? Gerçekten O, Yaratandır, Bilendir."},{"n":82,"t":"Bir şeyi dilediği zaman, ona sadece \"Ol!\" der ve o da hemen oluverir.*71 * 36:82 Evrenin yaratılışı böyle bir emir sonucu aniden olmuştur. Bak 21:30."},{"n":83,"t":"Her şeyin yönetimini elinde bulunduran çok yücedir ve siz de O'na döndürüleceksiniz."}]},{"id":37,"name":"DİZENLER (SAFFAT) SÛRESİ","verses":[{"n":1,"t":"And olsun sıralar halinde dizenlere,"},{"n":2,"t":"İtekleyip sürenlere,"},{"n":3,"t":"Ve mesajı okuyanlara..."},{"n":4,"t":"Ki sizin Tanrınız birdir."},{"n":5,"t":"Göklerin, yerin ve her ikisinin arasında bulunanların Rabbidir, doğuların Rabbidir."},{"n":6,"t":"Biz en aşağıdaki göğü gezegenler ile süsleyip,"},{"n":7,"t":"Her türlü inatçı şeytana karşı bir koruma yaptık."},{"n":8,"t":"Yüce topluluğu dinleyemezler; her yandan atılırlar."},{"n":9,"t":"Kovulurlar; sürekli bir azabı hakketmişlerdir."},{"n":10,"t":"Bir söz kapan olursa, onu, delici bir ışın izler."},{"n":11,"t":"Sor onlara, \"Yaratılış bakımından onlar mı daha çetin, yoksa bizim yarattıklarımız mı?\" Onları yapışkan bir balçıktan yarattık."},{"n":12,"t":"Sen hayranlık duyarken onlar alay ediyorlar."},{"n":13,"t":"Kendilerine hatırlatıldığında öğüt almıyorlar."},{"n":14,"t":"Bir delil gördüklerinde onu alaya alıyorlar."},{"n":15,"t":"Derler, \"Bu, apaçık bir büyüden başka bir şey değildir.\""},{"n":16,"t":"\"Ölüp, toprak ve kemik olduktan sonra mı, biz mi diriltilecekmişiz?\""},{"n":17,"t":"\"Hatta bizden önceki atalarımız da mı?\""},{"n":18,"t":"De ki, \"Evet, hem de horlanarak.\""},{"n":19,"t":"O, bir tek dokunmadır. O zaman (kalkıp) bakınırlar."},{"n":20,"t":"\"Vay halimize!\" derler, \"Bu Yargı Günüdür.\""},{"n":21,"t":"Bu, sizin yalanlamış olduğunuz karar günüdür."},{"n":22,"t":"Zalimleri toplayın. Eşlerini ve,"},{"n":23,"t":"ALLAH'tan başka taptıklarını... Onlara cehennemin yolunu gösterin."},{"n":24,"t":"Ve durdurun onları; sorguya çekileceklerdir."},{"n":25,"t":"\"Neden bir birinize yardım etmiyorsunuz?\""},{"n":26,"t":"Hayır, o gün tümüyle teslim olmuşlardır. Liderler İle İzleyicilerinin Karşılıklı Suçlamaları"},{"n":27,"t":"Dönüp birbirlerini sorgularlar."},{"n":28,"t":"\"Siz bize sağ yanımızdan yaklaşıyordunuz,\" derler."},{"n":29,"t":"Derler ki, \"Aslında siz inanmış kimseler değildiniz.\""},{"n":30,"t":"\"Bizim sizin üzerinizde her hangi bir gücümüz yoktu. Aksine siz azmış bir topluluktunuz.\""},{"n":31,"t":"\"Rabbimizin hakkımızdaki sözü gerçekleşti, artık tadacağız.\""},{"n":32,"t":"\"Biz azmıştık. Sizi de azdırdık.\""},{"n":33,"t":"Böylece, o gün onlar azabta ortaktırlar."},{"n":34,"t":"Biz suçlulara böyle yaparız. Müşrikler Sadece Tanrı'nın Anılmasından Rahatsız Olurlar"},{"n":35,"t":"Kendilerine \"La ilahe illa ALLAH\" denildiğinde büyükleniyorlardı."},{"n":36,"t":"\"Tanrılarımızı deli bir şair için mi terkedeceğiz?\" diyorlardı."},{"n":37,"t":"Doğrusu, o, gerçeği getirmiş ve elçileri doğrulamıştır. Yine O diriltecektir. O her türlü yaratmayı bilendir."},{"n":38,"t":"Siz elbette acı azabı tadacaksınız."},{"n":39,"t":"Sadece yapmış olduklarınızın karşılığını görüyorsunuz."},{"n":40,"t":"Kendilerini sadece ALLAH'a adamış kulları hariç."},{"n":41,"t":"Onlar bilinen bir rızkı haketmişlerdir."},{"n":42,"t":"Meyvelerle ağırlanacaklardır."},{"n":43,"t":"Nimet cennetlerinde."},{"n":44,"t":"Karşılıklı koltuklar üzerinde."},{"n":45,"t":"Onlara pınarlardan doldurulmuş kadehler sunulur."},{"n":46,"t":"Durudur, içenlere zevk ve lezzet verir."},{"n":47,"t":"Onda ne başağrısı ne de sarhoşluk vardır."},{"n":48,"t":"Yanlarında da, gözlerinin içine bakan güzel eşler..."},{"n":49,"t":"Kornumuş yumurtalar gibidirler. Cennet Halkı Cehennem Halkını Ziyaret Ediyor"},{"n":50,"t":"Birbirlerine dönüp soruşurlar."},{"n":51,"t":"İçlerinden biri der ki, \"Benim bir arkadaşım vardı.\""},{"n":52,"t":"\"Şöyle konuşurdu, 'Sen de doğruluyor musun?' \""},{"n":53,"t":"\" 'Biz toprak ve kemik olduktan sonra mı, biz mi dirileceğiz?' \""},{"n":54,"t":"(Yanındakilere,) \"Bakar mısınız?\" der."},{"n":55,"t":"Baktığında, onu cehennemin ortasında bulur."},{"n":56,"t":"\"ALLAH'a andolsun, az kalsın sen beni de mahfedecektin,\" der."},{"n":57,"t":"\"Rabbimin nimeti olmasaydı, ben de şimde seninle birlikte olurdum.\""},{"n":58,"t":"\"(Sana göre), biz öldüğümüzde,\""},{"n":59,"t":"\"İlk ölüm hariç, cezalandırılmayacaktık hani?\""},{"n":60,"t":"İşte büyük zafer budur."},{"n":61,"t":"Çalışanlar bunun için çalışmalı. Ateşin İçinde Biten Ağaç"},{"n":62,"t":"Bu mu daha iyi bir duraktır, yoksa zakkum ağacı mı?"},{"n":63,"t":"Biz onu zalimler için bir test kıldık."},{"n":64,"t":"O, cehennemin dibinden çıkan bir ağaçtır."},{"n":65,"t":"Tomurcukları şeytanların başı gibidir."},{"n":66,"t":"Onlar ondan yiyerek karınlarını doyuracaklar."},{"n":67,"t":"Bunun üstüne onlar için cehennemi bir kokteyl vardır."},{"n":68,"t":"Sonra dönüşleri yine cehennemedir. Atalarını Körükörüne İzlediler"},{"n":69,"t":"Onlar, atalarını sapık kimseler olarak bulmuşlardı."},{"n":70,"t":"Ve onların izlerini körükörüne izliyorlardı."},{"n":71,"t":"Kendilerinden önce de niceleri aynı şekilde sapmıştı."},{"n":72,"t":"İçlerinden uyarıcılar göndermiştik."},{"n":73,"t":"Uyarılanların sonunun nasıl olduğuna bir bak."},{"n":74,"t":"Kendilerini sadece ALLAH'a adayan kulları hariç. Nuh"},{"n":75,"t":"Nuh bize seslenmişti de ne güzel karşılık vermiştik."},{"n":76,"t":"Onu ve ailesini o büyük felaketten kurtarmıştık."},{"n":77,"t":"Onun soyunu ise yaşattık."},{"n":78,"t":"Ve biz onu daha sonrakiler için bıraktık."},{"n":79,"t":"Tarih boyunca Nuh'a selam."},{"n":80,"t":"Biz güzel davrananları işte böyle ödüllendiririz."},{"n":81,"t":"O, bizim inanan kullarımızdandı."},{"n":82,"t":"Sonra diğerlerini boğduk. İbrahim"},{"n":83,"t":"İbrahim onun bir kolundan idi."},{"n":84,"t":"Rabbine tertemiz bir kalp ile gelmişti."},{"n":85,"t":"Babasına ve halkına, \"Neye tapıyorsunuz?\" demişti."},{"n":86,"t":"\"ALLAH'ın dışında, uyduruk tanrılar mı istiyorsunuz?\""},{"n":87,"t":"\"Evrenlerin Rabbini ne zannediyorsunuz?\""},{"n":88,"t":"Yıldızlara bir göz attı.*72 ** 37:88-89 ibrahim'in halkı yıldızlara ve putlara tapıyordu. (6:76-78)"},{"n":89,"t":"\"Bıktım, yoruldum artık,\" dedi.*"},{"n":90,"t":"Onlar da onu bırakıp gittiler."},{"n":91,"t":"Sonra, tanrılarına yöneldi ve \"Yemez misiniz?\" dedi."},{"n":92,"t":"\"Neyiniz var, neden konuşmuyorsunuz?\""},{"n":93,"t":"Ve üzerlerine yürüyüp tüm gücüyle vurdu."},{"n":94,"t":"Hemen ona doğru koşuştular."},{"n":95,"t":"Dedi ki, \"Yonttuğunuz şeylere mi tapıyorsunuz?\"."},{"n":96,"t":"\"ALLAH, sizi de ve yaptığınız şeyleri de yaratandır.\""},{"n":97,"t":"Dediler ki, \"Onun için bir yapı kurun ve onu ateşe atın.\""},{"n":98,"t":"Onun için bir plan düşündüler, fakat biz onları altettik."},{"n":99,"t":"Dedi ki, \"Ben Rabbime gidiyorum; O bana yol gösterir.\""},{"n":100,"t":"\"Rabbim, bana erdemli birini bağışla.\""},{"n":101,"t":"Biz de ona yumuşak huylu bir erkek çocuk bağışladık."},{"n":102,"t":"Onunla birlikte çalışma çağına varınca, \"Oğlum,\" dedi, \"Rüyamda seni boğazlamam gerektiğini görüyorum. Ne düşünüyorsun?\" \"Babacığım,\" dedi, \"Sana emredileni uygula. ALLAH dilerse beni sabırlı bulacaksın.\""},{"n":103,"t":"Böylece ikisi de teslim oldu ve onu alnı üzerine yıktı."},{"n":104,"t":"Kendisine, \"İbrahim!\" diye seslendik,"},{"n":105,"t":"\"Sen rüyanı uyguladın.\" İyileri böyle ödüllendiririz.*73 * 37:105-107 İbrahim rüyasını Tanrı'nın emri sanınca tüm içtenliğiyle, canından çok sevdiği oğlunu kurban etmeye karar verdi. Bu, Tanrı'nın bir emri olamazdı. Tanrı ona bir hayvan göndererek onu rüyasını gerçekleştirmekten kurtardı."},{"n":106,"t":"Gerçekten bu apaçık bir sınavdı."},{"n":107,"t":"Ve biz ona fidye olarak büyük bir kurban verdik.*"},{"n":108,"t":"Sonrakiler için onun tarihini koruduk."},{"n":109,"t":"İbrahim'e selam olsun."},{"n":110,"t":"Biz iyi davrananları böyle ödüllendiririz."},{"n":111,"t":"O, bizim inanan kullarımızdandı."},{"n":112,"t":"Ona İshak'ı müjdeledik, erdemlilerden bir peygamber olarak."},{"n":113,"t":"Ona da İshak'a da lütufta bulunduk. Kuşkusuz, ikisinin de soyundan hem iyi davrananlar var, hem kendisine zulmedenler. Musa ve Harun"},{"n":114,"t":"Biz Musa'ya ve Harun'a iyilikte bulunmuştuk."},{"n":115,"t":"İkisini ve halklarını o büyük felaketten kurtardık."},{"n":116,"t":"Onlara yardım ettik de üstün geldiler."},{"n":117,"t":"Ve o ikisine apaçık anlaşılan kitabı verdik."},{"n":118,"t":"Her ikisini doğru yola ilettik."},{"n":119,"t":"O ikisinin tarihini sonrakiler için koruduk."},{"n":120,"t":"Musa'ya ve Harun'a selam (barış) olsun."},{"n":121,"t":"Biz, iyi davrananları işte böyle ödüllendiririz."},{"n":122,"t":"O ikisi bizim inanan kullarımızdandı. İlyas"},{"n":123,"t":"İlyas elçilerden biriydi."},{"n":124,"t":"Halkına, \"Erdemli olmayacak mısınız?\" dedi."},{"n":125,"t":"En güzel Yaratanı bırakıp Ba'le mi taparsınız?"},{"n":126,"t":"ALLAH sizin ve geçmişteki atalarınızın Rabbidir."},{"n":127,"t":"Onu yalanladılar; onlar hesaba çekileceklerdir."},{"n":128,"t":"Kendilerini sadece ALLAH'a adayan kulları hariç."},{"n":129,"t":"Sonrakiler için onun tarihini koruduk."},{"n":130,"t":"İlyasin'e salam olsun."},{"n":131,"t":"İyi davrananları biz böyle ödüllendiririz."},{"n":132,"t":"O bizim inanan kullarımızdandı. Lut"},{"n":133,"t":"Lut da elçilerden biriydi."},{"n":134,"t":"Onu ve ailesini topluca kurtardık."},{"n":135,"t":"Ancak geride kalan yaşlı kadın hariç."},{"n":136,"t":"Sonra diğerlerini yok ettik."},{"n":137,"t":"Siz yıkıntılarının yanından geçiyorsunuz; sabahleyin,"},{"n":138,"t":"Ve geceleyin. Aklınızı kullanmaz mısınız? Yunus"},{"n":139,"t":"Yunus da elçilerden biriydi."},{"n":140,"t":"Dolu bir gemiye kaçmıştı."},{"n":141,"t":"Karşı çıktı ve kayanlardan oldu."},{"n":142,"t":"Balık onu yuttu, bundan o sorumluydu."},{"n":143,"t":"(Tanrı'yı) anıp düşünmeseydi,"},{"n":144,"t":"Diriliş Gününe kadar onun karnında kalacaktı."},{"n":145,"t":"Onu çöl gibi bir sahile attık, yorgun ve bitkin..."},{"n":146,"t":"Ve onun için orada geniş yapraklı ağaç yetiştirdik."},{"n":147,"t":"Biz onu yüzbin veya daha çok kişiye gönderdik."},{"n":148,"t":"İnandılar, biz de onları bir süreye kadar geçindirdik."},{"n":149,"t":"Sor onlara, kızları senin Rabbine, erkekleri kendilerine mi ayırıyorlar?\""},{"n":150,"t":"Yoksa melekleri, onların gözü önünde dişi olarak mı yarattık?"},{"n":151,"t":"Aslında onlar uydurdukları yüzünden diyorlar ki:"},{"n":152,"t":"\"ALLAH doğurdu.\" Onlar yalancıdırlar."},{"n":153,"t":"Kızları erkeklere mi tercih etti?"},{"n":154,"t":"Size ne oldu, nasıl karar veriyorsunuz?"},{"n":155,"t":"Öğüt almaz mısınız?"},{"n":156,"t":"Yoksa apaçık bir delile mi sahipsiniz?"},{"n":157,"t":"Doğruysanız kitabınızı getirin."},{"n":158,"t":"Hatta O'nunla cinler arasında bir akrabalık uydurdular. Halbuki cinler sorguya çekileceklerini bilirler."},{"n":159,"t":"ALLAH onları yakıştırmalarından çok Yücedir."},{"n":160,"t":"Kendilerini sadece ALLAH'a adayan kulları hariç."},{"n":161,"t":"Siz ve tapmakta olduklarınız,"},{"n":162,"t":"O'na karşı kimseyi saptıramazsınız."},{"n":163,"t":"Ancak cehennemde yanacaklar hariç. Melekler"},{"n":164,"t":"Her birimizin belli bir görevi vardır."},{"n":165,"t":"Biz, dizenleriz,"},{"n":166,"t":"Biz, anıp yüceltenleriz. Ataları İzleyenler ve Elçiler"},{"n":167,"t":"Diyorlardı ki,"},{"n":168,"t":"\"Yanımızda öncekilerden bir uyarı bulunsaydı,\""},{"n":169,"t":"\"Kendimizi ALLAH'a adar, sadece O'na kul olurduk.\""},{"n":170,"t":"Böylece onu inkar ettiler; ileride bilecekler."},{"n":171,"t":"Elçilikle görevli kullarımız için söz verilmiştir."},{"n":172,"t":"Onlar elbette zafere ulaşacaklar."},{"n":173,"t":"Bizim ordumuz kesinlikle üstün gelecektir."},{"n":174,"t":"Öyleyse bir süre için onlara aldırış etme."},{"n":175,"t":"Onları seyret; onlar da görecekler."},{"n":176,"t":"Azabımıza mı meydan okuyorlar?"},{"n":177,"t":"Yurtlarına inince uyarılanların sabahı ne kötü olur!"},{"n":178,"t":"Bir süreye kadar onlara aldırış etme."},{"n":179,"t":"Onları gözle; onlar da görecekler."},{"n":180,"t":"Üstünlük ve onurun sahibi olan Rabbin, onların nitelemelerinden çok yücedir."},{"n":181,"t":"Gönderilmiş elçilere selam olsun."},{"n":182,"t":"Evrenlerin Rabbi olan ALLAH'a övgüler olsun."}]},{"id":38,"name":"SS (SAD) SÛRESİ","verses":[{"n":1,"t":"SS;*74 mesajı içeren bu Kuran'a andolsun."},{"n":2,"t":"Doğrusu, inkar edenler kibir ve ayrılık içindedir."},{"n":3,"t":"Onlardan önce nice nesilleri yok ettik. Feryat ettiler, ancak artık kurtuluş zamanı değildi."},{"n":4,"t":"Onlara, kendilerinden bir uyarıcının gelmesini yadırgadılar. İnkarcılar, \"Bu pek yalancı bir büyücüdür,\" dediler,"},{"n":5,"t":"\"Tanrıları tek tanrı mı yaptı? Bu, gerçekten çok tuhaf!\""},{"n":6,"t":"Onların liderleri öne fırladılar, \"Yürüyün, tanrılarınıza bağlı kalın. Sizden istenen sadece budur.\""},{"n":7,"t":"\"Son dinde böylesini işitmedik. Bu bir uydurmadır.\""},{"n":8,"t":"\"Mesaj, neden aramızdan ona indirildi?\" Aslında, onlar mesajımdan kuşku içindedirler.*75 Hayır, onlar azabı henüz tatmadılar. * 38:8 Kuran'ın bir ismi de Mesaj (Zikir) dir. Burada sözü edilen mesaj, hem Kuran'a ve hem de ilk ayette bildirildiği gibi Kuran'ın içerdiği bir mesaja da işaret ediyor. Bir başka deyişle, Mesaj, bu çağın insanına yeni bir mesaj içermektedir. Kuran, mesaj içinde mesaj, nur içinde nurdur (24:35). Mesajın niteliği için bak 74:30-35."},{"n":9,"t":"Yoksa Üstün olan ve Bahşeden Rabbinin rahmet hazineleri onların yanında mıdır?"},{"n":10,"t":"Yoksa göklerin, yerin ve aralarındakilerin yönetimi onlara mı aittir? Bırak, kendi kendilerini yüceltsinler."},{"n":11,"t":"Aksine onlar parti parti yenilgiye uğramış bir ordudur."},{"n":12,"t":"Onlardan önce Nuh halkı, Ad ve piramitler sahibi Firavun da yalanlamıştı."},{"n":13,"t":"Semud, Nuh halkı ve Eykeliler de... Onlar partilerdi."},{"n":14,"t":"Hepsi de elçileri yalanladılar ve cezamı hakkettiler."},{"n":15,"t":"Bunlar, onması olmayan bir tek patlama bekliyorlar."},{"n":16,"t":"Ve, \"Rabbimiz, Hesap Gününden önce acele olarak payımızı ver,\" diye meydan okudular. Davud'un Adalet Konusundaki Duyarlılığı"},{"n":17,"t":"Onların sözlerine karşı sabırlı ol, becerikli bir kulumuz olan Davud'u anımsa; o (Tanrı'ya) sürekli itaat ederdi."},{"n":18,"t":"Dağları onun emrine vermiştik; onunla birlikte akşamleyin ve tan doğumu (Tanrı'yı) yüceltirlerdi."},{"n":19,"t":"Kuşlar da toplanmıştı; hepsi onun buyruğunu izlerdi."},{"n":20,"t":"Yönetimini güçlendirdik; ona bilgelik ve çok iyi bir yargılama gücü verdik."},{"n":21,"t":"Davacıların haberi sana ulaştı mı? Hani mabedine tırmanmışlardı."},{"n":22,"t":"Davud'un yanına girdiklerinde onlardan irkilmişti. \"Korkma\" demişlerdi, \"Bir birinin hakkını çiğneyen iki davacı... Aramızda gerçeğe göre hüküm ver, haksızlık etme. Bize yolun ortasını göster.\""},{"n":23,"t":"\"Bu benim kardeşimdir. Onun doksan dokuz*76 koyunu, benim ise bir tek koyunum var. Böyle iken, \"Onu da bana ver,\" dedi ve tartışmada bana üstün geldi. * 38:23 Bak 74:30."},{"n":24,"t":"Dedi ki, \"Senin koyununu kendi koyunlarına katmayı istemekle sana haksızlık etmiştir. Doğrusu, ortakçıların çoğu bir birinin hakkına el uzatır. İnanıp erdemli davrananlar bunun dışındadır, onlar ise sayıca ne kadar azdır!\" Davud, kendisini sınadığımızı sanarak bağışlanma diledi, eğildi ve tevbe etti.*77 * 38:24 Bu örnekte, Davud peygamber, şikayetçi tarafı dinledikten sonra duygularına kapılarak karar veriyor. Diğer tarafı dinlememesi büyük bir hata idi. Adalet, tek tarafı dinleyerek gerçekleşmez. Şikayetçi, olayı tek taraflı aktarabilir veya olayla ilgili bazı önemli detayları gizleyebilir. Davaya sosyal adalet kaygısıyla yaklaşılsa bile durum değişmez. Şikayetçi taraf çok büyük bir araziye, bağ ve bahçelere sahipken, diğer tarafın tüm varlığı yüz koyundan ibaret olabilirdi."},{"n":25,"t":"Böylece onu bağışladık. Yanımızda onun yakınlığı ve güzel bir yeri vardır."},{"n":26,"t":"Ey Davud, biz seni yeryüzünde yönetici kıldık. Halkın arasında adaletle yargı ver, hevesine ve duygularına kapılma, sonra seni ALLAH'ın yolundan saptırır. ALLAH'ın yolundan sapanlara, Hesap Gününü unuttukları için çetin bir ceza vardır."},{"n":27,"t":"Göğü, yeri ve aralarındakileri boş yere yaratmadık. Bu inkar edenlerin sanısıdır. Kendilerini ateşe soktukları için inkar edenlere yazıklar olsun."},{"n":28,"t":"İnanıp iyi davrananları, yeryüzünde bozgunculuk yapanlar gibi mi tutacağız? Erdemlilere, yoldan çıkanlar gibi mi davranacağız?"},{"n":29,"t":"Sana indirdiğimiz bu kitap kutludur; ayetlerini incelesinler ve akıl sahipleri öğüt alsınlar. Süleyman Mal ve Mülk İle Sınanıyor"},{"n":30,"t":"Davud'a, Süleyman'ı verdik. İyi bir kuldu, (Tanrı'ya) sürekli yönelen biriydi."},{"n":31,"t":"Bir akşam, ona güzel koşu atları sunulmuştu."},{"n":32,"t":"Dedi ki, \"Mal ve mülk sevgisi beni Rabbimi anmaktan alıkoydu. Ta ki, o (güneş) bir örtünün ardından kayboldu.\"*78 * 38:32 Süleyman peygamberin, atlarıyla meşgul olurken akşam namazını kaçırdığı anlaşılıyor."},{"n":33,"t":"\"Onları bana geri getirin,\" dedi, (veda etmek için) bacaklarını ve boyunlarını okşadı."},{"n":34,"t":"Süleyman'ı böylece sınadık; onun hükümranlığına maddi zenginlik kattık; ancak o tümüyle (Tanrı'ya) yöneldi."},{"n":35,"t":"Dedi ki, \"Rabbim beni bağışla. Bana, benden sonra kimsenin ulaşamıyacağı bir yönetim ver. Sen Bahşedensin.\""},{"n":36,"t":"Bunun üzerine komutuyla hareket eden rüzgarı onun emrine verdik. Dilediği yere yağmur yağdırırdı."},{"n":37,"t":"Şeytanları da, yapı ustaları ve dalgıçlar olarak..."},{"n":38,"t":"Ve zincirlerle birbirine bağlı bekleyen yedekleri de..."},{"n":39,"t":"\"Bu bizim bağışımızdır. İster ver, ister tut, tükenmez.\""},{"n":40,"t":"Onun bizim yanımızda yakınlığı ve güzel yeri vardı. Eyyub, Hastalık ve Aile Sorunlarıyla Sınanıyor"},{"n":41,"t":"Kulumuz Eyyub'u an: \"Rabbim, şeytan bana bitkinlik ve acı dokundurdu,\" diye Rabbine seslenmişti."},{"n":42,"t":"\"Ayağını yere vur. İşte yıkanacak ve içilecek soğuk bir kaynak.\""},{"n":43,"t":"Çoluk çocuğunu bir katıyla birlikte ona geri verdik. Bu, akıl sahiplerine bizden bir rahmet ve mesajdır."},{"n":44,"t":"\"Şimdi eline bir değnek alıp yola çık. Yeminini bozma.\" Onu sabırlı bulduk. Ne iyi bir kul! Sürekli yönelirdi."},{"n":45,"t":"Kullarımız İbrahim, İshak ve Yakub'u anımsa. Becerikli idiler, ileri görüşlü idiler."},{"n":46,"t":"Salt ahireti düşündükleri için onları salt/dupduru kıldık."},{"n":47,"t":"Onlar bizim yanımızda iyilerden seçilmiş kimselerdi."},{"n":48,"t":"İsmail'i, Elyesa'ı ve Zülkifl'i de anımsa; hepsi iyilerdendi."},{"n":49,"t":"Bu bir mesajdır: Erdemliler için güzel bir gelecek,"},{"n":50,"t":"Ve kapıları kendilerine açılmış Adn cennetleri vardır."},{"n":51,"t":"Orada konfor içinde bol meyve ve içecek isterler."},{"n":52,"t":"Yanlarında gözlerinin içine bakan yaşıtları vardır."},{"n":53,"t":"Hesap Günü için size söz verilen budur."},{"n":54,"t":"Bizim bu rızkımız tükenmez."},{"n":55,"t":"Bu böyledir; azgınlar ise kötü bir yeri hakederler."},{"n":56,"t":"Cehennemde yanarlar; ne kötü bir duraktır."},{"n":57,"t":"İşte onu tatsınlar: Kaynar su ve irin."},{"n":58,"t":"Bunlara benzer daha başkaları da vardır."},{"n":59,"t":"\"Bunlar sizinle birlikte paldır küldür sürüklenen bir gruptur.\" (denilince, cehennemdeki liderler:) \"Onlar hoş gelmediler. Onlar ateşte yanacaklar.\""},{"n":60,"t":"Onlar da derler ki, \"Aslında siz hoş gelmediniz. Bizi bu duruma siz soktunuz; ne kötü bir son!\""},{"n":61,"t":"\"Rabbimiz, kim bizi bu duruma soktuysa onun cezasını ateşte ikiye katlayarak arttır,\" diye eklerler. Sürpriz!"},{"n":62,"t":"\"Nasıl oluyor da kötü olarak saydığımız insanları göremiyoruz?\""},{"n":63,"t":"\"Onlarla alay edip durduk. Yoksa onları gözlerimizden mi kaçırdık?\""},{"n":64,"t":"Cehennem halkının birbiriyle çekişmesi bir gerçektir."},{"n":65,"t":"De ki, \"Ben sadece bir uyarıcıyım. Tek ve Egemen olan ALLAH'tan başka bir tanrı yoktur.\""},{"n":66,"t":"Göklerin, yerin ve aralarındakilerin Rabbi; Üstündür, Bağışlayandır. Büyük Tartışma"},{"n":67,"t":"De ki, \"Bu, büyük bir haberdir.\""},{"n":68,"t":"\"Siz ise ondan yüz çeviriyorsunuz.\""},{"n":69,"t":"\"Onlar tartışırlarken Yüce Toplum'da neler olup bittiği hakkında bir bilgim yoktu.\""},{"n":70,"t":"\"Apaçık bir uyarıcı olduğum için bana vahyediliyor.\""},{"n":71,"t":"Rabbin meleklere demişti ki, \"Balçıktan bir insan yaratacağım.\""},{"n":72,"t":"\"Onu düzenlediğim ve ona ruhumdan üflediğim zaman ona secdeye kapanın.\""},{"n":73,"t":"Tüm melekler ona secdeye kapandı;"},{"n":74,"t":"Ancak İblis hariç. Büyüklük tasladı ve nankör oldu."},{"n":75,"t":"\"Ey İblis, ellerimle yarattığıma secde etmekten seni alıkoyan nedir? Büyüklük mü tasladın? Yoksa baş mı kaldırdın?\" dedi."},{"n":76,"t":"\"Ben ondan daha üstünüm,\" dedi, \"Beni ateşten yarattın, onu ise balçıktan yarattın.\""},{"n":77,"t":"\"Çık oradan,\" dedi, \"Sen kovuldun.\""},{"n":78,"t":"\"Yargı Gününe kadar lanetimi hakettin.\""},{"n":79,"t":"Dedi ki, \"Rabbim, dirilecekleri güne dek beni ertele.\""},{"n":80,"t":"Dedi ki, \"Sana süre verilmiştir;\""},{"n":81,"t":"\"Bilinen vaktin gününe kadar.\""},{"n":82,"t":"Dedi ki, \"Büyüklüğüne andolsun, tümünü azdıracağım.\""},{"n":83,"t":"\"Ancak onlardan kendilerini sadece sana adayan kulların hariç.\""},{"n":84,"t":"Dedi ki, \"Bu gerçektir ve ben sadece gerçeği söylerim:\""},{"n":85,"t":"\"Cehennemi seninle ve onlardan seni izliyenlerle topluca dolduracağım.\""},{"n":86,"t":"De ki, \"Buna karşılık olarak sizden bir ücret istemiyorum. Ben bir sahtekar değilim.\""},{"n":87,"t":"\"Bu, tüm dünyaya bir mesajdır.\""},{"n":88,"t":"\"Ve onun haberlerini bir süre sonra öğreneceksiniz.\""}]},{"id":39,"name":"YIĞINLAR (ZÜMER) SÛRESİ","verses":[]},{"id":40,"name":"BAĞIŞLAYAN (ĞAFİR) SÛRESİ","verses":[{"n":1,"t":"HH. M."},{"n":2,"t":"Bu kitabın indirilmesi, Üstün ve Her Şeyi Bilen ALLAH katındandır."},{"n":3,"t":"Günahları Bağışlayan, Tevbeyi Kabul Eden, Cezası Şiddetli, Sonsuz Güç Sahibi... O'ndan başka tanrı yoktur. Dönüş O'nadır."},{"n":4,"t":"İnkarcılardan başkası ALLAH'ın ayetleri ve mucizelerine karşı tartışmaz. Onların görünür başarıları seni aldatmasın."},{"n":5,"t":"Onlardan önce Nuh'un halkı da yalanlamıştı ve onlardan sonra bir çok parti de... Her topluluk elçilerini etkisiz hale getirmeye çalıştı. Gerçeği gidermek için boş ve yalnış şeylerle tartıştılar. Sonunda onları yakaladım; cezalandırmam nasılmış?"},{"n":6,"t":"Rabbinin, \"Onlar cehennemin halkıdır,\" diye inkarcılar hakkında verdiği sözü böylece gerçekleşir."},{"n":7,"t":"Yönetim merkezine hizmet edenler ve etrafındakiler Rab'lerini överek yüceltirler ve O'na inanırlar. İnananlar için bağışlanma dilerler: \"Rabbimiz, rahmetin ve bilgin her şeyi içine almıştır. Tevbe edenler ve senin yoluna uyanları bağışla ve onları ateşin azabından koru.\""},{"n":8,"t":"\"Rabbimiz onları, erdemli atalarını, eşlerini ve çocuklarını söz verdiğin Adn cennetlerine sok. Kuşkusuz sen Üstünsün, Bilgesin.\""},{"n":9,"t":"\"Onları kötülüklerden koru. O gün kimi kötülüklerden korursan onlara rahmet etmişsindir. Büyük zafer budur.\" SADECE O"},{"n":10,"t":"İnkar etmiş olanlara, \"ALLAH'ın hoşnutsuzluğu, sizin kendi kendinize olan hoşnutsuzluğunuzdan daha büyüktür. İmana çağrıldığınızda inkar ederdiniz,\" diye seslenilir."},{"n":11,"t":"Diyecekler ki, \"Rabbimiz, bizi iki kez öldürdün ve iki kez dirilttin. Şimdi günahlarımızı itiraf ettik. Buradan bir çıkış yolu var mı?\""},{"n":12,"t":"Çünkü, YALNIZ ALLAH çağrıldığı zaman inkar ederdiniz. Ancak kendisine ortak koşulduğunda inanırdınız. Hüküm, Üstün ve Büyük olan ALLAH'a aittir."},{"n":13,"t":"O ki size ayetlerini (kanıtlarını ve işaretlerini) göstermekte ve sizin için gökten bir rızık indirmektedir. Tümüyle yönelip teslim olandan başkası ibret almaz."},{"n":14,"t":"İnkarcılar hoşlanmasa da dini sadece ALLAH'a ait kılarak O'na kulluk edin. * 40:14 Bak 39:11. 15. Dereceleri Yükselten, Yönetim Sahibi. Buluşma gününe karşı uyarsın diye kullarından dilediğine, emirlerini içeren vahyini indirir."},{"n":16,"t":"O gün onlar tümüyle açığa çıkarılacaklardır. Hiç bir şey onları ALLAH'tan gizleyemez. O gün yönetim kime aittir? Tek ve En Üstün olan ALLAH'a aittir. Büyük Gün İçin Hazır Ol"},{"n":17,"t":"O gün her kişiye yaptığının karşılığı ödenir. O gün haksızlık yoktur. ALLAH hesabı çabuk görendir."},{"n":18,"t":"Onları yaklaşan gün hakkında uyar, o zaman yürekler gırtlaklara dayanmıştır, yutkunurlar. Zalimler için ne bir dost ne de sözü dinlenir bir şefaatçı vardır."},{"n":19,"t":"Gözlerin göremediğini ve göğüslerin gizlediğini bilir."},{"n":20,"t":"ALLAH adaletle yargı verir. O'ndan başka çağırdıkları ise hiç bir şeye yargı veremezler. ALLAH İşitendir, Görendir."},{"n":21,"t":"Kendilerinden öncekilerin sonucunun nasıl olduğuna bakmak için yeryüzünde dolaşmıyorlar mı? Onlardan daha fazla güce sahiptiler, yeryüzünde daha çok üreticiydiler. Ancak ALLAH onları günahlarıyla yakaladı. ALLAH'a karşı onları koruyabilecek yoktur."},{"n":22,"t":"Çünkü, elçiler onlara apaçık delillerle gittiklerinde inkar ediyorlardı. Sonunda ALLAH onları yakaladı. O Güçlüdür, Cezalandırması Şiddetlidir. Musa ve Zulüm Cephesi"},{"n":23,"t":"Musa'yı ayetlerimiz ve apaçık bir yetki ile gönderdik."},{"n":24,"t":"Firavun'a, Haman'a ve Karun'a... \"Bu sihirbazın ve yalancının biridir,\" dediler. * 40:24 Firavun, Haman, ve Karun, sırasıyla, siyasi otoritenin, militarize gücün, ve sermayenin temsilcileri olarak Tanrı'nın mesajına karşı güçbirliği ederek savaşmışlardı. Bu oligarşi, sihirbazları (dinadamlarını) sömürülerinin devamı için kullandılar (7:112-116). Nitekim totaliter rejimlerin birçoğu benzer mekanizmalara sahiptir."},{"n":25,"t":"Onlara bizden bir gerçeği götürünce, \"Onunla birlikte inananların oğullarını öldürün, kadınlarını ise yaşatın,\" dediler. İnkarcıların planı hep sapıkçadır."},{"n":26,"t":"Firavun dedi, \"Beni bırakın Musa'yı öldüreyim de o da Rabbine yalvarsın. Sizin dininizi değiştireceğinden veya yeryüzünde kötülük çıkaracağından endişeleniyorum.\""},{"n":27,"t":"Musa dedi, \"Ben, hesap gününe inanmıyan her azgından Rabbime ve sizin Rabbinize sığındım,\" dedi."},{"n":28,"t":"Firavun'un tarafından inancını gizleyen inanan bir adam dedi ki, \"Siz 'benim Rabbim ALLAH'tır' diyen bir adamı mı öldüreceksiniz? Halbuki size Rabbinizden apaçık deliller getirmiş bulunuyor. Yalancı ise, bu onun problemidir; yok doğru sözlü ise onun size anlattıkları gerçekleşir. Kuşkusuz ALLAH sınırı aşan yalancıları sevmez.\""},{"n":29,"t":"\"Ey halkım, yönetim bugün sizindir ve ülkede siz egemensiniz. Ancak ALLAH'ın hışmı bize gelirse kim ona karşı bize yardım edebilir?\" Firavun da, \"Size kendi görüşümü öğütlüyorum; size doğru yolu gösteriyorum,\" dedi."},{"n":30,"t":"İnanmış adam dedi ki, \"Ey halkım daha önceki partilerin günü gibi bir sonuca uğramanızdan korkuyorum.\""},{"n":31,"t":"\"Nuh, Ad, Semud ve onlardan sonrakilerin durumu gibi. Elbette ALLAH kullara haksızlık etmek dilemez.\""},{"n":32,"t":"\"Halkım, sizin için Toplanma Gününden korkuyorum.\""},{"n":33,"t":"\"O gün arkanızı dönüp kaçacaksınız; ancak sizi ALLAH'tan koruyacak yoktur. ALLAH'ın saptırdığına yol gösteren bulunmaz.\" Son Elçi Kimdir? İnsanlığın Trajik Tavrı"},{"n":34,"t":"Daha önce Yusuf da size apaçık delillerle gelmişti; fakat size getirdiği mesajı sürekli olarak kuşku ile karşılamıştınız. Nihayet o ölünce, \"ALLAH ondan sonra elçi göndermeyecektir (O son elçidir),\" demiştiniz. ALLAH, kuşkuda sınırı aşanı böylece saptırır.\" * 40:34 Aynı şekilde Yahudiler kendilerine gelen İsa'yı reddettiler, Hristiyanlar da Muhammed'i. Muhammed'i putlaştıranlar da ondan sonra gelen ve gelecek elçileri peşinen reddediyorlar."},{"n":35,"t":"ALLAH'ın ayet ve mucizelerine karşı, hiç bir delile sahip olmadan tartışanlar, hem ALLAH katında ve hem de inananlar katında büyük bir öfkeye muhataptır. ALLAH her kibirli zorbanın kalbini işte böyle mühürler. Tanrı'yla Alay Ediyor"},{"n":36,"t":"Firavun dedi ki, \"Haman, benim için bir kule dik de yollara erişeyim.\""},{"n":37,"t":"\"Göklerin yollarına... Böylece Musa'nın tanrısına bir bakayım. Onun bir yalancı olduğuna inanıyorum.\" Firavun'un kötü tavrı kendisine böyle süslenmişti ve böylece yoldan çıkarıldı. Firavun'un planı elbette boşa çıkacaktı."},{"n":38,"t":"İnanan adam dedi ki, \"Ey halkım, beni izleyin ki size doğru yolu göstereyim.\"*89 * 40:28-39 Bu onbir ayetin zamanımızda ilginç bir tecellisi var."},{"n":39,"t":"\"Ey halkım, bu dünya hayatı geçici bir geçinmedir. Ahiret yurdu ise ebedi bir duraktır.\" En Verimli İş"},{"n":40,"t":"Kim kötülük işlerse kendisine ancak onun kadar bir ceza verilir. Erkek veya kadın kim inançlı olarak erdemli işler yaparsa onlar cennete girerler ve orada hesapsız olarak nimetlenirler. İnanmış Adamın Halkı İle Tartışması"},{"n":41,"t":"\"Ey halkım, neden ben sizi kurtuluşa çağırırken siz beni ateşe çağırıyorsunuz?\""},{"n":42,"t":"\"Siz beni ALLAH'a karşı nankör olmaya ve hakkında bilgim olmayan şeyleri ona ortak koşmaya çağırıyorsunuz. Bense sizi O Üstün ve Bağışlayıcı olana çağırıyorum.\""},{"n":43,"t":"\"Kuşku yok ki, beni kendisine çağırdığınız şeyin ne dünyada ne de ahirette bir dayanağı yoktur. Dönüşümüz ALLAH'adır. Sınırı aşanlar, cehennemi boylayacaktır.\""},{"n":44,"t":"\"Size bu söylediklerimi ileride hatırlayacaksınız. Ben işimi ALLAH'a bırakıyorum. ALLAH kullarını Görendir.\" Sürekli Bir Kabus"},{"n":45,"t":"ALLAH onu onların planladıkları kötülüklerden korudu. Firavun'un taraftarlarını azabın en kötüsü kuşattı."},{"n":46,"t":"Onlara gündüz ve akşam ateş sunulur. Dünyanın son gününde ise: \"Firavun'un taraftarlarını azabın en çetinine sokun.\""},{"n":47,"t":"Ateşte tartışırlarken, güçsüzler, büyüklük taslamış olanlara, \"Biz sizin izleyicileriniz idik, öyleyse bu ateşin bir parçasını olsun bizden savabilir misiniz?\" derler."},{"n":48,"t":"Büyüklük taslamış olanlar, \"Hepimiz onun içindeyiz. ALLAH kulları arasında artık hüküm vermiştir,\" derler. Çok Geç"},{"n":49,"t":"Ateştekiler, cehennemin gardiyanlarına, \"Rabbinize yalvarın da bizden azabı hiç değilse bir gün hafifletsin,\" derler."},{"n":50,"t":"Onlar da derler ki, \"Elçileriniz size apaçık delillerle gelmemiş miydi?\" \"Evet\" derler. Bunun üzerine onlar, \"Öyleyse kendiniz yalvarın. Ne var ki inkarcıların yalvarması sonuç vermez.\" Garantili Zafer"},{"n":51,"t":"Biz elçilerimize ve inananlara bu dünya hayatında ve tanıkların duruşmalarda bulunacakları günde yardım ederiz."},{"n":52,"t":"O gün zalimlere özürleri bir yarar sağlamaz. Onlar laneti ve en kötü sonu hakkederler."},{"n":53,"t":"Biz Musa'ya hidayeti verdik ve İsrailoğullarını kitaba varis kıldık."},{"n":54,"t":"Anlayış sahiplerine bir yol gösterici ve bir uyarı olarak."},{"n":55,"t":"Öyleyse sabret. Çünkü ALLAH'ın sözü gerçektir. Günahların için de bağışlanma iste ve Rabbini akşam sabah överek yücelt."},{"n":56,"t":"Hiç bir delile sahip olmadan ALLAH'ın ayet ve mucizelerine karşı tartışanların göğüslerinde, erişemiyecekleri bir büyüklenme vardır. Öyleyse ALLAH'a sığın. O İşitendir, Görendir."},{"n":57,"t":"Göklerin ve yerin yaratılışı, insanın yaratılışından daha büyük bir şeydir. Ne var ki halkın çoğu bilmez."},{"n":58,"t":"Kör ile gören bir olmaz. İnanıp erdemli davrananlarla kötülük işleyenler de bir olmaz. Ne kadar az düşünürsünüz."},{"n":59,"t":"Dünyanın sonu (Saat) elbette gelecektir, bunda kuşku olmasın. Ne var ki insanların çoğu inanmaz. Yalvarış: Bir İbadet Biçimi"},{"n":60,"t":"Rabbiniz der ki, \"Bana yalvarın size cevap vereyim.\" Büyüklük taslayarak bana kulluk etmekten kaçınanlar aşağılanarak cehenneme gireceklerdir. * 40:60 Maddi konfor dahil herhangi bir şey için Tanrı'ya yalvarmak bir ibadettir. Bundan dolayı her türlü ihtiyacımız için Tanrı'ya yalvarmamız emredilmiştir."},{"n":61,"t":"ALLAH, geceyi dinlenmeniz için yaratan ve gündüzü de aydınlık yapandır. ALLAH halka karşı büyük lütuf sahibidir, fakat halkın çoğu şükretmez."},{"n":62,"t":"İşte Rabbiniz ALLAH, her şeyin Yaratıcısıdır; O'ndan başka tanrı yoktur. Nasıl da çevriliyorsunuz? 63. ALLAH'ın ayet ve mucizelerini red edenler işte böyle saptırılırlar."},{"n":64,"t":"ALLAH yeryüzünü sizin için bir yerleşim ve göğü de bir yapı kılandır. Sizi biçimlendirip biçiminizi güzel yapan ve sizi besinli gıdalarla besleyendir. Rabbiniz olan ALLAH budur. Evrenin Rabbi olan ALLAH ne yücedir! * 40:64 Bak 15:20; 20:54 ve 35:12-13. Ayrıca bak 4:119."},{"n":65,"t":"O, Diridir; O'ndan başka tanrı yoktur. Dini sadece O'na ait kılarak O'nu çağırın. Evrenin Rabbi ALLAH'a övgüler olsun. * 40:65 Bak 39:11. Muhammed, Peygamber Olmadan Önce Putlara Tapıyordu"},{"n":66,"t":"De ki, \"Bana açık deliller geldikten sonra, ALLAH'ın yanında yalvardıklarınıza tapmaktan menedildim ve evrenin Rabbine teslim olmakla emrolundum.\" * 40:66 Bak 93:7."},{"n":67,"t":"O ki sizi topraktan, sonra bir damladan, sonra asılı duran bir embriyodan yaratmıştır. Olgunlaşmanız ve ihtiyarlamanız için daha sonra sizi çocuk olarak dışarı çıkarır. Sizden bazılarının canı daha erken alınır. Daha önce belirlenmiş yaşa ulaşırsınız ki kavrayasınız."},{"n":68,"t":"Dirilten ve öldüren O'dur. Herhangi bir işi diledi mi, ona \"Ol\" der, o da oluverir. Tanrı'nın Ayet ve Mucizelerini Reddedenler"},{"n":69,"t":"ALLAH'ın ayet ve mucizelerine karşı mücadele edenlerin nasıl da çevrildiklerini görmez misin?"},{"n":70,"t":"Onlar, kitabı ve elçilerimiz yoluyla gönderdiğimiz mesajı yalanladılar. İleride bilecekler."},{"n":71,"t":"Boyunlarında prangalar ve zincirlerle sürüklenecekler."},{"n":72,"t":"Kaynar suda, sonra ateşte yakılacaklardır. * 40:72 Kendilerini hazırlamayanlar Yargı Gününde Tanrı'nın huzurunda alabildiğine acı çekeceklerdir. Nefislerini yeterli derecede beslememiş olduklarından Tanrı'nın enerjisine dayanamıyacaklardır. Bak 89:22-23."},{"n":73,"t":"Sonra onlara şöyle denir, \"Nerde ortak koştuklarınız,\""},{"n":74,"t":"\"ALLAH'ın yanında?\" Onlar da derler ki, \"Bizi terkettiler. Meğer biz daha önce hiç bir şeye yalvarmıyormuşuz.\" ALLAH inkarcıları işte böyle saptırır."},{"n":75,"t":"Çünkü siz yeryüzünde gerçeğe dayanmadan seviniyor ve şımarıyordunuz."},{"n":76,"t":"Sürekli kalmak üzere cehennemin kapılarından giriniz. Büyüklük taslayanların yeri ne de kötüdür."},{"n":77,"t":"Öyleyse sabret; ALLAH'ın sözü gerçektir. Onlara söz verdiğimiz (cezalandırmanın) bir kısmını sana göstersek de, ondan önce hayatına son versek de, onlar bize döndürüleceklerdir. Matematiksel Mucize Tanrı'nın İzniyle Verildi"},{"n":78,"t":"Senden önce göndermiş bulunduğumuz elçilerin bir kısmından sana söz ettik, bir kısmını da sana anlatmadık. Hiç bir elçi, ALLAH'ın izni olmadan bir mucize getiremez. ALLAH'ın emri gelince gerçeğe göre yargı verilir ve yanlışı savunanlar orada hüsrana uğrarlar.*90 * 40:78 İnkarcıların Kuran'ı kavrayamıyacaklarını 17:45-46; 18:57 ve 56:79 ayetlerinden öğreniyoruz. Sadece inananlar ve objektif araştırmacılar Kuran'ı anlamaya yetkilendirilmişlerdir. Büyük mucizelerden biri olan Kuran'ın matematiksel sistemi (74:30-35), bir elçi yoluyla iletildi."},{"n":79,"t":"Binesiniz ve onlardan yiyesiniz diye çiftlik hayvanlarını sizin için yaratan ALLAH'tır."},{"n":80,"t":"Sizin için onlarda çeşitli yararlar vardır. Gönlünüz dilediği gibi onlardan yararlanırsınız. Onlarla ve gemilerle taşınırsınız."},{"n":81,"t":"Size işaretlerini gösterir. ALLAH'ın hangi işaretini inkar ediyorsunuz?"},{"n":82,"t":"Kendilerinden öncekilerin sonunun nasıl olduğuna bakmak için yeryüzünü dolaşmazlar mı? Onlardan sayıca daha çok, daha güçlü olup yeryüzünde daha çok üretimde bulunmuşlardı. Ancak, kazandıkları şeyler kendilerini kurtaramadı."},{"n":83,"t":"Elçileri apaçık kanıtlarla kendilerine vardıklarında, yanlarındaki bilgiyle gururlandılar. Alaya aldıkları şey kendilerini sarıverdi. Tanrı'nın Sünneti"},{"n":84,"t":"Nihayet cezamızı gördüklerinde, \"Artık SADECE ALLAH'a inandık ve ortak koşmuş olduklarımızı inkar ettik,\" derler-"},{"n":85,"t":"Azabımızı gördüklerinde inanmaları kendilerine bir yarar sağlamaz. Bu, daha önceki kulları hakkında sürekli uygulanan ALLAH'ın sünneti (yasası) dır. İşte o zaman inkarcılar hüsrana uğramışlardır."}]},{"id":41,"name":"AÇIKLANMIŞ (FUSSİLET) SÛRESİ","verses":[{"n":1,"t":"HH. M."},{"n":2,"t":"Rahman ve Rahim'den bir indirilmiştir."},{"n":3,"t":"Bilen bir topluluk için, Arapça bir Kuran olarak ayetleri açıklanmış bir kitaptır. * 41:3 Bak 43:3 ve 11:1."},{"n":4,"t":"Bir müjdeci ve bir uyarıcıdır. Ancak onların çoğunluğu ondan yüz çevirmiştir; onlar işitmezler."},{"n":5,"t":"Dediler ki: \"Senin bizi çağırdığın şeye karşı sabit fikirliyiz, kulaklarımızda ağırlık ve bizimle sizin aranızda bir perde vardır. İstediğini yap, biz de yapacağız."},{"n":6,"t":"De ki, \"Ben, sadece sizin gibi bir insanım. Bana, sizin tanrınızın bir tek tanrı olduğu vahyediliyor. O'na yönelin, O'ndan bağışlanma dileyin. Vay ortak koşanlara!\""},{"n":7,"t":"\"Ki zekatı vermezler ve onlar ahireti de inkar ederler.\""},{"n":8,"t":"İnanıp erdemli davrananlar için sürekli bir ödül vardır. Kozmoloji ve Ekoloji"},{"n":9,"t":"De ki, \"Siz yeri iki günde yaratanı mı inkar ediyorsunuz ve O'na eşler mi koşuyorsunuz? O, evrenlerin Rabbidir.\" * 41:9-10 Yaratılışın \"günleri\" zaman dilimlerini simgeler. Kuran'a göre zaman göreli bir boyuttur (32:5; 70:4). Yeryüzünün yaratılışı iki birim zaman alırken, içindeki yaratıklar için gerekli tüm besinlerin ve koşulların düzenlenmesi ise dört birim zaman almıştır. Bu oranlama, yeryüzündeki ekolojik sistemin önemini vurgular."},{"n":10,"t":"Onun üstüne denge unsurları (olan dağlar) yerleştirdi ve onu bereketli kıldı.Tüm arayıp isteyenler için onun gıdalarını dört günde ölçüp düzenledi.*"},{"n":11,"t":"Sonra duman halindeki göğe yönelerek ona ve yere, \"İsteyerek veya istemeyerek (kaostan çıkıp) gelin,\" dedi. Onlar da, \"İsteyerek geldik,\" dediler. * 41:11 Tüm galaksiler ve içindekiler, Tanrı'nın koymuş olduğu fiziksel yasalara uyan müslümanlardır."},{"n":12,"t":"Böylece onları iki günde yedi gök olarak tamamladı ve her göğe özel yasaları bildirdi. Ve biz en aşağıdaki göğü ise lambalarla ve koruma sistemiyle donattık. Bu, Üstün ve herşeyi Bilen'in planıdır. Uyarı"},{"n":13,"t":"Yüz çevirirlerse de ki, \"Sizi Ad ve Semud yıldırımına benzer bir yıldırımla uyardım.\""},{"n":14,"t":"Onlara, \"ALLAH'tan başkasına tapmayın,\" diye önlerinden ve arkalarından elçiler gitmişti. Onlar ise, \"Rabbimiz dileseydi bir melek indirebilirdi. Bundan ötürü sizin getirdiğiniz mesaja inanmıyoruz,\" dediler."},{"n":15,"t":"Ad'a gelince, onlar yeryüzünde haksız yere büyüklük tasladılar ve \"Bizden daha güçlü kim var?\" dediler. Kendilerini yaratan ALLAH'ın onlardan daha güçlü olduğunu anlamadılar mı? Onlar ayet ve mucizelerimizi bilerek inkar ediyorlardı."},{"n":16,"t":"Nihayet, onlara dünya hayatında aşağılayıcı azabı tattırmak için uğursuz günlerde üzerlerine sert bir rüzgar gönderdik. Ahiret azabı ise daha aşağılayıcıdır ve onlar yardım görmezler."},{"n":17,"t":"Semud'a gelince, onlara yolu gösterdik. Ne var ki onlar körlüğü hidayete tercih ettiler. Sonunda, kazandıklarına karşılık, onları alçaltıcı azabın yıldırımı yakaladı."},{"n":18,"t":"İnananları ve erdemli davrananları ise kurtardık."},{"n":19,"t":"ALLAH düşmanlarının ateşe sürüklenerek toplatılacakları gün..."},{"n":20,"t":"Nihayet oraya vardıklarında, onların işitme, görme organları ve derileri yaptıkları hakkında tanıklık eder. Poligraf Yahut Video Kaydı"},{"n":21,"t":"Derilerine, \"Niçin bize karşı tanıklık ettiniz?\" diye sorarlar. Onlar da, \"Her şeyi konuşturan ALLAH bizi konuşturdu. Sizi ilk yaratan O'dur ve işte O'na döndürülüyorsunuz,\" derler."},{"n":22,"t":"Ne işitme ve görme organlarınızın, ne de derilerinizin aleyhinizdeki tanıklığını gizlemeye gücünüz yetmez. Buna rağmen siz yaptıklarınızın çoğunu ALLAH'ın bilemiyeceğini sanıyordunuz."},{"n":23,"t":"Rabbiniz hakkında bu düşünceniz sizi kaydırdı ve kaybedenlerden oldunuz."},{"n":24,"t":"Dayanırlarsa yerleri ateştir. Yok, hoş görülmek isterlerse özürleri kabul edilmeyecektir."},{"n":25,"t":"Geçmişlerini ve geleceklerini onlara güzel gösteren birtakım arkadaşları onlara atadık. Kendilerinden önce gelip geçmiş cin ve insan toplumları için gerçekleşen o söz kendileri için de geçerli oldu. Onlar kaybetmişlerdi. İnkarcılar Kuran'ı Anlamaya Çalışanlara Engel Olurlar"},{"n":26,"t":"İnkar edenler, \"Başa çıkmanız için, bu Kuran'ı dinlemeyin, anlaşılmasını engelleyin,\" dediler."},{"n":27,"t":"İnkar edenlere şiddetli bir azabı tattıracağız ve yaptıklarının en kötüsüyle onlara karşılık vereceğiz."},{"n":28,"t":"ALLAH düşmanlarının cezası işte bu ateştir. Ayetlerimizi bile bile inkar etmelerinin bir karşılığı olarak orası onların ebedi yurdu olacaktır. YargıGününde"},{"n":29,"t":"İnkar edenler, \"Rabbimiz, cinlerden ve insanlardan bizi saptıranları bize göster, onları ayaklarımızın altına alalım da en alçak olanlardan olsunlar,\" derler. Tam Mutluluk: Şimdiden Sonsuza Kadar"},{"n":30,"t":"\"Rabbimiz ALLAH'tır,\" dedikten sonra doğru yolu izleyenlerin üzerine melekler iner:\"Korkmayın, üzülmeyin ve davetli olduğunuz cennetle sevinin.\""},{"n":31,"t":"\"Dünya hayatında da, ahirette de sizin dostlarınız biziz. Orada canınızın çektiği ve istediğiniz her şey vardır.\""},{"n":32,"t":"\"Bağışlayan ve Rahim olandan bir ağırlama olarak.\" Müslüman Davetçiler"},{"n":33,"t":"ALLAH'a çağıran, erdemli davranan ve \"Ben teslim olanlardanım,\" diyenden daha güzel sözlü kim olabilir?"},{"n":34,"t":"İyilik ile kötülük bir olmaz. Sen en iyi bir biçimde karşılık ver. O zaman, aranızda düşmanlık bulunan kişi belki en iyi dostun oluverir."},{"n":35,"t":"Bu duruma ancak dirençli olanlar eriştirilir. Bu duruma ancak alabildiğine şanslı olanlar ulaştırılır."},{"n":36,"t":"Şeytandan herhangi bir düşünce seni etkisi altına alırsa ALLAH'a sığın. O İşitendir, Bilendir. Tanrı'nın İşaretleri"},{"n":37,"t":"Gece, gündüz, güneş ve ay O'nun ayetlerindendir. Güneşe ve ay'a secde etmeyin, onları yaratan ALLAH'a secde edin. O'na kulluk edecekseniz."},{"n":38,"t":"Büyüklenirlerse, Rabbinin yanındakiler hiç yorulmadan gece gündüz O'nu yüceltirler."},{"n":39,"t":"Kupkuru gördüğün toprağın üzerine su yağdırdığımızda onun titreşip kabarması da O'nun ayetlerindendir. Onu dirilten ölüleri de diriltir. O, herşeye gücü yetendir. Ayetleri Çarpıtanlar"},{"n":40,"t":"Ayetlerimiz konusunda çarpıtmalar yapanlar bizden gizli kalmaz. Ateşe atılan mı, yoksa diriliş gününde güven içinde bize gelen mi daha iyidir? Dilediğiniz gibi davranın. O, yaptıklarınızı elbette Görendir. * 41:40 Müşriklerin Kuran'da tahrifat yapmağa çalışacaklarını bilen Yüce Tanrı, Kuran'ın mükemmel korunmasından söz ettiği ayetlerden önce, tahrifatçılara uyarıda bulunmaktadır. Kuran'ın Korunma Sistemi ve Misakın Elçisi"},{"n":41,"t":"Kendilerine mesaj ulaştıktan sonra onu inkar edenler bilsin ki o üstün bir kitaptır. * 41:41 \"Zikir (mesaj)\" Kuran'ın bir ismi olup, Kuran'ın matematiksel kodu için de kullanılır. Bak 38:1-8 ve 74:30-31."},{"n":42,"t":"Batıl, onun ne önündenne de ardından yaklaşamaz. Bilge ve övgüye layık olanın indirdiği bir vahiydir. * 41:41-42 Kuran, müşriklerin kağıtlarında değil, bilgi sahiplerinin kalbindedir (29:49). Mesajı insanlar değil, Allah korumaktadır (15:9). Kuran'ın olağanüstü matematiksel kompozisyonu, Kuran'ın herhangi bir elementinde herhangi bir ekleme, çıkarma veya tahrifat yapılması halinde ortaya çıkarılıp reddedileceğini garantilemektedir. Muhammed peygamberi putlaştıranların iki hadis ekleme girişimleri başarısızlığa uğramıştır. Yirmi dört ayar altın bir yüzüğe yapıştırılan sarının altın olmadığı altının atom özelliği tarafından sürekli olarak ilan edilir ve reddedilir. Altın yüzük gibi Kuran da yapısındaki matematiksel sistemle sürekli olarak orijinal olarak vardı ve orijinal olarak var olmaya devam edecektir. Kodlanmış olan Kuran'a ekleme veya çıkarma yapmaya hiç kimsenin gücü yetmez. Bak 9:127."},{"n":43,"t":"Senin için söylenilenler, senden önceki elçiler için söylenilenlerin aynısıdır. Kuşkusuz senin Rabbin hem bağışlanma sahibi, hem de acı azap sahibidir. Kuran'ı Anlamakta Dil Konudışıdır"},{"n":44,"t":"Onu yabancı dilde bir Kuran kılsaydık, \"Onun ayetleri açıklanmalı değil miydi?\" diyeceklerdi. İster yabancı dil, ister Arapça olsun, de ki, \"O, inananlar için (dilleri sözkonusu olmaksızın) bir rehber ve şifadır. İnanmıyanların ise kulaklarında ağırlık vardır. Onlara sanki uzak bir yerden sesleniliyor gibi onlara kapalıdır.\" * 41:44 Kuran tüm dünya dillerine çevrilmelidir (26:198-200). İnananlar, doğru çeviri ile yanlış çeviri arasındaki farkı, Tanrı vergisi akıllarını kullanarak, karşılaştırıp tartışarak rahatlıkla görebilirler. Kuran'ın asıl öğretmeni Tanrı'dır (55:1-2). Bak 43:3; 11:1."},{"n":45,"t":"Biz Musa'ya kitabı (İbranice) verdik, onda da anlaşmazlığa düştüler. Rabbinin vermiş olduğu bir söz olmasaydıaralarında yargı verilirdi. Gerçekten onlar ondan kuşku ve şüphe içindedirler."},{"n":46,"t":"Kim erdemli davranırsa kendi yararınadır. Kim kötü davranırsa kendi zararınadır. Rabbin, kullara zulmetmez. Kendilerine Tapanları Reddederler"},{"n":47,"t":"Saatın (dünyanın sonunun) bilgisi O'nun katındadır. O'nun bilgisi olmadan ne meyveler kabuklarından çıkabilir, ne de bir dişi gebe kalır veya doğum yapar. \"Hani benim ortaklarım nerede?\" diye onlara seslendiği gün, onlar: \"Hiçbirimizin buna şahitlik etmediğini sana arzederiz,\" derler.* * 41:47 Bak 20:15; 15:87; 31:34. ** 41:47 Bak 3:18; 39:45; 63:1 ve 6:23, 148."},{"n":48,"t":"Daha önce yardım için çağırdıkları (dine ortak koştukları kişiler) onlardan uzaklaşmıştır. Artık kaçacak bir yerleri olmadığını anlarlar. İyi Gün veya Kötü Gün Dostları"},{"n":49,"t":"İnsan, iyilik istemekten bıkmaz. Ancak kendisine bir kötülük dokunduğunda umutsuzdur, kötümserdir."},{"n":50,"t":"Sıkıntısının ardından, kendisine bizden bir rahmet tattırsak, \"Bu bana aittir. Dünyanın sonunun da geleceğini sanmam. Rabbime döndürülürsem de O'nun katında benim için daha güzel şeyler vardır,\" der. İnkarcılara, yapmış olduklarının gerçek niteliğini elbette haber vereceğiz. Çetin bir azaptan tattıracağız onlara."},{"n":51,"t":"İnsana bir nimet verdik mi, yüz çevirip yan çizer. Başına bir kötülük geldiğinde ise yalvarıp durur. Gerçekleşmekte Olan Söz"},{"n":52,"t":"De ki, \"Ya o (mesaj) ALLAH'tan idiyse ve siz de onu yalanlamış iseniz? Buna karşı kesin bir tavır alandan daha sapık kim olabilir?"},{"n":53,"t":"Onun gerçek olduğu onlara apaçık oluncaya kadar onlara, ufuklarda ve kendi içlerinde ayetlerimizi (işaret ve kanıtlarımızı)göstereceğiz. Rabbinin her şeye tanık olması yetmez mi? * 41:53 Yanlışlanabilir ve Sınanabilir fiziksel deliller Kuran'ın Tanrı sözü olduğuna dair bilimsel deliller ve belgeler sağlar. 4:82; 74:30."},{"n":54,"t":"Aslında onlar Rab'lerinden bir kuşku içindedirler. O, her şeyi (bilgi ve yönetimiyle) kuşatmıştır."}]},{"id":42,"name":"DANIŞMA (ŞURA) SÛRESİ","verses":[{"n":1,"t":"HH. M."},{"n":2,"t":"'A. S. Q.*"},{"n":3,"t":"Üstün ve Bilge olan ALLAH sana ve senden öncekilere böyle vahyeder."},{"n":4,"t":"Göklerde, yerde ne varsa O'nundur. O Yücedir, Büyüktür."},{"n":5,"t":"Gökler (O'na olan saygıdan ötürü) nerdeyse üstlerinden çatlayacak. Melekler Rab'lerini överek yüceltirler ve yeryüzündekiler için bağışlanma dilerler. ALLAH kesinlikle Bağışlayandır, Rahimdir."},{"n":6,"t":"O'ndan başkasını veliler edinenleri ALLAH kollamaktadır. Sen onların avukatı değilsin."},{"n":7,"t":"Başkent ve çevresini uyarman için ve gerçekleşecek olan Toplanma Gününe karşı uyarman için biz kusursuz bir dile sahip olan bir Kuran'ı böylece sana vahyediyoruz. Onlardan bir kısmı cennete, bir kısmı da cehenneme girecektir. * 42:7 Bak 43:3."},{"n":8,"t":"ALLAH dileseydi onları bir tek toplum kılardı. Ancak O, dilediğini rahmetine sokar. Zalimlerin bir sahibi ve yardımcısı yoktur."},{"n":9,"t":"O'nun dışında veliler (sahipler) mi edindiler? Biricik veli ALLAH'tır, ölüleri O diriltir ve O herşeye Kadirdir. * 42:9 Din adamlarını putlaştıranlar (9:31; 42:21), özellikle Pakistan ve Hindistan'daki din adamlarını \"Mevlana\" yani \"velimiz, sahibimiz\" diye çağırmakta ve din adamları da bunu dini bir ünvan olarak kabul etmektedirler. Bak 2:286."},{"n":10,"t":"Bu mesajın her hangi bir bölümünde anlaşmazlığa düşerseniz hüküm ALLAH'a aittir. Rabbim ALLAH işte böyledir. Ben O'na güvendim ve O'na yönelirim."},{"n":11,"t":"O gökleri ve yeri yararak yaratandır. İçinizden sizin için eşler yarattı ve çiftlik hayvanlarını da çiftler halinde yarattı. Böylece sizi orada üretiyor. O'na benzer hiç bir şey yoktur. O, İşitendir, Görendir."},{"n":12,"t":"Göklerin ve yerin tüm kontrolu O'na aittir. Dilediğine rızkı bol verir veya kısar. O her şeyi Bilendir. Sadece Bir Tek Din: Monoteism"},{"n":13,"t":"Daha önce Nuh'a buyurduğu dini size yasa olarak belirledik. Sana vahyettiğimiz gibi İbrahim'e, Musa'ya ve İsa'ya da öğütledik: \"Bu dini doğru tutun ve onda ayrılığa düşmeyin.\" Fakat kendilerini çağırdığın şey, ortak koşanlara ağır gelmektedir. ALLAH dileyeni kendine seçer ve kendisine yöneleni doğruya ulaştırır."},{"n":14,"t":"Kendilerine bilgi ulaştıktan sonra sırf aralarındaki çekememezlik yüzünden ayrılığa düştüler. Belli bir zaman için Rabbinin verilmiş bir söz olmasaydı onların arasında hemen hüküm verilirdi. Onlardan sonra kitaba mirasçı olanlar da ondan kuşku ve şüphe içindedirler. Hıristiyan ve Yahudilere Mesaj"},{"n":15,"t":"Sen buna çağır ve sana emredildiğin gibi dosdoğru uygula. Onların arzularına uyma ve de ki \"ALLAH'ın bana indirdiği kitaba inandım. Sizin aranızda adaletle davranmakla emrolundum. ALLAH bizim de Rabbimiz, sizin de Rabbinizdir. Bizim işlediklerimiz bize, sizin işledikleriniz ise sizedir. Bizimle sizin aranızda herhangi bir tartışma yoktur. Bizi ALLAH biraraya getirecektir. Sonunda dönüş O'nadır."},{"n":16,"t":"ALLAH hakkında, O'nun çağrısına yanıt verildikten sonra tartışanların delilleri Rab'leri katında geçersizdir. Gazabı haketmişlerdir ve onlara çetin bir azap vardır."},{"n":17,"t":"O ALLAH ki kitabı gerçek ve adaletle indirmiştir. Ne bilirsin, belki Saat (dünyanın sonu) yakındır."},{"n":18,"t":"Ona inanmıyanlar onun hakkında meydan okuyorlar. Ona inananlar ise ondan kaygı duyarlar ve onun gerçek olduğunu bilirler. Saat konusunda kuşku duyanlar büyük bir sapıklık içindedirler."},{"n":19,"t":"ALLAH kullarına lütfedendir. Dilediğini ve/veya dileyeni rızıklandırır. O Güçlüdür, Üstündür."},{"n":20,"t":"Kim ahiret ödülünü isterse onun ödülünü arttırırız. Dünya ödülünü isteyene de onu veririz; ancak onun ahiretten bir payı olmaz. Din ve Şeriat Uyduranlar"},{"n":21,"t":"Yoksa ALLAH'ın izni olmadığı halde onlar için dini kurallar ve yasalar ortaya koyan ortakları mı var? Daha önce belirlenmiş bir karar olmasaydı onların arasında yargı verilirdi. Zalimlere acı bir azap vardır.*91 * 42:21 Günümüz \"Müslümanlarının\" bildiği ve uygulamaya çalıştığı İslam, yüzyıllar boyu, din adamlarının uydurdukları kurallarla öylesine bozulmuştur ki Muhammed'in bildirdiği islam diniyle ilgisi kalmamıştır. \"Ulema\" geçinen din adamları, o kadar çok şeriatlar, haramlar, çarşaflar, peçeler, gıdasal yasaklar, sakallar, sarıklar, istincalar, istibralar, misvaklar, sağ ayaklar, sol ayaklar, hadisler, sünnetler, şefaatler, hazretler, efendiler, kerametler, melanetler, evliyalar, şerifler, seyyitler, hırka-i şerifler, kıl-ı şerifler, takiyyeler, takkeler, tespihler, tekkeler, mezhepler, tarikatlar, şatahatlar, muskalar, istihareler, hülleler, hileler, türbeler, nafileler, mekruhlar, menduplar, sevaplar, müstehaplar, fetvalar ve palavralar uydurmuşlardır ki İslam dinini yaşanması felaket getiren bir şirk dine çevirmişlerdir. Müslüman halkların dünyanın bu kadar gerisinde kalmalarının en önemli sorumluları bu müşrik dinadamları ve onları kullanan politikacılardır. Tanrı bu durumu düzeltmek ve mesajını hurafe ve bidatlerden arındırmak için \"büyüklerden biri\" diye nitelediği mesajı gönderdi bize (74:30-35). Bak 9:31; 33:67."},{"n":22,"t":"Yaptıkları işler başlarına gelirken zalimleri kaygı içinde görürsün. İnanıp erdemli davrananlar cennetlerin bahçelerindedir. Rableri katında diledikleri her şeyi alırlar. İşte bu, büyük lütuftur."},{"n":23,"t":"ALLAH, inanıp erdemli davranan kullarını böyle müjdeler. De ki \"Ben sizden, akrabalık sevgisi dışında herhangi bir ücret istemiyorum.\" Kim bir iyilik işlerse onun iyilğini arttırırız. ALLAH Bağışlayandır, takdir edendir. * 42:23 Herkesin kendi akrabalarını gözetmesini öğütleyen bu ayeti çarpıtıp, Muhammed peygamberin akrabalarına özgü kılanlar; ehl-i beyt, seyyidler ve şerifler diye Hindu Brahmanlar gibi imtiyazlı bir asalak sınıf oluşturmuşlardır. Bak 33:33 Tanrı Yanlışı Siler ve Doğruyu Yerleştirir"},{"n":24,"t":"Onlar, \"O ALLAH hakkında yalan mı uydurdu.\" mu diyorlar? ALLAH dilese senin kalbini mühürler. ALLAH yanlışı siler ve sözleriyle gerçeği yerleştirir. O en gizli düşünceleri bilir."},{"n":25,"t":"O, kullarından tevbeleri kabul eder, günahları affeder ve yaptıklarınızı bilir."},{"n":26,"t":"İnanıp erdemli davrananların çağrısına cevap verir ve onlara lütfunu arttırır. İnkarcılar ise çetin bir cezayı hakketmiştir."},{"n":27,"t":"ALLAH kullarına rızkı bollaştırsaydı, yeryüzünde azacaklardı. Nitekim dilediği ölçüde gönderir. O, kullarından Haberdardır, Görendir."},{"n":28,"t":"Umutlarını kesmelerinden sonra yağmuru indiren ve rahmetini yayandır. O, Övgüye Layık bir Dosttur."},{"n":29,"t":"Gökleri ve yeri yaratıp onlarda çeşitli yaratıklar yayması O'nun ayetlerindendir. O, dilediği zaman onları toplayabilir."},{"n":30,"t":"Size dokunan bir kötülük, işlediklerinizin bir sonucudur. O, bir çoğunu da affeder."},{"n":31,"t":"Siz yeryüzünde kaçamazsınız. Sizin ALLAH 'tan başka bir sahibiniz ve yardımcınız yoktur."},{"n":32,"t":"Okyanusta dağlar gibi akıp giden gemiler de O'nun ayetlerindendir."},{"n":33,"t":"Dilerse rüzgarı durdurur ve onlar suyun üzerinde hareketsiz kalırdı. Bunda, her sabreden ve şükreden kişi için ibretler vardır."},{"n":34,"t":"Yahut, yaptıkları yüzünden onları yok eder. Bunun yerine bir çoğunu da bağışlar."},{"n":35,"t":"Ayetlerimiz ve mucizelerimiz üzerinde tartışanlar kendilerinin kaçacak bir yeri olmadığını bilirler."},{"n":36,"t":"Size ne verildiyse dünya hayatının geçimliğidir. Ancak inananlar ve Rab'lerine güvenenler için ALLAH'ın yanında bulunanlar daha iyidir ve süreklidir. İnananların Özellikleri"},{"n":37,"t":"Onlar ki büyük günahlardan çirkin işlerden kaçınırlar ve kızdıkları zaman bağışlarlar."},{"n":38,"t":"Onlar, Rab'lerinin çağrısına karşılık verirler, namazı gözetirler, işlerini aralarında danışma ile kararlaştırırlar ve kendilerine verdiğimiz rızıklardan yardım için verirler. * 42:38 En önemli işlerden biri başkan/lider seçimidir. Son peygamberin vefatından otuz yıl kadar sonra müşrikler, seçim yerine babadan oğula geçen şeytani bir halifeliği Tanrı adına egemen kıldılar. 1923 yılına kadar süren bu şeytani hilafet süresince sayısız zulüm ve cehalet Tanrı adına işlendi. Güçlerin ayırımı ilkesiyle uygulanan bir demokrasi, bazı zaaflarına rağmen şu ana kadar öğrendiğimiz en elverişli bir danışma sistemidir. Federal sistemler farklı hukuk, din ve kültürlere sahip toplumların ve etnik azınlıkların bir arada barış ve dayanışma içinde özgürce yaşamalarını mümkün kılmaktadır."},{"n":39,"t":"Haksızlığa uğradıklarında kendilerini savunurlar."},{"n":40,"t":"Kötülüğün cezası, benzeri bir kötülüktür; ancak kim affeder ve erdemli davranırsa ALLAH tarafından ödüllendirilir. O, zalimleri sevmez."},{"n":41,"t":"Haksızlığa uğradıktan sonra hakları için direnenler kınanmazlar, cezalandırılmazlar."},{"n":42,"t":"Ancak, halka zulmedenlere ve yeryüzünde haksız yere saldıranlara karşı durulmalıdır. Onlara acı bir azap vardır."},{"n":43,"t":"Saberedip bağışlamak, sağlam bir karakteri gösterir."},{"n":44,"t":"ALLAH kimi saptırmışsa, artık O'ndan sonra onun bir koruyucusu yoktur. Azabı gördüklerinde, zalimlerin, \"Bizim için bir şans daha yok mu?\" dediklerini görürsün."},{"n":45,"t":"Aşağılanmış ve başları eğilmiş olarak ateşe sunulurlarken göz ucuyla çevrelerine bakındıklarını görürsün. İnananlar, \"Gerçek kaybedenler, Diriliş Gününde kendilerini ve ailelerini kaybedenlerdir. Zalimler sürekli bir azaba mahkum olmuştur,\" derler."},{"n":46,"t":"Onların, ALLAH'tan başka kendilerine yardım edecek bir dostları yoktur. ALLAH'ın saptırdığı kimse için bir yol bulunmaz."},{"n":47,"t":"ALLAH katından, geri çevrilmesi olanaksız olan gün gelmezden önce Rabbinize cevap veriniz. O gün sizin için ne bir sığınak ne de bir koruyucu vardır."},{"n":48,"t":"Yüz çevririrlerse, biz seni onlara bir bekçi olarak göndermedik. Sana düşen sadece bildirmektir. Biz insana tarafımızdan bir rahmet taddırdığımız zaman onunla sevinir; ama kendi yaptıklarının bir sonucu olarak başlarına bir kötülük gelse, o zaman insan nankörleşir."},{"n":49,"t":"Göklerin ve yerin yönetimi ALLAH'ındır. Dilediğini yaratır. Dilediğine dişiler, dilediğine de erkekler verir."},{"n":50,"t":"Yahut hem erkek hem dişi olarak çift verir. Dilediğini de kısır yapar. O Bilendir, her şeye gücü yetendir. Tanrı Bizimle Nasıl İletişim Kurar"},{"n":51,"t":"ALLAH bir insanla ancak vahiy yoluyla veya bir perde arkasından iletişim kurar, yahut bir elçi gönderip izniyle dilediğini vahyeder. O, Yücedir, Bilgedir."},{"n":52,"t":"Biz böylece sana katımızdan bir ruh vahyettik. Sen kitap nedir iman nedir bilmezdin. Ancak onu, dilediğimiz kulları doğruya ulaştıran bir ışık kıldık. Sen elbette doğru yola kılavuzluk ediyorsun.* * 42:52 Bak 17:85; 15:29. ** 42:52 Muhammed dahil hiçbir insan kimseye kurtuluş için klavuzluk edemez (28:56) ancak, her mümin Tanrı tarafındın belirlenen \"doğru yola\" klavuzluk edebilir. Bir başka deyişle, dini ve hidayeti belirleyen Tanrı olup, bize düşen onun tebliğidir. Muhammed peygamberi ayrı bir hidayet kaynağı haline getirmek şirktir. Bak 6:112-114; 39:11."},{"n":53,"t":"Göklerde ve yerde bulunan herşeyin sahibi ALLAH'ın yoluna... Kesinlikle, tüm işler ALLAH'a döner."}]},{"id":43,"name":"GÖSTERİŞ (ZUHRUF) SÛRESİ","verses":[{"n":1,"t":"HH. M."},{"n":2,"t":"Apaçık kitaba andolsun ki,"},{"n":3,"t":"Anlamanız için onu kusursuz bir dile sahip bir Kuran yaptık. * 43:3 \"Arabiy\" (Arapça) kelimesinin kökü olan A'RB, Arapçada, \"kusursuz, mükemmel\" anlamına gelir. (Örneğin bak 56:37). Kuran'ın mesajı tüm insanlığa gönderildiğinden, Arapça olan orijinal Kuran'ın dilinin anlaşılması onun Arapça oluşundan değil, Arapçasının gerçekten A'RB, yani \"mükemmel\" oluşundan kaynaklanıyor. Bir başka deyişle, bu ayette kastedilen anlam, özel isim olarak Arapça değil, onun kelime anlamıdır. Her Adil adaletli olmayabildiği gibi, her Zeki zeki, her Arap arap (mükemmel) olmayabilir. Aynı şekilde her Arapça metin arapça (mükemmelce) olmayabilir! Kuran'ın dili arapçadır, kusursuzdur, mükemmeldir. Bir Arap peygambere mükemmel bir Arapça ile nazil olan Kuran, Rahman tarafından öğretildiği için (55:2), hangi dille konuşursa konuşsun, tüm insanlık için Tanrısal bir mesajdır, bir elçidir."},{"n":4,"t":"O, ana kitapta (korunur), katımızda üstündür, bilgedir."},{"n":5,"t":"Haddi aşan bir toplumsunuz diye mesajı size iletmekten vaz mı geçelim?"},{"n":6,"t":"Öncekilere nice peygamberler göndermişizdir."},{"n":7,"t":"Fakat, kendilerine giden her peygamberle alay ettiler."},{"n":8,"t":"Şunlardan daha güçlülerini yok ettik. Öncekilerin örneği geçmiştir."},{"n":9,"t":"Onlara, \"Gökleri ve yeri kim yarattı?\" diye sorsan, \"Onları, Üstün ve herşeyi bilen yarattı,\" diyeceklerdir."},{"n":10,"t":"O ki, yeryüzünü oturmanıza elverişli kıldı ve doğru gitmeniz için sizin için orada yollar açtır."},{"n":11,"t":"O ki gökten bir ölçüye göre su indirdi de onunla ölü bir ülkeyi dirilttik. İşte böyle çıkarılırsınız."},{"n":12,"t":"O ki bütün çiftleri yarattı ve binesiniz diye sizin için gemiler ve çiftlik hayvanları yarattı."},{"n":13,"t":"Ki onların üstüne binesiniz ve onlara bindiğiniz zaman Rabbinizin size olan nimetini düşünerek şunları diyesiniz: \"Bunu bizim emrimize veren çok yücedir. Onları kendi başımıza kontrol altına alamazdık.\""},{"n":14,"t":"\"Ve biz, sonunda Rabbimize döneceğiz.\" Kız Çocuklarını Aşağı Gören Müşriklerin Bir Uydurması"},{"n":15,"t":"Kullarından bazılarını O'na bir pay olarak ayırdılar. İnsan gerçekten apaçık bir nankördür."},{"n":16,"t":"Yaratıklarından kızları kendisine ayırdı da oğulları size mi seçti?"},{"n":17,"t":"Onlardan birisi, Rahman'a yakıştırdığı (kız çocuğu) ile müjdelenince, morali bozularak yüzü simsiyah kesilir:"},{"n":18,"t":"\"Süsler içinde yetiştirilmesine rağmen kavgada beceriksiz olan mı!?\""},{"n":19,"t":"Rahman'ın kulları olan melekleri dişi saydılar! Onların yaratılışlarına mı tanık oldular? Bu tanıklıkları kaydedilercek ve sorguya çekileceklerdir."},{"n":20,"t":"Hatta, \"Rahman dileseydi biz onlara tapmazdık,\" dediler. Onların bu konuda bir bilgileri yoktur. Onlar sadece tahminde bulunuyorlar."},{"n":21,"t":"Onlara bundan önce bir kitap mı verdik de ona mı dayanıyorlar? Geçmişi Sorgulamadan İzleme Cehaleti"},{"n":22,"t":"Hayır, \"Biz atalarımızı bir yol üzerinde bulduk ve biz onların öğretilerini izliyoruz,\" dediler."},{"n":23,"t":"Tıpkı bunun gibi, senden önce, bir kente her ne zaman bir uyarıcı gönderdiysek elit tabaka, \"Biz, atalarımızı bir yol üzerinde bulduk ve biz onların öğretilerini izliyoruz,\" derlerdi."},{"n":24,"t":"O da, \"Size, atalarınızı üzerinde bulduğunuzdan daha doğrusunu getirmiş isem de mi?\" derdi. Onlar da, \"Sizin getirdiğiniz mesajı inkar ediyoruz,\" derlerdi."},{"n":25,"t":"Biz de onlardan öc aldık. Yalanlayanların sonu nasıl olduğuna bir bak."},{"n":26,"t":"İbrahim, babasına ve halkına demişti ki, \"Sizin taptıklarınızdan uzağım.\""},{"n":27,"t":"\"Beni Yaratan bana doğru yolu gösterecektir.\""},{"n":28,"t":"Belki doğru yola dönerler diye onun ardından gelecekler için bunu ebedi bir ders kıldı."},{"n":29,"t":"Doğrusu, kendilerine gerçek ve apaçık bir elçi varıncaya kadar şunlara ve atalarına imkan tanıdım."},{"n":30,"t":"Kendilerine gerçek geldiği zaman, \"Bu bir büyüdür ve biz onu inkar ediyoruz,\" dediler. Muhammed Küçümsenip Alaya Alınıyor"},{"n":31,"t":"\"Bu Kuran, şu iki kentten ünlü ve büyük bir adama indirilmeli değil miydi?\" dediler."},{"n":32,"t":"Rabbinin rahmetini onlar mı paylaştırıyorlar? Dünya hayatında onların geçimliklerini aralarında biz paylaştırdık; birbirlerine iş gördürebilmeleri için onları birbirlerine derecelerle üstün kıldık. Rabbinin rahmeti onların biriktirdiklerinden daha iyidir. Dünya Materyali: İnkarcıların Tüm Kazanabilecekleri"},{"n":33,"t":"Tüm insanlar (inkarcılıkta) bir tek toplum olacak olmasaydı, Rahman'ı inkar edenlerin evini gümüş tavanlar ve binip çıkacakları merdivenlerle donatırdık."},{"n":34,"t":"Evlerine kapılar ve konforlu mobilyalar."},{"n":35,"t":"Ve nice gösterişli maddeler. Tüm bunlar bu dünya hayatının geçici materyalidir. Ahiret ise Rabbinin katında erdemlilerindir. Fanatikleşen İnkarcılar Şeytanlarla Dost Olurlar"},{"n":36,"t":"Kim Rahman'ın mesajına aldırış etmezse, ona bir şeytanı sardırırız da onun arkadaşı olur."},{"n":37,"t":"Nitekim onları yoldan çıkarırlar. Buna rağmen onlar doğru yolda olduklarını sanırlar."},{"n":38,"t":"Nihayet bize geldiğinde, \"Keşke benimle senin aranda iki doğu arası kadar uzaklık olsaydı; sen ne kötü bir arkadaş mışsın sen!\" der."},{"n":39,"t":"Haksızlık etmiş olduğunuz için, o gün (pişmanlığınız) size bir yarar sağlamaz; siz cezayı paylaşacaksınız."},{"n":40,"t":"Sen mi sağıra işittireceksin, yahut körü ve apaçık bir sapıklıkta olanı yola getireceksin?"},{"n":41,"t":"Seni alıp götürsek de biz onları cezalandıracağız."},{"n":42,"t":"Yahut, onlara söz verdiğimizi sana gösteririz; bizim onlara gücümüz yeter."},{"n":43,"t":"Sana vahyedilene sarıl; çünkü sen doğru yoldasın."},{"n":44,"t":"Bu, sana ve halkına bir mesajdır; ondan sorulacaksınız."},{"n":45,"t":"Senden önce gönderdiğimiz elçileri araştır: \"Rahman'ın dışında tapılacak tanrılar kabul etmiş miyiz?\""},{"n":46,"t":"Örneğin; Musa'yı ayetlerimizle Firavun'a ve erkanına gönderdik ve \"Ben evrenlerin Rabbinin elçisiyim,\" demişti. Musa ve Firavun"},{"n":47,"t":"Mucizelerimizi kendilerine götürdüğü zaman, o mucizelere gülmüşlerdi."},{"n":48,"t":"Onlara bir birinden büyük mucizeler gösterdik ve belki dönerler diye başlarına çeşitli felaketler getirdik."},{"n":49,"t":"\"Ey büyücü, bizim için Rabbine dua et. Çünkü sen ona daha yakınsın; biz bundan sonra yola geleceğiz,\" dediler."},{"n":50,"t":"Fakat, onlardan felaketi kaldırdığımızda, sözlerinden hemen dönüverdiler."},{"n":51,"t":"Firavun halkına şöyle seslendi: \"Ey halkım, Mısır'ın yönetimi ve şu altımda akıp giden ırmaklar bana ait değil mi? Görmüyor musunuz?\""},{"n":52,"t":"\"Yahut ben, şu aşağılık ve konuşmaktan aciz olan adamdan daha üstün değil miyim?\""},{"n":53,"t":"\"Neden ona altınlardan oluşan bir hazine verilmiyor, yahut neden yanında çalışacak melekler gelmiyor?\""},{"n":54,"t":"Böylece halkını yanılttı ve onlar da ona uydular. Onlar bayağı insanlardı."},{"n":55,"t":"Bizimle savaşmakta israr edince onlardan öc aldık, hepsini boğduk."},{"n":56,"t":"Onları, sonradan gelecekler için bir ibret ve örnek yaptık. Irkçı Tepki"},{"n":57,"t":"Meryemoğlu bir örnek olarak gösterilince senin halkın hemen reddettiler."},{"n":58,"t":"\"Bizim tanrılarımız mı daha iyidir yoksa o mu?\" dediler. Sadece seninle tartışmak için bunu söylediler. Onlar gerçekte, kavgacı bir toplumdur."},{"n":59,"t":"O, kendisine iyilikte bulunduğumuz bir kuldan başka bir şey değildi. Onu İsrailoğullarına bir örnek kıldık."},{"n":60,"t":"Dileseydik sizi, yeryüzünü koloni haline getiren meleklere çevirirdik. İsa'nın Doğumu ve Dünyanın Sonu*"},{"n":61,"t":"O (İsa), Saat hakkında bir bilgi kaynağı ve işarettir. Öyleyse onun (zamanı) hakkında kuşku beslemeyin ve beni izleyin. Doğru yol budur. * 43:61 Kuran, Dünyanın Sonunun tarihini verir (20:15; 15:87). İsa'nın doğum tarihi, bu hesabı doğrulayıp destekleyen işeretlerden birisidir. Dünyanın, İsa'nın doğumundan 2280 (19x120) yıl sonra son bulacağını Kuran ayetlerinin işaretiyle öğrenmiş bulunuyoruz. Ayrıca, dünyanın sonunun tarihleri olan 1710 (19x90) kameri/hicri ve 2280 (19x120) şemsi/miladi yılları, İsa ile Muhammed'in doğumu arasındaki yılların sayısı olan 570 (19x30) sayısına ayrı ayrı tam olarak bölünmektedir. Bak 47:18."},{"n":62,"t":"Şeytan sizi yoldan çıkarmasın. O size açık bir düşmandır."},{"n":63,"t":"İsa apaçık mucizelerle gelince demişti ki, \"Size bilgelik, ve ayrılığa düştüğünüz konulara açıklama getirdim. ALLAH'ı dinleyiniz ve bana uyunuz.\""},{"n":64,"t":"\"ALLAH benim Rabbim ve sizin de Rabbinizdir, sadece O'na kulluk etmelisiniz. Dosdoğru yol budur.\""},{"n":65,"t":"Partiler ve mezhepler aralarında tartıştılar. Acı azaptan dolayı vay zalimlerin haline."},{"n":66,"t":"Onlar, farkında değilken, Saatin kendilerine ansızın gelmesini mi bekliyorlar?"},{"n":67,"t":"Erdemlilerin dışında, o gün yakın dostlar birbirlerine düşman kesilecek. Cennet ve Cehennem"},{"n":68,"t":"Kullarım, bugün size korku yoktur ve üzülmeyeceksiniz."},{"n":69,"t":"Ayetlerime inananlar ve teslim olanlar,"},{"n":70,"t":"Siz ve eşleriniz cennete girin; sevinç içinde ağırlanacaksınız."},{"n":71,"t":"Onlara altın tepsiler ve kadehlerle sunulur. Orada canların çektiği ve gözlerin hoşlandığı herşey vardır. Siz orada ebedi kalacaksınız."},{"n":72,"t":"Yaptıklarınızın bir karşılığı olarak size miras olarak verilen cennet budur."},{"n":73,"t":"Orada sizin yemeniz için bol meyveler vardır."},{"n":74,"t":"Suçlular, cehennem azabında ebedi kalıcıdırlar."},{"n":75,"t":"Onlardan hafifletilmez ve onlar orada ümitsizdirler."},{"n":76,"t":"Biz onlara haksızlık etmedik, onlar kendi kendilerine haksızlık ettiler."},{"n":77,"t":"\"Ey Malik, artık Rabbin bizim işimizi bitirsin,\" diye seslenirler. O da, \"Siz böyle kalacaksınız,\" der."},{"n":78,"t":"Size gerçeği getirdik; ancak çoğunuz gerçekten hoşlanmıyorsunuz."},{"n":79,"t":"Yoksa onlar bir plan mı kurdular? Biz de plan kurarız."},{"n":80,"t":"Yoksa, sırlarını ve komplolarını işitmediğimizi mi sanıyorlar. Doğrusu, yanlarındaki elçilerimiz kaydetmektedirler."},{"n":81,"t":"De ki; \"Rahman'ın bir çocuğu olsaydı, ona tapanların ilki ben olurdum.\""},{"n":82,"t":"Göklerin ve yerin Rabbi, Yönetimin Rabbi, onların nitelemelerinden çok yücedir."},{"n":83,"t":"Bırak onları, kendilerine söz verilen günlerine kavuşuncaya kadar dalsınlar, oynasınlar."},{"n":84,"t":"Gökte de tanrı, yerde de tanrı O'dur. O Bilgedir, Bilendir."},{"n":85,"t":"Göklerin, yerin ve aralarındakilerin yönetimine sahip olan çok yücedir. Saat'in (dünyanın sonunun) bilgisi O'nun yanındadır ve siz O'na döndürüleceksiniz. Putperestlerin Şefaatle Kurtulma Ümitleri Boş Bir Hayal Şefaat, Gerçeğe Tanıklık Biçiminde Gerçekleşecektir"},{"n":86,"t":"Onların O'nun dışında çağırdıkları şefaat edemezler. Ancak bilerek gerçeğe tanıklık edenler hariç*92 * 43:86 Bak 25:30 ve 2:48."},{"n":87,"t":"Onlara, kendilerini kimin yarattığını sorsan, \"ALLAH\" diyeceklerdir. Öyleyse neden çevriliyorlar?"},{"n":88,"t":"\"Rabbim bunlar inanmıyan bir topluluktur,\" denmişti."},{"n":89,"t":"Onlara aldırma ve \"Selam\" (barış ve esenlik), de; yakında bilecekler."}]},{"id":44,"name":"DUMAN (DUHAN) SÛRESİ","verses":[{"n":1,"t":"HH. M."},{"n":2,"t":"Apaçık olan bu kitaba andolsun."},{"n":3,"t":"Biz uyarmak için onu kutlu bir gecede indirdik."},{"n":4,"t":"Onda tüm bilgelik işleri belirlenir."},{"n":5,"t":"Katımızdan bir buyruktur; biz elçiler göndeririz."},{"n":6,"t":"Rabbinden bir rahmet olarak. O İşitendir, Bilendir."},{"n":7,"t":"Göklerin, yerin ve aralarındakilerin Rabbidir. Kesin bir inanca sahipseniz..."},{"n":8,"t":"O'ndan başka tanrı yoktur. Yaşatır ve öldürür. Sizin de, önceki atalarınızın da Rabbidir."},{"n":9,"t":"Doğrusu, onlar bir kuşku içinde oynamaktadırlar. Duman: Gelecekle İlgili Büyük Haber"},{"n":10,"t":"Göğün apaçık bir dumanı getireceği günü gözetle."},{"n":11,"t":"İnsanları çepeçevre saracaktır; bu acı bir azaptır."},{"n":12,"t":"\"Rabbimiz, bizden bu azabı kaldır; biz inanıyoruz.\""},{"n":13,"t":"Mesaja aldırış etmediler. Halbuki kendilerine apaçık bir elçi gelmişti."},{"n":14,"t":"Sonra ondan yüz çevirdiler ve, \"Öğrenim görmüş bir deli!\" dediler."},{"n":15,"t":"Biz azabı birazcık kaldıracağız; ama siz yine döneceksiniz."},{"n":16,"t":"Asıl o büyük yakalama ile yakaladığımızda öc alırız."},{"n":17,"t":"Onlardan önce Firavun'un halkını sınamıştık; onlara şerefli bir elçi gitmişti:"},{"n":18,"t":"\"Ey ALLAH'ın kulları, bana kulak verin. Ben size gönderilmiş güvenilir bir elçiyim.\""},{"n":19,"t":"\"ALLAH'a karşı ululanmayın. Ben size apaçık bir delille gelmiş bulunuyorum.\""},{"n":20,"t":"\"Sizin beni taşlamanızdan, benim Rabbime ve sizin Rabbinize sığınıyorum.\""},{"n":21,"t":"\"Bana inanmıyorsanız, bari beni yalnız bırakın.\""},{"n":22,"t":"Ve, \"Bunlar suçlu bir topluluk,\"diye Rabbine yalvardı."},{"n":23,"t":"\"Kullarımla geceleyin yola çık. Siz izleniyorsunuz.\""},{"n":24,"t":"\"Denizi yarılmış olarak terket. Onlar boğulmaya mahkum bir ordudur.\""},{"n":25,"t":"Onlar geride neler bırakmışlardı: Bahçeler, pınarlar,"},{"n":26,"t":"Ekinler ve yüksek makamlar,"},{"n":27,"t":"Ve içinde sefa sürdükleri nice nimetler..."},{"n":28,"t":"Böylece hepsini başka bir topluluğa miras bıraktık."},{"n":29,"t":"Ne gök ve ne de yer onlara ağladı; ertelenmediler de."},{"n":30,"t":"İsrailoğullarını alçaltıcı zulümden kurtarmıştık;"},{"n":31,"t":"Firavun'dan. O, azgın bir diktatör idi."},{"n":32,"t":"Tüm halkın arasından özellikle onları seçtik."},{"n":33,"t":"Ve onlara, açık bir sınav olarak mucizeler verdik."},{"n":34,"t":"Şunlar da diyorlar ki:"},{"n":35,"t":"\"Sadece bir kez ölürüz; dirilecek değiliz.\""},{"n":36,"t":"\"Doğru sözlüler iseniz, atalarımızı geri getirin.\""},{"n":37,"t":"Onlar mı, yoksa Tubba' halkı ve onlardan öncekiler mi daha iyidir? Suçlu oldukları için onları yok etmiştik."},{"n":38,"t":"Biz, gökler, yer ve aralarındakileri oyun eğlence için yaratmadık."},{"n":39,"t":"Biz onları ancak belli bir amaca göre yarattık. Ne var ki onların çoğu bilmezler. Suçlular"},{"n":40,"t":"Hepsi Karar Günü topluca buluşacaklardır."},{"n":41,"t":"O gün dost, dostunu hiç bir şeyden koruyamaz ve yardım da görmezler. * 44:41 Bak 2:286."},{"n":42,"t":"Yalnız ALLAH'ın merhamet ettikleri hariç. O Üstündür, Rahimdir."},{"n":43,"t":"Elbette, zakkum ağacı"},{"n":44,"t":"Günahkarın yiyeceğidir."},{"n":45,"t":"Derişik asit gibi ve midelerde kaynayacaktır."},{"n":46,"t":"Sıcak suyun kaynaması gibi."},{"n":47,"t":"Onu yakalayın ve cehennemin ortasına sürükleyin."},{"n":48,"t":"Sonra başına kaynar su azabından dökün."},{"n":49,"t":"\"Tad bakalım; sen çok üstün ve şerefliydin!\""},{"n":50,"t":"\"Bu, işte kuşkulanıp durduğunuz şeydir.\" Erdemliler"},{"n":51,"t":"Erdemli olanlar ise güvenlikli bir makamdadırlar."},{"n":52,"t":"Bahçeler ve pınarlar içerisinde."},{"n":53,"t":"İpek ve atlastan giysiler içinde karşılıklı otururlar."},{"n":54,"t":"Bu böyledir; onlara güzel eşler vermişizdir."},{"n":55,"t":"Tam bir güvenlik içinde her meyveyi isterler."},{"n":56,"t":"Orada, ilk ölümden başka ölüm tatmazlar. Onları cehennem azabından korumuştur. * 44:56 Cennette işlediğimiz suçtan dolayı ilk ölümü tadıp bu dünyaya doğduk. Bak 40:11."},{"n":57,"t":"Rabbinin bir lütfu olarak. İşte büyük zafer budur."},{"n":58,"t":"Öğüt alsınlar diye senin dilinle onu kolaylaştırdık."},{"n":59,"t":"Öyleyse bekle; onlar da beklemektedirler."}]},{"id":45,"name":"DİZ ÇÖKÜŞ (CASİYE) SÛRESİ","verses":[{"n":1,"t":"HH. M. * 45:1 Bu harflerin anlamı için bak 2:1; 40:1; 74:30."},{"n":2,"t":"Bu kitabın indirilmesi, Üstün ve Bilge olan ALLAH katındandır."},{"n":3,"t":"İnananlar için göklerde ve yerde ayetler var."},{"n":4,"t":"Sizin yaratılışınızda ve yaydığı tüm canlılarda kuşkusuz bir inanca sahip bir toplum için ayetler var."},{"n":5,"t":"Gecenin ve gündüzün birbirini izlemesinde, ALLAH'ın gökten bir rızık indirerek onunla ölümünden sonra toprağı diriltmesinde, ve rüzgarları yönetmesinde anlayan bir toplum için ayetler var. Kuran'dan Başka Hangi Hadis?"},{"n":6,"t":"Bunlar, sana gerçek olarak okuduğumuz ALLAH'ın ayetleridir. ALLAH'tan ve ayetlerinden başka hangi hadise inanıyorlar? * 45:6-9 Allah'ı ve ayetlerini yetersiz görenler bu soruya, hadis kitaplarını sayarak cevap vermektedirler. Bak: 6:112-114; 12:111; 33:38."},{"n":7,"t":"Vay haline her uydurukçu günahkarın!"},{"n":8,"t":"Kendisine okunan ALLAH'ın ayetlerini işittikten sonra, sanki onları hiç işitmemiş gibi büyüklük taslayarak direniyor. Onu acı bir cezayla müjdele."},{"n":9,"t":"Ayetlerimizden bir şey öğrendiği zaman onu alaya alır."},{"n":10,"t":"Onları cehennem beklemektedir. Ne işledikleri şeyler, ne de ALLAH'tan başka edindikleri dostlar onu kurtarabilir. Onlar, acı bir azabı haketmişlerdir."},{"n":11,"t":"Bu bir rehberdir. Rab'lerinin ayetlerini inkar edenler için iğrenç ve acı bir azap vardır."},{"n":12,"t":"Lütfundan payınızı aramanız ve şükretmeniz için gemileri emriyle sürmenize uygun olarak denizi buyruğunuz altına veren ALLAH'tır."},{"n":13,"t":"Göklerde ve yerde ne varsa hepsini kendi katından buyruğunuza vermiştir. Düşünen bir topluluk için elbette bunda ibretler vardır."},{"n":14,"t":"İnananlara söyle ki, ALLAH'ın günlerini ummayanları bağışlasınlar. Zira O, yaptıkları işlere göre bir topluluğa karşılık verir."},{"n":15,"t":"Kim erdemli davranırsa kendisi içindir, kim de kötülük işlerse kendi aleyhinedir. Sonra, siz Rabbinize döndürüleceksiniz."},{"n":16,"t":"İsrailoğullarına kitabı, bilgeliği ve peygamberliği vermiştik. Onları iyi nimetlerle rızıklandırmış ve onları tüm halklara üstün kılmıştık."},{"n":17,"t":"Onlara apaçık emirler verdik. Kendilerine bilgi geldikten sonra, aralarındaki çekememezlikten ötürü ayrılığa düştüler. Diriliş Günü senin Rabbin, ayrılığa düştükleri konularda onların arasında yargı verecektir."},{"n":18,"t":"Sonra sana da din konusunda bir yasa verdik; sen ona uymalısın, bilmeyenlerin keyfine uyma."},{"n":19,"t":"Onlar, ALLAH'tan hiçbir şeyi senden savamazlar. Zalimler birbirlerinin dostlarıdır. ALLAH da erdemlilerin dostudur."},{"n":20,"t":"Bunlar, halk için aydınlatıcı delillerdir, kesin inanca sahip bir topluma bir rehber ve rahmettir."},{"n":21,"t":"Kötülükleri işleyen kimseler, dirildiklerinde ve ölümlerinde, kendilerini, inanıp erdemli davrananlarla bir mi tutacağımızı sandılar? Ne kötü hüküm veriyorlar!"},{"n":22,"t":"ALLAH gökleri ve yeri belli bir amaç için yarattı ki her can, kazandığının karşılığını haksızlığa uğramadan görsün. Egonun Tanrılaştırılması"},{"n":23,"t":"Egosunu tanrı edinen kimseye dikkat ettin mi? Nitekim ALLAH onu bilerek saptırmış, işitme duyusunu ve beynini mühürlemiş ve görüşüne perde koymuştur. ALLAH'tan başka kim onu doğruya iletebilir? Öğüt almaz mısınız?"},{"n":24,"t":"Onlar derler ki, \"Biz sadece dünya hayatında yaşarız. Yaşarız, ölürüz ve bizi zamandan başkası yok etmez.\" Onların bu konuda bir bilgisi yoktur. Onlar sadece zannediyorlar."},{"n":25,"t":"Onlara açık açık ayetlerimiz okunduğunda, \"Doğru sözlü iseniz atalarımızı geri getirin,\" demekten başka delilleri yoktur."},{"n":26,"t":"De ki \"Sizi ALLAH diriltir ve öldürür. Sonra, gerçekleşmesinde kuşku bulunmayan Diriliş Gününde sizi bir araya toplar. Fakat insanların çoğu bilmez.\""},{"n":27,"t":"Göklerin ve yerin yönetimi ALLAH'a aittir. Saat (dünyanın sonu) gerçekleştiği gün, işte o gün batılı savunanlar hüsrana uğrayacaktır."},{"n":28,"t":"Her toplumu diz çökmüş halde görürsün. Her toplum kendi kitabına çağrılır: \"Bugün size, yaptıklarınızın karşılığı ödenecektir.\""},{"n":29,"t":"\"Bu kitabımız size karşı gerçeği konuşmaktadır. Çünkü biz, yaptıklarınızı kaydediyorduk.\""},{"n":30,"t":"İnanan ve erdemli davrananlara gelince, Rab'leri onları rahmetine sokacaktır. Apaçık zafer işte budur."},{"n":31,"t":"İnkar edenlere gelince: \"Ayetlerimiz size okunmuş ve siz de büyüklenip suçlu bir topluluk olmamış mıydınız?\""},{"n":32,"t":"Kendilerine ALLAH'ın sözünün bir gerçek ve Saat'in kesinleşmesi kaçınılmaz bir olay olduğu söylendiğinde siz, \"Saat'in ne olduğunu bilmeyiz! Biz sadece çeşitli sanılara sahibiz ve bu konuda kesin bir bilgi elde etmiş değiliz,\" derdiniz."},{"n":33,"t":"Yaptıkları kötülükler kendilerine görünecek ve alay etmekte oldukları şey onları kuşatıp avlayacaktır."},{"n":34,"t":"Ve onlara şöyle denir: \"Bugünkü karşılaşmanızı unuttuğunuz için biz de bugün sizi unutuyoruz. Yeriniz ateştir ve sizin bir yardımcınız da olmayacaktır.\""},{"n":35,"t":"\"Çünkü siz ALLAH'ın ayetlerini alaya aldınız ve dünya hayatı sizi kandırdı.\" Sonuç olarak, onlar oradan çıkamazlar ve özürleri de dinlenmez."},{"n":36,"t":"Göklerin Rabbi, yerin Rabbi ve evrenlerin Rabbi olan ALLAH'a övgüler olsun."},{"n":37,"t":"Göklerde ve yerde tüm büyüklükler O'na aittir. O Üstündür, Bilgedir."}]},{"id":46,"name":"KUM TEPECİKLERİ (AHKAF) SÛRESİ","verses":[{"n":1,"t":"HH. M."},{"n":2,"t":"Kitabın indirilmesi, Üstün ve Bilge olan ALLAH'tandır."},{"n":3,"t":"Biz gökleri, yeri ve aralarındakileri ancak belli bir amaca göre ve belli bir süre için yarattık. İnkar edenler uyarıya aldırış etmemektedirler."},{"n":4,"t":"De ki, \"ALLAH'ın dışında yalvardıklarınıza bir bakın. Onların yerden neyi yarattığını bana gösterin. Yoksa göklerde onların bir ortaklığı mı var? Bundan önce bir kitap veya bir bilimsel belge getirin, doğru sözlü iseniz?\" Tümüyle Habersiz"},{"n":5,"t":"ALLAH'ı bırakıp da Diriliş Gününe kadar kendilerine cevap veremiyen ve hatta onların dualarından bile habersiz olanları çağıranlardan daha sapık kim olabilir? Kendilerine Tapanları Reddedecekler*"},{"n":6,"t":"Halk toplandığı zaman onlara düşman olacaklardır ve onların kendilerine tapmalarına karşı çıkacaklardır. * 46:6 Ayrıca Matta 7:21-23'e de bakın. İsa, kendisini \"Rab\" diye çağıranları cehennemi haketmekle uyarmaktadır. İncildeki bu ayet çeşitli İncil nüshalarında tahrif edilmesine rağmen nüshaların karşılaştırılması ile bu çarpıcı gerçeği çok net bir biçimde ortaya çıkarmaktadır. \"Hristiyan Dinadamlarına 19 Soru\" adlı kitabımızda bu konuyu genişçe tartıştık. Bak: 41:47-48."},{"n":7,"t":"Kendilerine apaçık ayetlerimiz okunduğunda, kendilerine gelen gerçeğe karşı çıkanlar, \"Bu, açıkça bir büyüdür,\" dediler."},{"n":8,"t":"Yoksa \"Onu uydurdu\" mu diyorlar? De ki, \"Onu ben uydurduysam siz beni ALLAH'tan gelecek hiç bir şeye karşı koruyamazsınız. O, sizin taşkınlığınızı en iyi bilendir. Benimle sizin aranızda tanık olarak O yeter. O Bağışlayandır, Rahimdir."},{"n":9,"t":"De ki \"Ben türedi bir elçi değilim. Bana ve size ne olacağını da bilmem. Ben, ancak bana vahyedilene uyuyorum. Ben apaçık bir uyarıcıdan başka bir şey değilim.\" Haham Juda: İsrail Oğullarından Bir Şahit"},{"n":10,"t":"De ki, \"Düşündünüz mü, ya o ALLAH katından ise ve siz de ona karşı çıkmışsanız ve İsrail oğullarından bir tanık da bunun benzerini görüp inandığı halde, siz kibirlenip yüz çevirmişseniz?! Kuşkusuz ALLAH zalim topluluğu doğru yola iletmez.\" * 46:10 Onbirinci yüzyılda Fransa'da yaşamış bulunan Rabi Juda adlı bir Yahudi hahamının, Tevrat'ın orijinal bir parçasında 19 kodu üzerine kurulu matematiksel sistemi keşfetmiş olduğu ortaya çıktı. Juda'nın çalışmaları üzerine Joseph Dan tarafından yazılan bir makale Californiya Universitesi'nin yayımladığı \"Studies in Jewish Mysticism\" (Yahudi Mistisizmi üzerine Araştırmalar) adlı dergide 1978 yılında yayımlandı."},{"n":11,"t":"İnkar edenler, inananlara, \"O iyi bir şey olsaydı onlar (İsrail oğulları) bizden öne geçemezlerdi\" derler ve ona yol bulamadıkları için, \"Bu bir efsanedir\" diyeceklerdir. * 46:11 Diyanet işleri eski başkanı ve birkaç dinadamından oluşan bir heyet de 19 mucizesine karşı olarak yayımladıkları kitaba \"19 Efsanesi\" adını verdiler. Bu, Kuran'ın bir haberinin tecellisidir. Bak: 6:25."},{"n":12,"t":"Bundan önce Musa'nın kitabı rehber ve rahmet idi. Bu, zalimleri uyarmak ve güzel davrananlara bir müjde olmak üzere Arapça indirilmiş doğrulayıcı bir kitaptır. Müjde"},{"n":13,"t":"\"Rabbimiz ALLAH'tır\" deyip dosdoğru davrananlara bir korku yoktur ve onlar üzülmezler de."},{"n":14,"t":"Onlar cennet halkıdır; yapmış olduklarına karşılık olarak orada ebedi kalacaklardır. 40: Karar İçin Kritik Yaş"},{"n":15,"t":"Biz insana, ana ve babasına iyilik etmesini öğütledik. Anası onu zahmetle taşır, zahmetle doğurur. Ana karnında taşınması ile sütten kesilmesi otuz ay sürer. Nihayet olgunluk çağına erince ve kırk yaşına varınca: \"Rabbim, bana, anama ve babama verdiğin nimete şükretmeğe ve razı olacağın yararlı işler yapmağa beni yönelt. Benim soyumu islah et. Ben tövbe edip, sana teslim olanlardanım,\" demelidir.* * 46:15 Bu ayet, insanın gebelik döneminde ana karnında geçirdiği süre ile emzirme süresinin toplamı 30 ay olduğunu bildiriyor. Bu ayet, emzirme süresini 24 ay olarak bildiren 31:14 ayetiyle birlikte değerlendirilirse, bebeğin ana karnında sadece 6 ay insan/kişi/nefs kabul edildiği anlaşılır. Gebelik süresinin döllenmeden itibaren tam 266 gün olduğunu biliyoruz (77:23). Bu, Tanrı'nın doğadaki bir ayetidir. Altı ay, 180 gün olduğuna göre bunu 266'dan çıkarırsak, gebeliğin ilk 86 gününde ceninin insan veya \"nefs\" sayılmadığı anlaşılır. Nitekim, insanın ana karnındaki gelişimini dört evrede açıklayan 22:5 ve 23:14 ayetleri gebeliğin ilk günlerini \"nefs\" yahut \"insan\" olarak değil de başka kelimelerle ifade eder. Bunlar sırasıyla: (1) sperm; (2) embriyo; (3) on santim büyüklüğündeki cenin evresine kemiklerin ve etin oluşması; ve nihayet (4) yeni bir yaratık. Yeni bir yaratığın döllenmeden 89 gün sonra yaratıldığı anlaşılıyor. Bir başka değişle \"nefs\"in (bilinç/kişilik) ilk belirtileri, döllenmeden yaklaşık üç ay sonra ceninin beyninde zuhur etmektedir. Kuran'daki ayetlerle doğadaki ayetlerin birlikte değerlendirilmesiyle elde edilen bu bilginin kürtaj konusuna aydınlık getirdiğini ifade etmeğe gerek var mı? Ayrıca bak: 16:58-59; 17:31 * 46:15 Tanrı, kimin cenneti hakettiğini iyi bilir. 40 yaşına varmadan kimin canını alırsa o kişi cennete girer. Tanrı o kadar geniş merhamet sahibidir ki çoğu kişi bu süreyi çok bulmakta ve onlar için cennet yerine cehennemi istemektedir. Bak 35:37."},{"n":16,"t":"İşlediklerinin en iyisini kabul ettiğimiz ve kötülüklerini geçtiğimiz bu kimseler cennet halkı arasındadırlar. Bu, kendilerine verilen doğru sözdür."},{"n":17,"t":"Öte yanda bir başkası var ki anne babasına, \"Öf size, benden önce nice kuşaklar geçmiş olmasına rağmen benim diriltileceğimi mi iddia ediyorsunuz?\" O ikisi ise ALLAH'a sığınarak: \"Yazık sana; lütfen inan. ALLAH'ın sözü gerçektir.\" Bunun üzerine o, \"Bu, eskilerin masallarından başka bir şey değil,\" der."},{"n":18,"t":"Bu gibiler, gelip geçmiş cin ve insan toplumları arasında azap sözünü haketmiş kimselerdir. Onlar kaybedenlerdir. Tanrı'nın Adaleti"},{"n":19,"t":"Her biri için, yaptıklarına göre dereceler vardır. Yaptıklarının karşılığı, haksızlık edilmeden tam verilir."},{"n":20,"t":"İnkarcılar cehenneme sunulduğu gün, \"Dünya hayatında tüm güzel şeylerinizi boşa harcayıp onların zevkini sürdünüz. Yeryüzünde haksız yere büyüklenmenizin ve yoldan çıkmanızın karşılığında bugün alçaltıcı azabı göreceksiniz.\" Hud"},{"n":21,"t":"Ad'ın kardeşinin kum tepeciklerindeki halkını uyarmış olduğunu hatırla. Ondan önce ve sonra \"ALLAH'tan başkasına kulluk etmeyin. Sizin için büyük bir günün azabından korkarım,\" diyen nice uyarıcılar geçmişti."},{"n":22,"t":"\"Bizi tanrılarımızdan saptırmak için mi bize geldin? Doğru sözlü isen bize söz verdiğini getir bakalım,\" dediler."},{"n":23,"t":"\"Onun bilgisi sadece ALLAH'ın yanındadır. Ben benimle gönderilen şeyi size duyuruyorum; fakat sizin cahil bir toplum olduğunuzu görüyorum.\""},{"n":24,"t":"Nihayet onun yayılarak vadilerine yönelmiş olduğunu gördüklerinde, \"Bu, bize yağmur yağdıracak bir buluttur,\" dediler. Hayır, bu sizin gelmesi için meydan okuduğunuz acı bir azaba sahip bir fırtınadır."},{"n":25,"t":"Rabbinin emriyle herşeyi yerle bir eder. Sabahladıklarında, evlerinden başka herşey görülmez olmuştu. Suçlu topluluğu işte böyle cezalandırırız."},{"n":26,"t":"Sizi yerleştirmediğimiz yerlere yerleştirmiştik onları. Onlara işitme ve görme duyuları ile beyinler vermiştik. ALLAH'ın ayet ve mucizelerini bile bile inkar ettikleri için ne işitme, ne görme duyuları ve ne de beyinleri onlara hiç bir yarar sağlamadı. Alaya aldıkları şeyler kendilerini çepeçevre kuşatıverdi."},{"n":27,"t":"Çevrenizdeki nice kentleri de yok ettik. Dönerler diye onlara ayetleri açıklamıştık."},{"n":28,"t":"ALLAH'tan başka, O'na yakınlık sağlamak amacıyla edindikleri tanrılar kendilerine yardım etmeli değil miydi? Aksine, onları terkettiler. İşte onların yalanları ve uydurmaları böyledir. İnanan Cinler"},{"n":29,"t":"Cinlerden bir grubu, Kuran'ı dinlemek üzere sana yöneltmiştik. Ona geldiklerinde, \"Susun\" dediler. (Okuma) bitirilince topluluklarına birer uyarıcı olarak döndüler.*"},{"n":30,"t":"\"Ey halkımız,\" dediler, \"Biz, Musa'dan sonra, kendisinden öncekileri doğrulayıcı olarak indirilen bir kitabı dinledik. O gerçeğe ve dosdoğru yola iletmektedir.\""},{"n":31,"t":"\"Ey halkımız, ALLAH'a çağıranı yanıtlayın. O'na inanın ki günahlarınızı bağışlasın ve sizi acı azaptan korusun.\""},{"n":32,"t":"ALLAH'a çağıranı yanıtlamıyanlar yeryüzünde kaçamaz. Onların O'na karşı dostları da olmaz. Onlar apaçık bir sapıklık içindedirler."},{"n":33,"t":"Gökleri ve yeri yaratan ve bunları yaratmakla yorulmayan ALLAH'ın ölüleri diriltebileceğini düşünmezler mi? Evet, O her şeye gücü yetendir."},{"n":34,"t":"İnkarcılar ateşe sunuldukları gün: \"Bu gerçek değil mi?\" Derler ki, \"Evet, Rabbimize andolsun.\" O da, \"İnkar etmiş olduğunuz için azabı tadın,\" der. Acele Etme, Sabret"},{"n":35,"t":"Karar ve azim sahibi elçiler nasıl sabrettiyse sen de sabret ve onlar için acele etme. Onlar, kendilerine söz verileni gördüklerinde, (sanki dünyada) gündüzün bir saati kadar kalmışlardır. Bu bir bildiridir: Yoldan çıkmış topluluklardan başkası mı yok edilir?"}]},{"id":47,"name":"MUHAMMED (MUHAMMED) SÛRESİ","verses":[{"n":1,"t":"İnkar edip ALLAH'ın yolundan ayrılanların tüm işlerini O boşa çıkarır."},{"n":2,"t":"İnanıp erdemli davrananların ve Rab'lerinden bir gerçek olarak Muhammed'e indirilene inananların ise günahlarını örter ve durumlarını düzeltir."},{"n":3,"t":"Çünkü inkar edenler batıla uymakta, inananlar ise Rab'lerinden gelen gerçeğe uymaktadırlar. ALLAH halkın durumunu böyle sergiler."},{"n":4,"t":"Savaşta inkar edenlerle karşılaştığınzda boyunlarını vurun. Sonunda üstün geldiğinizde onları esir alın; onları ya karşılıksız veya fidye karşılığında salın. Savaş durumu kalkıncaya kadar bunu uygulayın. ALLAH dileseydi sizi savaş derdinden kurtarırdı; ancak O sizi böylece birbirinizle sınamaktadır. ALLAH yolunda öldürenlere gelince, onların yaptıklarını boşa çıkarmıyacaktır."},{"n":5,"t":"Onlara yol gösterecek ve işlerini düzeltecektir."},{"n":6,"t":"Onları kendilerine tanıtmış olduğu cennete sokacaktır."},{"n":7,"t":"Ey inananlar, ALLAH'ı desteklerseniz, O da sizi destekler ve ayaklarınızı sağlam tutar."},{"n":8,"t":"İnkar edenler ise yıkımı haketmişlerdir; onların işlerini boşa çıkarmıştır."},{"n":9,"t":"Çünkü onlar ALLAH'ın indirdiğini beğenmediler. O da onların işlerini geçersiz kılmıştır."},{"n":10,"t":"Kendilerinden öncekilerin sonunun nasıl olduğuna bakmak için yeryüzünü dolaşmazlar mı? ALLAH onları imha etmiştir ve bu inkarcıları da aynı son beklemektedir."},{"n":11,"t":"Çünkü ALLAH inananların koruyucusudur. İnkarcıların ise bir koruyucusu yoktur."},{"n":12,"t":"ALLAH inanıp erdemli davrananları içlerinden ırmaklar akan cennetlere sokar. İnkarcılar ise hayvanlar gibi yiyip yaşamaktadırlar ve sonunda ateşi boylarlar."},{"n":13,"t":"Seni çıkaran ülkenden daha güçlü nice ülkeler vardı ki onları yok ettik, onlara yardım eden olmadı."},{"n":14,"t":"Rabbinden bir delil üzerinde bulunan, işlediği kötülükler kendisine güzel gözüken gibi olur mu? Onlar arzularına uymaktadırlar. Cennet ve Cehennem, Mecaz Yoluyla Anlatılıyor"},{"n":15,"t":"Erdemlilere söz verilen cennetin örneği şudur: İçinde arı sudan ırmaklar, tadı bozulmayan sütten ırmaklar, içenlere lezzet veren sarhoş edici maddelerden oluşan ırmaklar ve süzme baldan ırmaklar vardır. Onlar için orada her türlü ürün ve Rab'lerinden bir bağışlanma vardır. Bunların durumu, ateşte sürekli kalan ve bağırsaklarını yırtan kaynar bir sudan içirilen kimselerin durumu gibi olur mu? * 47:15 Cennetteki sarhoşluğun dünyadakinden farklı olduğu bildiriliyor. Bak 52:23; 76:21."},{"n":16,"t":"Onlardan bazıları var ki seni dinlerler. Fakat senin yanından çıkınca, kendilerine bilgi verilmiş olanlara, \"Bu, demin ne söyledi?\" diye sorarlar. İşte bunlar, ALLAH'ın kalplerini damgaladığı kimselerdir ve onlar heveslerinin ardına düşmüşlerdir."},{"n":17,"t":"Doğru yolu bulanların ise hidayetini arttırır ve onların erdemli olmalarını sağlar."},{"n":18,"t":"Saatin kendilerine ansızın gelmesini mi bekliyorlar? Kuşkusuz onun alametleri gelmiş bulunuyor.*93 Onlara gelip çatınca kendilerine gelen mesajın ne yararı olur? * 47:18 Kuran, son kitap olduğundan dünyanın 2280 tarihinde son bulacağını ön işaretleriyle birlikte bildirmektedir. Bak 20:15; 15:87."},{"n":19,"t":"Bil ki, ALLAH'tan başka tanrı yoktur. Kendinin, inanan erkeklerin ve inanan kadınların günahları için bağışlanma dile. ALLAH sizin tüm hareketlerinizi ve duracağınız yeri bilir. İkiyüzlüler Zor Durumlarda Belli Oluyor"},{"n":20,"t":"İnananlar, \"(Savaşmaya izin veren) bir süre indirilse ya?\" diyorlardı. Ancak hükmü açık bir sure indirilip de içinde savaştan söz edilince, kalplerinde hastalık bulunanların, ölüm korkusuyla bayılan bir kimsenin bakışı gibi sana baktıklarını görürsün. Onlar için uygun olan,"},{"n":21,"t":"İtaat etmek ve güzel konuşmaktır. İş kararlaştırılınca ALLAH'a karşı dürüst olsalar kendileri için iyi olurdu."},{"n":22,"t":"Demek işbaşına gelecek olsanız yeryüzünde bozgunculuk çıkaracak ve akrabalık bağlarını koparacaksınız?"},{"n":23,"t":"İşte, ALLAH'ın lanetlediği, sağırlaştırıp körleştirdiği kimseler bunlardır. Kuran'ı İncele"},{"n":24,"t":"Neden Kuran'ı araştırıp incelemezler? Yoksa kilitli mi beyinleri?"},{"n":25,"t":"Kendilerine doğru yol belli olduktan sonra geriye dönenleri şeytan ayartmıştır ve onlara ümit vermiştir."},{"n":26,"t":"Zira onlar, ALLAH'ın indirdiğini beğenmiyenlere, \"Bazı konularda size uyuyoruz,\" demişlerdi. ALLAH onların komplolarını bilmektedir."},{"n":27,"t":"Melekler canlarını alırken nasıl da (pişmanlık içinde) yüzlerine ve sırtlarına vururlar?"},{"n":28,"t":"Çünkü onlar, ALLAH'ı kızdıran şeye uydular, O'nun hoşnut edecek şeyleri beğenmediler ve sonunda yaptıklarını geçersiz hale getirdiler."},{"n":29,"t":"Kalplerinde hastalık bulunanlar, ALLAH'ın, onların kinlerini açığa çıkaracağını bilmezler mi?"},{"n":30,"t":"Dileseydik onları sana gösterirdik, sen de onları yüzlerinden tanırdın. Sen onları sözlerinin eğriliğinden tanıyabilirsin. ALLAH tüm işlediklerinizi bilir."},{"n":31,"t":"Sizden çaba gösterenleri ve güçlüklere karşı direnenleri ortaya çıkarıncaya kadar sizi sınayacağız ve kalitenizi sınayacağız."},{"n":32,"t":"İnkar edip ALLAH'ın yolundan sapanlar ve kendilerine doğru yol belli olduktan sonra elçiye karşı gelenler ALLAH'a hiç bir zarar veremezler. Aksine, onların yaptıklarını geçersiz kılacaktır."},{"n":33,"t":"Ey inananlar, ALLAH'a uyunuz, elçiye uyunuz ve işlerinizi boşa çıkarmayınız."},{"n":34,"t":"İnkar edip ALLAH'ın yolundan saptıktan sonra inkarcılar olarak ölenleri ALLAH bağışlamıyacaktır. Barışı Gerçekleştirin"},{"n":35,"t":"Barışa giden yolda gevşemeyin. Zafer sizindir. ALLAH sizinle beraberdir ve işlediklerinizi ziyan etmeyecektir."},{"n":36,"t":"Dünya hayatı bir oyun ve eğlenceden ibarettir. İnanıp erdemli davranırsanız, ödüllerinizi verir. O sizden paralarınızı istemiyor."},{"n":37,"t":"Onları sizden isteseydi ve sizi sıkıştırsaydı cimrilik ederdiniz ve sizin gizli kötülüklerinizi açığa çıkarırdı."},{"n":38,"t":"Sizler, ALLAH yolunda harcamaya çağrılıyorsunuz, ancak bir kısmınız cimrilik etmektedir. Kim cimrilik ederse kendisine karşı cimrilik etmiş olur. ALLAH zengindir, siz ise yoksulsunuz. Yüz çevirirseniz, yerinize başka bir topluluk getirir de onlar sizin gibi olmazlar."}]},{"id":48,"name":"ZAFER (FETİH) SÛRESİ","verses":[{"n":1,"t":"Biz sana apaçık bir zafer verdik."},{"n":2,"t":"Ki ALLAH, geçmiş ve gelecek günahlarını bağışlasın, sana olan nimetini tamamlasın ve seni doğru yola iletsin."},{"n":3,"t":"Ve ALLAH seni üstün bir zaferle desteklesin."},{"n":4,"t":"O inançlarına inanç katmak için inananların kalbine huzur indirendir. Göklerin ve yerin orduları ALLAH'ındır. ALLAH Bilendir, Bilgedir."},{"n":5,"t":"Ve inanan erkeklerle inanan kadınları, içinden ırmaklar akan cennetlere ebedi kalmak üzere soksun ve onların günahlarını örtsün. Elbette bu, ALLAH'ın katında büyük bir başarıdır."},{"n":6,"t":"Ve ALLAH hakkında kötü düşünceler besleyen ikiyüzlü erkeklerle ikiyüzlü kadınları ve putperest erkeklerle putperest kadınları cezalandırsın. Kötülükleri geri tepecektir. ALLAH onlara gazaplanmış, onları lanetlemiş ve onlar için cehennemi hazırlamıştır. Orası ne kötü bir dönüş yeridir."},{"n":7,"t":"Göklerin ve yerin orduları ALLAH'a aittir. ALLAH Üstündür, Bilgedir."},{"n":8,"t":"Biz seni bir tanık, bir müjdeci ve bir uyarıcı olarak gönderdik."},{"n":9,"t":"Ki siz insanlar, ALLAH'a ve elçisine inanasınız ve O'na saygı gösteresiniz, O'nu dinleyesiniz ve sabah akşam O'nu yüceltesiniz. Allah'ın Elçilerini Desteklemelisiniz"},{"n":10,"t":"Sana bağlılık sözü verenler, ALLAH'a bağlılık sözü vermişlerdir. ALLAH'ın eli onların elleri üzerindedir. Kim sözünü bozarsa, kendi aleyhine bozmuş olur. ALLAH'a verdiği sözü yerine getirene ise büyük bir ödül vereceğiz."},{"n":11,"t":"Araplardan geride kalanlar, \"Paralarımız ve çoluk çocuğumuz bizi alıkoydu, bizim için bağışlanma dile,\" diyeceklerdir. Onlar gönüllerindekini değil, dilleriyle söylerler. De ki, \"Sizin için bir zarar veya yarar dilerse ALLAH'ın bu dileğine kim engel olabilir?\" Oysa ALLAH tüm yaptıklarınızdan haberdardır."},{"n":12,"t":"Aslında siz, elçinin ve inananların ebedi olarak ailelerine dönmeyeceklerini sandınız ve bu düşünce gönlünüze hoş gelmişti. Kötü hayaller kurup durdunuz ve sonunda bayağı bir topluluk oldunuz."},{"n":13,"t":"Kim ALLAH'a ve elçisine inanmazsa, biz inkarcılar için bir ateş hazırlamışızdır."},{"n":14,"t":"Göklerin ve yerin yönetimi ALLAH'a aittir. Dileyeni bağışlar ve dileyeni de cezalandırır. ALLAH Bağışlayandır, Rahimdir."},{"n":15,"t":"Savaştan geri kalmış olanlar, siz ganimetleri almak için gittiğinizde, \"Bırakın biz de sizinle gelelim,\" diyecekler. Onlar ALLAH'ın sözünü değiştirmek istiyorlar. De ki, \"Siz bizi izlemiyeceksiniz. Bu ALLAH'ın önceden almış olduğu karardır.\" Bunun üzerine onlar, \"Siz aslında bizi çekemiyorsunuz,\" diyeceklerdir. Doğrusu, onlar pek az söz anlarlar."},{"n":16,"t":"Araplardan geri kalanlara de ki, \"Siz çok güçlü bir topluluğa karşı çağrılacaksınız. Onlar teslim olana kadar onlarla savaşacaksınız. İtaat ederseniz ALLAH size güzel bir ödül verir. Daha önce yüz çevirdiğiniz gibi yüz çevirirseniz sizi acı bir azap ile cezalandırır."},{"n":17,"t":"Köre bir güçlük yoktur, felçliye bir güçlük yoktur, hastaya da bir güçlük yoktur. Kim ALLAH'a ve elçisine uyarsa, O onu içinden ırmaklar akan cennetlere sokar. Kim yüz çevirirse onu da acı bir biçimde cezalandırır."},{"n":18,"t":"ALLAH, ağacın altında sana bağlılık sözü veren inananlardan hoşnut olmuştur. Onların kalplerinde olanı bilmiş, onlara huzur indirmiş ve onları yakın bir zaferle ödüllendirmiştir."},{"n":19,"t":"Ek olarak, birçok ganimet ele geçirdiler. ALLAH Üstündür, Bilgedir."},{"n":20,"t":"ALLAH sizin birçok ganimet ele geçireceğinizi size söz vermiş bulunuyor. Size bunu çabucak verdi ve halkın ellerini sizden çekti. Böylece bunu inananlar için bir delil kıldı ve sizi dosdoğru yola iletti."},{"n":21,"t":"Güç yetirmediğiniz diğer gruba gelince, onları ALLAH kuşatmıştır. ALLAH elbette her şeye gücü yetendir."},{"n":22,"t":"İnkarcılar sizinle savaşsalardı dönüp kaçarlardı. Sonra ne bir sahip, ne de bir yardımcı bulamazlardı."},{"n":23,"t":"Öteden beri uygulanan ALLAH'ın sünneti (sistemi) budur. ALLAH'ın sünnetinde bir değişme bulamazsın."},{"n":24,"t":"Sizi onlara karşı üstün getirdikten sonra Mekke'nin göbeğinde onların ellerini yakanızdan sizin de ellerinizi onların yakasından çeken odur. ALLAH yaptıklarınızı görendir."},{"n":25,"t":"Onlar inkar edenlerdir, sizi Kutsal Mescitten ve kurbanları yerine ulaşmaktan alıkoyanlardır. Kendilerini tanımadığınız için inciteceğiniz inanan erkekler ve inanan kadınlar bulunmasaydı ve böylece onlardan dolayı bilmeden kendinizi üzmeniz ihtimali olmasaydı... Böylece ALLAH dileyeni rahmetine sokar. Birbirleriyle karışmış halde olmasalardı onlardan inkar edenleri acı bir azapla cezalandırırdık. Cahiliyye Bağnazlığı"},{"n":26,"t":"İnkar edenler, gönüllerindeki öfke ve bağnazlığı, cahiliyye döneminin fanatizmini ateşlediklerinde, ALLAH elçisinin ve inananların üzerine huzurunu indirmiş ve onların erdemlilik sözünü tutmalarını sağlamıştı. Onlar buna tam yaraşan ve hakkeden kimselerdi. ALLAH herşeyi bilendir."},{"n":27,"t":"ALLAH elçisinin rüyasını gerçekleştirdi: \"ALLAH dilerse, güvenlik içinde, başlarınızı (saçlarınızı) traş etmiş ve kısaltmış olarak Kutsal Mescide gireceksiniz. Bir korku duymayacaksınız. Sizin bilmediklerinizi bildiğinden, size bundan önce acil bir zafer hazırlamıştır.\" Büyük Haber"},{"n":28,"t":"O, tüm dinlere üstün kılmak üzere elçisini hidayetle ve gerçek dinle gönderendir. Tanık olarak ALLAH yeterlidir. İnananların Özellikleri"},{"n":29,"t":"ALLAH'ın elçisi Muhammed ve beraberinde bulunanlar inkarcılara karşı sert ve kendi aralarında ise merhametlidirler. Onları, eğilip secde ederek ALLAH'tan lütuf ve hoşnutluk dilerken görürsün. Yüzlerinde secdelerin izleri vardır. Bu, onların Tevrat'taki nitelikleridir. İncil'deki nitelikleri ise, filizini çıkarıp güçlendirmiş ve kalınlaşıp gövdesi üzerine dikilerek ekincileri sevindiren bitki gibidir. O, onlarla inkarcıları öfkelendirir. ALLAH, onlardan inanıp erdemli davrananlara bağışlanma ve büyük bir ödül söz vermiştir."}]},{"id":49,"name":"ODALAR (HUCURAT) SÛRESİ","verses":[{"n":1,"t":"Ey inananlar, ALLAH'ın ve elçisinin huzurunda öne geçmeyiniz. ALLAH'ı dinleyiniz. ALLAH İşitir, Bilir."},{"n":2,"t":"Ey inananlar, sesinizi peygamberin sesinin üstüne çıkarmayın ve birbirinize bağırdığınız gibi ona bağırmayın. Yoksa siz farketmeden işleriniz boşa gider."},{"n":3,"t":"Seslerini ALLAH'ın elçisinin huzurunda kısanlar öyle kimselerdir ki, ALLAH onların kalplerini erdemlilik için uygun hale getirmiştir. Onlar için bağışlanma ve büyük bir ödül vardır."},{"n":4,"t":"Odaların/duvarların ardından sana seslenenlerin çoğu düşüncesiz kimselerdir."},{"n":5,"t":"Sen yanlarına çıkıncaya kadar sabretselerdi kendileri için daha iyi olurdu. ALLAH Bağışlayandır, Rahimdir. Söylentilere İnanmadan Önce Araştır"},{"n":6,"t":"Ey inananlar, kötü huylara sahip birisi size bir haber getirirse onu araştırınız. Yoksa bilmeden bir topluluğa karşı haksızlık edersiniz ve daha sonra yaptığınızdan pişmanlık duyarsınız."},{"n":7,"t":"Bilesiniz ki ALLAH'ın elçisi aranızdadır. İşlerin çoğunda sizlere uysaydı sıkıntıya düşerdiniz. Fakat, ALLAH inancı size sevdirdi ve onu gönüllerinizde süsledi; inkarı, kötülüğü ve isyanı ise size çirkin gösterdi. İşte doğruyu izleyenler bunlardır."},{"n":8,"t":"ALLAH'ın lütfu ve nimeti böyledir. ALLAH Bilendir, Bilgedir. İnananların Arasını Düzeltin"},{"n":9,"t":"İnananlardan iki grup birbirleriyle savaşırlarsa onların arasını bulun. Onlardan biri ötekine saldırırsa, ALLAH'ın buyruğuna dönünceye kadar saldırgan grupla savaşın. Dönerse onların arasını tarafsızca düzeltin ve adaletli davranın. ALLAH adaletli davrananları sever. Gerçek Aile"},{"n":10,"t":"İnananlar kardeştirler. Kardeşlerinizin arasını düzeltin. ALLAH'ı sayın ki merhamet edilesiniz."},{"n":11,"t":"Ey inananlar, bir topluluk diğer bir topluluk ile alay etmesin, belki onlar kendilerinden daha iyidirler. Kadınlar da kadınlarla alay etmesinler, belki onlar kendilerinden daha iyidirler. Birbirinizi ayıplamayın ve birbirinizi, küçük düşürücü kelimelerle çağırmayın. İnançtan sonra yoldan çıkmak ne kötü bir isimdir. Kim tevbe etmezse onlar zalimlerdir."},{"n":12,"t":"Ey inananlar, zandan tümüyle sakının, çünkü zannın bir kısmı günahtır. Birbirinizin gizli şeylerini araştırmayın ve birbirinizi arkadan çekiştirmeyin. Ölü kardeşinizin etini yemekten hoşlanır mısınız? Elbette ondan iğrenirsiniz. ALLAH'ı dinleyin. ALLAH tevbeleri kabul edendir, Rahimdir. Halkın Arasındaki Ayırımın Biricik Kriteri"},{"n":13,"t":"Ey halk, sizi bir erkek ile bir dişiden yarattık ve birbirinizle tanışmanız için sizi ırklara ve boylara ayırdık. ALLAH yanında sizin en değerliniz en erdemli olanınızdır. ALLAH Bilendir, Haberdardır. Müslüman ve Mümin"},{"n":14,"t":"Araplar \"İnandık,\" dediler. De ki, \"Siz inanmadınız, fakat inanç kalbinize girinceye kadar, 'teslim olduk' deyin. ALLAH'a ve elçisine uyarsanız yaptıklarınızdan hiç bir şeyi eksiltmez. ALLAH Bağışlayandır, Rahimdir."},{"n":15,"t":"İnananlar onlardır ki, ALLAH'a ve elçisine inandılar, sonra kuşku beslemediler ve ALLAH yolunda paraları ve canlarıyla savaşım verdiler. Onlar doğru olanlardır."},{"n":16,"t":"De ki, \"ALLAH'a dininizi mi öğretiyorsunuz? ALLAH göklerde ve yerde olanı bilir. ALLAH her şeyi bilendir.\" Kim Kime Minnet Borçludur?"},{"n":17,"t":"Müslüman (teslim) oldular diye seni minnet altında bırakmak istiyorlar. De ki, \"Müslümanlığınızı başıma kakmayın. Aslında, sizi inanca ulaştırdığı için ALLAH sizi kendisine borçlu görür, eğer doğru kimselerseniz.\""},{"n":18,"t":"ALLAH göklerin ve yerin gizemlerini bilir. ALLAH yaptıklarınızı görendir."}]},{"id":50,"name":"Q (QAF) SÛRESİ","verses":[{"n":1,"t":"Q, şanlı Kuran'a andolsun.*"},{"n":2,"t":"İçlerinden bir uyarıcının kendilerine gelmesini tuhaf karşıladılar! Kafirler, \"Bu tuhaf bir şey\" dediler, 3. \"Ölüp toprak olduktan sonra mı? Bu imkansız bir dönüştür.\""},{"n":4,"t":"Yeryüzünün onlardan kimi alıp götürdüğünü bilmişizdir. Yanımızda koruyan bir kayıt vardır. 5. Oysa onlar gerçek kendilerine geldiği zaman onu yalanladılar; kararsızlık içindedirler."},{"n":6,"t":"Üstlerindeki göğe bakmadılar mı, onu hiçbir çatlağı olmadan nasıl yaptık ve onu nasıl süsledik?"},{"n":7,"t":"Yeri ise yaydık, içine dağlar yerleştirdik ve içinde her çeşit güzel bitkiler yetiştirdik."},{"n":8,"t":"Her yönelen kul için bu bir aydınlatma ve mesajdır."},{"n":9,"t":"Ve gökten kutlu bir su indirerek onunla bahçeler ve biçilecek taneler bitirdik."},{"n":10,"t":"Küme küme tomurcuklara sahip yüksek hurma ağaçları yetiştirdik."},{"n":11,"t":"Kullara bir besin olarak. Onunla bölgeyi dirilttik. Çıkış (diriliş) de böyledir."},{"n":12,"t":"Onlardan önce Nuh'un halkı, Res'liler ve Semud da yalanlamıştı."},{"n":13,"t":"Ad, Firavun ve Lut'un kardeşleri..."},{"n":14,"t":"Eyke'liler ve Tubba' halkı da... Hepsi elçileri yalanladılar. Bunun üzerine tehdidim gerçekleşti."},{"n":15,"t":"İlk yaratılıştan yorulduk mu ki? Doğrusu onlar yeni bir yaratılıştan kuşku içindedirler."},{"n":16,"t":"İnsanı biz yarattık ve onun kendi kendine neyi fısıldadığını iyi biliriz. Biz ona şahdamarından daha yakınız."},{"n":17,"t":"Sağında ve solunda iki alıcı melek oturmuş kaydetmektedirler."},{"n":18,"t":"Yanında gözetleyen tanıklar olmaksızın ağzından bir söz çıkmaz."},{"n":19,"t":"Sonunda ölüm sarhoşluğu gerçekten gelmiştir; işte senin kendisinden kaçıp durduğun şey budur."},{"n":20,"t":"Boruya üflenmiştir. Bu, söz verilen gündür."},{"n":21,"t":"Her can yanında bir sürücü ve bir tanık ile gelir."},{"n":22,"t":"Sen tümüyle bundan gafildin. Şimdi biz örtünü kaldırdık; bugün gözün çelik gibi keskindir."},{"n":23,"t":"Yanındaki arkadaşı, \"İşte yanımdaki hazır\" der."},{"n":24,"t":"Haydi ikiniz atın cehenneme her inatçı kafiri,"},{"n":25,"t":"İyiliği engelleyen, azgın, kuşkucuyu..."},{"n":26,"t":"O ki ALLAH ile birlikte başka tanrı edindi. Onu o çetin cezanın içine atın."},{"n":27,"t":"Arkadaşı, \"Rabbim, ben onu azdırmadım; fakat o kendisi derin bir sapıklık içindeydi,\" der."},{"n":28,"t":"O da der ki, \"Huzurumda cekişmeyin. Size daha önceden uyarı göndermiştim.\""},{"n":29,"t":"\"Benim katımda söz değiştirilmez ve ben kullara asla haksızlık etmem.\""},{"n":30,"t":"O gün cehenneme, \"Doldun mu?\" deriz. O, \"Daha yok mu?\" der."},{"n":31,"t":"Erdemlilere ise cennet yaklaştırılır, uzak değildir."},{"n":32,"t":"Bu, size söz verilendir. Her yönelen ve her koruyana,"},{"n":33,"t":"Onlar yalnız başınayken bile Rahman'ı sayarlar ve içtenlikle gelirler."},{"n":34,"t":"Oraya esenlikle girin; bu, sonsuz yaşama günüdür."},{"n":35,"t":"Diledikleri her şeyi elde ederler ve hatta katımızda fazlası da vardır."},{"n":36,"t":"Onlardan önce, onlardan daha güçlü nice nesilleri yok etmiştik. Ülke ülke dolaşmışlardı; kurtuluşu var mı?"},{"n":37,"t":"Bunda, zeka sahibi olan yahut tanık olarak kulak veren herkes için bir mesaj vardır."},{"n":38,"t":"Gökleri, yeri ve aralarındakileri altı günde yarattık. Hiç bir yorgunluk da duymadık.*"},{"n":39,"t":"Onların söylediklerine sabret ve güneşin doğuşundan ve batışından önce Rabbini överek yücelt."},{"n":40,"t":"Geceleyin O'nu yücelt ve secdelerin ardından da..."},{"n":41,"t":"Çağırıcının yakın bir yerden çağıracağı güne kulak ver."},{"n":42,"t":"O gün o çığlığı kesinlikle duyarlar; bu, çıkış günüdür."},{"n":43,"t":"Biz diriltiriz, öldürürüz ve dönüş de bizedir."},{"n":44,"t":"O gün yer onlardan dolayı yarılıverir. Bu, bizim için kolay bir toparlamadır. Kuran İle Öğüt Verin"},{"n":45,"t":"Biz onların ne konuştuğunu iyi biliyoruz. Sen onların üzerinde bir zorba değilsin. Uyarılarımdan korkanlara sen bu Kuran ile öğüt ver."}]},{"id":51,"name":"SAVURANLAR (ZARİYAT) SÛRESİ","verses":[{"n":1,"t":"Esip savuranlara,"},{"n":2,"t":"Yük yüklenenlere,"},{"n":3,"t":"Kolayca akıp gidenlere,"},{"n":4,"t":"Ve işi bölümlere ayıranlara andolsun ki"},{"n":5,"t":"Size söz verilen kuşkusuz bir gerçektir."},{"n":6,"t":"Yargılama kesinlikle gerçekleşecektir."},{"n":7,"t":"Mükemmel çizilmiş yörüngelere sahip göğe andolsun ki"},{"n":8,"t":"Siz ihtilaf içindesiniz."},{"n":9,"t":"Çevrilen, ondan çevrilir."},{"n":10,"t":"Kahrolsun palavracılar,"},{"n":11,"t":"Ki şaşkınlıkları içinde umursamıyorlar."},{"n":12,"t":"Yargı Gününün zamanını sorarlar."},{"n":13,"t":"O gün onlar ateşe sunulacaklardır."},{"n":14,"t":"Cezanızı tadın, meydan okumakta olduğunuz şey budur işte!"},{"n":15,"t":"Erdemliler cennetlerdedir, pınar başlarındadır."},{"n":16,"t":"Rab'lerinin kendilerine verdiğini alırlar. Çünkü onlar bundan önce güzel davranıyorlardı."},{"n":17,"t":"Geceleri az uyurlardı."},{"n":18,"t":"Seher vakitlerinde bağışlanma dilerlerdi."},{"n":19,"t":"Paralarında, isteyenler ve yoksullar için bir pay vardı."},{"n":20,"t":"Kesin inananlar için yerde ayetler (işaret ve deliller) vardır."},{"n":21,"t":"Kendi içinizde de... Görmez misiniz?"},{"n":22,"t":"Gökte rızkınız ve size söz verilenler vardır."},{"n":23,"t":"Göğün ve yerin Rabbine andolsun ki sizin konuşmanız nasıl bir gerçek ise, bu da öylece bir gerçektir. İbrahim'e Müjde ve Lut Halkına Azap"},{"n":24,"t":"İbrahim'in ağırlanan konuklarının haberini aldın mı?"},{"n":25,"t":"Onun huzuruna girmişlerdi ve \"Selam (barış)\" demişlerdi. O da, \"Selam size, yabancılar!\" demişti."},{"n":26,"t":"Ailesine yöneldi ve sonra semiz bir buzağı ile geldi."},{"n":27,"t":"Onu onların önüne sürüp, \"Yemez misiniz?\" dedi."},{"n":28,"t":"Onlardan bir korku duydu. Bunun üzerine onlar, \"Korkma\" dediler ve ona bilgin bir oğul müjdelediler."},{"n":29,"t":"Karısı hayret içinde, (hayretten) yüzüne vurarak, \"Kısır bir yaşlı kadın!\" dedi."},{"n":30,"t":"Dediler ki, \"Rabbin böyle söylemiştir. O Bilgedir, Bilendir.\""},{"n":31,"t":"(İbrahim:) \"Ey elçiler asıl göreviniz nedir?\" dedi."},{"n":32,"t":"Dediler ki, \"Biz suçlu bir topluluğa gönderildik.\""},{"n":33,"t":"\"Üzerlerine balçıktan taşlar göndermek için...\""},{"n":34,"t":"\"Rabbin tarafından taşkınlar için işaretlenmiş olarak.\""},{"n":35,"t":"Sonra, orada inananlardan kim varsa çıkardık."},{"n":36,"t":"Zaten orada bir evin dışında hiç bir müslüman bulmadık."},{"n":37,"t":"Acı azaptan korkacaklar için orada bir ders bıraktık. Musa, Ad, Semud ve Nuh Halkı"},{"n":38,"t":"Musa'da da (bir ders vardır). Onu Firavun'a apaçık bir delil ile göndermiştik."},{"n":39,"t":"Erkanıyla birlikte yüz çevirdi ve \"Ya bir büyücüdür, ya da bir deli,\" dedi."},{"n":40,"t":"Onu ve askerlerini yakalayıp denize attık. Bu sonucu haketmişti."},{"n":41,"t":"Ad halkında da (bir ders vardır). Üzerlerine korkunç bir rüzgar gönderdik."},{"n":42,"t":"Rastgeldiği her şeyi toz toprağa çeviriyordu."},{"n":43,"t":"Semud'da da (bir ders vardır). Onlara, \"Belli bir süreye kadar keyfinize bakın\" denmişti."},{"n":44,"t":"Rab'lerinin emrine karşı geldiler. Bunun üzerine bakınırlarken onları bir yıldırım çarptı."},{"n":45,"t":"Ne kalkabildiler, ne de yardım görebildiler."},{"n":46,"t":"Daha önce de Nuh halkını... Onlar yoldan çıkmış bir topluluktu. \"Evrenin Genişlemesi Teorisi\" Doğrulanıyor"},{"n":47,"t":"Göğü gücümüzle biz kurduk ve onu biz genişletmekteyiz."},{"n":48,"t":"Yeri biz döşedik; ne güzel döşeyiciyiz."},{"n":49,"t":"Öğüt almanız için de herşeyi çiftler halinde yarattık."},{"n":50,"t":"Öyleyse ALLAH'a kaçınız. Ben, O'nun tarafından size gönderilmiş bir uyarıcıyım."},{"n":51,"t":"ALLAH ile birlikte başka tanrılar edinmeyin. Ben O'nun tarafından size gönderilmiş bir uyarıcıyım."},{"n":52,"t":"İşte böyle, onlardan öncekilere her ne zaman bir elçi geldiyse, \"Bu, bir büyücüdür,\" yahut \"Bu bir delidir,\" derlerdi."},{"n":53,"t":"Bunu (söylemeyi) birbirlerine öğütlediler mi? Doğrusu, onlar sınırı aşan bir topluluktur."},{"n":54,"t":"Onlardan yüz çevir; sen kınanacak değilsin. * 51:54 Yunus peygamber görevini tamamlamadan halkından yüz çevirdiği için kınanmıştı (37:142)."},{"n":55,"t":"Hatırlat, çünkü hatırlatmak inananlara yarar sağlar. Yaratılışımızın Amacı"},{"n":56,"t":"Cinleri ve insanları ancak bana kulluk etmeleri için yarattım."},{"n":57,"t":"Onlardan ne bir rızık istiyorum, ne de beni beslemelerini."},{"n":58,"t":"Kuşkusuz Rızık veren, Kuvvet sahibi ve Güçlü olan ancak ALLAH'tır."},{"n":59,"t":"Elbette, bu zulmedenlerin de (geçmiş) yoldaşlarının payına benzer bir payları vardır."},{"n":60,"t":"Kendilerine söz verilen günden dolayı vay haline şu inkarcıların!"}]},{"id":52,"name":"SİNA DAĞI (TUR) SÛRESİ","verses":[{"n":1,"t":"Andolsun Tur'a,"},{"n":2,"t":"Kaydedilmiş kitaba,"},{"n":3,"t":"Ki parşömen üzerinde yayımlanmış."},{"n":4,"t":"Sık sık ziyaret edilen Eve (Kabe'ye),"},{"n":5,"t":"Yükseltilmiş tavana,"},{"n":6,"t":"Ve kaynatılmış denize..."},{"n":7,"t":"Rabbinin cezalandırması kesinlikle gerçekleşecektir."},{"n":8,"t":"Onu engelleyecek hiç bir güç yoktur."},{"n":9,"t":"O gün gök sallanıp sarsılacak,"},{"n":10,"t":"Dağlar yürütülüp silinecek,"},{"n":11,"t":"Yalanlayanların vay haline o gün!"},{"n":12,"t":"Onlar ki bir bataklıkta oynamaktadırlar."},{"n":13,"t":"Cehennem ateşine itildikleri gün:"},{"n":14,"t":"İşte, yalanlamakta olduğunuz Ateş budur."},{"n":15,"t":"Bu bir büyü müdür, yoksa siz mi görmüyorsunuz?"},{"n":16,"t":"Orda yanın. İster sabredin, ister sabretmeyin sizin için değişmeyecektir. Yaptığınızın karşılığını görmektesiniz."},{"n":17,"t":"Erdemliler bahçeler ve nimetler içindedir."},{"n":18,"t":"Rab'lerinin kendilerine vermiş olduğu şeylerden zevk duyarlar. Rab'leri onları cehennem azabından korumuştur."},{"n":19,"t":"Yapmış olduklarınıza karşılık afiyetle yeyin, için."},{"n":20,"t":"Dizilmiş koltuklara yaslanmışlardır ve onları güzel eşlerle eşlendirmişizdir."},{"n":21,"t":"Soyları tarafından izlenen inananlara soylarını da katarız ve onların yaptıklarından hiç bir şeyi eksiltmeyiz. Herkes kazanmış olduğu şeylerin bir ipoteğidir."},{"n":22,"t":"Onlara canlarının istediği meyveden ve etten bol bol veririz."},{"n":23,"t":"Orada birbirlerinden kadeh kapışırlar, onda ne bir saçmalama, ne de bir günaha girme vardır."},{"n":24,"t":"Çevrelerinde, inciler gibi korunmuş kendilerine ait hizmetkarlar (servis için) dolaşıp durur."},{"n":25,"t":"Birbirlerine dönüp geçmişi anarlar:"},{"n":26,"t":"\"Daha önce halkımızın arasında çekinirdik,\" derler,"},{"n":27,"t":"\"ALLAH bize iyilik etti de bizi içe işleyen azaptan korudu.\""},{"n":28,"t":"\"Biz daha önce O'na yalvarırdık; O, İyilik edendir, Rahimdir.\" Elçi"},{"n":29,"t":"Sen öğüt ver. Rabbinin sana olan iyiliği sayesinde sen ne bir kahinsin, ne de deli."},{"n":30,"t":"Yoksa, \"O bir şairdir, onun ölmesini bekliyoruz.\" mu diyorlar?"},{"n":31,"t":"De ki, \"Bekleyedurun; ben de sizinle birlikte beklemekteyim.\""},{"n":32,"t":"Bunları rüyalarının etkisiyle mi söylüyorlar, yoksa onlar haddi aşan bir topluluk mudur?"},{"n":33,"t":"Yoksa, \"Onu kendi uydurdu\" mu diyorlar? Hayır, onlar inanmazlar. Kuran'ın Benzeri Bir Hadis Yoktur"},{"n":34,"t":"Doğru sözlüler iseler bunun benzeri bir hadis getirsinler."},{"n":35,"t":"Onlar yokluktan mı yaratıldılar? Yoksa yaratanlar kendileri mi?"},{"n":36,"t":"Gökleri ve yeri onlar mı yarattılar? Doğrusu, onlar kesin bir inanca sahip olmazlar."},{"n":37,"t":"Yoksa Rabbinin hazineleri onların mı yanındadır? Onlar mı kontrol etmektedirler?"},{"n":38,"t":"Yoksa üzerine çıkıp (vahyi) dinledikleri bir merdivenleri mi var? Öyleyse dinleyicileri açık bir delil getirsin."},{"n":39,"t":"Yoksa kızlar O'na, oğullar size mi?"},{"n":40,"t":"Yoksa sen onlardan bir ücret istiyorsun da bu onlara ağır bir borç mu yüklüyor?"},{"n":41,"t":"Yoksa gizemlerin bilgisine mi sahipler ve onu kendileri mi yazıyorlar?"},{"n":42,"t":"Yoksa bir planı mı uygulamak istiyorlar? Halbuki kafirlerin kendileri bir plana mahkum edilmiştir."},{"n":43,"t":"Yoksa ALLAH'tan başka tanrıları mı vardır? ALLAH onların ortak koştuklarından yücedir."},{"n":44,"t":"Gökten bir parçanın düştüğünü görseler, \"Bulut kümesidir!\" derler."},{"n":45,"t":"Çarpılacakları günlerine kavuşuncaya kadar onları bırak."},{"n":46,"t":"O gün, planları kendilerini hiç bir şeyden korumayacak ve yardım da görmeyeceklerdir."},{"n":47,"t":"Zulmedenlere bunun dışında bir ceza daha vardır, fakat çokları bilmezler."},{"n":48,"t":"Rabbinin hükmü gerçekleşinceye kadar sabret sen gözlerimiz önündesin ve kalktığın zaman Rabbini överek yücelt."},{"n":49,"t":"Geceleyin ve yıldızlar kaybolurken O'nu yücelt."}]},{"id":53,"name":"YILDIZLAR (NECM) SÛRESİ","verses":[{"n":1,"t":"Düşerken yıldızlara andolsun."},{"n":2,"t":"Arkadaşınız (Muhammed) ne sapmıştır, ne de azmıştır."},{"n":3,"t":"Ne de kendi kişisel arzusundan konuşmaktadır."},{"n":4,"t":"O (Kuran) ancak ve ancak bildilen bir vahiydir."},{"n":5,"t":"Onu, büyük güce sahip olan öğretmiştir."},{"n":6,"t":"Üstün otoritenin sahibi göründü,"},{"n":7,"t":"En yüksek ufukta."},{"n":8,"t":"Sonra inip yaklaştı."},{"n":9,"t":"Mesafe iki yay kadar veya daha yakın oldu."},{"n":10,"t":"Ve sonra kuluna ne bildirilecekse onu vahyetti."},{"n":11,"t":"Gördüğünü gönlü yalanlamadı."},{"n":12,"t":"Onun gördüğü hakkında kendisiyle tartışıyor musunuz?"},{"n":13,"t":"Onu bir kez daha görmüştü."},{"n":14,"t":"En son noktada."},{"n":15,"t":"Ki yanında barınılacak cennet vardır."},{"n":16,"t":"Tüm bölge olağanüstü biçimde kuşatılmıştı."},{"n":17,"t":"Göz şaşmadı, sınırı da aşmadı."},{"n":18,"t":"Rabbinin büyük ayetlerini gördü."},{"n":19,"t":"Gördünüz mü (dişi putlarınız olan) Lat ve Uzza'yı?"},{"n":20,"t":"Ve üçüncüleri olan Menat'ı?"},{"n":21,"t":"Erkekler sizin de dişiler O'nun mu?"},{"n":22,"t":"Ne de insafsız bir paylaşma!"},{"n":23,"t":"Onlar, sizin ve atalarınızın taktığı isimlerden başka bir şey değildir ve ALLAH onlar için hiç bir delil indirmemiştir. Kendilerine, Rab'lerinde bir yol gösterici geldiği halde, sadece kuruntuları ve kişisel arzularını izliyorlar. * 53:19-23 Mekke müşrikleri, soyut bir putperestlik anlayışına sahiptiler. İbrahim döneminde yaygın olan heykellere tapma biçimindeki putperestlik İbrahim'in mücadelesi sonucunda biçim değiştirmek zorunda kaldı. İbrahim'in yolunu izlediklerini sanan Mekke müşrikleri, Tanrı'ya yakın sandıkları meleklerin ve ölmüş evliyaların isimlerini şefaat amacıyla anıyorlar (39:3) ve kendilerini tektanrıcı sanıyorlardı (6:23; 16:35). Muhammed'den sonra, peygamberle birlikte birçok arkadaşını ve \"evliyaları\" putlaştıran ve şefaatleri için onların isimlerini anan müşrikler, kendileriyle Mekke müşrikleri arasındaki benzerliği kaldırmak için onların heykellere taptıklarını uydurdular. Ne var ki hayali heykellerin biçimi konusunda ihtilafa düştüler. Kuran'a göre Mekke müşrikleri İbrahim'in kurduğu Mescid'de namaz kılıyor, hac ediyor, oruç tutuyorlardı (8:35; 9:19, 45, 54; 2:199)."},{"n":24,"t":"İnsan her umduğuna kavuşacak mıdır?"},{"n":25,"t":"Son da ilk de ALLAH'ındır."},{"n":26,"t":"Göklerdeki meleklerin bile şefaati bir yarar sağlamaz. Ancak ALLAH'ın dilediği kimse için izin vermesinden ve O'nun rızasına uygun olduktan sonra... * 53:26 Bak 2:48."},{"n":27,"t":"Ahirete inanmıyanlar melekleri dişi olarak nitelendirmektedirler."},{"n":28,"t":"Onların bu konuda bir bilgileri yoktur, sadece sanıları izlemektedirler ve sanılar gerçeğin yerini tutmaz. Arkadaşını Dikkatle Seç"},{"n":29,"t":"Mesajımızdan yüz çeviren ve dünya hayatından başkasını arzulamıyan kimseyi önemseme."},{"n":30,"t":"İşte onların ulaştıkları bilgilerinin düzeyi budur. Elbette, Rabbin yolundan sapanı iyi bilir, doğru yolda olanı da iyi bilir."},{"n":31,"t":"Göklerde ve yerde ne varsa ALLAH'ındır. Kötülük işleyenleri yaptıklarından dolayı cezalandıracaktır ve güzel davrananları da ödüllendirecektir. Kendinizi Günahsız Görmeyin"},{"n":32,"t":"Onlar, büyük günahlardan ve kötülüklerden kaçınırlar, yalnız küçük suçlar işlerler. Rabbinin bağışlaması engindir. Sizi topraktan yaratırken ve annelerinizin karınlarında cenin (fetus) durumundayken sizi iyi bilmektedir. Öyleyse kendinizi (övüp) temize çıkarmayın. O, erdemlileri iyi bilir."},{"n":33,"t":"Gördün mü o yüz çevireni?"},{"n":34,"t":"Ender olarak ve pek az verdi."},{"n":35,"t":"Gizemlerin bilgisine mi sahiptir ki (geleceği) görüyor?"},{"n":36,"t":"Ona Musa'nın öğretisi hakkında bilgi verilmedi mi?"},{"n":37,"t":"Ve sözünü gerçekleştiren İbrahim'in?:"},{"n":38,"t":"Ki hiçbir kimse bir başkasının günah yükünü taşımaz,"},{"n":39,"t":"İnsan için ancak kendi çalışması vardır."},{"n":40,"t":"Ve onun çalışması da yakında görülecektir."},{"n":41,"t":"Sonra kendisine ödülü tam olarak verilecektir."},{"n":42,"t":"Son varış Rabbinedir. Mutluluğun Tanrı'nın Elinde"},{"n":43,"t":"O'dur seni güldüren ve ağlatan."},{"n":44,"t":"O'dur öldüren ve dirilten."},{"n":45,"t":"O'dur iki çifti yaratan; erkeği ve dişiyi..."},{"n":46,"t":"Atıldığı zaman bir damlacık meniden. * 53:45-46 Çocuğun erkek ve dişi oluşu erkeğin menisindeki sperm tarafından belirlenmektedir. Bak 4:82."},{"n":47,"t":"O'na aittir tekrar yaratmak."},{"n":48,"t":"O'dur Zengin eden, yoksul yapan."},{"n":49,"t":"O'dur Şira galaksisinin Rabbi."},{"n":50,"t":"O'dur helak eden eski Ad halkını,"},{"n":51,"t":"Semudu da bırakmadı,"},{"n":52,"t":"Ve ondan önce Nuh'un halkını da; onlar çok zalim ve çok azgın kimselerdi."},{"n":53,"t":"Yıkılıp batırılmış olanlar (Sodom ve Gomora), en bayağılardı."},{"n":54,"t":"Onları örten örttü."},{"n":55,"t":"O halde Rabbinin hangi nimetlerinden kuşkulanırsın?"},{"n":56,"t":"Bu, eski uyarıcılardan bir uyarıcıdır."},{"n":57,"t":"Kaçınılmaz olan yaklaşmıştır."},{"n":58,"t":"ALLAH'tan başkası onu kaldıramaz."},{"n":59,"t":"Bu sözü mü tuhaf karşılıyorsunuz?"},{"n":60,"t":"Gülüyorsunuz da ağlamıyorsunuz?"},{"n":61,"t":"Ve aylak aylak oyalanıyorsunuz?"},{"n":62,"t":"Haydi ALLAH'a secde edin, kulluk edin."}]},{"id":54,"name":"AY (KAMER) SÛRESİ","verses":[{"n":1,"t":"Saat (dünyanın sonu) yaklaştı ve ay yarıldı."},{"n":2,"t":"Bir mucize görseler yüz çevirirler ve, \"Süregelen bir büyüdür\" derler."},{"n":3,"t":"Yalanladılar; arzularına ve tümüyle statükoya uydular. * 54:3 Ayet, başka türlü okunarak, \"Yalanladılar, arzularına uydular. Halbuki her iş yerini bulacaktır,\" diye de anlaşılabilir."},{"n":4,"t":"Oysa, kötülüklerini engelleyecek uyarılar dolu haberler kendilerine gelmiş bulunuyor."},{"n":5,"t":"Bu üstün bir hikmettir; ancak uyarılar yarar sağlamıyor."},{"n":6,"t":"Onlara aldırma; çağırıcının, görülmemiş ve tanınmamış bir şeye çağıracağı gün,"},{"n":7,"t":"Gözleri zillet içinde mezarlardan çıkarlar; tıpkı saçılmış çekirgeler gibi..."},{"n":8,"t":"Çağırıcıya doğru koşarlarken, inkarcılar, \"Bu zorlu bir gündür,\" derler."},{"n":9,"t":"Onlardan önce de Nuh'un halkı yalanlamıştı. Kulumuzu yalanlayıp, \"Delidir\" dediler. Nitekim o engellendi."},{"n":10,"t":"Rabbini çağırdı, \"Ben yenildim; bana yardım et.\""},{"n":11,"t":"Bunun üzerine göğün kapılarını boşanan sularla açtık."},{"n":12,"t":"Yerden de pınarlar fışkırttık. Nihayet sular, daha önce belirlenmiş seviyeye ulaştılar."},{"n":13,"t":"Onu ağaç lifleri ile (bağlanmış) kütükler üzerinde taşıdık. * 54:13 Nuh ile birlikte bir kaç inananı ve Nuh'un çiftliğindeki hayvanlardan birer çifti taşıyan bir su salının bir buharlı gemi olduğu ieri sürenler, Nuh'un yaşayıp dolaştığı bölgeyle sınırlı tufanı dünya çapında bir tufan olarak sunanlar gerçeği abartmışlardır. Nitekim bazı Hristiyanlar hala dağ tepelerinde gemi parçalarını aramaktadır; üstelik yanlış yerde. Bak: 11:44."},{"n":14,"t":"Reddedilmiş olan kişiye bir ödül olarak gözetimimiz altında akıp gidiyordu."},{"n":15,"t":"Bunu bir ders olarak bıraktık. Öğüt alan yok mudur? Kuran Anlaşılır Bir Mesajdır"},{"n":16,"t":"Cezalandırmam ve uyarılarım nasılmış!"},{"n":17,"t":"Kuran'ı mesaj için kolaylaştırdık; öğüt alan yok mudur?"},{"n":18,"t":"Ad da yalanladı. Cezalandırmam ve uyarılarım nasılmış!"},{"n":19,"t":"Uğursuzluk üstüne uğursuzluğa sahip bir günde üzerlerine vahşi bir rüzgar gönderdik."},{"n":20,"t":"İnsanları, sanki köklerinden koparılmış hurma kötükleriymiş gibi yıkıyordu."},{"n":21,"t":"Cezalandırmam ve uyarılarım nasılmış!"},{"n":22,"t":"Kuran'ı mesaj için kolaylaştırdık; öğüt alan yok mudur?"},{"n":23,"t":"Semud da uyarıları yalanladı."},{"n":24,"t":"Dediler ki, \"Bizden bir insana mı uyalım? O zaman biz sapar ve cehenneme gireriz.\""},{"n":25,"t":"\"Mesaj aramızdan ona mı verildi? O, yalancı küstahın biridir.\""},{"n":26,"t":"Yalancı küstahın kim olduğunu yarın öğreneceklerdir."},{"n":27,"t":"Deveyi bir sınav olarak göndereceğiz. Onları gözetle, sabırlı ol."},{"n":28,"t":"Onlara, suyun (deveyle) aralarında paylaşılacağını bildir. Her içim sırayla sunulacaktır."},{"n":29,"t":"Bir arkadaşlarını çağırdılar, o da çekip (deveyi) kesti."},{"n":30,"t":"Cezalandırmam ve uyarılarım nasılmış!"},{"n":31,"t":"Üzerlerine bir tek patlama gönderdik ve onlar ağılcının topladığı saman yığınına döndüler."},{"n":32,"t":"Kuran'ı mesaj için kolaylaştırdık; öğüt alan yok mudur?"},{"n":33,"t":"Lut halkı da uyarıları yalanlamıştı."},{"n":34,"t":"Üzerlerine taş yağdıran bir fırtına gönderdik, yalnız Lut'un ailesini seher vakti kurtardık."},{"n":35,"t":"Katımızdan bir iyilik olarak. Şükredeni işte böyle ödüllendiririz."},{"n":36,"t":"Onları bu yakalayışımıza karşı uyarmıştı; ancak onlar uyarıları kuşkuyla karşıladılar."},{"n":37,"t":"Onun konuklarına göz diktiler, biz de onları kör ettik. Azabımı ve uyarılarımı tadın bakalım."},{"n":38,"t":"Ertesi gün, yaman bir azap sabahlarını kutladı."},{"n":39,"t":"Azabımı ve uyarılarımı tadın bakalım."},{"n":40,"t":"Kuran'ı mesaj için kolaylaştırdık; öğüt alan yok mudur?"},{"n":41,"t":"Firavun'un erkanına da uyarıcılar gitmişti."},{"n":42,"t":"Tüm mucizelerimizi yalanladılar ve biz de onları En üstün ve her şeye gücü yetenin yakalayışı gibi yakaladık."},{"n":43,"t":"Sizin inkarcılarınız onlarınkinden daha mı iyi? Yoksa kitaplarda kendiniz için bir af ilanına mı rastladınız?"},{"n":44,"t":"Yoksa, \"Biz, zafere ulaşacak bir cemaatiz\" mi diyorlar?"},{"n":45,"t":"O cemaat bozguna uğratılacak; dönüp kaçacaklar."},{"n":46,"t":"Saat onları beklemektedir, daha korkunç ve acıdır."},{"n":47,"t":"Suçlular bir sapıklık ve cehennem içindedir."},{"n":48,"t":"Yüzükoyun ateşe sürüklenecekleri gün: \"Cehennemin dokunuşunu tadın.\""},{"n":49,"t":"Biz her şeyi belli bir ölçüyle yaratmışızdır."},{"n":50,"t":"Buyruğumuz göz kırpması gibi anidir."},{"n":51,"t":"Sizin benzerlerinizi yok etmiştik. Yok mu öğüt alan?"},{"n":52,"t":"Tüm yaptıkları kitaplarda kayıtlıdır."},{"n":53,"t":"Küçük ve büyük hepsi yazılmıştır."},{"n":54,"t":"Erdemliler, cennetler (bahçeler) ve ırmaklar içindedir."},{"n":55,"t":"Güçlü Kralın yanında onurlu makamlardadırlar."}]},{"id":55,"name":"RAHMAN SÛRESİ","verses":[{"n":1,"t":"Rahman,"},{"n":2,"t":"Kuran'ı öğretti."},{"n":3,"t":"İnsanı yarattı."},{"n":4,"t":"Ona beyanı (açıklama yeteneğini) öğretti."},{"n":5,"t":"Güneş ve ay bir hesap ile (hareket etmekte) dir."},{"n":6,"t":"Yıldızlar ve ağaçlar secde etmektedirler."},{"n":7,"t":"Göğü yükseltti ve ölçüyü/dengeyi koydu."},{"n":8,"t":"Ki ölçüyü aşmayasınız."},{"n":9,"t":"Ölçüyü adaletle gözetiniz; ölçüyü kaybetmeyiniz."},{"n":10,"t":"Yeryüzünü tüm yaratıklar için yarattı."},{"n":11,"t":"Orada meyvalar, salkımlı hurma ağaçları vardır. * 55:11 Yenilenebilen sistemlere ve üreyen astronotlara sahip olan uzay gemimiz yeryüzüyle en gelişmiş uzay aracımızı karşılaştırınız."},{"n":12,"t":"Kabuklu taneler ve baharatlar."},{"n":13,"t":"(Ey insanlar ve cinler), Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":14,"t":"İnsanı, çömlek gibi kuru bir çamurdan yarattı."},{"n":15,"t":"Cinleri de dumansız ateşten yarattı."},{"n":16,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":17,"t":"İki doğunun ve iki batının Rabbi."},{"n":18,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":19,"t":"İki denizi salmıştır; birbirlerine kavuşuyorlar."},{"n":20,"t":"Aralarında bir engel vardır; birbirinin sınırını aşıp karışmazlar. * 55:20 Bak 25:53."},{"n":21,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":22,"t":"İkisinden de inci ve mercan çıkar."},{"n":23,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":24,"t":"Denizde dağlar gibi akıp giden gemiler O'nundur."},{"n":25,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":26,"t":"Üzerinde bulunan herkes ölümlüdür."},{"n":27,"t":"Sadece Görkemli ve Onurlu Rabbinin varlığı kalıcıdır."},{"n":28,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":29,"t":"Göklerde ve yerde olan herkes O'na yalvarır. O her gün kesintisiz kontrol etmektedir."},{"n":30,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":31,"t":"Ey sorumlu iki topluluk, sizi elbette sorguya çekeceğiz."},{"n":32,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":33,"t":"Ey insanlar ve cinler topluluğu, göklerin ve yerin sınırlarını aşmaya gücünüz yetiyorsa, aşıp geçin. Bir yetkiye sahip olmadan geçemezsiniz."},{"n":34,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":35,"t":"Üzerinize ateşten toplar ve ışınlar gönderilir; yardım görmezsiniz."},{"n":36,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":37,"t":"Gök parçalanıp da, yağ gibi eridiği ve kırmızı bir güle dönüştüğü zaman..."},{"n":38,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":39,"t":"O gün ne insana ne de cine günahından sorulmaz."},{"n":40,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":41,"t":"Suçlular yüzlerinden tanınır ve yaka paça götürülürler."},{"n":42,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":43,"t":"İşte bu, suçluların yalanlayıp durduğu cehennemdir."},{"n":44,"t":"Onunla kaynar su arasında dönüp dolaşırlar."},{"n":45,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":46,"t":"Rabbinin görkeminden korkan (cin ve insan) lar için iki cennet vardır."},{"n":47,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":48,"t":"Türlü besinlerle doludur her ikisi."},{"n":49,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":50,"t":"İçlerinde akan pınarlar vardır."},{"n":51,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":52,"t":"İkisinde de her meyveden iki çeşit vardır."},{"n":53,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":54,"t":"Astarları atlastan yataklara yaslanırlar, her iki cennetin meyveleri pek yakındır."},{"n":55,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":56,"t":"Oralarda, daha önce ne bir insan ne de bir cin tarafından dokunulmamış, bakışlarını dikmiş eşler vardır."},{"n":57,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":58,"t":"Onlar yakut ve mercan gibidirler."},{"n":59,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":60,"t":"İyiliğin karşılığı, yalnız iyilik değil midir?"},{"n":61,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":62,"t":"O ikisinin ötesinde iki cennet daha var."},{"n":63,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":64,"t":"Yemyeşildirler."},{"n":65,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":66,"t":"İkisinde de fışkıran iki kaynak vardır."},{"n":67,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":68,"t":"Her ikisinde de meyvalar, hurmalar ve narlar vardır."},{"n":69,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":70,"t":"Her ikisinde de iyilikler, güzellikler vardır."},{"n":71,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":72,"t":"Çadırlara kapanmış güzeller"},{"n":73,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":74,"t":"Daha önce onlara ne insan ne de cin dokunmamıştı."},{"n":75,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":76,"t":"Yeşil yastıklara ve işlemeli halılara yaslanırlar."},{"n":77,"t":"Rabbinizin hangi nimetlerini yalanlayabilirsiniz?"},{"n":78,"t":"Görkemli ve Onurlu Rabbinin ismi ne yücedir!"}]},{"id":56,"name":"KAÇINILMAZ OLAY (VAKIA) SÛRESİ","verses":[{"n":1,"t":"Kaçınılmaz olay gerçekleştiği zaman,"},{"n":2,"t":"Onun gerçekleşmesini artık yalanlayan çıkmaz."},{"n":3,"t":"O alçaltıcıdır, yücelticidir."},{"n":4,"t":"Yerin sallanıp sarsılacağı,"},{"n":5,"t":"Ve dağların paramparça edileceği zaman,"},{"n":6,"t":"Artık o toz duman haline gelmiştir."},{"n":7,"t":"Sizler de üç bölüme ayrılırsınız."},{"n":8,"t":"Mutlular ne kadar da mutludurlar!"},{"n":9,"t":"Mutsuzlar ne kadar da mutsuzdurlar!"},{"n":10,"t":"Bir de ileri geçen öncü elitler vardır."},{"n":11,"t":"Onlar (Tanrı'ya) yaklaştırılanlardır. Üst Cennet"},{"n":12,"t":"Nimet cennetlerinde (bahçelerinde)..."},{"n":13,"t":"Onların büyük bir kısmı önceki nesillerden,"},{"n":14,"t":"Küçük bir kısmı da sonraki nesillerdendir."},{"n":15,"t":"Lüks mobilyalar üzerinde,"},{"n":16,"t":"Karşılıklı yaslanmışlardır."},{"n":17,"t":"Onlara ölümsüz gençler servis yaparlar."},{"n":18,"t":"Kaynaktan doldurulmuş bardaklar, sürahiler ve kadehlerle."},{"n":19,"t":"Ne ara verirler ne de yorulurlar."},{"n":20,"t":"Ve beğendikleri meyveler..."},{"n":21,"t":"Canlarının çektiği kuş etleri..."},{"n":22,"t":"Güzel eşler..."},{"n":23,"t":"Korunmuş inciler gibi..."},{"n":24,"t":"Yapmış olduklarına bir karşılık olarak verilir."},{"n":25,"t":"Orada ne bir saçmalık, ne de günaha sokan bir söz işitmezler."},{"n":26,"t":"Sadece, \"Selam, selam,\" derler. Alt Cennet"},{"n":27,"t":"Sağ tarafta olanlar sağ tarafta olacaklar!"},{"n":28,"t":"Dikensiz meyve ağaçları,"},{"n":29,"t":"Salkımları sarkmış muz ağaçları,"},{"n":30,"t":"Uzamış gölgeler,"},{"n":31,"t":"Fışkıran sular,"},{"n":32,"t":"Ve bol meyveler içindedirler."},{"n":33,"t":"Bunlar ne tükenirler, ne de yasak edilirler!"},{"n":34,"t":"Ve onlar yükseltilmiş mobilyalar üzerindedirler."},{"n":35,"t":"Biz kadınları yeniden biçimlendirdik."},{"n":36,"t":"Onları, gençleştirdik."},{"n":37,"t":"Mükemmel biçimde eşlenmişlerdir."},{"n":38,"t":"Sağ tarafta olanlar içindir."},{"n":39,"t":"Onların bir çoğu önceki nesillerdendir."},{"n":40,"t":"Onların bir çoğu da sonraki nesillerdendir. * 56:13-40 İnanıp sadece Tanrı'ya kulluk ederek kendilerini rındıranlar cennete girerler. İnkarcıların ve gelenekçi çevrelerinin baskı ve zulümlerine karşı direndikleri için mesajı ilk kabul eden öncüler üst cenneti hakkederler. Kırk yaşından önce ölenlerse en azından alt cennete girer. Bak 46:15. Cehennem"},{"n":41,"t":"Sol tarafta bulunanlar, sol tarafta olacaklardır."},{"n":42,"t":"İşleyen ve kaynayan bir azap içindedirler."},{"n":43,"t":"Sıcak gölgeler altındadırlar."},{"n":44,"t":"Ne soğuktur, ne de yararlı."},{"n":45,"t":"Bundan önce onlar konfor içinde şımarmışlardı."},{"n":46,"t":"Büyük günahı işlemekte direniyorlardı."},{"n":47,"t":"Diyorlardı ki, \"Biz öldükten, toz ve kemiğe dönüştükten sonra mı diriltileceğiz?\""},{"n":48,"t":"\"Önceki atalarımız da mı?\""},{"n":49,"t":"De ki, \"Öncekiler de, sonrakiler de.\""},{"n":50,"t":"\"Bilinen günün buluşma anı için toplanacaklardır.\""},{"n":51,"t":"\"Sonra da siz, ey sapıtmışlar, ey yalanlayıcılar,\""},{"n":52,"t":"\"Zakkum ağacından yiyeceksiniz.\""},{"n":53,"t":"\"Onunla karnınızı dolduracaksınız.\""},{"n":54,"t":"\"Ve üzerine kaynar su içeceksiniz.\""},{"n":55,"t":"\"Susamış devenin içişi gibi içeceksiniz.\""},{"n":56,"t":"Yargı gününde işte böyle ağırlanacaklardır. Sorular"},{"n":57,"t":"Sizi biz yarattık, doğrulamanız gerekmez miydi?"},{"n":58,"t":"Attığınız meniye dikkat ettiniz mi?"},{"n":59,"t":"Siz mi onu yaratıyorsunuz, yoksa biz mi yaratıyoruz?"},{"n":60,"t":"Aranızda ölümünüzü önceden biz belirledik. Kimse bizi engelleyemez:"},{"n":61,"t":"Sizi başka nesillerle değiştirmekten, yahut sizi bilmediğiniz bir biçimde yaratmaktan...."},{"n":62,"t":"İlk yaratılışı biliyorsunuz. Öğüt almalı değil misiniz?"},{"n":63,"t":"Ektiğinize dikkat ettiniz mi?"},{"n":64,"t":"Siz mi onu yetiştiriyorsunuz, yoksa biz mi?"},{"n":65,"t":"Dileseydik onu samana çevirirdik de siz şaşardınız:"},{"n":66,"t":"\"Borca girdik.\""},{"n":67,"t":"\"Doğrusu, yoksun bırakıldık.\""},{"n":68,"t":"İçmekte olduğunuz suya dikkat ettiniz mi?"},{"n":69,"t":"Onu bulutlardan siz mi indiriyorsunuz, yoksa biz mi?"},{"n":70,"t":"Dileseydik onu tuzlu yapardık. Şükretmez misiniz?"},{"n":71,"t":"Yakmakta olduğunuz ateşe dikkat ettiniz mi?"},{"n":72,"t":"Onun ağacını siz mi başlattınız, yoksa biz mi başlatmaktayız?"},{"n":73,"t":"Kullananlar için biz onu bir ibret ve yararlı yaptık."},{"n":74,"t":"Öyleyse Büyük Rabbinin ismini yücelt. Sadece Şirkten Arınmış Olanlar Kuran'ı Anlar"},{"n":75,"t":"Yıldızların yerlerine yemin ederim."},{"n":76,"t":"Onun ne büyük bir yemin olduğunu bir bilseniz! * 56:75-76 Yedi evrenden biri olan evrenimiz, milyonlarca yıldızlardan oluşan milyonlarca galaksiden oluşmuştur. Saymaktan aciz kaldığımız bu göksel varlıkların her biri kendileri için belirlenmiş yörüngelerde düzen ve harmoni içinde hareket etmektedir. Astronomi bilgimiz arttıkça bu yeminin büyüklüğünü daha iyi kavrıyoruz. \"Yıldızların yeri\" ifadesi, çöken yıldızların oluşturduğu nütron yıldızlarına, yani karadeliklere işaret olabilir mi? Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":77,"t":"Bu, onurlu bir Kuran'dır."},{"n":78,"t":"Gizli bir kitaptadır."},{"n":79,"t":"Onu ancak temizler kavrayabilir. * 56:77-79 Bu ayetler, hemen hemen tüm Kuran ciltlerinin kapağına konan ayetlerdir. Bütün Kuran'ın içinden neden bu ayetler icma ile seçiliyor? Neden, Kuran'ın ellinin üzerindeki isim-sıfatı arasından sadece bir kez burada geçen \"Kerim\" (Şerefli/Yüce) seçiliyor? Kuran'a ihanet edenlerin, ortak koştukları öğretiler için seçtikleri Hadis, Sünnet ve İcma gibi kelimelerin Kuran'da olumsuz anlamlarda kullanıldığını biliyoruz (33:38; 35:43). Neredeyse ölülere özgülenen YaSin Suresinin, mesajın \"dirileri\" uyarmak için gönderildiğini bildiren biricik ayeti içerdiğini biliyoruz (36:70). Peki neden Kuran için sıkça kullanılan Zikr (Mesaj), Hakim (Hikmet), Mübin (Apaçık), Nur (Işık) gibi kelimeleri değil, bu ayette geçen Kerim? Neden bu ayet? Neden örneğin, Kuran'ın anlaşılır bir kitap olduğunu üstüste dört kez vurgulayan ayet değil (54:17, 22, 32, 40)? Veya neden 12:111; 15:1; 17:9; 17:88-89; 30:58; 41:3; 55:2 . . . ayetlerinden biri değil? Kuran bilgisine sahip olanlar için cevap meçhul değildir. Müşrik din adamları, bu üç ayeti (56:77-79) icma ile anlamamışlar ve saptırdıkları biçimiyle bu ayetlerin halkın büyük çoğunluğunu Kuran'dan uzaklaştırabileceğini düşünmüşlerdir. Müşrik dinadamları bu ayeti, abdestsiz olanların Kuran'a DOKUNMAMAları olarak çevirirler. Hayızlı kadınları \"pis\" gördüklerini de düşünürsek, anlamı icma ile çarpıtılmış bir ayeti en populer ayet ve o ayette geçen Kerim kelimesini en popüler sıfat haline getirmelerinin şeytani bir melanetin ürünü olduğu anlaşılır. Kuran'ın bir cep kitabı, bir başucu kitabı olmasını engellemek ve Kuran'ı rafa kaldırıp duvara çivilemek amacını güden plan ne yazık ki büyük oranda başarıya ulaşmıştır. Kuran, bir tren, yüksek voltajlı bir trafo veya cin gibi çarpacak tehlikeli bir nesneye çevrilmiştir. Kuran, anlaşılması çok zor, dokunulması tehlikeli, ve ulaşılması imkansız \"yüce\" bir kitap olunca, hoşgelsin hadisler, sünnetler, mezhepler ve bilumum palavralar! Kuran'ı Kerimi yeterli görmeyen inkarcılar, Tanrı tarafından Kuran'ı Kerim'i anlamaktan menedilmişlerdir (17:45; 18:57). Çok ilginçtir ki, Kuran'ı kaynak olarak yeterli görmeyenler Kuran'ın anlaşılması ile ilgili ayetlerin bizzat kendilerini anlamamışlardır. Nitekim, 7:3; 17:46; 41:44; 56:79 ayetleri, \"hem-tez-hem-kanıt\" olan özgün bir dille kanıtı tezin içine gömen birer sanat eseridir."},{"n":80,"t":"Evrenlerin Rabbinden indirilmiştir."},{"n":81,"t":"Siz bu sözü mü küçümsüyorsunuz?"},{"n":82,"t":"İnkar etmeyi iş mi ediniyorsunuz?"},{"n":83,"t":"Ya can boğaza dayandığı zaman?"},{"n":84,"t":"O anda siz bakınmaktasınız."},{"n":85,"t":"Biz ona (can çekişene) sizden daha yakınız; ancak siz göremezsiniz."},{"n":86,"t":"Yaptığınızın karşılığını görmeyeceğiniz doğruysa,"},{"n":87,"t":"Onu geri çevirsenize, eğer doğru sözlü iseniz?"},{"n":88,"t":"Ancak o, (bana) yaklaştırılanlardan ise-"},{"n":89,"t":"o zaman neşe, çiçekler ve nimet cennetleri..."},{"n":90,"t":"O, sağda olanlardan ise,"},{"n":91,"t":"\"Sana sağdakilerden selam olsun!\""},{"n":92,"t":"Ama o yalanlayan sapıklardan ise-"},{"n":93,"t":"kaynar sudan bir ağırlanma-"},{"n":94,"t":"ve cehennemde yanma..."},{"n":95,"t":"Mutlak gerçek budur."},{"n":96,"t":"Öyleyse Büyük Rabbinin ismini yücelt. * 56:96 Veya \"Rabbini, büyük olan ismiyle yücelt.\""}]},{"id":57,"name":"DEMİR (HADİD) SÛRESİ","verses":[{"n":1,"t":"Göklerde ve yerde ne varsa ALLAH'ı yüceltir. O Üstündür, Bilgedir."},{"n":2,"t":"Göklerin ve yerin yönetimi O'na aittir. Yaşatır, öldürür. O her şeye gücü yetendir."},{"n":3,"t":"O ilktir, sondur. O en dıştakidir, en içtekidir. O her şeyi bilir."},{"n":4,"t":"O'dur gökleri ve yeri altı günde yaratan ve daha sonra tüm otoriteyi kuran. Yere giren ve ondan çıkanı, gökten inen ve ona yükselen her şeyi bilir. Nerede olursanız olun O sizinle beraberdir. ALLAH tüm yaptıklarınızı görendir."},{"n":5,"t":"Göklerin ve yerin yönetimi O'na aittir. Her şey ALLAH 'a havale edilir."},{"n":6,"t":"Geceyi gündüze sokar, gündüzü de geceye sokar. O, göğüslerin içindekini bilir."},{"n":7,"t":"ALLAH'a ve elçisine inanın ve yönetiminize verdiği şeylerden yardım için verin. Sizden inanıp yardım edenler için büyük bir ödül vardır."},{"n":8,"t":"Rabbinize inanmanız için elçi sizi çağırdığı halde size ne oluyor ki hâlâ ALLAH'a inanmıyorsunuz? Hem O, sizden söz almıştı, eğer inanıyor iseniz."},{"n":9,"t":"Sizi karanlıklardan aydınlığa çıkarmak için kuluna apaçık ayetleri indiren O'dur. Kuşkusuz ALLAH size karşı Şefkatlidir, Rahimdir. Özel Onur"},{"n":10,"t":"Size ne oluyor ki ALLAH yolunda harcamıyorsunuz? Oysa göklerin ve yerin zenginlikleri ALLAH'ındır. Zaferden önce harcayıp savaşanlarınız, daha sonra harcayıp savaşanlarla bir olmazlar; onlardan daha üstündürler. ALLAH her birine kurtuluşu söz vermiştir. ALLAH tüm yaptıklarınızdan haberdardır."},{"n":11,"t":"Kim (erdemli davranarak) ALLAH'a güzel bir borç verirse, karşılığını kat kat alır ve cömert bir ödül kazanır. Büyük Başarı"},{"n":12,"t":"İnanan erkeklerin ve kadınların ışıklarının önlerinden ve sağ yanlarından yayıldığını gördüğün gün, \"Müjde, bugün, sürekli olarak kalacağınız altlarından ırmaklar akan cennetler var. Bu, en büyük zaferdir. Kaybedenlerin En Kötüsü"},{"n":13,"t":"O gün, ikiyüzlü erkekler ve kadınlar inananlara, \"Bize bakın da sizin ışığınızdan alalım,\" diyecekler. Onlara, \"Geriye dönün de ışık arayın,\" denir. Aralarına, iç taraftaki merhametle, dış taraftaki azabı ayıran kapılı bir engel konacaktır."},{"n":14,"t":"\"Biz sizinle birlikte değil miydik?\" diye onlara seslenirler. \"Evet,\" derler, \"Ancak siz kendinizi kandırdınız, beklediniz, kuşkular beslediniz ve ALLAH'ın kararı gelinceye kadar kuruntularla oyalandınız. Kandırıcı, sizi ALLAH hakkında yanılttı."},{"n":15,"t":"Bugün ne sizden ne de inkar edenlerden bir fidye kabul edilmez. Yeriniz cehennemdir; mevlanız odur. Ne kötü bir duraktır. Dinin Dejenere Edilmesi"},{"n":16,"t":"İnananlar için ALLAH'ın mesajına ve inen gerçeğe gönüllerini açmanın vakti gelmedi mi? Daha önce kendilerine kitap verilmiş olanlar gibi olmasınlar; onların üzerinden uzun zaman geçince kalpleri katılaşmıştı. Onların çoğunluğu yoldan çıkmış kimselerdir."},{"n":17,"t":"Biliniz ki ALLAH ölümünden sonra yeri diriltir. Düşünesiniz diye size ayetleri böyle açıklıyoruz."},{"n":18,"t":"Sadaka veren erkekler ve kadınlar, ALLAH'a güzel bir borç vermişlerdir. Onlara kat kat ödenir ve onlar cömert bir ödül hakketmişlerdir."},{"n":19,"t":"ALLAH'a ve elçisine inananlar, dosdoğru olanlar ve şehidlerdir. Rab'leri katında onlar için ödülleri ve ışıkları vardır. İnkar edip ayet ve mucizelerimizi yalanlayanlar ise cehennem halkıdır. Dünya Hayatına Dalmak Kınanmıştır"},{"n":20,"t":"Bilesiniz ki dünya hayatı bir oyun, eğlence, süs, aranızda övünme, para ve çocuk çoğaltma yarışından ibarettir. Bu, inkarcıların hoşuna giden bir bitkiyi yetiştiren bir yağmura benzer. Ne var ki daha sonra o bitki kurur, sararır ve sonunda çerçöp olur. Ahirette ise ALLAH'tan çetin bir azap, bir bağışlanma ve hoşnutluk vardır. Dünya hayatı, kandıran, geçici bir zevkten ibarettir. Akıllı Seçim"},{"n":21,"t":"Rabbinizden bir bağışlanmaya ve genişliği gökler ve yer kadar olan bir cennete koşun. ALLAH'a ve elçisine inananlar için hazırlanmıştır. Bu, ALLAH'ın dilediğine ve/veya dileyene verdiği lütfudur. ALLAH Büyük Lütuf sahibidir. Mutluluğun Anahtarı * 57:22-23 Felsefi olarak özgür iradenin varlığını kabul etmek çok güç. Her şey belli deterministik yasalarla işliyor gibi. Tanrı'nın öldüğünü ilan etmekle ünlenen bir felsefecinin dediği gibi yüzlerce bilardo topunun birbirine çarpması sonucu oluşan hareketlerin yönünü kestirmek mümkün görülmeyebilir, ancak her bir topun hareketi kendisiyle çarpışan bir önceki topun momuntumu ve açısına bağlıdır. Topların tüm hareketi ilk topun hareketine ve onun da hareketi kendisine vuran istakanın açısına ve gücüne bağlıdır. Kuantum teorisinin atomdan küçük parçalar düzeyinde gözemlenen belirsizlik konusundaki spekülasyonları bir yana bırakırsak, genetik yapısını ve doğduğu çevreyi seçmeyen bir insanın (zaten böyle bir şey mümkün değil; varolmadan önce seçim sözkonusu değil) özgür bir iradeye sahip olduğunu felsefi olarak savunmak çok zorlu bir iş. Bu konuda pek kafa yormamış sözde ateistlerin \"insanın özgür iradesi\" olduğundan kuşku duymamaları ve müslümanları kaderci olmakla suçlamaları gariptir. İnsanın seçme özgürlüğüne sahip olduğuna inanmak ancak Allah'a ve O'nun Mesajına inanmakla mümkün. Yarattığı bir yaratığa, yaratandan bağımsız olarak seçimde bulunabilme gücü verebilen bir Yaratıcı olmadan özgür iradenin olması mümkün değildir. Müslümanlar olsa olsa, insanların seçme özgürlüğüne inanmakla suçlanabilir. Bak 6:110; 13:11; 18:29; 42:13, 48; 46:15; 57:22."},{"n":22,"t":"Yeryüzünde ve aranızda oluşan hiç bir şey yoktur ki biz onu yaratmadan önce bir kitapta kayıtlı olmasın. Bu, kuşkusuz ALLAH için çok kolaydır."},{"n":23,"t":"Bu, yitirdiğiniz bir şey için üzülmemeniz ve O'nun size verdiği nimetlerle de şımarmamanız içindir. ALLAH kendini beğenip övünenleri sevmez."},{"n":24,"t":"Onlar ki cimrilik ederler ve halka cimri olmayı öğütlerler. Kim yüz çevirirse, kuşkusuz ALLAH Zengindir, Övgüye layık olandır. Demir: Yararlı Bir Metal"},{"n":25,"t":"Elçilerimizi apaçık kanıtlarla gönderdik, onlarla birlikte kitabı ve yasayı indirdik ki halk adaleti gözetsin. Büyük bir kuvvete ve halk için yararlara sahip olan demiri de indirdik ki ALLAH kendisini ve elçisini inançla destekleyenleri ayırsın. ALLAH Güçlüdür, Üstündür. * 57:25 Demirin öneminden ve özelliğinden söz eden biricik ayetin yer aldığı Demir Suresi, demir elementinin bazı kimyasal özelliklerini sayısal ilişkilerle vermektedir. HHaDYD (demir) kelimesinin ebced, yani sayısal değeri, 8+4+10+4=26 olup demir elementinin atom numarasına denktir. EL-HHaDYD (belli bir demir) kelimesinin sayısal değeri de, 1+30+8+4+10+4=57 olup demirin belli bir izotopunun atom ağırlığına eşittir. Kuşkusuz, bunu, Kuran'dan da önce varolan Arapça dilinin ilginç bir rastlantısı olarak değerlendirenler olacaktır. Ne var ki aynı kelimeyle isimlendirilen bu Surenin sıra numarasının 57 olması Kuran'ı düzenleyenin bu \"rastlantı\"dan haberli olduğuna işaret ediyor. Demir elementinden sözeden bu ayet, Besmele dahil edilirse, Surenin 26'ıncı ayetidir; yani demirin atom numarasına denktir. (Kuran'ın 19 kodlu matematiksel sisteminde, numarasız Besmeleler kelime sayımlarına katılmamakta ancak Kuran ayetlerinin sayımına katılmaktadır). Bu Suredeki toplam ayetler Besmele'siz 29, Besmele dahil 30 olup, herbiri demir atomunun dört izotopundan ikisinin nütron sayılarına denktir. Tanrı isminin Sure içindeki tekrar sayısı da geride kalan izotopun nütron sayısını vermektedir. Surenin başından itibaren 26'ıncı Tanrı ismi demirden söz eden ayetin içindedir. Ayetteki \"indirdik\" kelimesinin kullanılışı da ilginçtir. Yıldızların ve gezegenlerin oluşumu konusunu inceleyen modern astronomi kitaplarına bakarsanız, gezegenlerin yaratılışında demir elementinin rolunu ve \"yarattık\" yerine \"indirdik\" sözünün tercih edilme nedenini öğrenebilirsiniz. Bu konu üzerindeki gözlemlerim ve yorumlarım, 1986 yılında \"Kuran'da Demirin Kimyasal Esrarı\" adlı kitapçıkta yayımlandı. Bak 4:82."},{"n":26,"t":"Biz Nuh'u, İbrahim'i gönderdik, soylarına peygamberlik ve kitap bağışladık. Bir kısmı doğruyu buldu; ama onlardan çoğu yoldan çıkmışlardı. Din Adamlarının Dini Dejenere Etmeleri"},{"n":27,"t":"Sonra onların peşinden, ard arda elçilerimizi gönderdik. Meryem oğlu İsa'yı da gönderdik ve ona İncil'i verdik. Onu izleyenlerin gönüllerine şefkat ve merhamet koyduk. Fakat, bizim kendileri için onaylamadığımız bir ruhbanlık uydurdular. Halbuki onlardan sadece ALLAH'ı hoşnut edecek hususlara uymalarını istemiştik. Üstelik ruhbanlığa hakkıyla da uymadılar. Aralarından inananlara ödüllerini verdik; ancak çokları yoldan çıkmışlardı."},{"n":28,"t":"Ey inananlar, ALLAH'ı sayıp dinleyin ve elçisine inanın ki rahmetinden size iki pay versin, size, aydınlığında yürüyeceğiniz bir ışık bağışlasın ve sizi bağışlasın. ALLAH Bağışlayandır, Rahimdir."},{"n":29,"t":"Böylece kitap halkı bilsin ki, onlar ALLAH'ın lütfunu tekelleştiremezler, tüm lütuf ALLAH'ın elindedir, onu dilediğine ve/veya dileyene verir. ALLAH Büyük Lütuf Sahibidir."}]},{"id":58,"name":"TARTIŞMA (MÜCADELE) SÛRESİ*[1]","verses":[]},{"id":59,"name":"SÜRGÜN (HAŞR) SÛRESİ","verses":[]},{"id":60,"name":"SORGULANAN (MUMTAHİNE) SÛRESİ","verses":[]},{"id":61,"name":"DÜZENLİ BİRLİK (SAFF) SÛRESİ","verses":[{"n":1,"t":"Göklerde ve yerde olanlar ALLAH'ı yüceltir. O, Üstündür, Bilgedir."},{"n":2,"t":"Ey inananlar, neden yapmadığınız veya yapmayacağınız şeyleri söylüyorsunuz?"},{"n":3,"t":"Yapmadığınız şeyi söylemeniz, ALLAH katında en sevilmeyen davranışlardandır. Düzenli Birlikler"},{"n":4,"t":"ALLAH kendi yolunda kenetlenmiş bir duvar gibi düzenli birlikler halinde savaşanları sever."},{"n":5,"t":"Hani Musa, halkına: \"Ey halkım, benim, ALLAH'ın bir elçisi olarak size geldiğimi bildiğiniz halde neden beni incitiyorsunuz?\" demişti. Onlar eğrilince, ALLAH ta kalplerini eğriltti. ALLAH yoldan çıkmış toplulukları doğruya ulaştırmaz. Muhammed: İsa'dan Sonra ki Elçi"},{"n":6,"t":"Hani İsa, halkına: \"Ey İsrail oğulları, ben, size gönderilmiş ALLAH'ın bir elçisiyim. Benden önceki Tevrat'ı onaylayıcı ve benden sonra gelecek ve ismi daha çok övülen bir elçiyi müjdeliyorum.\" Sonra kendilerine apaçık delilleri gösterdiğinde, \"Bu apaçık bir büyüdür,\" dediler."},{"n":7,"t":"İslam'a çağrıldığı halde ALLAH hakkında yalan uydurandan daha zalim kim olabilir? ALLAH zalim topluluğu doğruya iletmez."},{"n":8,"t":"ALLAH'ın ışığını ağızlarıyla söndürmek isterler. İnkarcılar hoşlanmasa da ALLAH ışığını tamamlayacaktır."},{"n":9,"t":"O, elçisini hidayet ve gerçek din ile gönderdi ki onu tüm dinlere üstün kılsın, ortak koşanlar hoşlanmasa da..."},{"n":10,"t":"Ey inananlar, sizi acı azaptan kurtaracak bir ticareti size göstereyim mi?"},{"n":11,"t":"ALLAH'a ve elçisine inanırsınız, ALLAH'ın yolunda canınız ve paranızla çaba gösterirsiniz. Bu sizin için en iyisidir, bir bilseniz."},{"n":12,"t":"Günahlarınızı bağışlar ve sizi içinden ırmaklar akan bahçelere ve Adn bahçelerindeki saraylara sokar. Büyük başarı budur."},{"n":13,"t":"Bundan başka sevdiğiniz bir şey daha: ALLAH'tan bir destek ve yakın bir zafer... İnananları müjdele."},{"n":14,"t":"Ey inananlar, ALLAH'ı destekleyenler olun. Nasıl ki Meryem oğlu İsa, öğrencilerine, \"ALLAH yolunda kim benim destekçilerim olur?\" diye sormuştu. Öğrencileri, \"Biz ALLAH'ın destekçileriyiz,\" demişlerdi. İsrail oğullarından bir grup inandı, bir grup da inkar etti. İnananları düşmanlarına karşı destekledik; onlar üstün geldiler."}]},{"id":62,"name":"CUMA (CUMA) SÛRESİ","verses":[{"n":1,"t":"Göklerdekilerin ve yerdekilerin hepsi ALLAH'ı yüceltir. O Kraldır, En kutsaldır, Üstündür, Bilgedir."},{"n":2,"t":"O ki, ümmilerin arasından, kendilerinden olan bir elçi göndermiştir ki onlara O'nun ayetlerini okuyor, onları temizliyor ve onlara kitabı ve bilgeliği öğretiyor. Bundan önce onlar apaçık bir sapıklık içinde bulunuyorlardı."},{"n":3,"t":"Ve henüz kendilerine katılmamış bulunan başkalarına da... O Üstündür, Bilgedir."},{"n":4,"t":"Bu, ALLAH'ın lütfudur; dileyene ve/veya dilediğine verir. ALLAH büyük lütuf sahibidir."},{"n":5,"t":"Kendilerine Tevrat verilip de onun gereğini yerine getirmeyenlerin örneği, kitaplar taşıyan eşeğin durumuna benzer. ALLAH'ın ayetlerini yalanlayan topluluğun durumu ne kötüdür. ALLAH zalim toplumu doğruya ulaştırmaz."},{"n":6,"t":"De ki; \"Ey Yahudiler, halkın arasından yalnız kendinizin ALLAH'ın dostları olduğunuzu iddia ediyorsanız, ölümü dileyin; doğru iseniz.\""},{"n":7,"t":"Onlar, yapmış olduklarından ötürü hiç bir vakit onu dileyemiyeceklerdir. ALLAH zalimleri iyi bilir."},{"n":8,"t":"De ki; \"Kaçmakta olduğunuz ölüm, mutlaka size ulaşacak ve daha sonra gizliyi ve açığı Bilenin huzuruna döndürüleceksiniz. Yaptığınız her şeyi size bildirecektir. Toplantı Namazının Kadın ve Erkek, Tüm İnananlar İçin Önemi"},{"n":9,"t":"Ey inananlar, cuma (toplantı) günü namaza çağrıldığınızda ALLAH'ı anmak için acele edin ve alışverişi bırakın. Bilseniz, bu sizin için daha iyidir."},{"n":10,"t":"Namaz bitince, yeryüzüne yayılarak ALLAH'ın lütfunu arayın ve ALLAH'ı sürekli anmaya devam edin."},{"n":11,"t":"Bazıları, bir ticaret veya bir eğlence gördükleri zaman, seni ayakta bırakıp oraya akın ettiler. De ki, \"ALLAH'ın yanında bulunanlar eğlenceden ve ticaretten daha iyidir. ALLAH en iyi rızık verendir.\""}]},{"id":63,"name":"İKİYÜZLÜLER (MUNAFİKUN) SÛRESİ","verses":[{"n":1,"t":"İkiyüzlüler sana geldiklerinde, \"Senin ALLAH elçisi olduğuna şehadet ederiz,\" derler. ALLAH senin kendi elçisi olduğunu bilir ve ALLAH ikiyüzlülerin yalan söylediğine de şehadet eder.*94"},{"n":2,"t":"Onlar, yeminlerini kalkan yapıp ALLAH'ın yolundan saptırmaktadırlar. Yaptıkları ne kötüdür."},{"n":3,"t":"Çünkü onlar inandıktan sonra inkar ettiler; bu yüzden kalpleri mühürlendi; onlar anlamazlar. Paranoyak Karakter"},{"n":4,"t":"Onları gördüğün zaman, görünüşleri hoşuna gider. Konuşurlarsa sözlerini dinlersin. Onlar, dikilip dayanmış kütükler gibidir. Her gürültüyü kendi aleyhlerine sanarlar; onlar gerçek düşmandır; onlardan sakın. ALLAH onları kahretsin; nasıl da çevriliyorlar!"},{"n":5,"t":"Onlara, \"Gelin de ALLAH'ın elçisi sizin için bağışlanma dilesin,\" denildiğinde, başlarını çevirirler; büyüklük taslayarak saptıklarını görürsün."},{"n":6,"t":"Onlar için bağışlanma dilesen de dilemesen de birdir; ALLAH onları bağışlamıyacaktır. ALLAH yoldan çıkmış topluluğu doğruya ulaştırmaz."},{"n":7,"t":"Onlar, \"ALLAH''ın elçisinin yanında bulunanlara yardım etmeyin ki dağılıp gitsinler,\" diyenlerdir. Oysa göklerin ve yerin hazineleri ALLAH'a aittir; ama ikiyüzlüler kavrayamazlar."},{"n":8,"t":"\"Kente dönersek, üstün olanlar alçakları çıkaracaktır,\" diyorlar. Oysa üstünlük ALLAH'a, elçisine ve inananlara aittir. Ne var ki ikiyüzlüler bilmezler."},{"n":9,"t":"Ey inananlar, paralarınız ve çocuklarınız sizi ALLAH'ı anmaktan alıkoymasın. Böyle davrananlar kaybedenlerdir."},{"n":10,"t":"Size ölüm gelip de, \"Rabbim keşke beni kısa bir süre için ertelesen de, yoksullara yardım ederek erdemlilerden olsam,\" demeden önce verdiğimiz rızıklardan yardım için veriniz."},{"n":11,"t":"ALLAH süresi geldiği zaman hiçbir canı ertelemez. ALLAH yaptıklarınızdan Haberdardır."}]},{"id":64,"name":"ALDANMA (TEĞABUN) SÛRESİ","verses":[{"n":1,"t":"Göklerde ve yerde ne varsa ALLAH'ı yüceltir. Yönetim O'nundur, övgü O'nadır. O her şeye Gücü yetendir."},{"n":2,"t":"Sizi O yarattı. Sonra kiminiz inkarcı, kiminiz de inançlıdır. ALLAH tüm yaptıklarınızı Görendir."},{"n":3,"t":"Gökleri ve yeri belli bir amaç için yaratmış, size biçim vermiş ve biçiminizi güzelleştirmiştir.*95 Dönüş O'nadır. * 64:3 Bak 4:119."},{"n":4,"t":"Göklerde ve yerde olanları bilir; sizin gizlediklerinizi ve açığa vurduklarınızı da bilir. ALLAH gizli düşüncelerinizi çok iyi bilir."},{"n":5,"t":"Daha önce inkar edip de yaptıklarının karşılığını tadanların haberi size ulaşmadı mı? Onlara acı bir azap vardır."},{"n":6,"t":"Çünkü, elçileri onlara apaçık kanıtlarla gidiyorlar ve onlar ise, \"Bize doğru yolu bir insan mı gösterecek?\" diyorlardı. Böylece inkar edip yüz çeviriyorlardı. ALLAH hiç bir şeye muhtaç değildir. ALLAH Zengindir, Övülendir."},{"n":7,"t":"İnkarcılar, diriltilmeyeceklerini ileri sürerler. De ki, \"Evet, Rabbime andolsun diriltileceksiniz ve sonra yaptıklarınız size bildirilecektir. Bu, ALLAH'a kolaydır."},{"n":8,"t":"ALLAH'a, elçisine ve indirdiğimiz bu ışığa inanınız. ALLAH yaptıklarınızdan Haberdardır."},{"n":9,"t":"Gün gelir, sizi toplanma günü için toplarız. Bu, aldanma günüdür. Kim ALLAH'a inanır ve erdemli davranırsa, kötülüklerini örter ve onu altından ırmaklar akan cennetlere sokar. Orada ebedi kalırlar. Büyük başarı işte budur."},{"n":10,"t":"İnkar edenler, ayetlerimizi ve mucizelerimizi yalanlayanlar ateşin halkıdır; orada ebedi kalıcıdırlar. Ne kötü bir varış noktasıdır!"},{"n":11,"t":"Başa ne gelirse ALLAH'ın izniyledir. Kim ALLAH'a inanırsa, gönlüne yön gösterir. ALLAH her şeyi bilendir."},{"n":12,"t":"ALLAH'a uyunuz, elçisine uyunuz. Yüz çevirirseniz, elçimizin görevi açıkça bildirmekten ibarettir."},{"n":13,"t":"ALLAH: O'ndan başka tanrı yoktur. İnananlar yalnız ALLAH'a güvenmelidirler."},{"n":14,"t":"Ey inananlar, eşleriniz ve çocuklarınız size düşman olabilirler. Öyleyse onlardan sakının. Ama affeder, hoşgörülü davranır ve bağışlarsanız, elbette ALLAH da Bağışlayandır, Rahimdir."},{"n":15,"t":"Paralarınız ve çocuklarınız bir sınavdır. Büyük ödül ALLAH'ın yanındadır."},{"n":16,"t":"Gücünüz yettiği kadar ALLAH'ı sayın. Dinleyin, itaat edin ve kendi yararınız için yardımda bulununuz. Nefsinin bencillik ve cimriliğinden korunanlar başaranlardır."},{"n":17,"t":"ALLAH'a güzel bir ödünç sunarsanız, O da onu sizin için katlar ve sizi bağışlar. ALLAH Değer verir, Şefkatlidir."},{"n":18,"t":"Gizliyi ve açığı Bilendir; Üstündür, Bilgedir."}]},{"id":65,"name":"BOŞANMA (TALAK) SÛRESİ","verses":[{"n":1,"t":"Ey peygamber, kadınları boşadığınız zaman boşama sürelerini gözetin ve bu süreyi iyice hesaplayın.*96 Rabbiniz olan ALLAH'ı dinleyin. Onları evlerinden çıkarmayın, onlar da çıkmasınlar (kötü davranarak onları buna zorlamayın). Ancak kanıtlanmış bir zina işlemeleri bunun dışındadır. ALLAH'ın yasası budur. Kim ALLAH'ın yasasını çiğnerse kendisine zulmetmiş olur. Bilmezsin, belki ALLAH bundan sonra (olumlu) bir iş ortaya çıkarır. * 65:1 Boşanan kadın tekrar evlenebilmek için üç aybaşı hali beklemelidir (2:228)."},{"n":2,"t":"Sürelerini doldurdukları zaman, onları güzelce tutun, yahut güzelce ayırın. İçinizden adalet sahibi iki kişiyi de bu işleme tanık tutun. Tanıklığı ALLAH için yapınız. İşte bu, ALLAH'a ve ahiret gününe inananlar için bir öğüttür. Kim ALLAH'ı sayıp dinlerse ona bir çıkış yolu yaratır."},{"n":3,"t":"Ve beklemediği yerden ona rızık verir. Kim ALLAH'a güvenirse O, ona yeter. ALLAH buyruğunu yerine getirendir. ALLAH herşey için bir ölçü koymuştur."},{"n":4,"t":"Menopoz dönemine girerek aybaşından kesilen kadınlarınıza gelince, kuşkunuz varsa, bekleme süreleri üç aydır. Aybaşı hali görmeyen ve gebe olanların süresi, yüklerini bırakmalarıyla sona erer. Kim ALLAH'ı dinlerse, onun işini kolaylaştırır."},{"n":5,"t":"Bu, ALLAH'ın size indirdiği emridir. Kim ALLAH'ı dinlerse onun kötülüklerini örter ve ödülünü büyütür. Boşanmış Kadınlara Karşı Sorumluluklar"},{"n":6,"t":"O kadınları, gücünüz oranında, oturduğunuz yerde oturtun. Ayrılmaya zorlamak için onları rahatsız etmeyin. Gebe iseler, yüklerini bırakıncaya kadar onların geçimlerini sağlayın. Sizin için emzirirlerse ücretlerini ödeyin. Aranızda güzel bir ilişki kurun. Güçlükle karşılaşırsanız, onu başka bir kadın emzirecektir."},{"n":7,"t":"Varlıklı kimse varlığı oranında nafaka yardımında bulunsun. Dar gelirli ise, ALLAH'ın kendisine verdiğinden versin. ALLAH bir kimseye vermiş olduğundan fazla bir sorumluluk yüklemez. ALLAH zorluktan sonra kolaylık getirecektir. Korunmuş Mesaj, Manevi Bir Elçi"},{"n":8,"t":"Nice kentler, Rab'lerinin ve O'nun gönderdiği elçilerin emirlerine baş kaldırdı. Sonunda biz de onları çetin bir hesaba çektik ve onları görülmemiş biçimde cezalandırdık."},{"n":9,"t":"Kararlarının sonucunu tattılar. Kararlarının sonucu bir hüsran oldu."},{"n":10,"t":"ALLAH onlar için çetin bir ceza hazırlamıştır. Öyleyse, ey akıl sahibi inananlar, ALLAH'ı dinleyiniz. ALLAH size bir mesaj..."},{"n":11,"t":"bir elçi indirmiştir.*97 İnanıp erdemli davrananları karanlıklardan aydınlığa çıkarmak için size ALLAH'ın apaçık ayetlerini okur. Kim ALLAH'a inanır ve erdemli davranırsa onu içinde ırmaklar akan cennetlere sokar; orada ebedi kalırlar. ALLAH ona güzel rızık vermiştir. * 65:10-11 Kuran evrensel ve ölümsüz bir elçidir; bir müjdeci ve uyarıcıdır. Bak 41:4. Yedi Gök ve Yedi Yer"},{"n":12,"t":"Yedi göğü ve yerden/topraktan da o kadar yaratan ALLAH'tır. Buyruklar onların arasında akıp durur. Böylece ALLAH'ın herşeye gücü yettiğini ve ALLAH'ın herşeyi bilgiyle kuşatmış olduğunu bilesiniz. * 65:12 Burada maksat dünya gibi yedi gezegen mi yoksa atomun yapısı mı? \"Arz\" kelimesi, yeryüzü ve toprak anlamına gelir. Modern kimyaya göre, yeryüzündeki maddeleri oluşturan atomlar maximum 7 enerji yörüngesine sahip bulunmaktadır. Bu teze göre, dengeli bir elementteki maximum elektron sayısı da 114'tür. Bak 4:82."}]},{"id":66,"name":"YASAKLAMA (TAHRİM) SÛRESİ","verses":[{"n":1,"t":"Ey peygamber, sırf eşlerini memnun etmek amacıyla, ALLAH'ın sana helal (yasal) kıldığını kendine yasaklıyorsun. ALLAH Bağışlayandır, Rahimdir."},{"n":2,"t":"ALLAH, yeminlerinizin helalleştirmenin yolunu bildirmiştir. Mevlanız (efendiniz) ALLAH'tır. O Bilendir, Bilgedir."},{"n":3,"t":"Peygamber, eşlerinden birine gizlice bir hadis söylemişti. Eşi bunu yayınca, ALLAH onu bundan haberdar kıldı. Ona durumun bir kısmını bildirmiş, bir kısmından ise vazgeçmişti. Peygamber konuyu eşine açınca eşi, \"Bunu sana kim haber verdi?\" diye sordu. \"Herşeyi Bilen ve herşeyden Haberdar olan bana bildirdi,\" diye cevapladı.*98 * 66:3 Peygamberle ilişkili olarak \"hadis\" (söz) kelimesi iki kez kullanılır. Biri burada diğeri ise, 33:53 ayetindedir. Burada, Peygamberden işitilen hadisin başkalarına yayılması eleşitiriliyor, 33:53 ayetinde ise, hadislerin dinlenilmesi eleştiriliyor. Geleceği bilen Allah, Hadis, Sünnet ve İcma denilen üçlemeyi Kuran'a şirk koşanları her yönüyle mahkum etmektedir. Bak 33:38; 45:6."},{"n":4,"t":"İkiniz ALLAH'a tevbe ederseniz kalbiniz yönelmiş olur. Ona (elçiye) karşıt olarak birbinizi destekleseniz, onun mevlası (koruyucusu/efendisi) ALLAH'tır; Cibril, erdemli inananlar ve melekler de onu destekler. * 66:4 Bu ayet geleneksel çevirilerde yanlış çevrilmiştir. Müminlerin Tanrı'dan başka bir mevlası yoktur. Bak 2:286."},{"n":5,"t":"Sizi boşarsa, Rabbi ona, belki sizin yerinize sizden daha iyi, (Tanrı'ya) teslim olan, inanan, adayan, yönelen, kulluk eden, aktif, dul ve genç eşler verir."},{"n":6,"t":"Ey inananlar, yakıtı halk ve taşlar olan ateşten kendinizi ve ailenizi koruyun. Ateşin üzerinde sert ve güçlü melekler olup, ALLAH'ın buyruğuna karşı gelmezler ve kendilerine ne emredilmişse onu uygularlar."},{"n":7,"t":"Ey inkarcılar, bugün özür beyan etmeyin. Siz, ancak yapmış olduklarınızın karşılığını görmektesiniz. İnananlar Tevbe Eder"},{"n":8,"t":"Ey inananlar, ALLAH'a yürekten tevbe edin ki Rabbiniz kötülüklerinizi örtsün ve altından ırmaklar akan cennetlere soksun. ALLAH, o gün peygamberi ve beraberinde bulunanları utandırmaz. Işıkları, önlerinden sağ yanlarına doğru yayılır ve, \"Rabbimiz, bizim için ışığımızı tamamla ve bizi bağışla; sen herşeye gücü yetensin,\" derler."},{"n":9,"t":"Ey peygamber, kafirlere ve ikiyüzlülere karşı savaşım ver ve onlara karşı sert davran. Yerleri cehennemdir. O ne kötü duraktır. İnkarcılara Örnek İki Kadın ve Şefaat Mitolojisi"},{"n":10,"t":"ALLAH inkarcılara, Nuh'un karısı ile Lut'un karısını örnek verir. İki erdemli kulumuzun nikahı altında bulunuyorlardı; ancak onlara ihanette bulundular. Kocaları ALLAH'tan gelen hiç bir şeyi o ikisinden savamadı. İkisine de, \"Girenlerle birlikte cehenneme girin,\" denildi. * 66:10 Bak 2:48. İnanlara Örnek İki Kadın"},{"n":11,"t":"ALLAH inananlara, Firavun'un hanımını örnek verir. O, \"Rabbim, benim için cennette bir ev kur ve beni Firavun'dan ve yaptıklarından kurtar; beni bu zalim halktan kurtar,\" demişti."},{"n":12,"t":"Ve İmran kızı Meryem de... O, iffetini korudu, biz de ruhumuzdan ona üfledik. O Rabbinin kelimelerine ve kitaplarına inandı; itaat edenlerden oldu."}]},{"id":67,"name":"YÖNETİM (MULK) SÛRESİ","verses":[{"n":1,"t":"Yönetimi elinde bulunduran çok yücedir. O herşeye Kadirdir. Hayatın Amacı"},{"n":2,"t":"Hanginizin daha güzel işler yapacağını sınamak için ölümü ve hayatı yaratandır. O, Üstündür, Bağışlayandır."},{"n":3,"t":"O yedi göğü kat kat yaratmıştır. Rahman'ın yaratışında her hangi bir kusur bulamazsın. Bakışlarını yönelt de bak; herhangi bir çatlak görebiliyor musun?"},{"n":4,"t":"Sonra tekrar tekrar bak; bakışların usanmış ve yenilmiş olarak sana döner."},{"n":5,"t":"En aşağı göğü lambalarla süsledik ve onları şeytanlar için bir taşlama kıldık. Onlara alevli ateş azabını hazırladık."},{"n":6,"t":"Rab'lerini inkar edenler cehennem cezasını hakketmişlerdir. Ne kötü bir duraktır."},{"n":7,"t":"Oraya atıldıkları zaman, onun kaynayıp tüterken uğultusunu işittiler."},{"n":8,"t":"Neredeyse öfkeden patlayacak! İçine her ne zaman bir grup atılsa, oranın gardiyanları, \"Size bir uyarıcı gelmedi mi?\" diye sodular."},{"n":9,"t":"Onlar da dediler ki, \"Evet, bize bir uyarıcı gelmişti, ama biz yalanladık ve, 'ALLAH hiçbir şey indirmemiştir. Siz tümüyle sapıtmışsınız,' dedik.\""},{"n":10,"t":"\"Dinleseydik veya aklımızı kullansaydık biz şu ateşin halkı içinde olmazdık,\" dediler."},{"n":11,"t":"Böylece günahlarını itiraf ettiler. Ateşin halkı uzak olsunlar."},{"n":12,"t":"Kendi başlarına iken Rab'lerine saygı duyanlar için bir bağışlanma ve büyük bir ödül vardır."},{"n":13,"t":"İsterseniz sözünüzü gizleyin veya onu açıklayın; O gizli düşüncelerinizi çok iyi Bilir."},{"n":14,"t":"Hiç Yaratan yarattığını bilmez mi? O, Latiftir, Haberdardır. * 67:14 Ayet aynı zamanda \"Yaratan bilmez mi\" diye anlaşılabilir."},{"n":15,"t":"O ki yeri emriniz altına verdi. Yeryüzünü dolaşın ve onun besinlerinden yeyin. Son dönüş O'nadır."},{"n":16,"t":"Yoksa, aniden sallanmaya başlayacak olan yerin dibine sizi batırmayacağına dair göktekinden güvence mi aldınız?"},{"n":17,"t":"Aynı şekilde, üstünüze gökten taş yağdıran bir fırtına göndermeyeceğine dair göktekinden güvence mi aldınız? Uyarının nasıl olduğunu öğreneceksiniz."},{"n":18,"t":"Onlardan öncekiler de inkar etmişti. Beni tanımamak da nasıl mış?"},{"n":19,"t":"Üzerlerinde düzenli sıralar halinde kanat çırpan kuşları görmezler mi? Rahman'dan başkası onları tutmuyor. O herşeyi Görendir."},{"n":20,"t":"Rahman'ın dışında size yardım edecek o ordularınız nerede? Gerçekten, inkarcılar bir aldanma içindedirler."},{"n":21,"t":"O, verdiği besinleri kesse, sizi besleyecek olan kimdir? Gerçekten azgınlık ve nefret içinde direnmektedirler."},{"n":22,"t":"Yüzüstü sürünen mi, yoksa dosdoğru yol üzerinde düzgün bir biçimde yürüyen mi daha doğru yoldadır?"},{"n":23,"t":"De ki, \"Sizi yaratan, size duyma, görme duyuları ve beyinler veren O'dur. Ne kadar seyrek şükredersiniz!\""},{"n":24,"t":"De ki, \"Sizi yeryüzünde üreten O'dur ve siz O'nun huzurunda toplanacaksınız.\""},{"n":25,"t":"\"Doğru iseniz, bu söz ne zaman gerçekleşecek?\" derler."},{"n":26,"t":"De ki, \"Bu bilgi ALLAH'ın katındadır. Ben sadece apaçık bir uyarıcıyım.\""},{"n":27,"t":"Onu yaklaşırken gördükleri zaman inkarcıların suratı asılır, ve onlara \"İşte isteyip durduğunuz şey budur,\" denir."},{"n":28,"t":"De ki, \"Baksanıza, ALLAH yanımdakilerle birlikte beni helak etse de, yahut bize acısa da, inkarcıları acı azaptan kim kurtarabilir?\""},{"n":29,"t":"De ki, \"O Rahman'dır; biz O'na inandık ve O'na güvendik. Kimin gerçekten tam bir sapıklık içinde olduğunu ileride öğreneceksiniz.\""},{"n":30,"t":"De ki, \"Hiç düşündünüz mü ki: suyunuz çekilse, size kim temiz bir su getirebilir?"}]},{"id":68,"name":"KALEM (KALEM) SÛRESİ","verses":[{"n":1,"t":"NuN, kaleme ve yazdıklarına andolsun."},{"n":2,"t":"Sen Rabbinin nimetiyle delirmiş değilsin."},{"n":3,"t":"Senin için kesintisiz bir ödül vardır."},{"n":4,"t":"Kuşkusuz sen güçlü bir karaktere sahipsin."},{"n":5,"t":"Sen de göreceksin, onlar da görecekler;"},{"n":6,"t":"Hanginizin şaşkın olduğunu."},{"n":7,"t":"Rabbin, kimin yolundan sapmış olduğunu da en iyi bilir, doğru yolda olanları da en iyi bilir."},{"n":8,"t":"Öyleyse yalanlayanlara uyma."},{"n":9,"t":"Kendilerinin ödün verip uzlaşabilmesi için senin de ödün verip uzlaşmanı istediler. Kötü Karakter"},{"n":10,"t":"Şunların hiçbirine uyma: yemin edip duran, aşağılık,"},{"n":11,"t":"İftiracı, söz götürüp getiren,"},{"n":12,"t":"İyiliğe ve yardıma engel olan, saldırgan, günahkar."},{"n":13,"t":"İnsafsız ve sahtekar."},{"n":14,"t":"Mal ve çocuk sahibidir diye (onlara uyma)."},{"n":15,"t":"Ayetlerimiz kendisine okunduğu zaman, \"Efsane\" der."},{"n":16,"t":"Onun burnunu işaretliyeceğiz."},{"n":17,"t":"Onları sınadık; tıpkı bahçe sahiplerini sınadığımız gibi. Sabahleyin devşireceklerine yemin etmişlerdi."},{"n":18,"t":"Bundan hiç bir kuşkuları yoktu."},{"n":19,"t":"Onlar uykudayken Rabbin tarafından gönderilen bir ziyaretçi (fırtına) bahçelerini ziyaret etti."},{"n":20,"t":"Ve bahçe meyvesiz kalmıştı."},{"n":21,"t":"Sabahleyin birbirlerine seslendiler:"},{"n":22,"t":"\"Devşirecekseniz, haydi ekinlerinize erken varın.\""},{"n":23,"t":"Derken yola çıktılar, aralarında konuşuyorlardı."},{"n":24,"t":"\"Sakın, bugün hiçbir yoksul oraya yanınıza girmesin.\""},{"n":25,"t":"Sonuçtan emin bir halde erken vardılar."},{"n":26,"t":"Fakat bahçeyi görünce, \"Biz yolu şaşırdık,\" dediler."},{"n":27,"t":"\"Yok, doğrusu biz yoksun bırakıldık.\" \"Tanrı Dilerse\" (İnşallah) Demeleri Gerekirdi"},{"n":28,"t":"Ortancaları (erdemlileri), \"Ben size demedim mi? Rabbinizi yüceltmeniz gerekmez miydi?\" dedi."},{"n":29,"t":"Dediler ki, \"Rabbimiz yücedir. Biz zalimler imişiz.\""},{"n":30,"t":"Ve hemen birbirlerini suçlamaya başladılar."},{"n":31,"t":"Dediler ki, \"Yazıklar olsun bize. Azgınmışız.\""},{"n":32,"t":"\"Belki Rabbimiz bize daha iyisini verir. Biz Rabbimize dönüyoruz.\""},{"n":33,"t":"İşte azap böyledir. Ahiret azabı ise daha büyüktür. Bir bilselerdi."},{"n":34,"t":"Erdemliler, Rab'lerinden nimet bahçeleri (cennetleri) haketmişlerdir. Çelişkiler Kolleksiyonu Hadis ve Fıkıh Kitapları"},{"n":35,"t":"Müslümanlara suçlular gibi mi davranalım?"},{"n":36,"t":"Neyiniz var, ne biçim hüküm veriyorsunuz?"},{"n":37,"t":"Yoksa bir kitabınız var da onu mu okuyup duruyorsunuz?"},{"n":38,"t":"Ve içinde her dilediğinizi bulabiliyorsunuz?"},{"n":39,"t":"Yoksa, dilediğiniz hükmü verebileceğinize dair Diriliş Gününe kadar sürecek bir güvence mi aldınız bizden?"},{"n":40,"t":"Sor onlara, \"Bunu kim garanti etmektedir?\""},{"n":41,"t":"Yoksa onların ortakları mı var? Haydi ortaklarını getirsinler, eğer doğru kimseler iseler? * 68:41 Bak 42:21; 9:31; 6:112-116, 145-150."},{"n":42,"t":"Gün gelecek, onların içyüzleri açığa çıkarılacak, secdeye çağrılacaklar; ancak buna güçleri yetmeyecektir. * 68:42 Hadise dayalı tefsirler bu ifadeyi çarpıtmışlar ve bu çarpıtmayı her zamanki gibi peygambere yakıştırmışlardır. Buhari'de üç kez rivayet edilen bir hadise göre Tanrı, Yargı Gününde kimliğini kanıtlamak için örtüsünü kaldırıp bacaklarını peygamberlere gösterecekmiş! Tanrı'ya bir striptiz sahnesini yakıştıran Buhariyi \"sahih ve kutsal\" kabul eden Diyanet Meali, bu ayetin çevirisinde onu dinlememiştir."},{"n":43,"t":"Gözleri düşmüş bir durumda, onları aşağılanma kaplar. Oysa onlar sağlam iken secdeye çağrılmışlardı."},{"n":44,"t":"Bu hadisi (sözü) yalanlayanla Beni başbaşa bırak. Onları, bilmedikleri yerden yavaş yavaş yaklaştıracağız."},{"n":45,"t":"Onlara mühlet veriyorum. Benim planım sağlamdır."},{"n":46,"t":"Yoksa sen onlardan bir ücret istiyorsun da onlar ağır bir borç altında mı kalıyorlar?"},{"n":47,"t":"Yoksa geçmişin ve geleceğin bilgisi onların yanında da onlar mı kaydediyorlar?"},{"n":48,"t":"Rabbinin hükmünün gerçekleşmesi için sabret. Balığın arkadaşı (Yunus) gibi olma. Hani o, (balık tarafından) yutulmuş bir durumda iken seslenmişti. * 68:48 Kuran, Yunus peygamberin ismi yerine \"Sahib-il Hut\" yani Balığın Arkadaşı ifadesini kullanıyor. Böylece, Nun harfiyle başlayan bu surede, Yunus kelimesindeki \"Nun\" harfine dikkatimiz çekiliyor. Başka örnekler için bak 21:87; 50:13; 3:96; 7:69."},{"n":49,"t":"Rabbinden ona bir nimet ulaşmasaydı, kınanmış olarak çorak bir sahile atılacaktı."},{"n":50,"t":"Ancak Rabbi onu seçip erdemlilerden kıldı."},{"n":51,"t":"Mesajı işittikleri zaman, inkarcılar neredeyse seni gözleriyle yiyeceklerdi. \"O, delidir!\" diyorlardı."},{"n":52,"t":"Halbuki o, tüm evrene bir mesajdır."}]},{"id":69,"name":"GERÇEKLEŞEN (HAKKA) SÛRESİ","verses":[{"n":1,"t":"Gerçekleşen (olay)."},{"n":2,"t":"Nedir o gerçekleşen!"},{"n":3,"t":"Gerçekleşenin ne olduğunu nerden bileceksin?"},{"n":4,"t":"Semud ve Ad (halkı) sarsıcı olayı yalanladı."},{"n":5,"t":"Ve Semud o azgın (sarsıntı) ile yok edildi."},{"n":6,"t":"Ad ise sert ve azgın bir kasırga ile yok edildi."},{"n":7,"t":"Onu, yedi gece ve sekiz gün boyunca üzerlerine bir bela olarak saldı. Halkın, çürümüş hurma gövdeleri gibi yere yıkıldıklarını görürsün. * 69:7 Bu ayetteki \"yedi gece ve sekiz gündüz\" ifadesi kesintisiz bir zaman dilimini ifade eder. Bu ayete göre Kuran'ın kabul ettiği gün, Yahudi geleneğindeki gibi gece ile değil gündüz ile başlar. Gece (leyl) kelimesinin Kuran'da gündüz (nehar) kelimesinden önce kullanılmasını delil olarak kabul eden geleneksel anlayış, gece ile gündüzü tanımlayan 91:3-4 ayetleriyle çelişir. Gecenin gündüzü geçemiyeceğini ifade eden 36:40 ayeti bu açıdan ilginçtir. 2:187 ayeti de gündüz ile gecenin ne zaman başlayacağını bildirir. 3:27; 17:12 ayetleri gece ile gündüzün karıştığı sabah ve akşam saatlerini anlatır. Bu ayetlere göre, gece guneş batımı ile başlar ve gündüz ise guneş batımından kısa bir süre sonra aydınlık çizginin kaybolduğu zamanda biter. Aynı şekilde, gündüz, günes daha doğmadan kısa bir süre önce başlar ve gece ise güneşin doğumuyla biter. Gündüz ve gece icin ayrıca bak 10:67; 25:62; 36:37."},{"n":8,"t":"Onların hiç bir kalıntısını görüyor musun?"},{"n":9,"t":"Firavun, ondan öncekiler ve altüst olan (Sodomlu) larda kötülük işlemişti."},{"n":10,"t":"Rab'lerinin elçisine isyan ettiler. Bunun sonucu olarak da onları şiddeti gittikçe artan bir biçimde yakalamıştı."},{"n":11,"t":"Su taşınca sizi akıp giden (sal) üzerinde taşımıştık."},{"n":12,"t":"Ki o size bir ders olsun ve dinleyen kulaklar anlasın."},{"n":13,"t":"Boruya bir kez üfürüldüğü zaman,"},{"n":14,"t":"Yer ve dağlar kaldırılıp birbirine çarpılıp darmadağın edildiği zaman,"},{"n":15,"t":"İşte o gün kaçınılmaz olay gerçekleşmiştir."},{"n":16,"t":"Gök yarılmıştır, parçalanmıştır."},{"n":17,"t":"Melekler her yandadır. Rabbinin yönetimi o gün sekiz (evren) üzerinde egemen olacaktır. * 69:17 Olumsuzluklarla dolu olan bu dünya yedinci evren olduğundan manevi olarak Tanrı'dan çok uzaktır (7:143). Ahirette ise sekizinci evren yaratılacaktır. O, bizim yedinci evrenimizden daha da fazla uzak olacaktır ve \"cehennem\" olacaktır (89:23)."},{"n":18,"t":"O gün ortaya çıkarılırsınız ve hiçbir şeyiniz gizli kalmaz. İnananlar"},{"n":19,"t":"Kitabı sağından verilen, \"Alın kitabımı okuyun,\" der,"},{"n":20,"t":"\"Hesabımla karşılaşacağıma inanıyordum.\""},{"n":21,"t":"O mutlu bir yaşantı içindedir,"},{"n":22,"t":"Yüksek bir cennette (bahçede),"},{"n":23,"t":"Meyveleri ulaşılabilecek mesafededir."},{"n":24,"t":"Geçmiş günlerinizde yaptığınız işlerden ötürü afiyetle yiyiniz, içiniz. İnkarcılar"},{"n":25,"t":"Kitabı solundan verilenlere gelince, onlar, \"Keşke kitabım bana verilmeseydi,\" der,"},{"n":26,"t":"\"Hesabımın ne olduğunu öğrenmeyeydim.\""},{"n":27,"t":"\"Keşke ölümüm sonsuz olsaydı.\""},{"n":28,"t":"\"Param bana yaramadı.\""},{"n":29,"t":"\"Tüm gücümü yitirdim.\""},{"n":30,"t":"Yakalayın, bağlayın onu."},{"n":31,"t":"Ve sonra cehennemde yakın."},{"n":32,"t":"Sonra, onu yetmiş arşın boyunda bir zincire vurun."},{"n":33,"t":"Çünkü o, Yüce ALLAH'a inanmıyordu."},{"n":34,"t":"Yoksullara yedirmeğe de çalışmıyordu."},{"n":35,"t":"Bu yüzden onun buralarda bir dostu yoktur."},{"n":36,"t":"Hiç bir yiyeceği de... İrin hariç,"},{"n":37,"t":"Onu ancak günahkarlar yer."},{"n":38,"t":"Yemin ederim gördüklerinize,"},{"n":39,"t":"Ve görmediklerinize,*99 * 69:38 Fiziksel evrenin bile büyük bir bölümü görünmez maddeden oluşmuştur. Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":40,"t":"Ki bu şerefli bir elçinin (getirdiği) sözdür."},{"n":41,"t":"O bir şair sözü değildir; ne de az inanıyorsunuz?"},{"n":42,"t":"Kahin sözü de değildir; ne de az düşünüyorsunuz?"},{"n":43,"t":"Evrenlerin Rabbinden indirilmedir. Muhammed'in Herhangi Dini Bir Öğreti Ortaya Koyması Yasaklanmıştır"},{"n":44,"t":"O bize bazı sözler yakıştırsa,"},{"n":45,"t":"Biz onu kuvvetle yakalar,"},{"n":46,"t":"Sonra, ondan vahyi keserdik."},{"n":47,"t":"Ve sizden kimse de buna engel olamazdı."},{"n":48,"t":"Kuşkusuz bu, erdemliler için bir hatırlatmadır."},{"n":49,"t":"İçinizden yalanlayanlar olduğunu iyi biliyoruz."},{"n":50,"t":"O, inkarcılar için bir üzüntü kaynağıdır."},{"n":51,"t":"O, kuşkusuz mutlak gerçektir."},{"n":52,"t":"Öyleyse Büyük olan Rabbinin ismini yücelt.*[4 * 69:52 Veya \"Öyleyse Rabbini büyük ismiyle yücelt.\""}]},{"id":70,"name":"YÜKSELİŞ YOLLARI (MEARİC) SÛRESİ","verses":[{"n":2,"t":"Onu inkarcılardan savacak kimse yoktur."},{"n":3,"t":"Yükseliş Yollarının Sahibi olan ALLAH'tandır."},{"n":4,"t":"Melekler ve ruh (vahiy/komutlar/Cebrail), elli bin yıla eşit bir gün içinde O'na yükselir. * 70:4 Zaman görelidir. Bak 22:47; 32:5."},{"n":5,"t":"Şimdi sen güzelce sabret."},{"n":6,"t":"Onlar onu uzak görüyorlar."},{"n":7,"t":"Biz ise onu yakın görüyoruz."},{"n":8,"t":"Gün gelecek, gök erimiş maden gibi."},{"n":9,"t":"Dağlar ise atılmış yün gibi olur."},{"n":10,"t":"Dost dostun durumunu sormaz. 11. Birbirlerine gösterilirler. Suçlu, o günün azabından kurtulmak için fidye vermek ister: Oğullarını,"},{"n":12,"t":"Eşini, kardeşini,"},{"n":13,"t":"Kendisini yetiştiren tüm akrabalarını,"},{"n":14,"t":"Ve yeryüzünde bulunan herkesi, ki kurtulsun."},{"n":15,"t":"Hayır, o alevli ateştir."},{"n":16,"t":"Yakmak için isteklidir..."},{"n":17,"t":"Çağırır, sırtını dönüp gideni,"},{"n":18,"t":"Toplayıp kasaya saklayanı."},{"n":19,"t":"Doğrusu insan endişeli bir karaktere sahiptir. 20. Kendisine kötülük dokunduğu zaman ümidini keser. 21. Kendisine iyilik dokunduğu zaman ise cimridir. Müslümanların Karakteri"},{"n":22,"t":"Ancak namaz kılanlar hariç:"},{"n":23,"t":"Onlar ki namazlarını kaçırmazlar; 24. Paralarında bilinen bir pay (zekat) ayrılmıştır,"},{"n":25,"t":"İsteyen yoksula ve yoksuna..."},{"n":26,"t":"Onlar Din Gününü doğrularlar; 27. Rab'lerinin azabından çekinirler; 28. Rab'lerinin azabına güven olmaz."},{"n":29,"t":"Onlar cinsel ilişkiden sakınırlar;"},{"n":30,"t":"Ancak eşleri, yahut yeminlerinin/anlaşmalarının hak sahibi olduklari hariç; onlardan dolayı yerilmezler. * 70:30 Bak 4:25."},{"n":31,"t":"- bunun ötesini arayanlar ise aşırı gidenlerdir-"},{"n":32,"t":"Onlar güvenilirdirler, sözlerine bağlıdırlar;"},{"n":33,"t":"Gereği gibi tanıklıkta bulunurlar; 34. Namazlarına özen gösterirler."},{"n":35,"t":"Onlar cennetlerde ağırlanırlar."},{"n":36,"t":"Peki şimdi inkarcılara ne oluyor da senin önünde koşuşuyorlar?"},{"n":37,"t":"Sağdan, soldan gruplar halinde..."},{"n":38,"t":"Herbiri, nimet cennetine sokulacağını mı umuyor?"},{"n":39,"t":"Asla; biz onları yarattık, bildikleri şeyden..."},{"n":40,"t":"Doğuların ve batıların Rabbine andolsun; bizim gücümüz yeter..."},{"n":41,"t":"Onları, kendilerinden daha iyilerle değiştirmeye... Bizi kimse yenemez."},{"n":42,"t":"Bırak onları, kendilerine söz verilen gün ile karşı karşıya gelinceye kadar dalsınlar, oynasınlar."},{"n":43,"t":"O gün mezarlarından hızlı hızlı çıkarlar; kurban taşına sürülüyorlarmış gibi..."},{"n":44,"t":"Gözleri dönmüş, kendilerini utanç sarmış olarak. İşte bu, onlara söz verilmiş olan gündür."}]},{"id":71,"name":"NUH (NUH) SÛRESİ","verses":[{"n":1,"t":"\"Kendilerine acı azap gelmezden önce halkını uyar,\" diye Nuh'u halkına gönderdik."},{"n":2,"t":"Dedi ki, \"Ey halkım, ben size apaçık bir uyarıcıyım.\""},{"n":3,"t":"\"ALLAH'a kulluk edin, O'nu sayın ve beni izleyin.\""},{"n":4,"t":"\"Ki günahlarınızı bağışlasın ve sizi belli bir süreye kadar ertelesin. Kuşkusuz, ALLAH'ın verdiği süre gelince ertelenmez; bir bilseydiniz."},{"n":5,"t":"Dedi ki, \"Rabbim, ben halkımı gece gündüz çağırdım.\""},{"n":6,"t":"\"Ne var ki, çağrım onların kaçışını arttırmaktan başka şeye yaramadı.\""},{"n":7,"t":"\"Her ne zaman senin onları bağışlaman için onları çağırdıysam parmaklarını kulaklarına tıkadılar, elbiselerini başlarına örttüler, direndiler, büyüklendikçe büyüklendiler.\""},{"n":8,"t":"\"Sonra onları açıkça çağırdım.\""},{"n":9,"t":"\" Sonra onlara ilan ettim, gizliden gizliye de konuştum.\""},{"n":10,"t":"\"Dedim ki, 'Rabbinizden bağışlanma dileyin; O çok Bağışlayandır.' \""},{"n":11,"t":"\" 'Size gökten bol yağmur göndersin.' \""},{"n":12,"t":"\" 'Size bol para ve çocuklarla desteklesin, size bahçeler ve ırmaklar versin.' \""},{"n":13,"t":"Size ne oluyor ki ALLAH'a saygı göstermek istemiyorsunuz? İnsan Soyunun Evrimi"},{"n":14,"t":"Oysa sizi evrimler halinde yaratan O'dur. * 71:14-17 Evrim, Tanrı'nın düzenlediği harika bir sistemdir. Bak 15:26-28."},{"n":15,"t":"ALLAH'ın yedi göğü tabakalar halinde nasıl yarattığını görmez misiniz?"},{"n":16,"t":"Ayı bunların içinde bir ışık, güneşi de bir lamba yaptı."},{"n":17,"t":"Ve ALLAH sizi topraktan bir bitki olarak bitirdi.*"},{"n":18,"t":"Sonra sizi ona döndürecek ve sizi tekrar çıkaracaktır."},{"n":19,"t":"ALLAH yeryüzünü sizin için bir yerleşim yeri yaptı."},{"n":20,"t":"Ki orada geniş yollarda gidesiniz."},{"n":21,"t":"Nuh dedi ki, \"Rabbim, onlar bana karşı geldiler ve parası, çocukları kendisine sadece zarar veren bir kimseye uydular.\""},{"n":22,"t":"\"Ve hatta büyük tuzaklar kurdular.\""},{"n":23,"t":"\"Dediler ki, 'Tanrılarınızı terketmeyin. Ne Vedd'i, ne Suva'ı, ne Yeğus'u, Yeuk'u ve Nesr'i bırakmayın.' \""},{"n":24,"t":"\"Çok kişiyi saptırdılar. Öyleyse, sen de zalimlerin şaşkınlığını arttır.\""},{"n":25,"t":"Suçlarından ötürü boğuldular ve ateşe sokuldular. Kendilerine ALLAH'tan başka yardımcı da bulamadılar."},{"n":26,"t":"Nuh dedi ki, \"Rabbim, yeryüzünde bir tek inkarcı bırakma.\""},{"n":27,"t":"\"Onları bırakırsan kullarını saptırırlar ve ancak bayağı inkarcılar doğururlar.\""},{"n":28,"t":"\"Rabbim, beni, anamı babamı, evime inanan olarak girenleri, inanan erkek ve kadınları bağışla; zalimlerin ise ancak yıkımlarını arttır.\""}]},{"id":72,"name":"CİN (CİN) SÛRESİ","verses":[{"n":1,"t":"De ki, \"Bana vahyedildiğine göre, cinlerden bir grup dinlediler ve şöyle dediler:\" \"Biz ilginç bir Kuran işittik.\""},{"n":2,"t":"\"O doğruya iletiyor ve biz ona inandık; bundan böyle Rabbimize hiç kimseyi ortak koşmayacağız.\""},{"n":3,"t":"\"Rabbimiz çok yücedir. O ne bir eş ne de bir çocuk edinmemiştir. \""},{"n":4,"t":"\"ALLAH hakkında saçma şeyler söyleyip duran bizim o beyinsizdi.\" Yeni Elçilere, Tanrı Adına Karşı Koyma Alışkanlığı"},{"n":5,"t":"\"İnsanların ve cinlerin ALLAH'a karşı yalan uyduramıyacaklarını sanmıştık.\""},{"n":6,"t":"\"Ne var ki bazı insanlar, bazı cinlere sığınırlardı ve bu da onların azgınlıklarını arttırırdı.\""},{"n":7,"t":"\"Onlar, tıpkı sizin sandığınız gibi, ALLAH'ın hiç bir kimseyi göndermeyeceğini sanıyorlardı.\""},{"n":8,"t":"\"Biz göğe dokunduk ve onu güçlü bekçilerle ve ateş toplarıyla korunmuş bulduk.\""},{"n":9,"t":"\"Biz orada casusluk için otururduk. Ancak şimdi her kim dinlemek isterse kendisini gözleyen bir ateş topu bulur.\""},{"n":10,"t":"\"Yerdekiler için bir kötülük mü planlanmıştır, yoksa Rab'leri onlar için bir iyilik mi dilemiştir, bilmiyoruz.\""},{"n":11,"t":"\"Aramızda erdemliler de var, bunun aşağısında olanlar da var; biz çeşitli tarikatlara(yollara) ayrıldık. \""},{"n":12,"t":"\"Biz, yeryüzünde ALLAH'ı aciz bırakamıyacağımızı, kaçmakla da O'nu atlatamıyacağımızı anladık.\""},{"n":13,"t":"\"Biz, yol gösteren (Kuran)ı işitir işitmez ona inandık. Rabbine inanan hiçbir haksızlığa ve sıkıntıya uğramaz.\""},{"n":14,"t":"\"Aramızdan müslümanlar da var uzlaşmacılar da vardır.\" Kim teslim olursa, işte gerçeği araştıranlar onlardır."},{"n":15,"t":"Uzlaşmacılara gelince, cehenneme odun olmuşlardır."},{"n":16,"t":"Doğru yola girselerdi onlara bol su verirdik."},{"n":17,"t":"Ki onunla onları sınayalım. Kim Rabbinin mesajından yüz çevirirse onu zorlu ve yokuşlu bir cezaya süreriz. Camiler, Mescidler Sadece Allah'a Aittir"},{"n":18,"t":"Mescidler sadece ALLAH'a aittir; öyleyse ALLAH ile birlikte hiç kimseyi çağırmayın. Geçmişte, Şimdi ve Gelecekte Değişmeyen Tepki"},{"n":19,"t":"ALLAH'ın kulu kalkıp sadece O'na çağırdığında ona karşı nerdeyse hepsi bir bütün oldular."},{"n":20,"t":"De ki, \"Ben sadece Rabbime çağırırım; ve O'na hiç kimseyi ortak koşmam.\""},{"n":21,"t":"De ki, \"Ben size ne bir zarar ne de bir yarar verme gücüne sahip değilim.\""},{"n":22,"t":"De ki, \"Hiç kimse beni ALLAH'a karşı savunamaz, O'ndan başka sığınak da bulamam.\""},{"n":23,"t":"\"Ancak ALLAH'tan bir duyuruyu ve mesajını iletirim.\" Artık kim ALLAH'a ve elçisine karşı gelirse içinde ebedi kalacağı cehennem ateşini hakeder. Sayısal Gizem"},{"n":24,"t":"Kendilerine söz verilen şeyi gördüklerinde kimin yardımcısının güçsüz ve sayıca az olduğunu görecekler."},{"n":25,"t":"De ki, \"Size söz verilen yakın mıdır yoksa Rabbim onun için uzun bir süre mi belirlemiştir bilmiyorum.\""},{"n":26,"t":"O geleceği bilendir; ve O sırrını hiç kimseye göstermez."},{"n":27,"t":"Ancak seçtiği bir elçi hariç; nitekim O, o elçiden önceye ve sonraya ait bir gözlem sunar."},{"n":28,"t":"Böylece, elçilerin Rab'lerinin mesajını ilettikleri ortaya çıksın. O onların yaptıklarını tümüyle kuşatmıştır ve herşeyi sayı olarak hesaplamıştır."}]},{"id":73,"name":"BÜRÜNEN (MÜZEMMİL) SÛRESİ","verses":[{"n":1,"t":"Ey bürünen,"},{"n":2,"t":"Bazı geceler hariç, geceleyin kalk."},{"n":3,"t":"Yarısında veya yarısından biraz önce."},{"n":4,"t":"Yahut yarısından biraz sonra... Kuran'ı da özenle düşüne düşüne oku."},{"n":5,"t":"Biz sana ağır bir söz bırakacağız."},{"n":6,"t":"Kuşkusuz gece kalkıp meditasyonda bulunmak çok daha etkili ve ifade açısından daha uygundur."},{"n":7,"t":"Seni gündüzün epeyce uğraştıracak işlerin vardır."},{"n":8,"t":"Rabbinin ismini an ve tüm gönlünle O'na yönel."},{"n":9,"t":"Doğunun ve batının Rabbi; O'ndan başka tanrı yoktur. Kendine avukat olarak O'nu seç."},{"n":10,"t":"Onların sözlerine karşı sabırlı ol ve onlardan güzellikle ayrıl."},{"n":11,"t":"Varlık sahibi olup da seni yalanlayanları bana bırak; onlara biraz süre tanı."},{"n":12,"t":"Yanımızda zincirler ve cehennem vardır."},{"n":13,"t":"Yutulması güç bir yiyecek ve acı bir azap..."},{"n":14,"t":"Gün gelir, yer ve dağlar titrer ve dağlar dağılan kum yığınına dönüşür."},{"n":15,"t":"Biz, size hakkınızda tanıklık edecek bir elçi gönderdik; nasıl ki Firavun'a da bir elçi göndermiştik."},{"n":16,"t":"Ancak Firavun, elçiye karşı geldi; biz de onu feci bir biçimde yakaladık."},{"n":17,"t":"Peki, inkar ederseniz, çocukların saçlarını ağartan bir günden nasıl korunursunuz?"},{"n":18,"t":"Gök bile ondan dolayı yarılır. O'nun sözü gerçekleşir."},{"n":19,"t":"Bu bir hatırlatmadır; dileyen, Rabbine doğru yol tutar. Geceleyin Kuran Çalışması"},{"n":20,"t":"Rabbin, senin ve yoldaşlarıdan bir grubun, gecenin üçte ikisinden az, yarısında ve üçte birinde kalktığını bilir. Gecenin ve gündüzün miktarını ALLAH belirler. O, sizin bunu yapamıyacağınızı bildiği için sizi affetmiştir. Öyleyse Kuran'dan kolayınıza geldiği kadar okuyun. Aranızda hastalar, yeryüzünde ALLAH'ın lütfundan rızık arayanlar ve ALLAH yolunda savaşanlar olduğunu bilmektedir. Ondan kolayınıza geldiği kadar okuyun. Namazı gözetin, zekatı verin ve güzel davranmak yoluyla ALLAH'a bir borç sunun. Kendiniz için yaptığınız her iyiliği, ALLAH katında daha iyi ve daha büyük bir ödül olarak bulacaksınız. ALLAH'tan bağışlanma dileyin; ALLAH Bağışlayandır, Rahimdir."}]},{"id":74,"name":"GİZLENEN (MUDDESİR) SÛRESİ","verses":[{"n":1,"t":"Ey gizlenen, * 74:1 Bilge Tanrı, Kuran'ı Muhammed'e indirdiği halde Kuran'ın olağanüstü matematiksel mucizesini çağımız insanına bir mesaj olarak sakladı. 19 asal sayısı üzerine kurulu matematiksel sistemden söz eden ayetler, ismi Gizlenen olan 74. surede bir giz olarak bulunuyordu. Kuran'ın inişinden tam 19x74 kameri yıl sonra, 1974 yılında, isminin kökleri Kuran'da tam 19 kez geçen bir monoteist müslüman yoluyla çıkarılması takdir edilen bu mucize, kompüter çağının insanına Kuran'ın kaynağı konusunda evrensel ve fiziksel bir kanıt sunmaktadır. Bu mucizeyi görebilme şansına sahip olan müminler, gelenekleri, mezhepleri ve kalabalıkları sorgulayıp eleştirebilme cesareti gösterebilmektedir. Gerçekleşenlere baktığımızda, tüm surenin 19 koduna dolaylı ve dolaysız referanslarda bulunduğunu görüyoruz. \"Ey gizlenen\" hitabının muhatabı insandan başka bir şey de olabilir mi? Kitabın sonundaki Notlar bölümünde bu konuda bazı örnekleri bulacaksınız."},{"n":2,"t":"Kalk ve uyar."},{"n":3,"t":"Rabbini yücelt."},{"n":4,"t":"Örtülerini temizle. * 74:4 Bu surenin bağlamı içinde, bu ayetin mecazi olarak işaret ettiği farklı bir anlam var mı?"},{"n":5,"t":"Kötülükten uzaklaş."},{"n":6,"t":"İhtiraslı olma."},{"n":7,"t":"Rabbin için sabret."},{"n":8,"t":"Duyuru yapıldığı zaman,"},{"n":9,"t":"İşte, zorlu gün o gündür."},{"n":10,"t":"İnkarcılar için kolay değil."},{"n":11,"t":"Bir birey olarak yarattığım kişiyi bana bırak."},{"n":12,"t":"Ona hem zenginlik verdim,"},{"n":13,"t":"Hem de gözü önünde çocuklar..."},{"n":14,"t":"Ona nimetler yağdırdım."},{"n":15,"t":"Buna rağmen, daha fazlasını istiyor."},{"n":16,"t":"Asla, çünkü o, ayetlerimize karşı bir inatçı kesildi."},{"n":17,"t":"Onu sarp bir yokuşa sardıracağım."},{"n":18,"t":"Nitekim o düşündü; ölçtü biçti."},{"n":19,"t":"Kahrolası, ne biçim ölçüp biçti."},{"n":20,"t":"Kahrolası, gene ne biçim ölçüp biçti."},{"n":21,"t":"Baktı."},{"n":22,"t":"Sonra surat astı, kaşlarını çattı."},{"n":23,"t":"Ve arkasını döndü; büyüklük tasladı:"},{"n":24,"t":"\"Bu,\" dedi, \"etkileyici bir büyüden başka bir şey değil.\""},{"n":25,"t":"\"Bu sadece bir insan sözüdür.\""},{"n":26,"t":"Onu Sakar'a atacağım."},{"n":27,"t":"Sakar nedir bilir misin?"},{"n":28,"t":"Ne bırakır, ne de yüklenir (tam ve mükemmel),"},{"n":29,"t":"Halklar için (evrensel) bir göstergedir/ekrandır. Matematiksel Mucizenin Kodu"},{"n":30,"t":"Üzerinde ondokuz vardır. * 74:30-35 Kuran'ın Tanrı sözü olduğuna dair, herkese açık fiziksel bir kanıt sağlayan bu büyük mucizenin bazı detaylarını \"Üzerinde 19 Var\" adlı kitapta sergiledik. Bu çevirinin sonundaki Notlar bölümünde bazı örnekleri bulabilirsiniz. Ama dilerseniz, bu konuda araştırma yapmış olanlar tarafından yazılmış hiçbir makale veya kitaba bakmadan, sıfırdan başlayarak, \"Kuran, 19 kodu üzerine kurulu bir matematiksel yapıyla örülmüş müdür?\" sorusunun cevabını kendiniz araştırabilirsiniz: Araştırmayı objektif olarak yaparsanız, şu ana kadar keşfedilen nice örneği aynen bulacağınızdan hiç kuşkum yok. Matematikten ve olasılık hesaplarından pek anlamayan bazı saf kişiler; rakamları yanyana koyarak, ekleyip bölerek manipülasyonlarla sözde \"mucizeler\" bulabildiği gibi; inkarcı bağnazlıktan ötürü Kuran'da mevcut olan matematiksel sistemi görmek istemiyenler de vardır."},{"n":31,"t":"Biz ateşe bekçi olarak sadece melekleri atadık. Onların sayısını (ondokuz'u) da, (1) inkarcılar için bir fitne (sınav/huzursuzluk kaynağı) yaptık, (2) kitap verilmiş olanları ikna etsin, (3) inananların inancını güçlendirsin, (4) kitap verilmiş olanlarla inananların kuşkularını ortadan kaldırsın, ve (5) kalplerinde hastalık olanlarla inkarcılar da, \"ALLAH bu örnekle ne demek istiyor?\" desinler. Böylece ALLAH dilediğini/dileyeni saptırır ve dilediğini/dileyeni de doğruya iletir. Rabbinin ordularını kendisinden başkası bilmez. Bu (sayı) halklara bir mesajdır."},{"n":32,"t":"Hayır, andolsun Ay'a,*100 * 74:32 Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":33,"t":"Geçtiği vakit geceye,"},{"n":34,"t":"Ağardığı vakit sabaha,"},{"n":35,"t":"Bu büyüklerden birisidir.*"},{"n":36,"t":"Halklara bir uyarıdır."},{"n":37,"t":"İlerlemek yahut geride kalmak dileyenleriniz için."},{"n":38,"t":"Her kişi kendi günahıyla mahkum olur."},{"n":39,"t":"Ancak sağ tarafta olanlar hariç;"},{"n":40,"t":"Cennetler içindedirler, sorarlar,"},{"n":41,"t":"Suçlulara:"},{"n":42,"t":"\"Sizi bu cezaya sokan nedir?\""},{"n":43,"t":"Diyecekler ki, \"Desteklemezdik/namaz kılmazdık\" * 74:43 Bu ayetle başlayan ifadeler, hem dindar ve hem dinsiz inkarcıları tanımlamaktadır.Burada \"desteklemezdik/namaz kılmazdık\" diye çevirdiğimiz kelime, bağlam içinde her iki anlama da gelebilir. Bak 2:157; 9:99, 103; 33:43, 56; 75:31."},{"n":44,"t":"\"Yoksula da yedirmezdik.\""},{"n":45,"t":"\"Biz, boş şeylere dalanlarla birlikte dalardık.\""},{"n":46,"t":"\"Yargı gününü yalanlardık.\" * 74:46 Yahudilerin, Hıristiyanların ve müslümanların büyük bir çoğunluğu, aslında Yargı Gününü yalanlamaktadırlar. Yargı Gününün tanımını yapan Kuran'a göre, o günün tek sahibi Allah'tır (1:4) ve o gün kimsenin kimseye bir yararı dokunmaz (82:19). Şefaat yoluyla kurtarılacaklarına inananlar Kuran'ın bildirdiği özelliklere sahip Yargı Gününü inkar etmiş olurlar. Ateistler ise Yargı Gününü açıkça inkar ederler."},{"n":47,"t":"\"Nihayet (şimdi) kesin gerçeğe ulaştık.\" Ne İsa, Ne Muhammed, Ne Ali, Ne de Veli Onları Kurtaramaz"},{"n":48,"t":"Aracıların şefaati onlara bir yarar sağlamaz. Ondokuz Mesajından Kaçıyorlar"},{"n":49,"t":"Öyleyse neden bu mesajdan yüz çeviriyorlar."},{"n":50,"t":"Ürkmüş zebralar gibi,"},{"n":51,"t":"Aslandan kaçan..."},{"n":52,"t":"Hayır, onlardan her biri, kendisine özel olarak açılmış sayfalar verilmesini ister."},{"n":53,"t":"Doğrusu, onlar ahiretten korkmuyor."},{"n":54,"t":"Doğrusu, bu bir öğüttür."},{"n":55,"t":"Dileyen ondan öğüt alır."},{"n":56,"t":"ALLAH dilemezse onlar öğüt alamazlar. O, erdemli davranmanın kaynağıdır; bağışlamanın kaynağıdır."}]},{"id":75,"name":"DİRİLİŞ (KIYAME) SÛRESİ","verses":[{"n":1,"t":"Diriliş Gününe and içerim.*101 * 75:1-2 Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":2,"t":"Sürekli özeleştiride bulunan kişiye and içerim."},{"n":3,"t":"İnsan, kemiklerini bir araya toplayamayız mı sanıyor?"},{"n":4,"t":"Evet; parmak uçlarını bile düzenlemeye gücümüz yeter. * 75:4 Ba ayet, her kişinin parmak uçlarındaki parmak izlerinin, taklidi zor ve hayat boyu değişmeyen birer organik kimlik kartı olduğuna işaret ediyor olabilir mi?"},{"n":5,"t":"Doğrusu, insan her şeyin önüne sergilenmesini ister."},{"n":6,"t":"\"Diriliş Günü ne zaman?\" diye sorar."},{"n":7,"t":"Gözün kamaştığı,"},{"n":8,"t":"Ayın tutulduğu,"},{"n":9,"t":"Ve güneş ile ay bir araya toplandığı zaman,"},{"n":10,"t":"O gün insanoğlu, \"Kaçacak yer nerede?\" der."},{"n":11,"t":"Hayır, bir sığınak yok."},{"n":12,"t":"O gün son durak Rabb'inin huzurudur."},{"n":13,"t":"O gün insana, yapıp yapmadığı herşey haber verilir."},{"n":14,"t":"Doğrusu, insan kendi kendisine tanıktır."},{"n":15,"t":"Birtakım özürler ortaya atsa da... Kuran'ı Açıklayan Muhammed Değil Tanrı'dır"},{"n":16,"t":"Onu aceleye getirip dilini oynatma. * 75:16 Bak 20:114"},{"n":17,"t":"Onu toplamak da okutmak da bize düşer."},{"n":18,"t":"Biz onu okuduğumuz zaman, onun okunuşunu izle."},{"n":19,"t":"Sonra, onu açıklamak da bizim görevimizdir."},{"n":20,"t":"Ne var ki, siz geçici (dünyayı) seviyorsunuz."},{"n":21,"t":"Ahireti ise önemsemiyorsunuz."},{"n":22,"t":"O gün bazı yüzler parlar."},{"n":23,"t":"Rabb'ine bakar."},{"n":24,"t":"O gün bazı yüzler de var ki asıktır."},{"n":25,"t":"Belkemiğinin kırılacağının endişesi içindedir."},{"n":26,"t":"Doğrusu, (nefis) boğaza dayandığı,"},{"n":27,"t":"Ve, \"Çare bulan var mı?\" dendiği zaman."},{"n":28,"t":"Bunun artık o ayrılık zamanı olduğunu anlar."},{"n":29,"t":"Bacakları birbirine dolaşmıştır."},{"n":30,"t":"O gün sevk Rabbine doğrudur."},{"n":31,"t":"O ne doğruladı, ne de destekledi; * 75:31 Bak 74:43."},{"n":32,"t":"Fakat yalanladı ve yüz çevirdi."},{"n":33,"t":"Sonra çalım satarak ailesine gitti."},{"n":34,"t":"Sen bunu haketmişsin."},{"n":35,"t":"Gerçekten sen bunu haketmiş bulunuyorsun."},{"n":36,"t":"İnsan, başıboş bırakılacağını mı sanıyor?"},{"n":37,"t":"Dökülen meniden bir sperm değil miydi?"},{"n":38,"t":"Ve bir embriyoya dönüştükten sonra O yaratıp biçim verdi?"},{"n":39,"t":"Ve ondan erkek ve dişi olmak üzere iki çift yarattı?"},{"n":40,"t":"Bunları yapanın ölüleri diriltmeye gücü yetmez mi?"}]},{"id":76,"name":"İNSAN (İNSAN) SÛRESİ","verses":[{"n":1,"t":"İnsanın üzerinden, kendisinin anılmaya değer bir şey olmadığı bir zaman periyodu geçmemiş midir?"},{"n":2,"t":"Biz insanı bir sıvı karışımdan yarattık ki onu sınayalım. Bu yüzden onu işiten ve gören yaptık."},{"n":3,"t":"Ona yolu gösterdik; ya şükredendir, ya da nankör."},{"n":4,"t":"İnkarcılar için zincirler, prangalar ve alevli bir ateş hazırlamışızdır."},{"n":5,"t":"İyiler ise, kafur (C10H16O) karıştırılmış bir kadehten içerler."},{"n":6,"t":"ALLAH'ın kullarının taşıra taşıra içtikleri bir kaynak..."},{"n":7,"t":"Onlar sözlerini yerine getirirler ve alabildiğine kötü olan bir günden korkarlar."},{"n":8,"t":"Yoksula, öksüze ve tutsağa sevdikleri yiyecekleri yedirirler."},{"n":9,"t":"\"Biz sizi ALLAH rızası için yediriyoruz. Sizden ne bir karşılık, ne de bir teşekkür beklemiyoruz.\""},{"n":10,"t":"\"Biz, suratsız ve belalı bir günden ötürü Rabbimizden çekiniriz.\""},{"n":11,"t":"Nitekim, ALLAH onları o günün kötülüğünden korur ve onlara neşe ve sevinç verir."},{"n":12,"t":"Direndikleri için onları bahçe ve ipekle ödüllendirir."},{"n":13,"t":"Orada koltuklara yaslanırlar; orada ne (yakıcı) güneş ne de dondurucu soğuk görürler."},{"n":14,"t":"Ağaçların gölgesi üzerlerine sarkmış ve meyveler yaklaştırılarak koparılmaları kolaylaştırılmıştır."},{"n":15,"t":"Onlara gümüş tepsiler ve şeffaf bardaklarda sunulur."},{"n":16,"t":"Gümüşten yapılmış şeffaf bardaklar... Onları tam olarak haketmişlerdir. * 76:16 Gümüşten yapılmış şeffaf bardaklar, ateş içinde yetişen ağaç gibi bir mecazdır. Bak 2:26; 17:60. (\"Şeffaf\" diye çevirdiğimiz kelimenin anlamı için bak 27:44)."},{"n":17,"t":"Orada zencefil (ginger) karıştırılmış bir kadehten içirilirler."},{"n":18,"t":"Bir kaynak ki, ona \"Selsebil\" denir."},{"n":19,"t":"Onlara ölümsüz gençler servis yapacaktır. Onları görsen, kendilerini saçılmış inci sanırsın."},{"n":20,"t":"Nereye baksan nimetler ve büyük bir yönetim görürsün."},{"n":21,"t":"Üstlerinde yeşil kadifeden elbiseler ve ipekler vardır. Gümüş bilezikler takınmışlardır. Rab'leri onlara temiz bir içecek içirir."},{"n":22,"t":"Bu, ödülünüzdür ve gayretinize teşekkür edilmiştir."},{"n":23,"t":"Kuşkusuz, Kuran'ı sana bir indirişle biz indirdik."},{"n":24,"t":"Öyleyse Rabbinin hükmünü izlemekte sabret; onlardan hiç bir nankör günahkara uyma."},{"n":25,"t":"Sabah akşam Rabbinin ismini an."},{"n":26,"t":"Geceleyin O'na secde et ve O'nu uzun gecelerde yücelt."},{"n":27,"t":"Bunlar şu geçici (dünya hayatını) seviyorlar ve önlerindeki ağır bir günü ise önemsemiyorlar."},{"n":28,"t":"Onları biz yarattık ve yerleştirdik. Dilediğimiz zaman da onları benzerleriyle değiştiririz."},{"n":29,"t":"Bu bir hatırlatmadır: Dileyen, Rabbine varan bir yol tutar."},{"n":30,"t":"ALLAH dilemedikçe siz dileyemezsiniz. ALLAH Bilendir, Bilgedir. * 76:30 Bak 57:22-23."},{"n":31,"t":"O, dilediğini ve/veya dileyeni Rahmetine sokar. Zalimlere ise acı bir ceza hazırlamıştır."}]},{"id":77,"name":"GÖNDERİLENLER (MURSELAT) SÛRESİ","verses":[{"n":1,"t":"Andolsun ard arda gönderilenlere, * 77:1-6 Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":2,"t":"Esip savuranlara,"},{"n":3,"t":"Yaydıkça yayanlara,"},{"n":4,"t":"Ayırdıkça ayıranlara,"},{"n":5,"t":"Mesajı verenlere,"},{"n":6,"t":"Bir müjde veya uyarı olarak..."},{"n":7,"t":"Size söz verilenler kesinlikle gerçekleşecektir."},{"n":8,"t":"Yıldızlar söndürüldüğü,"},{"n":9,"t":"Göğün yarıldığı,"},{"n":10,"t":"Dağların ufalanıp savrulduğu,"},{"n":11,"t":"Ve elçilere randevu verildiği zaman,"},{"n":12,"t":"Belirlenen gün için..."},{"n":13,"t":"Yani Karar Günü için!"},{"n":14,"t":"O nasıl bir yargılama günüdür bilir misin!"},{"n":15,"t":"Yalanlayanların vay haline o gün!"},{"n":16,"t":"Öncekileri helak etmedik mi?"},{"n":17,"t":"Sonra, diğerlerini de onlara katmadık mı?"},{"n":18,"t":"Suçlulara işte böyle davranırız."},{"n":19,"t":"Yalanlayanların vay haline o gün!"},{"n":20,"t":"Sizi değersiz bir sudan yaratmadık mı?*"},{"n":21,"t":"Ve sonra onu iyi korunan bir yere yerleştirmedik mi?"},{"n":22,"t":"Bilinen bir süreye kadar.*102 * 77:20-23 Modern embriyolojinin belirlemesine göre, olgun bir bebek için gebelik süresi, döllenmeden itibaren tam 266 gün veya 38 haftadır."},{"n":23,"t":"Biz ölçtük, biçtik. Biz en iyi biçim verenleriz."},{"n":24,"t":"Yalanlayanların vay haline o gün!"},{"n":25,"t":"Yeryüzünü bir toplanma yeri yapmadık mı?"},{"n":26,"t":"Yaşayanlar için, ölüler için..."},{"n":27,"t":"Üzerine yüksek dağlar yerleştirip size tatlı su içirmedik mi?"},{"n":28,"t":"Yalanlayanların vay haline o gün!"},{"n":29,"t":"Haydi yalanlamakta olduğunuz şeye doğru yürüyün."},{"n":30,"t":"Yürüyün, (cehennem alevinin) üç kollu gölgesine doğru..."},{"n":31,"t":"O ne gölgelendirir ne de alevden korur."},{"n":32,"t":"Kıvılcımlar saçar, saraylar gibi..."},{"n":33,"t":"(Rengi de) Sarı deve gibi."},{"n":34,"t":"Yalanlayanların vay haline o gün!"},{"n":35,"t":"Bu, onların konuşamıyacağı bir gündür."},{"n":36,"t":"Ve özür dilemeleri için onlara izin de verilmez."},{"n":37,"t":"Yalanlayanların vay haline o gün!"},{"n":38,"t":"Bu, Karar Günüdür. Sizi ve öncekileri toplamışızdır."},{"n":39,"t":"Bir planınız varsa bana karşı onu uygulayın!"},{"n":40,"t":"Yalanlayanların vay haline o gün!"},{"n":41,"t":"Erdemliler gölgeliklerde ve pınarlar arasında..."},{"n":42,"t":"Ve canlarının çektiği meyvalar..."},{"n":43,"t":"Yaptıklarınıza karşılık afiyetle yiyip için."},{"n":44,"t":"İyi davrananları işte böyle ödüllendiririz."},{"n":45,"t":"Yalanlayanların vay haline o gün!"},{"n":46,"t":"Yiyiniz ve geçici olarak eğleniniz; siz suçlularsınız."},{"n":47,"t":"Yalanlayanların vay haline o gün!"},{"n":48,"t":"Onlara eğilin dendiğinde eğilmezler."},{"n":49,"t":"Yalanlayanların vay haline o gün!"},{"n":50,"t":"Artık bundan sonra hangi hadise (söze) inanırlar?"}]},{"id":78,"name":"HABER (NEBE) SÛRESİ","verses":[{"n":1,"t":"Neyi birbirlerine sorup duruyorlar?"},{"n":2,"t":"Büyük haberi mı?*103 * 78:2 Kuran'ın inişi büyük bir haberdi. Bak 38:67"},{"n":3,"t":"Ki onlar onda anlaşmazlık halindedirler."},{"n":4,"t":"Hayır, öğreneceklerdir."},{"n":5,"t":"Hayır, kesinlikle öğreneceklerdir."},{"n":6,"t":"Yapmadık mı yeryüzünü bir beşik,"},{"n":7,"t":"Dağları da birer kazık?"},{"n":8,"t":"Sizi çiftler halinde yarattık."},{"n":9,"t":"Uykunuzu bir dinlenme yaptık."},{"n":10,"t":"Geceyi bir örtü yaptık."},{"n":11,"t":"Gündüzü de geçimi sağlama zamanı olarak belirledik."},{"n":12,"t":"Ve üstünüze yedi sağlam (göğü) kurduk."},{"n":13,"t":"Parlayan bir lamba yerleştirdik."},{"n":14,"t":"Bulutlardan ise şarıl şarıl yağmur indirdik."},{"n":15,"t":"Ki onunla taneler ve bitkiler."},{"n":16,"t":"Ve çeşit çeşit bahçeler çıkaralım."},{"n":17,"t":"Yargılama Günü, belirlenmiş bir vakittedir."},{"n":18,"t":"Sur'a üfürüldüğü gün, hepiniz bölük bölük gelirsiniz."},{"n":19,"t":"Gök açılmış; kapı kapı olmuştur."},{"n":20,"t":"Dağlar yürütülmüş; serap olmuştur."},{"n":21,"t":"Cehennem ise gözetlemekte:"},{"n":22,"t":"Azgınlar için bir varış yeri olarak..."},{"n":23,"t":"Orada çağlar boyu kalacaklardır."},{"n":24,"t":"Orada bir serinlik ve bir içecek bulamazlar;"},{"n":25,"t":"Ancak kaynar su ve acı bir yiyecek hariç."},{"n":26,"t":"Yaptıklarına uygun bir karşılık olarak. Cahiller Bir Hesap Ummadılar"},{"n":27,"t":"Onlar bir hesap ummuyorlardı. * 78:27 Burada sözü edilen hesap, dirildikten sonra yargılanmanın dışında başka bir şeyi daha içerir mi?"},{"n":28,"t":"Ve ayetlerimizi, mucizelerimizi yalanladılar."},{"n":29,"t":"Halbuki biz herşeyi sayıp yazmıştık."},{"n":30,"t":"Öyleyse tadın, sizin sadece cezanızı arttıracağız. Erdemliler"},{"n":31,"t":"Erdemliler için kurtuluş vardır."},{"n":32,"t":"Bağlar, bahçeler..."},{"n":33,"t":"Genç ve yaşıt eşler..."},{"n":34,"t":"Dolu kadehler..."},{"n":35,"t":"Orada ne bir boş söz ne de bir yalan işitmezler."},{"n":36,"t":"Rabbinden bir karşılık; hesaplanmış bir armağandır."},{"n":37,"t":"Göklerin, yerin ve aralarındakilerin Rabbidir, Rahman'dır. Hiç bir davada O'na hitap edemezler."},{"n":38,"t":"Gün gelecek Ruh ve melekler sıra sıra dururlar. Rahman'ın izin verdikleri hariç hiç kimse konuşamaz. Onlar da doğruyu söylerler."},{"n":39,"t":"İşte gerçek gün budur. Dileyen, Rabbine doğru yol tutsun."},{"n":40,"t":"Biz, sizi yakın bir azap ile uyarmış bulunuyoruz. O gün kişi yapmış olduklarına bakar ve inkarcı ise, \"Keşke toprak olsaydım!\" der."}]},{"id":79,"name":"SÖKÜP ÇIKARANLAR (NAZİAT) SÛRESİ","verses":[{"n":1,"t":"Andolsun söküp çıkaranlara,*104 * 79:1-5 Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":2,"t":"Rahatça çekenlere,"},{"n":3,"t":"Yüzüp akanlara,"},{"n":4,"t":"Yarışıp birbirlerini geçenlere,"},{"n":5,"t":"Ve böylece emirleri uygulayanlara..."},{"n":6,"t":"O gün o sarsıntı sarsar."},{"n":7,"t":"Ardından bir diğeri izler."},{"n":8,"t":"O gün yürekler titrer."},{"n":9,"t":"Gözleri ise alçalır."},{"n":10,"t":"Derler ki, \"Daha önceki halimize mi döndürüldük?\""},{"n":11,"t":"\"Biz çürümüş kemikler olduktan sonra ha!?\""},{"n":12,"t":"\"Öyleyse bu zararına bir dönüştür,\" derler."},{"n":13,"t":"O bir tek dürtüşten ibarettir."},{"n":14,"t":"Onlar uyanıvermişlerdir."},{"n":15,"t":"Sana Musa'nın tarihi ulaştı mı?"},{"n":16,"t":"Rabbi, kutsal Tuva vadisinde ona seslenmişti:"},{"n":17,"t":"\"Firavun'a git; o azdı.\""},{"n":18,"t":"\"Ona de ki: Arınmayacak mısın?\""},{"n":19,"t":"\"Seni Rabbine ileteyim de saygılı olasın.\""},{"n":20,"t":"Ona büyük mucizeyi gösterdi."},{"n":21,"t":"Fakat o yalanladı ve karşı geldi."},{"n":22,"t":"Sonra, sırtını döndü, (aleyhte) çaba gösterdi."},{"n":23,"t":"Toplayıp, ilan etti."},{"n":24,"t":"\"Ben sizin en yüce rabbinizim,\" dedi. * 79:24 Köle sahipleri Arapça'da efendi anlamına gelen \"rab\" kelimesiyle ifade edilir (12:41). Firavunlar köleleştirdikleri insanlar üzerinde efendilik \"rablık\" iddiasındaydı. İnsanları köleleştirmek yoluyla efendilik (rablık) iddia etmek, kendini Tanrı'ya ortak koşmaktır. Bak 12:39-42; 90:13; 4:25."},{"n":25,"t":"Sonunda, ALLAH onu ahiret ve dünya cezasına çarptı."},{"n":26,"t":"Kuşkusuz, saygı duyanlar için bunda bir ibret vardır."},{"n":27,"t":"Siz mi, yoksa gök mü yaratılış açısından daha zorludur? Onu O yaptı."},{"n":28,"t":"Onu alabildiğine yükseltti ve düzenledi."},{"n":29,"t":"Gecesini kararttı, sabahını ise ortaya çıkardı. Dünya Küreseldir"},{"n":30,"t":"Ve yeri de yumurta biçimine soktu * 79:30 Arapça \"dahhaha\" kelimesinin yalın hali olan \"dahya\" kelimesi \"yumurta\" anlamına gelir. Dünyanın yumurta gibi yuvarlak olamıyacağına inanan eski Kuran yorumcuları, \"onu yumurta biçimine soktu\" ifadesini bir mecaz olarak kabul etmişler ve yumurta kelimesiyle yumurtanın konduğu kuluçkanın kastedilmiş olduğunu ileri sürmüşlerdir. Böylece çok açık olan ayetin anlamını bozarak \"Ve yeri de kuluçka gibi düzenledi,\" diye tefsir etmişlerdir. Bak 4:82."},{"n":31,"t":"Ondan suyunu ve otlağını çıkardı."},{"n":32,"t":"Dağları da çaktı."},{"n":33,"t":"Tüm bunlar sizin ve hayvanlarınızın geçimi için."},{"n":34,"t":"Büyük baskın geldiği zaman,"},{"n":35,"t":"O gün insan, neyin uğrunda çaba harcadığını anlar."},{"n":36,"t":"Cehennem göz önüne çıkarılacaktır."},{"n":37,"t":"Azgınlara,"},{"n":38,"t":"Ve dünya hayatını yeğleyenlere gelince."},{"n":39,"t":"Gidilecek yer cehennem olacaktır."},{"n":40,"t":"Rabbinin makamına karşı saygı duyan ve kendini kötü arzulardan alıkoyanlara gelince"},{"n":41,"t":"Gidilecek yer cennet olacaktır."},{"n":42,"t":"Sana Saat (dünyanın sonu) ne zaman gerçekleşecektir diye soruyorlar."},{"n":43,"t":"Onu bildirmek, (ey Muhammed) senin görevin değildir."},{"n":44,"t":"Onun kararı Rabbine aittir."},{"n":45,"t":"Senin görevin, sadece ondan korkanları uyarmaktır."},{"n":46,"t":"Onu gördükleri gün, sanki (dünyada) bir akşam veya kuşluk vakti kadar kalmışlardır."}]},{"id":80,"name":"SURAT ASTI (ABESE) SÛRESİ","verses":[{"n":1,"t":"Surat astı ve döndü;"},{"n":2,"t":"O kör adam geldi diye."},{"n":3,"t":"Ne bilirsin, belki de o arınacak;"},{"n":4,"t":"Yahut ta öğüt alacak ve ona mesajın yararı dokunacaktı."},{"n":5,"t":"Kendisini zengin görüp önemsemeyene gelince;"},{"n":6,"t":"Sen ona yöneliyorsun."},{"n":7,"t":"Onun arınmamasından sana ne?"},{"n":8,"t":"Oysa, sana büyük bir hevesle gelen,"},{"n":9,"t":"Saygı gösterdiği halde,"},{"n":10,"t":"İlgi göstermedin ona."},{"n":11,"t":"Doğrusu, bu bir hatırlatmadır."},{"n":12,"t":"Dileyen bundan öğüt alır."},{"n":13,"t":"Onurlu kitaplardadır,"},{"n":14,"t":"Yüce ve temiz."},{"n":15,"t":"Elçilerin elleriyle (yazılmıştır)."},{"n":16,"t":"Onurlu ve güzel huylu (elçiler)."},{"n":17,"t":"Yazıklar olsun insana; ne kadar da nankördür!"},{"n":18,"t":"Onu hangi şeyden yaratmıştı?"},{"n":19,"t":"Bir spermadan onu yarattı; ölçü ve biçim verdi."},{"n":20,"t":"Sonra ona yolu kolaylaştırdı."},{"n":21,"t":"Sonra onu öldürdü, mezara koydu."},{"n":22,"t":"Dilediği zaman da onu diriltti."},{"n":23,"t":"Ne var ki O'nun kendisine emrettiğini yerine getirmedi."},{"n":24,"t":"İnsan, yiyeceğine bir baksın!"},{"n":25,"t":"Biz suyu döktükçe döktük."},{"n":26,"t":"Toprağı yardıkça yardık."},{"n":27,"t":"Ve orada taneler bitirdik,"},{"n":28,"t":"Üzümler, çayırlar,"},{"n":29,"t":"Zeytinler, hurmalar,"},{"n":30,"t":"İri ve sık ağaçlı bahçeler,"},{"n":31,"t":"Meyveler ve sebzeler..."},{"n":32,"t":"Size ve hayvanlarınıza bir geçimlik olarak."},{"n":33,"t":"Sonra, o müthiş patlama gerçekleşince,"},{"n":34,"t":"O gün kişi kaçar: kardeşinden,"},{"n":35,"t":"Annesinden, babasından,"},{"n":36,"t":"Eşinden ve çocuklarından..."},{"n":37,"t":"O gün herkesin kendisine yetecek işi vardır."},{"n":38,"t":"O gün bazı yüzler var ki aydınlık;"},{"n":39,"t":"Güleç, neşeli."},{"n":40,"t":"O gün bazı yüzler de perişan;"},{"n":41,"t":"Karanlık bürümüştür."},{"n":42,"t":"İşte onlar inkarcılardır, sapanlardır."}]},{"id":81,"name":"YUVARLAMA (TEKVİR) SÛRESİ","verses":[{"n":1,"t":"Güneş yuvarlandığı zaman,"},{"n":2,"t":"Yıldızlar sönüp düştüğü zaman,"},{"n":3,"t":"Dağlar yürütüldüğü zaman,"},{"n":4,"t":"En değerli mallar terkedildiği zaman,"},{"n":5,"t":"Yabani hayvanlar toplandığı zaman,"},{"n":6,"t":"Denizler kaynatıldığı zaman,"},{"n":7,"t":"Nefisler/kişiler çiftleştirildiği zaman,"},{"n":8,"t":"Canlı canlı gömülen kız çocuğu sorulduğu zaman:"},{"n":9,"t":"Hangi suçtan ötürü öldürüldü diye."},{"n":10,"t":"Kayıtlar yayımlandığı zaman,"},{"n":11,"t":"Gök yerinden oynatıldığı zaman,"},{"n":12,"t":"Cehennem alevlendirildiği zaman,"},{"n":13,"t":"Cennet yaklaştırıldığı zaman,"},{"n":14,"t":"Her kişi ne yapıp getirdiğini bilir."},{"n":15,"t":"Andolsun gizlenen yıldızlara, * 81:15-19 Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":16,"t":"Akıp deliklerine girenlere."},{"n":17,"t":"Andolsun kararmaya başlayan geceye,"},{"n":18,"t":"Ve nefes almağa başlayan sabaha,"},{"n":19,"t":"Bu, onurlu bir elçinin sözüdür."},{"n":20,"t":"Güçlüdür; Yönetimin Sahibi katından yetkilidir."},{"n":21,"t":"Kendisine uyulmalı ve güvenilmeli."},{"n":22,"t":"Arkadaşınız deli değildir."},{"n":23,"t":"Onu apaçık bir ufukta görmüştür. * 81:23 Bak 53:1-18"},{"n":24,"t":"O, hiçbir haberi gizlemiyor."},{"n":25,"t":"O, kovulan şeytanın sözü olamaz."},{"n":26,"t":"Öyleyse nereye gidiyorsunuz?"},{"n":27,"t":"Bu, tüm halklara bir mesajdır."},{"n":28,"t":"Sizden doğru davranmak isteyenler için..."},{"n":29,"t":"Ne dilerseniz, ancak evrenlerin Rabbi olan ALLAH'ın dilediğine göredir. * 81:29 Bak 57:22-23."}]},{"id":82,"name":"YARILMA (İNFİTAR) SÛRESİ","verses":[{"n":1,"t":"Gök yarıldığı zaman,"},{"n":2,"t":"Gezegenler saçıldığı zaman,"},{"n":3,"t":"Denizler akıtılıp taşırıldığı zaman,"},{"n":4,"t":"Mezarların içi dışına çevrildiği zaman,"},{"n":5,"t":"Her kişi, yaptığını ve yapmadığını öğrenecektir. Tanrı'nın Yaratış Sistemini Düşünmek"},{"n":6,"t":"Ey insan, seni Onurlu olan Rabbine karşı aldatan nedir?"},{"n":7,"t":"O ki seni yarattı, düzenledi, uyumlu hale soktu; * 82:7 Bak 4:119."},{"n":8,"t":"Dilediği bir biçimde seni oluşturdu."},{"n":9,"t":"Doğrusu, siz, dini yalanlıyorsunuz."},{"n":10,"t":"Halbuki üstünüzde koruyucular vardır."},{"n":11,"t":"Onlar onurlu kayıtçılardır."},{"n":12,"t":"Yaptıklarınızı bilirler."},{"n":13,"t":"İyiler nimetler içindedir."},{"n":14,"t":"Kötüler ise cehennemde."},{"n":15,"t":"Din Günü oraya girerler."},{"n":16,"t":"Oradan hiç ayrılamazlar."},{"n":17,"t":"Din Gününün ne olduğunu bilir misin?"},{"n":18,"t":"Evet, Din Gününün ne olduğunu bilir misin?"},{"n":19,"t":"O gün kimsenin kimseye yardımı dokunmaz. O gün tüm kararlar yalnız ALLAH'a aittir. * 82:19 Kuran boyunca sadece bu sure \"Allah\" kelimesiyle son bulmakta ve bu surenin 19. ayetinde yer alan \"Allah\" kelimesi Kuran'ın sonundan itibaren 19. sırada yer almaktadır. Baştan itibaren 19. sırada yer alan \"Allah\" sözcüğü için 2:55 ayetine bakınız. Ayrıca, Din Günü için bak 1:4 ve 74:46."}]},{"id":83,"name":"KANDIRANLAR (MUTAFFİFİN) SÛRESİ","verses":[{"n":1,"t":"Yazıklar olsun kandıranlara."},{"n":2,"t":"Halktan bir şey aldıklarında ölçüyü tam uygularlar."},{"n":3,"t":"Verdikleri zaman ise ölçüyü ve tartıyı eksik tutarlar."},{"n":4,"t":"Onlar hiç dirileceklerini sanmazlar mı?"},{"n":5,"t":"Büyük bir günde?"},{"n":6,"t":"O gün halk Evrenlerin Rabbinin huzurunda dururlar. Rakamlarla Kodlanmış Kitap 7. Doğrusu, kötülerin yazgısı Siccin'dedir. 8. Siccin nedir bilir misin? 9. Rakamlanmış bir kitaptır. * 83:9,20 İnkarcılar için bir zindan (Siccin), iyiler için ise bir kule (İlliyyun) fonksiyonu gösteren ve onların yazgılarını içeren kitap, \"Kitabun Markum\" yani Rakamlarla Kodlanmış Kitap olarak tanımlanır. İnkarcılar onu yalanlar; iyiler ise ona tanık olurlar."},{"n":10,"t":"O gün yalanlayanlara yazıklar olsun."},{"n":11,"t":"Onlar Din Gününü yalanlar. * 83:11 \"Din Günü\"nün tanımı 82:19'da Yargı Günü olarak yapılmıştır. Herhangi bir yaratığın şefaat ederek kendilerini kurtaracağına inananlar Kuran'da tanımı yapılan Din Gününü inkar etmiş olurlar. Ayrıca bak 74:46-48 ve 1:4"},{"n":12,"t":"Onu ancak azgın günahkarlar yalanlar."},{"n":13,"t":"Kendisine ayetlerimiz iletildiğinde, \"Efsane\" derdi."},{"n":14,"t":"Doğrusu, işledikleri günahlar kalplerini kaplamış."},{"n":15,"t":"Doğrusu, o gün onlar Rab'lerinden perdelenir."},{"n":16,"t":"Ve böylece onlar cehenneme atılır."},{"n":17,"t":"\"Yalanlamakta olduğunuz şey işte budur\" denir."},{"n":18,"t":"Doğrusu, iyilerin kitabı İlliyyun'dadır."},{"n":19,"t":"İlliyyun nedir bilir misin?"},{"n":20,"t":"Rakamlanmış bir kitaptır.*"},{"n":21,"t":"(Tanrı'ya) yakın olanlar ona tanık olur."},{"n":22,"t":"İyiler nimetler içindedir."},{"n":23,"t":"Koltuklar üzerinde çevreyi seyrederler."},{"n":24,"t":"Yüzlerinden nimetlerin sevinç ve parıltısını okursun."},{"n":25,"t":"Çeşni katılmış bir nektardan içirilecekler."},{"n":26,"t":"Çeşnisi misktir. Yarışanlar işte bunun için yarışsınlar."},{"n":27,"t":"Onun karışımı Tesnimdir."},{"n":28,"t":"Ki o, (Tanrı'ya) yakın olanların içtiği bir pınardır."},{"n":29,"t":"Suçlular, inananlara gülerlerdi."},{"n":30,"t":"Yanlarından geçtikleri zaman da birbirlerine göz kaş edip küçümserlerdi."},{"n":31,"t":"Taraftarlarının yanına döndükleri zaman da alaya alırlardı."},{"n":32,"t":"Onları gördüklerinde, \"Bunlar sapıklardır!\" derlerdi."},{"n":33,"t":"Oysa onların üzerine gözcü olarak gönderilmemişlerdi."},{"n":34,"t":"Bugün de inananlar inkarcılara güler."},{"n":35,"t":"Koltuklar üzerinde bakarlar:"},{"n":36,"t":"İnkarcılar yaptıklarıyla cezalandılar mı diye."}]},{"id":84,"name":"ÇATLAMA (İNŞİKAK) SÛRESİ","verses":[{"n":1,"t":"Gök çatladığı zaman."},{"n":2,"t":"Ve doğal yapısı gereğince Rabbine kulak verdiği zaman."},{"n":3,"t":"Yer dümdüz edildiği,"},{"n":4,"t":"İçindekileri atıp boşalttığı,"},{"n":5,"t":"Ve doğal yapısı gereğince Rabbine kulak verdiği zaman."},{"n":6,"t":"Ey insan, Rabbine doğru çalışıp çabalarsın ve sonunda O'nunla karşılaşırsın."},{"n":7,"t":"Kitabı sağ taraftan verilen,"},{"n":8,"t":"Kolay bir hesaba çekilecek,"},{"n":9,"t":"Ve arkadaşlarına sevinç içinde dönecektir."},{"n":10,"t":"Kitabı arkasından verilen ise,"},{"n":11,"t":"Yok olmayı arzulayacak,"},{"n":12,"t":"Ve bir ateşte yanacaktır."},{"n":13,"t":"Oysa arkadaşları arasında sevinçliydi;"},{"n":14,"t":"Bir daha (Rabbine) dönmeyeceğini sanmıştı."},{"n":15,"t":"Doğrusu, Rabbi onu görmektedir."},{"n":16,"t":"Andolsun akşamın kızıllığına,"},{"n":17,"t":"Gecenin topladığına,"},{"n":18,"t":"Dolunay halindeki aya,"},{"n":19,"t":"Siz evreden evreye binip geçeceksiniz."},{"n":20,"t":"Peki onlar neden inanmıyorlar?"},{"n":21,"t":"Onlara Kuran okunduğunda neden kabul etmiyorlar?"},{"n":22,"t":"Aksine, inkarcılar yalanlıyorlar."},{"n":23,"t":"ALLAH onların sakladıklarını çok iyi bilir."},{"n":24,"t":"Onları acı bir azapla müjdele."},{"n":25,"t":"İnanıp erdemli davrananlara ise kesilmez bir ödül var."}]},{"id":85,"name":"GALAKSİLER (BURUC) SÛRESİ","verses":[{"n":1,"t":"Andolsun galaksiler sahibi göğe. * 85:1 \"Buruc\" kelimesi Burc'un çoğulu olup yıldız kümeleri, yani galaksiler demektir. Yıldızlara tapanların burçlara yakıştırdığı paranormal güçlere olan inanç, dünyanın birçok ülkesinde insanlar arasında hala taraftar bulmaktadır. Günlük astroloji falları en modern gazetelerde bile görülebilir. Astrolojiyi dinsel semboller ve öğretilerle karıştırarak saf insanları sömüren şarlatanlar, kendilerine inananları genel ifadelerle kandırmakta bir hayli başarılıdır. Astrolojiyi bir bilim diye sunanların mumlarını söndürmek için şöyle bir deneyi önerebilirsiniz: Doğum günleri hakkında bilgi sahibi olamıyacakları 6 kişi seçmeli, onlara karakterleri ile ilgili beş-altı soru sorma imkanı verilmeli ve cevaplara dayanarak onların burçlarının, yani doğdukları ayların bilinmesi istenmeli. Her burç belli bir karakteri ve kaderi temsil ediyorsa, belli karakter ve kaderlerden kişilerin burçlarını bulmak da mümkün olmalıdır. Ayrıca, Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":2,"t":"Söz verilen güne,"},{"n":3,"t":"Ve tanığa da tanık olunana da andolsun."},{"n":4,"t":"Kanyon halkına yazıklar olsun."},{"n":5,"t":"Tutuşturulmuş ateşin-"},{"n":6,"t":"Başında oturmuşlar,"},{"n":7,"t":"Ve inananlara yaptıkları işkenceyi seyrediyorlar."},{"n":8,"t":"İnananlardan nefret ediyorlardı. Sadece, onlar Üstün ve Övgüye layık olan ALLAH'a inandıkları için..."},{"n":9,"t":"Göklerin ve yerin yönetimi O'na aittir. Ve ALLAH herşeye Tanıktır."},{"n":10,"t":"İnanan erkeklere ve kadınlara zulüm ve işkencede bulunan ve daha sonra tevbe etmeyenler cehennem azabını haketmişlerdir. Onlar için yakıcı bir azap vardır."},{"n":11,"t":"İnanan ve erdemli davrananlar ise içlerinden ırmaklar akan cennetleri haketmişlerdir. Büyük başarı budur."},{"n":12,"t":"Doğrusu, Rabbinin yakalaması pek çetindir."},{"n":13,"t":"Başlatan ve tekrarlayan O'dur."},{"n":14,"t":"O Bağışlayandır, Sevendir."},{"n":15,"t":"Şanlı yönetimin sahibidir."},{"n":16,"t":"Dilediğini yapandır."},{"n":17,"t":"Orduların tarihinden haberin var mı?"},{"n":18,"t":"Firavun'un, Semud'un?"},{"n":19,"t":"İnkarcılar, kronik yalanlayıcılardır."},{"n":20,"t":"ALLAH onları arkalarından kuşatmıştır."},{"n":21,"t":"Gerçekten, o şanlı bir Kuran'dır."},{"n":22,"t":"Korunmuş bir ana levhadadır. * 85:22 Kuran'ın matematiksek sistemi onun her elementinin Tanrı tarafından korunduğunu sergiler. Buradaki \"levha\" kelimesi ile 74:29'daki \"levvaha\" kelimesinin aynı kökten oluşu ilginçtir. Bak 74:30."}]},{"id":86,"name":"PARLAK YILDIZ (TARIK) SÛRESİ","verses":[{"n":1,"t":"Göğe ve Tarık'a andolsun. * 86:1 Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":2,"t":"Tarık'ın ne olduğunu bilir misin?"},{"n":3,"t":"Parlak yıldızdır."},{"n":4,"t":"Her kişinin üzerinde mutlaka bir koruyucu vardır."},{"n":5,"t":"İnsan neden yaratılmış olduğuna bir baksın."},{"n":6,"t":"Atılan bir sıvıdan yaratıldı."},{"n":7,"t":"Omurga ile kaburga kemikleri arasından çıkar."},{"n":8,"t":"Kuşkusuz O, onu diriltmeğe gücü yetendir."},{"n":9,"t":"Gizemlerin ortaya çıkarılacağı gün."},{"n":10,"t":"Onun ne bir gücü ne de bir yardımcısı olmayacaktır."},{"n":11,"t":"Geri çeviren göğe andolsun,"},{"n":12,"t":"Ve yarılan yeryüzüne andolsun ki,"},{"n":13,"t":"Bu, ayırdedici bir sözdür."},{"n":14,"t":"Şakaya alınamaz."},{"n":15,"t":"Onlar bir plan kuruyor."},{"n":16,"t":"Ben de bir plan kuruyorum."},{"n":17,"t":"Öyleyse inkarcılara az bir süre daha tanı."}]},{"id":87,"name":"YÜCE (A'LA) SÛRESİ","verses":[{"n":1,"t":"Yüce Rabbinin ismini eksikliklerden uzak tut."},{"n":2,"t":"O ki yarattı, düzene koydu."},{"n":3,"t":"O ki ölçtü, yol gösterdi."},{"n":4,"t":"O ki yeşillikler bitirdi."},{"n":5,"t":"Sonra onu kuruyup kararmış bir samana çevirir."},{"n":6,"t":"Seni okutacağız; sen de unutmayacaksın."},{"n":7,"t":"ALLAH'ın dilediği hariç; O açığı da bilir, gizliyi de."},{"n":8,"t":"Sana kolayı daha da kolaylaştıracağız."},{"n":9,"t":"Öğüt yararlı olacaksa öğüt ver."},{"n":10,"t":"Saygı duyanlar öğüt alacaktır."},{"n":11,"t":"Mutsuz ise ondan yan çizecektir."},{"n":12,"t":"Ve büyük ateşe girecektir."},{"n":13,"t":"Nitekim, orada ne ölecek, ne de yaşayacaktır."},{"n":14,"t":"Kurtulmuştur arınan,"},{"n":15,"t":"Rabbinin ismini anıp namaz kılan."},{"n":16,"t":"Ne var ki siz dünya hayatını seçiyorsunuz."},{"n":17,"t":"Oysa ahiret daha iyi ve süreklidir."},{"n":18,"t":"Bu, ilk sayfalarda/öğretilerde kayıtlıdır."},{"n":19,"t":"İbrahim'in ve Musa'nın sayfalarında."}]},{"id":88,"name":"BUNALTAN (ĞAŞİYE) SÛRESİ","verses":[{"n":1,"t":"Sana o bunaltanın haberi ulaştı mı?"},{"n":2,"t":"O gün yüzler saygı gösterir."},{"n":3,"t":"Çalışmıştır, yorgun düşmüştür."},{"n":4,"t":"Kızgın ateşe girerler."},{"n":5,"t":"Kaynar bir pınardan içirilirler."},{"n":6,"t":"Değersiz bir yiyeceğin dışında bir şeyleri yoktur;"},{"n":7,"t":"Ne besler, ne de açlığı giderir."},{"n":8,"t":"O gün başka yüzler de var ki mutludur."},{"n":9,"t":"Yaptıklarından ötürü sevinçlidir."},{"n":10,"t":"Yüksek bir cennettedir."},{"n":11,"t":"Orada bir saçmalık işitmezler."},{"n":12,"t":"Orada akan bir kaynak var."},{"n":13,"t":"Orada yüksek mobilyalar var."},{"n":14,"t":"Kadehler konulmuş,"},{"n":15,"t":"Yastıklar dizilmiş,"},{"n":16,"t":"Ve halılar serilmiştir."},{"n":17,"t":"Bakmazlar mı develere, nasıl yaratıldı?"},{"n":18,"t":"Ve göğe, nasıl yükseltildi?"},{"n":19,"t":"Ve dağlara, nasıl dikildi?"},{"n":20,"t":"Ve yere, nasıl döşendi?"},{"n":21,"t":"Hatırlat, çünkü sen hatırlatıcısın."},{"n":22,"t":"Sen onları zorlayacak değilsin."},{"n":23,"t":"Fakat kim yüz çevirir ve inkar ederse,"},{"n":24,"t":"ALLAH onu en büyük ceza ile cezalandırır."},{"n":25,"t":"Onların dönüşleri bizedir."},{"n":26,"t":"Hesaplarını görmek de bize düşer."}]},{"id":89,"name":"TAN (FECR) SÛRESİ","verses":[{"n":1,"t":"Andolsun tan vaktine,"},{"n":2,"t":"On geceye,"},{"n":3,"t":"Çifte ve teke,"},{"n":4,"t":"Ve geçmekte olan geceye."},{"n":5,"t":"Zeka sahipleri için bunlar birer yemin değil midir? * 89:5 Kuran'da \"andolsun\" olarak çevirdiğimiz \"yeminler\" Kuran dilinde bazı gerçeklere dikkat çekmek amacıyla kullanılır. Tüm yemin ayetlerini \"dikkatinizi .....'a çekerim\" diye çevirmek mümkün. Yeminin halk arasındaki kullanışını temel alarak, Kuran'daki yeminlere eleştiri getiren inkarcılar, \"Tanrı nasıl olur da yemin ediyor?\" diye itirazlarda bulunabilmektedir. Tanrı'yı kendi arzularına göre biçimlendirdikleri bir kalıba oturtma hevesinde olanlar, Kuran'daki yeminleri dikkatle inceleseler o yeminlerin halk tarafından yapılan yeminlerden farklı bir fonksiyona sahip olduklarını göreceklerdi. Biz yemin edince Tanrı'yı sözümüze tanık tutarız; o kadar. Yeminle desteklemeye çalıştığımız tezimizin doğruluk derecesine göre, bu tanıklık lehimizde de aleyhimizde de olabilir. Bu nedenle, bizim Tanrı ismiyle yemin etmemizin herhangi bir kanıtlama değeri yoktur. Yeminlerimiz, muhatabımızı inandırmayı amaçlar; yalan söylüyorsak yalanımızı büyütür ve sorumluluğumuzu arttırır. Oysa, Kuran'daki yeminler, bizi inandırmak için değil, düşündürmek içindir. Tanrı yarattıklarıyla yemin edince, dikkatimizi doğadaki ayetlere, düzene ve sisteme çekerek rasyonel ve tutarlı düşünmeye teşvik eder. Kuran, doğayı yaratan ve idare eden Yaratıcı ile bu mesajı gönderen Tanrı arasında bir fark olmadığını ve doğa ayetleriyle kitabın ayetlerinin gerçeklik bakımından aynı olduğunu hatırlatır. Kendisiyle yemin edilerek dikkat çekilen nesneler ve olaylar, bu genel hatırlatmanın ötesinde, tartışılacak olan konuya veya teze zihinlerimizi hazırlayan estetik ve semantik tablolar sunarlar. Örneğin, yukarıdaki yeminler onluk ve ikili sayı sistemlerine dikkatimizi çekiyor olabilir mi? On gece 7:141 ayetindeki on gece'ye işaret olabilir mi? Dördüncü ayet ile 74:33 arasında bir anlam ilişkisi var mı? Bak: 56:75; 69:38; 70:40; 75:1,2; 77:1-7; 79:1-5; 81:15-19; 84:16; 85:1-3; 86:1, 11-13; 90:1; 91:1-8; 92:1-4; 93:1-3; 95:1-4; 100:1-6; 103:2."},{"n":6,"t":"Görmedin mi Rabbin ne yaptı Ad halkına?"},{"n":7,"t":"Yüksek kulelere sahip İrem'e ki; * 89:7 Kaybolan Irem kentinin taş kulelerinin, şehrin kayboluşundan 4800 yıl sonra, Amerikalı arkeologlar tarafından Umman'da keşfedildiği ileri sürüldü. Bu keşif, Challenger uzay gemisine takılmış, kumların altını görebilen SIR-B radarlarıyla NASA'daki bilim adamları tarafından bölgenin taranması sonucu gerçekleşmiş. (Newsweek, Şubat 17, 1992, s. 38)."},{"n":8,"t":"Hiç bir ülkede eşi ortaya konmamıştı?"},{"n":9,"t":"Vadideki kayaları oyan Semud'a?"},{"n":10,"t":"Ve piramitler sahibi Firavun'a?"},{"n":11,"t":"Tüm bunlar ülkelerinde azmışlardı."},{"n":12,"t":"Oralarda kötülükleri yaygınlaştırmışlardı."},{"n":13,"t":"Nitekim, Rabbin de üstlerine türlü felaketler yağdırdı. * 89:13 Tanrı'nın doğaya koyduğu yasalara aykırı bireysel veya toplumsal isyanlar çeşitli felaketlere yol açar. Örneğin, enerji israfı ve sorumsuzluk hava, su kirliliğine ve sert iklim koşullarına; diktatörlük yönetimleri ve ırkçılık gibi sosyal ve politik azgınlıklar, iç savaş, yoksulluk ve kıtlığa; cinsel ilişkilerde sınır tanımamazlık, cinsel hastalıklara, sahipsiz çocuklara ve suç artışına; fizik yasalarına kayıtsızlık depremlerde can kaybına; içki, esrar, eroin gibi aptallaştırıcı maddeleri kullanmak bireye ve topluma çeşitli zararlara; kumar, sahtekarlık, tefecilik gibi üreticiliğe aykırı uğraşlar da sosyal ve ekonomik felaketlere yol açar. Bireylere ve özellikle azınlıklara fikir ve inanç özgürlüğünün tanınmaması ise tüm kötülüklere davetiye çıkarır."},{"n":14,"t":"Rabbin sürekli gözetlemektedir."},{"n":15,"t":"Rabbi, sınamak için insana bolca verip sevindirdiği zaman, \"Rabbim bana cömert davrandı,\" der."},{"n":16,"t":"Ancak ne zaman ki rızkını kısarak onu sınarsa, \"Rabbim beni küçük düşürdü,\" der."},{"n":17,"t":"Hayır! Doğrusu siz öksüze cömert davranmıyorsunuz?"},{"n":18,"t":"Yoksulu yedirmeye birbirinizi teşvik etmiyorsunuz."},{"n":19,"t":"Mirası da hak gözetmeden yiyorsunuz."},{"n":20,"t":"Parayı/malı da çok fazla seviyorsunuz."},{"n":21,"t":"Doğrusu, yer çarpılıp paralandığı zaman,"},{"n":22,"t":"Rabbin, dizi dizi meleklerle birlikte geldiği zaman,"},{"n":23,"t":"Ki cehennem de o gün getirilmiştir. İşte o gün insan anlayacaktır. Artık anlamanın kendisine ne yararı var ki!"},{"n":24,"t":"\"Keşke bu hayatım için önceden bir şeyler yapsaydım,\" der."},{"n":25,"t":"O gün, O'nun cezası gibi bir cezayı kimse veremez."},{"n":26,"t":"O'nun vurduğu bağ gibisini de kimse bağlayamaz."},{"n":27,"t":"Ey doygunluğa ermiş kişi,"},{"n":28,"t":"Hoşnut olarak ve hoşnut olunarak Rabbine dön."},{"n":29,"t":"Kullarımın arasına hoşgeldin."},{"n":30,"t":"Cennetime hoşgeldin."}]},{"id":90,"name":"KENT (BELED) SÛRESİ","verses":[{"n":1,"t":"And içerim bu kente,*105 * 90:1-4 Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":2,"t":"Ki sen bu kentte oturmaktasın."},{"n":3,"t":"Doğurana ve doğurduğuna da andolsun."},{"n":4,"t":"İnsanı zorluklar arasında (direnmesi için) yarattık."},{"n":5,"t":"Kendisine güç yetiremiyeceğimizi mi sanıyor?"},{"n":6,"t":"(Övünerek) \"Çok para harcadım,\" diyor."},{"n":7,"t":"Kimsenin kendisini görmediğini mi sanıyor?"},{"n":8,"t":"Ona vermedik mi: İki göz,"},{"n":9,"t":"Bir dil ve iki dudak?"},{"n":10,"t":"Ona iki yolu göstermedik mi?"},{"n":11,"t":"Ne var ki zor yola katlanamadı."},{"n":12,"t":"Zor yolun ne olduğunu bilir misin?"},{"n":13,"t":"Köleleri özgürlüklerine kavuşturmaktır; * 90:13 Müminler köle sahibi olamazlar. Köle sahibi olmak, bir insana efendi (rab veya mevla) olmayı iddia etmektir ve kendini biricik Rab olan Tanrı'ya ortak koşmaktır. Bak 2:286; 4:25; 12:39-42; 79:24."},{"n":14,"t":"Kıtlık anında doyurmaktır:"},{"n":15,"t":"Akraba bir öksüzü,"},{"n":16,"t":"Yahut düşkün bir yoksulu..."},{"n":17,"t":"Dahası, birbirlerine sabır ve sevgiyi öğütleyen inananlardan olmaktır."},{"n":18,"t":"Nitekim mutlular onlardır."},{"n":19,"t":"Ayet ve mucizelerimizi inkar edenlerse talihsizlerdir."},{"n":20,"t":"Onlar ateşe kapatılacaklardır."}]},{"id":91,"name":"GÜNEŞ (ŞEMS) SÛRESİ","verses":[{"n":1,"t":"Andolsun güneşe ve onun aydınlığına, * 91:1-9 Kuran'daki yeminlerin fonksiyonu için bak 89:5."},{"n":2,"t":"Onu izleyen aya,"},{"n":3,"t":"Onu açığa çıkaran gündüze,"},{"n":4,"t":"Onu örten geceye,"},{"n":5,"t":"Göğe ve onu kurana,"},{"n":6,"t":"Yere ve onu yuvarlayıp döşeyene,"},{"n":7,"t":"Nefse ve onu düzenleyene,"},{"n":8,"t":"Sonra da ona kötülüğünü ve erdemliliğini bildirene andolsun ki;"},{"n":9,"t":"Onu temizleyen kurtulmuştur."},{"n":10,"t":"Onu başıboş bırakan ise zarar etmiştir."},{"n":11,"t":"Semud (halkı), azgınlığı yüzünden yalanladı."},{"n":12,"t":"En azgınları ayaklanmıştı."},{"n":13,"t":"ALLAH'ın elçisi, onlara, \"ALLAH'ın devesine ve onun suyuna dokunmayın,\" demişti."},{"n":14,"t":"Onu yalanlayıp deveyi boğazladılar. Bunun üzerine Rab'leri suçlarından ötürü onları silip yerle bir etti. * 91:14 Bak 26:155; 54:27-29."},{"n":15,"t":"Ne var ki hâlâ onların sonlarından ders alınmıyor"}]},{"id":92,"name":"GECE (LEYL) SÛRESİ","verses":[{"n":1,"t":"Andolsun bürüdüğü zaman geceye, * 92:1 Bak 89:5."},{"n":2,"t":"Ortaya çıktığı zaman gündüze,"},{"n":3,"t":"Erkeği ve dişiyi yaratana andolsun ki,"},{"n":4,"t":"İşleriniz çeşit çeşittir."},{"n":5,"t":"Kim verir ve erdemli davranır,"},{"n":6,"t":"Ve iyiyi, güzeli doğrularsa,"},{"n":7,"t":"Ona iyice kolaylaştırırız."},{"n":8,"t":"Fakat, kim cimrilik edip zenginlik taslar,"},{"n":9,"t":"Ve iyiyi, güzeli yalanlarsa,"},{"n":10,"t":"Onu da zora yöneltiriz."},{"n":11,"t":"Düştüğü vakit kurtaramaz parası/malı onu."},{"n":12,"t":"Doğruya biz iletiriz;"},{"n":13,"t":"Sonu da ilki de biz kontrol ederiz."},{"n":14,"t":"Ben sizi alevli bir ateşe karşı uyardım."},{"n":15,"t":"Oraya talihsiz olandan başkası girmez."},{"n":16,"t":"O ki yalanladı ve sırtını döndü."},{"n":17,"t":"Erdemli ise ondan uzak tutulacaktır."},{"n":18,"t":"O ki malını vererek temizlenir;"},{"n":19,"t":"Hiç kimseden de buna karşılık bir iyilik beklemez."},{"n":20,"t":"Sadece En Yüce olan Rabbinin rızasını gözetir."},{"n":21,"t":"Kendisi de yakında mutlu olacaktır."}]},{"id":93,"name":"KUŞLUK (DUHA) SÛRESİ","verses":[{"n":1,"t":"Andolsun kuşluk vaktine,"},{"n":2,"t":"Ve dingin olduğu zaman geceye,"},{"n":3,"t":"Rabbin seni ne bıraktı ne de sana darıldı."},{"n":4,"t":"Senin için son (ahiret) ilkten (dünyadan) daha iyidir."},{"n":5,"t":"Rabbin yakında sana verecek ve sen de beğeneceksin."},{"n":6,"t":"Seni bir öksüz olarak bulup barındırmadık mı?"},{"n":7,"t":"Seni bir sapık olarak bulup doğruya iletmedik mi? * 93:7 Bak 47:19; 48:2."},{"n":8,"t":"Seni fakir bulup zengin etmedik mi?"},{"n":9,"t":"Öyleyse, öksüzü yüzüstü bırakma."},{"n":10,"t":"Dilenciyi de azarlama."},{"n":11,"t":"Ve Rabbinin sana yaptığı iyilikleri de anlat."}]},{"id":94,"name":"SAKİNLEŞTİRME (ŞARH) SÛRESİ","verses":[{"n":1,"t":"Göğsünü genişletip seni sakinleştirmedik mi? * 94:1 Göğsü genişletip ferahlatmaktan söz eden bu ayet, Cibril'in kalp ameliyatı yaparak Muhammed'in kalbini temizlediği biçimindeki uydurma rivayetlerle çarpıtılmıştır. Bu ayetin muhatabı sadece Muhammed peygamber değil, tüm inananlardır. Bak 6:125; 20:25; 39:22."},{"n":2,"t":"Üzerindeki yükünü indirmedik mi?"},{"n":3,"t":"Ki belini bükmüştü."},{"n":4,"t":"Senin şanını yükseltmedik mi?"},{"n":5,"t":"Elbette, kolaylık zorlukla birliktedir."},{"n":6,"t":"Evet, kolaylık zorlukla birliktedir."},{"n":7,"t":"Ne zaman fırsat bulursan uğraş ver."},{"n":8,"t":"Ve sadece Rabbini arzula."}]},{"id":95,"name":"İNCİR (TİN) SÛRESİ","verses":[{"n":1,"t":"Andolsun incire ve zeytine,"},{"n":2,"t":"Sina Dağına,"},{"n":3,"t":"Ve andolsun bu güvenilir kente (Mekke'ye) ki; * 95:1-3 Sina ve Mekke kelimeleri o yörelerde vahiy alan Musa ve Muhammed için kullanılan semboller ise İncir ve Zeytin de başka peygamberlerin vahiy aldıkları yörelere işaret olabilir mi? Ayrıca bak 89:5."},{"n":4,"t":"Biz insanı en güzel bir biçimde yarattık."},{"n":5,"t":"Sonra onu aşağıların aşağısı kıldık."},{"n":6,"t":"Ancak inanıp erdemli davrananlar hariç; onlara kesintisiz bir ödül vardır."},{"n":7,"t":"Artık neden hala bu dini yalanlıyorsun."},{"n":8,"t":"ALLAH bilgelerin En Bilgesi değil midir?"}]},{"id":96,"name":"EMBRİYO (ALAK) SÛRESİ","verses":[{"n":1,"t":"Yaratan Rabbinin ismiyle oku. * 96:1-19 Muhammed'in okuma yazma bildiğini kanıtlayan ayetlerden birisi de ilk inen ayetlerdir. Bak 2:78; 7:157-158. Bu sure Kuran'ın sonundan itibaren 19. sırada olup 19 ayete sahiptir."},{"n":2,"t":"O, insanı bir embriyodan yarattı. * 96:2 Arapça \"Alak\" kelimesi, üç anlama sahiptir. 1) Kan pıhtısı, 2) Asılı duran madde, 3) Sülük. Eskiler, doğal olarak birinci anlamı, yani kan pıhtısı anlamını yeğlemişlerdir. Ne var ki modern biyolojinin gözlemleri bu anlamın doğru olmadığını ortaya koymuştur. İnsanın yaratılış evrelerinde kan pıhtısı diye bir evre yoktur. Bu yüzden, \"rahim duvarına sülük gibi asılı duran madde\" anlamını seçtik. Nitekim, meniden sonraki evre olarak anılan bu biçimin (22:5; 23:14) tek kelimelik karşılığı \"embriyo\"dur. Bak 4:82."},{"n":3,"t":"Oku, Rabbin En Cömert/Yüce olandır."},{"n":4,"t":"Kalem yoluyla öğretir."},{"n":5,"t":"İnsana bilmediklerini öğretti."},{"n":6,"t":"Doğrusu, insan azar;"},{"n":7,"t":"Zenginlik taslayarak."},{"n":8,"t":"Elbette, dönüş senin Rabbinedir."},{"n":9,"t":"Gördün mü, şu engelleyeni:"},{"n":10,"t":"Namaz kılarken bir kulu?"},{"n":11,"t":"Ne dersin, o doğru yolu izleseydi?"},{"n":12,"t":"Yahut erdemliliği öğütleseydi?"},{"n":13,"t":"Ne dersin, o yalanlayıp yüz çevirdiyse?"},{"n":14,"t":"Bilmez mi ki ALLAH herşeyi görmektedir."},{"n":15,"t":"Doğrusu, buna son vermezse, yakalarız perçeminden,"},{"n":16,"t":"O yalancı ve günahkar perçeminden."},{"n":17,"t":"O zaman haydi çağırsın kurultayını."},{"n":18,"t":"Biz de zebanileri çağıracağız.."},{"n":19,"t":"Asla, ona uyma; secde et ve yaklaş!"}]},{"id":97,"name":"KUDRET (KADR) SÛRESİ","verses":[{"n":1,"t":"Biz onu Kudret Gecesinde indirdik. * 97:1 Her mümin için bir Kadir/Yazgı Gecesi vardır. Benim için Kadir Gecesi, dinadamlarının öğretilerini Tanrı'nın öğretisine eş koşmaktan vazgeçtiğim geceydi. 1 Temmuz 1986 sabahına kadar süren o gece hayatımın tümüne bedeldir."},{"n":2,"t":"Kudret Gecesi ne kadar önemlidir, bilir misin?"},{"n":3,"t":"Kudret Gecesi bin aydan daha hayırlıdır."},{"n":4,"t":"Melekler ve Ruh (Cebrail) o gece Rab'lerinin izniyle tüm buyrukları yerine getirmek için inerler."},{"n":5,"t":"O, tan yeri ağarıncaya kadar esenliktir."}]},{"id":98,"name":"KANIT (BEYYİNE) SÛRESİ","verses":[{"n":1,"t":"Kitap halkının inkarcıları ve putperestler, kendilerine açık delil/kanıt gelmesine rağmen yollarını terketmezler."},{"n":2,"t":"ALLAH'ın bir elçisi kendilerine arınmış sahifeler okuyor."},{"n":3,"t":"Onda dosdoğru öğretiler vardır."},{"n":4,"t":"Gerçek şu ki, kendilerine kitap verilmiş olanlar, ancak onlara açık delil geldikten sonra ayrılığa düştüler."},{"n":5,"t":"Oysa onlardan, dini sadece ALLAH'a ait kılan tektanrıcılar (monoteist) olarak O'na kulluk etmeleri, namazı gözetmeleri ve zekatı vermeleri istenmişti. İşte dosdoğru din budur. * 98:5 Bak 39:11."},{"n":6,"t":"Kitap halkının inkarcıları ve putperestler, cehennem ateşinin içindedirler ve orada ebedi kalıcıdırlar. Onlar, yaratıkların en kötüsüdür."},{"n":7,"t":"İnanıp erdemli davrananlar ise yaratıkların en iyisidir."},{"n":8,"t":"Rableri katındaki ödülleri, içinden ırmaklar akan cennetlerdir. Orada ebedi olarak kalacaklardır. ALLAH onlardan hoşnut olmuş, onlar da O'ndan hoşnut olmuşlardır. Rabbine saygı gösterenin ödülü işte böyledir."}]},{"id":99,"name":"DEPREM (ZİLZAL) SÛRESİ","verses":[{"n":1,"t":"Yerin korkunç bir depremle sarsıldığı,"},{"n":2,"t":"Yerin ağırlıklarını fışkırttığı,"},{"n":3,"t":"İnsanın da, \"Buna ne oluyor?\" dediği zaman,"},{"n":4,"t":"İşte o gün (yer), haberlerini anlatacaktır."},{"n":5,"t":"Çünkü Rabbin ona vahyetmiştir."},{"n":6,"t":"O gün, insanlar yapmış oldukları kendilerine gösterilsin diye bölükler halinde çıkagelirler."},{"n":7,"t":"Kim bir atom ağırlığı iyilikte bulunursa onu görür."},{"n":8,"t":"Ve kim bir atom ağırlığı kötülükte bulunursa onu görür."}]},{"id":100,"name":"AŞANLAR (ADİYAT) SÛRESİ","verses":[{"n":1,"t":"Andolsun soluyarak aşanlara, 100:1-5 Geçmiş kuşaklar, bu ayetlerden atları anlamışlar. Oysa, ayetteki ifadeler havadaki oksijeni yutarak ve arkasından ateş fışkırtarak giden jet uçaklarının tarifi olarak da anlaşılabilir. Bu ayetleri yüzlerce yıl önce yaşamış insanlar gibi anlamak zorunda değiliz kuşkusuz. Yeminlerin amacı için bak 89:5."},{"n":2,"t":"Ateş saçarak gidenlere,"},{"n":3,"t":"Sabah sabah akın edenlere,"},{"n":4,"t":"Toz koparanlara,"},{"n":5,"t":"Ve topluluğun içine dalanlara ki;"},{"n":6,"t":"İnsan Rabbine karşı çok nankördür."},{"n":7,"t":"Üstelik buna da tanıktır."},{"n":8,"t":"O mala çok düşkündür."},{"n":9,"t":"Bilmez mi ki, mezardakiler ortaya atıldığı,"},{"n":10,"t":"Ve göğüslerde gizlenenler açığa çıkarıldığı zaman,"},{"n":11,"t":"Evet o gün Rab'leri onların herşeyinden haberlidir."}]},{"id":101,"name":"SOK (KARIA)  SURESI","verses":[{"n":1,"t":"Şok."},{"n":2,"t":"Hem de ne şok!"},{"n":3,"t":"Şoke edenin niteliği sana bildirildi mi?"},{"n":4,"t":"O gün halk, yayılmış kelebekler gibi olur."},{"n":5,"t":"Dağlar da atılmış yün gibi olur."},{"n":6,"t":"Kimin tartıları ağır gelirse,"},{"n":7,"t":"O, mutlu bir hayat içinde olacaktır."},{"n":8,"t":"Kimin de tartıları hafif gelirse,"},{"n":9,"t":"Onun da anası uçurumdur."},{"n":10,"t":"O uçurumun ne olduğunu bilir misin?"},{"n":11,"t":"O, kızgın bir ateştir!"}]},{"id":102,"name":"ÇOĞALTMA YARIŞI (TEKASÜR) SÛRESİ","verses":[{"n":1,"t":"Çoğaltma yarışı sizi alabildiğine meşgul etti; * 102:1 Para, altın, gayri menkul, çocuk, oy, ödül, şöhret gibi nice şeyi çoğaltma yarışı içinde bulunan insanlar bu dünyaya geliş amacını rahatlıkla unutabilmektedir."},{"n":2,"t":"Mezarlara varıncaya (ölünceye) kadar..."},{"n":3,"t":"Doğrusu, yakında bileceksiniz."},{"n":4,"t":"Elbette, yakında bileceksiniz."},{"n":5,"t":"Doğrusu, kesin olarak bilseydiniz."},{"n":6,"t":"Cehennemi görürdünüz."},{"n":7,"t":"Zaten, onu gözünüzle kesin olarak göreceksiniz."},{"n":8,"t":"Sonra, o gün (size verilen) nimetlerden sorulacaksınız."}]},{"id":103,"name":"ÇAĞ (ASR) SÛRESİ","verses":[{"n":1,"t":"Andolsun akıp giden zamana ki;"},{"n":2,"t":"İnsanlar zarardadır."},{"n":3,"t":"Ancak inanıp erdemli davrananlar, birbirlerine gerçeği öğütleyenler ve birbirlerine sabretmeyi öğütleyenler hariç."}]},{"id":104,"name":"DEDİKODUCU (HUMEZE) SÛRESİ","verses":[{"n":1,"t":"Yazıklar olsun her dedikoducuya ve iftiracıya."},{"n":2,"t":"Ki o para/mal biriktirir ve onu sayar durur."},{"n":3,"t":"Sanki parası/malı onu ölümsüz yapacakmış gibi."},{"n":4,"t":"Asla; onu Hutama'ya atacağım."},{"n":5,"t":"Hutama'nın ne olduğunu bilir misin?"},{"n":6,"t":"ALLAH'ın tutuşturulmuş ateşidir."},{"n":7,"t":"Ki beyinlere işler."},{"n":8,"t":"Onların üzerine kapanmıştır."},{"n":9,"t":"Yükselen direkler arasında."}]},{"id":105,"name":"FİL (FİL) SÛRESİ","verses":[{"n":1,"t":"Rabbinin fil halkını ne hale soktuğuna dikkat ettin mi?"},{"n":2,"t":"Planlarını boşa çıkarıp onları şaşkına çevirmedi mi?"},{"n":3,"t":"Onların üstüne kuş sürüleri gönderdi."},{"n":4,"t":"Onlara çamurdan sertleşmiş taşlar atıyorlardı."},{"n":5,"t":"Ve böylece onları yenmiş ekin gibi perişan etmişti."}]},{"id":106,"name":"KUREYŞ (KUREYŞ) SÛRESİ","verses":[{"n":1,"t":"Kureyş (bu mesajı) bağrına basmalı;"},{"n":2,"t":"Kış ve yaz kervanlarını sevdikleri gibi."},{"n":3,"t":"Bu evin Rabbine kulluk etsinler."},{"n":4,"t":"O ki onları açlıktan kurtarıp doyurdu ve korkudan güvene kavuşturdu."}]},{"id":107,"name":"YARDIMLAŞMA (MAUN) SÛRESİ","verses":[{"n":1,"t":"Dini yalanlayanı gördün mü?"},{"n":2,"t":"İşte, öksüze kötü davranan odur."},{"n":3,"t":"Yoksulları doyurmaya da yanaşmaz."},{"n":4,"t":"Yazıklar olsun o namaz kılanlara, * 107:4 Namaz ve diğer ibadetler İbrahim peygamberden itibaren uygulanmakta olup Mekke müşrikleri tarafından biliniyordu. Bak 21:73."},{"n":5,"t":"Onlar ki namazlarından tümüyle habersizdirler."},{"n":6,"t":"Onlar ki gösteriş yaparlar."},{"n":7,"t":"Ve yardımı da engellerler."}]},{"id":108,"name":"BOLLUK (KEVSER) SÛRESİ","verses":[{"n":1,"t":"Biz sana bolca nimetler verdik."},{"n":2,"t":"Öyleyse Rabbin için namaz kıl ve kendini ada/yönel."},{"n":3,"t":"Asıl mahfolacak olanlar sana kin duyanlardır."}]},{"id":109,"name":"İNKARCILAR (KAFİRUN) SÛRESİ","verses":[{"n":1,"t":"De ki, \"Ey inkarcılar.\""},{"n":2,"t":"\"Ben, sizin taptıklarınıza tapmam.\""},{"n":3,"t":"\"Siz de benim taptığıma tapmazsınız.\""},{"n":4,"t":"\"Ben asla sizin taptığınıza tapacak değilim.\""},{"n":5,"t":"\"Siz de benim taptığıma tapacak değilsiniz.\""},{"n":6,"t":"\"Sizin dininiz size, benim dinim bana.\""}]},{"id":110,"name":"YARDIM (NASR) SÛRESİ","verses":[{"n":1,"t":"ALLAH'ın yardımı ve zafer geldiği zaman, * 110:1-3 Ondokuz Arapça kelimeden oluşan bu Sure'nin ilk ayeti 19 harften oluşur. Bak 48:28."},{"n":2,"t":"Halkın akın akın ALLAH'ın dinine girdiğini göreceksin."},{"n":3,"t":"Rabbini överek yücelt ve ondan bağışlanma dile. O, tevbeleri sürekli kabul edendir."}]},{"id":111,"name":"DİKEN (MESED) SÛRESİ","verses":[{"n":1,"t":"Ateş kürükleyenin elleri kahrolsun, zaten kendisi kahroldu. * 111:1 Arapça'daki \"ebu leheb\" ifadesi, alev babası, ateş sahibi, ateşçi olarak da çevirilebilir Türkçe'ye. Bu tanımın, Muhammed'in amcası Abd ul-Uzza Ibn Ebu-l-Muttalib için kullanıldığı ileri sürülür. Bu sureye ilk muhatap olan kişi peygamberin amcası olsa bile, ayetteki eleştiri ve tehdit, inançlarından dolayı insanlara zulmeden despotlara ve onlara yardımcı olanların hepsine yöneliktir."},{"n":2,"t":"Ne parası, ne de bir kazancı ona yaramadı."},{"n":3,"t":"O, alev sahibi bir ateşe girecektir."},{"n":4,"t":"Odun taşıyan (zulmun ateşine yakıt hazırlayan) karısı da."},{"n":5,"t":"Boynunda, dikenlerden/liften örülmüş bir ip bulunduğu (kötülükleri boynuna dolanmış) halde..."}]},{"id":112,"name":"ÖZGÜLEME (İHLAS) SÛRESİ","verses":[{"n":1,"t":"De ki, \"O ALLAH bir tektir.\""},{"n":2,"t":"\"ALLAH Sonsuz ve Mutlaktır.\""},{"n":3,"t":"\"Doğurmamıştır, doğurulmamıştır.\""},{"n":4,"t":"\"Hiçbir kimse de O'na denk değildir.\""}]},{"id":113,"name":"ŞAFAK (FELAK) SÛRESİ","verses":[{"n":1,"t":"De ki, \"Şafağın Rabbine sığınırım.\""},{"n":2,"t":"\"Yarattığı şeylerin şerrinden.\""},{"n":3,"t":"\"Çöktüğü zaman karanlığın şerrinden.\""},{"n":4,"t":"\"Arabozucuların, sözleşmeleri bozanların şerrinden.\""},{"n":5,"t":"\"Kıskandığı vakit kıskananın şerrinden.\""}]},{"id":114,"name":"HALK (NAS) SÛRESİ","verses":[{"n":1,"t":"De ki, \"Sığınırım halkın Rabbine,\""},{"n":2,"t":"\"Halkın Yöneticisine,\""},{"n":3,"t":"\"Halkın Tanrısına,\""},{"n":4,"t":"\"Şerrinden sinsice fısıldayanların.\" * 114:4 Bak 7:116-117."},{"n":5,"t":"\"Onlar halkın göğsüne fısıldarlar.\""},{"n":6,"t":"\"Onlar hem cinlerden hem de halktandır.\""}]}];
